        function earn_startLookupLoadingUi(opts) {
            opts = opts || {};
            earn_clearLookupLoadingUi();
            earn_lookupLoadingUi = {
                active: true,
                runId: Number(opts.runId || earn_activeLookupRunId || 0),
                chainId: String(opts.chainId || document.getElementById('earn-chain')?.value || ''),
                startedAt: earn_nowMs(),
                estimateMs: earn_getLookupEstimateMs(opts.chainId || document.getElementById('earn-chain')?.value || ''),
                progress: 0.08,
                stageIndex: 0,
                headline: String(opts.headline || 'Loading verified Earn data'),
                detail: String(opts.detail || 'We are collecting balances, replaying ledger history and verifying total yield before showing the final view.'),
                cached: !!opts.cached,
            };
            const results = document.getElementById('earn-results');
            if (results) {
                results.classList.add('visible', 'loading-gate');
                results.classList.remove('is-refreshing');
            }
            earn_renderLookupLoadingUi();
            earn_lookupLoadingTimer = setInterval(() => {
                if (!earn_lookupLoadingUi.active) return;
                earn_renderLookupLoadingUi();
            }, 250);
        }

        function earn_updateLookupLoadingUi(runId, patch) {
            if (!earn_lookupLoadingUi.active) return;
            if (runId !== undefined && Number(runId || 0) !== Number(earn_lookupLoadingUi.runId || 0)) return;
            patch = patch || {};
            if (patch.progress !== undefined) {
                const nextProgress = Number(patch.progress || 0);
                if (Number.isFinite(nextProgress)) {
                    earn_lookupLoadingUi.progress = Math.max(earn_lookupLoadingUi.progress || 0, Math.min(0.99, nextProgress));
                }
            }
            if (patch.stageIndex !== undefined) {
                const nextStage = Number(patch.stageIndex || 0);
                if (Number.isFinite(nextStage)) {
                    earn_lookupLoadingUi.stageIndex = Math.max(earn_lookupLoadingUi.stageIndex || 0, Math.min(3, nextStage));
                }
            }
            if (patch.headline) earn_lookupLoadingUi.headline = String(patch.headline);
            if (patch.detail) earn_lookupLoadingUi.detail = String(patch.detail);
            earn_renderLookupLoadingUi();
        }

        function earn_finishLookupLoadingUi(opts) {
            opts = opts || {};
            if (opts.runId !== undefined && earn_lookupLoadingUi.active) {
                if (Number(opts.runId || 0) !== Number(earn_lookupLoadingUi.runId || 0)) return;
            }
            const chainId = opts.chainId || earn_lookupLoadingUi.chainId;
            const durationMs = Number(opts.durationMs || 0);
            if (opts.recordEstimate !== false && chainId && Number.isFinite(durationMs) && durationMs > 0) {
                earn_storeLookupEstimateMs(chainId, durationMs);
            }
            earn_clearLookupLoadingUi();
        }

        function earn_createLookupProfiler(chainId, address, usedCache) {
            return {
                chainId: String(chainId || ''),
                address: String(address || '').toLowerCase(),
                usedCache: !!usedCache,
                startedAt: earn_nowMs(),
                marks: {},
                extras: {},
                loggedStages: {},
            };
        }

        function earn_markLookupProfile(profile, key, value) {
            if (!profile || !key || profile.marks[key] !== undefined) return;
            profile.marks[key] = value !== undefined ? value : (earn_nowMs() - profile.startedAt);
        }

        function earn_setLookupProfileExtra(profile, key, value) {
            if (!profile || !key) return;
            profile.extras[key] = value;
        }

        function earn_logLookupProfile(profile, stage) {
            if (!EARN_PROFILE_LOGS || !profile || !stage || profile.loggedStages[stage]) return;
            profile.loggedStages[stage] = true;

            const shortAddr = profile.address
                ? `${profile.address.slice(0, 6)}...${profile.address.slice(-4)}`
                : 'unknown';
            const marks = profile.marks || {};
            const lines = [];
            const pushLine = (label, key) => {
                if (marks[key] !== undefined) lines.push(`${label}: ${earn_formatDuration(marks[key])}`);
            };

            pushLine('balances', 'balances');
            pushLine('replay', 'replay');
            pushLine('prices', 'prices');
            pushLine('total yield', 'totalYield');
            pushLine('APR API', 'apy');
            pushLine('first render ready', 'firstRenderReady');
            pushLine('history', 'history');
            pushLine('lending', 'lending');
            pushLine('complete', 'complete');

            const suffix = marks[stage] !== undefined ? ` · ${earn_formatDuration(marks[stage])}` : '';
            console.groupCollapsed(`[Earn profile] ${profile.chainId} ${shortAddr} · ${stage}${suffix}`);
            console.log(`cache warm start: ${profile.usedCache ? 'yes' : 'no'}`);
            Object.entries(profile.extras || {}).forEach(([key, value]) => {
                console.log(`${key}:`, value);
            });
            lines.forEach(line => console.log(line));
            console.groupEnd();
        }

