        function earn_resetRpcPolicy() {
            const chainId = String(document.getElementById('earn-chain')?.value || 'ethereum');
            const chain = EARN_CHAINS[chainId] || EARN_CHAINS.ethereum;
            earn_rpcPolicyChainId = chainId;
            earn_rpcPolicy = typeof EarnRpcPolicy !== 'undefined'
                ? EarnRpcPolicy.create(chain.rpcs)
                : null;
        }

        function earn_getRpcPolicy() {
            const chainId = String(document.getElementById('earn-chain')?.value || 'ethereum');
            if (!earn_rpcPolicy || earn_rpcPolicyChainId !== chainId) earn_resetRpcPolicy();
            return earn_rpcPolicy;
        }

        function earn_nextRpc() {
            const policy = earn_getRpcPolicy();
            if (policy) return policy.next();
            const chain = earn_getChain();
            return chain.rpcs[chain.rpcIdx++ % chain.rpcs.length];
        }

        // Fetch total oDOLO claimed by a given address using Dolomite subgraph
        // oDOLO rewards only exist on Berachain
        const ODOLO_SUBGRAPH_CHAINS = {
            berachain: 'https://api.goldsky.com/api/public/project_clyuw4gvq4d5801tegx0aafpu/subgraphs/dolomite-berachain-mainnet/latest/gn',
        };
        async function earn_fetchOdoloClaimed(userAddr) {
            const addr = String(userAddr || '').trim().toLowerCase();
            if (!addr) {
                earn_odoloClaimed = 0;
                earn_odoloUnclaimed = 0;
                earn_odoloCumulative = 0;
                earn_odoloAmountPerNetwork = {};
                return 0;
            }
            if (earn_odoloClaimedLoadedFor === addr) return earn_odoloClaimed;
            if (earn_rewardRequestCache.odoloClaimed[addr]) {
                return earn_rewardRequestCache.odoloClaimed[addr];
            }

            const request = (async () => {
                let claimedValue = 0;
                let unclaimedValue = 0;

                const [apiResult, contractClaimed] = await Promise.allSettled([
                    fetch(`https://api.dolomite.io/liquidity-mining/odolo/seasons/0/wallets/${addr}`)
                        .then(r => r.json())
                        .then(j => j?.user || null),
                    earn_beraRpcCall(IBGT_CONTRACTS.DISTRIBUTOR,
                        IBGT_CONTRACTS.SEL_USER_CLAIM_AMOUNT + '000000000000000000000000' + addr.slice(2))
                        .then(hex => parseInt(hex || '0x0', 16) / 1e18),
                ]);

                const apiUser = apiResult.status === 'fulfilled' ? apiResult.value : null;
                const cumulativeAllocation = parseFloat(apiUser?.amount || '0') || 0;
                const amountPerNetwork = apiUser && apiUser.amountPerNetwork && typeof apiUser.amountPerNetwork === 'object'
                    ? apiUser.amountPerNetwork
                    : {};
                const alreadyClaimed = contractClaimed.status === 'fulfilled' ? contractClaimed.value : 0;

                claimedValue = alreadyClaimed > 0 ? alreadyClaimed : 0;
                unclaimedValue = cumulativeAllocation > alreadyClaimed
                    ? cumulativeAllocation - alreadyClaimed : 0;

                if (claimedValue === 0 && cumulativeAllocation > 0) {
                    try {
                        const endpoint = ODOLO_SUBGRAPH_CHAINS.berachain;
                        let allClaims = [];
                        let skip = 0;
                        const PAGE = 1000;
                        while (true) {
                            const query = `{ liquidityMiningClaims(first: ${PAGE}, skip: ${skip}, where: { user: "${addr}" }) { amount } }`;
                            const resp = await fetch(endpoint, {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({ query }),
                            });
                            const json = await resp.json();
                            const claims = (json.data && json.data.liquidityMiningClaims) || [];
                            allClaims = allClaims.concat(claims);
                            if (claims.length < PAGE) break;
                            skip += PAGE;
                        }
                        claimedValue = allClaims.reduce((sum, c) => sum + parseFloat(c.amount || '0'), 0);
                        unclaimedValue = cumulativeAllocation - claimedValue;
                        if (unclaimedValue < 0) unclaimedValue = 0;
                    } catch (e) {
                        console.warn('oDOLO subgraph fallback error:', e);
                    }
                }

                if (!earn_isLookupAddrCurrent(addr)) {
                    console.log('oDOLO: stale response for', addr, '— globals not updated');
                    return claimedValue;
                }
                earn_odoloClaimed = claimedValue;
                earn_odoloUnclaimed = unclaimedValue;
                earn_odoloCumulative = cumulativeAllocation;
                earn_odoloAmountPerNetwork = amountPerNetwork;
                earn_odoloClaimedLoadedFor = addr;
                console.log(`oDOLO: claimed=${claimedValue.toFixed(2)}, unclaimed=${unclaimedValue.toFixed(2)}, total=${cumulativeAllocation.toFixed(2)}`);
                return claimedValue;
            })();

            earn_rewardRequestCache.odoloClaimed[addr] = request;
            try {
                return await request;
            } finally {
                delete earn_rewardRequestCache.odoloClaimed[addr];
            }
        }

        // Berachain-specific RPC call (always uses Berachain RPC, not the selected chain)
        async function earn_beraRpcCall(to, data) {
            const BERA_RPCS = ['https://rpc.berachain.com/', 'https://berachain-rpc.publicnode.com'];
            for (let i = 0; i < BERA_RPCS.length; i++) {
                try {
                    const resp = await fetch(BERA_RPCS[i], {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0', method: 'eth_call',
                            params: [{ to, data }, 'latest'], id: earn_rpcId++
                        })
                    });
                    const json = await resp.json();
                    if (json.error) throw new Error(json.error.message);
                    return json.result;
                } catch (e) {
                    if (i === BERA_RPCS.length - 1) throw e;
                }
            }
        }

        // Fetch iBGT staking rewards (HONEY, WBERA, wiBGT) for a given user
        // Call chain: diBGT Factory → Registry → MetaVault → Staking Vault
        async function earn_fetchIBGTRewards(userAddr) {
            const addr = String(userAddr || '').trim().toLowerCase();
            if (!addr) {
                earn_ibgtRewards = null;
                return null;
            }
            if (earn_ibgtRewardsLoadedFor === addr) return earn_ibgtRewards;
            if (earn_rewardRequestCache.ibgt[addr]) {
                return earn_rewardRequestCache.ibgt[addr];
            }

            const request = (async () => {
                const pad = '000000000000000000000000';

                // Step 1: Get user's MetaVault from BerachainRewardsRegistry
                const mvHex = await earn_beraRpcCall(
                    IBGT_CONTRACTS.REWARDS_REGISTRY,
                    IBGT_CONTRACTS.SEL_GET_META_VAULT + pad + addr.slice(2)
                );
                const metaVault = '0x' + (mvHex || '').slice(26, 66);
                if (!metaVault || metaVault === '0x' + '0'.repeat(40)) {
                    console.log('iBGT: No MetaVault for this user');
                    return null;
                }

                // Step 2: Query staked balance + earned rewards from iBGT Staking Vault
                const stVault = IBGT_CONTRACTS.STAKING_VAULT;
                const mvAddr = metaVault.slice(2).toLowerCase();

                const rewardTokens = [
                    { symbol: 'HONEY', address: IBGT_CONTRACTS.HONEY },
                    { symbol: 'WBERA', address: IBGT_CONTRACTS.WBERA },
                    { symbol: 'wiBGT', address: IBGT_CONTRACTS.WIBGT },
                ];

                // Batch all calls in parallel
                const [balHex, ...earnedHexes] = await Promise.all([
                    earn_beraRpcCall(stVault, IBGT_CONTRACTS.SEL_BALANCE_OF + pad + mvAddr),
                    ...rewardTokens.map(t =>
                        earn_beraRpcCall(stVault, IBGT_CONTRACTS.SEL_EARNED + pad + mvAddr + pad + t.address.slice(2))
                    ),
                ]);

                const staked = parseInt(balHex || '0x0', 16) / 1e18;
                const rewards = rewardTokens.map((t, i) => ({
                    symbol: t.symbol,
                    address: t.address,
                    amount: parseInt(earnedHexes[i] || '0x0', 16) / 1e18,
                })).filter(r => r.amount > 0.000001);

                const ibgtResult = { staked, rewards, metaVault };
                if (!earn_isLookupAddrCurrent(addr)) {
                    console.log('iBGT: stale response for', addr, '— globals not updated');
                    return ibgtResult;
                }
                earn_ibgtRewards = ibgtResult;
                earn_ibgtRewardsLoadedFor = addr;
                console.log(`iBGT Rewards: staked=${staked.toFixed(2)}, rewards=`, rewards);
                return earn_ibgtRewards;
            })().catch(e => {
                console.warn('iBGT rewards fetch error:', e);
                if (earn_isLookupAddrCurrent(addr)) {
                    earn_ibgtRewards = null;
                    earn_ibgtRewardsLoadedFor = addr;
                }
                return null;
            });

            earn_rewardRequestCache.ibgt[addr] = request;
            try {
                return await request;
            } finally {
                delete earn_rewardRequestCache.ibgt[addr];
            }
        }

        // dGMX Staking Rewards (Arbitrum) — GMX protocol staking rewards
        // GMX staking goes through the dfsGLP Factory vault (not dGMX factory!)
        // Call chain: dfsGLP Factory → getVaultByAccount(user) → vault
        //             sbeGmxTracker.claimable(vault)    → GMX rewards (from esGMX vesting)
        //             feeGmxTracker.claimable(vault)    → ETH fees (legacy, usually 0)
        //             stakedGmxTracker.claimable(vault)  → esGMX pending
        //             feeGmxTracker.balanceOf(vault)     → total staked (sbfGMX)
        const DGMX_CONTRACTS = {
            DFSGLP_FACTORY: '0x34df4e8062a8c8ae97e3382b452bd7bf60542698', // dfsGLP Factory — vault with handleRewards
            SBE_GMX_TRACKER: '0x0755D33e45eD2b874C9EBF5b279023C8BD1E5E93',  // sbeGMX — GMX rewards
            FEE_GMX_TRACKER: '0xd2d1162512f927a7e282ef43a362659e4f2a728f',  // sbfGMX — ETH fees
            STAKED_GMX_TRACKER: '0x908c4d94d34924765f1edc22a1dd098397c59dd4', // sGMX — esGMX
            BONUS_GMX_TRACKER: '0x4d268a7d4C16ceB5a606c173Bd974984343fea13', // sbGMX — bnGMX
            WETH_ARB: '0x82af49447d8a07e3bd95bd0d56f35241523fbab1',
            ESGMX: '0xf42ae1d54fd613c9bb14810b0588faaa09a426ca',
            GMX_TOKEN: '0xfc5a1a6eb076a2c7ad06ed22c90d7e710e35ad0a',
        };

        // Arbitrum RPC call helper
        async function earn_arbRpcCall(to, data) {
            const ARB_RPCS = ['https://arbitrum.drpc.org/', 'https://arbitrum-one-rpc.publicnode.com'];
            for (let i = 0; i < ARB_RPCS.length; i++) {
                try {
                    const resp = await fetch(ARB_RPCS[i], {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0', method: 'eth_call',
                            params: [{ to, data }, 'latest'], id: earn_rpcId++
                        })
                    });
                    const json = await resp.json();
                    if (json.error) throw new Error(json.error.message);
                    return json.result;
                } catch (e) {
                    if (i === ARB_RPCS.length - 1) throw e;
                }
            }
        }

        let earn_dgmxRewards = null; // { staked, rewards: [{symbol, amount, address}], vault }

        async function earn_fetchDGMXRewards(userAddr) {
            const addr = String(userAddr || '').trim().toLowerCase();
            if (!addr) {
                earn_dgmxRewards = null;
                return null;
            }
            if (earn_dgmxRewardsLoadedFor === addr) return earn_dgmxRewards;
            if (earn_rewardRequestCache.dgmx[addr]) {
                return earn_rewardRequestCache.dgmx[addr];
            }

            const request = (async () => {
                const pad = '000000000000000000000000';
                const SEL_GET_VAULT = '0xb01f61e1'; // getVaultByAccount(address)
                const SEL_CLAIMABLE = '0x402914f5'; // claimable(address)
                const SEL_BALANCE = '0x70a08231';   // balanceOf(address)

                // Step 1: Get user's dfsGLP vault (handles GMX staking)
                const vaultHex = await earn_arbRpcCall(
                    DGMX_CONTRACTS.DFSGLP_FACTORY,
                    SEL_GET_VAULT + pad + addr.slice(2)
                );
                const vault = '0x' + (vaultHex || '').slice(26, 66);
                if (!vault || vault === '0x' + '0'.repeat(40)) {
                    console.log('dGMX: No dfsGLP vault for this user');
                    return null;
                }

                // Step 2: Query staked GMX + all reward sources
                const [balHex, gmxRewardHex, ethHex, esgmxHex, bnGmxHex] = await Promise.all([
                    earn_arbRpcCall(DGMX_CONTRACTS.FEE_GMX_TRACKER, SEL_BALANCE + pad + vault.slice(2)),
                    earn_arbRpcCall(DGMX_CONTRACTS.SBE_GMX_TRACKER, SEL_CLAIMABLE + pad + vault.slice(2)),  // GMX rewards!
                    earn_arbRpcCall(DGMX_CONTRACTS.FEE_GMX_TRACKER, SEL_CLAIMABLE + pad + vault.slice(2)),  // ETH fees
                    earn_arbRpcCall(DGMX_CONTRACTS.STAKED_GMX_TRACKER, SEL_CLAIMABLE + pad + vault.slice(2)), // esGMX
                    earn_arbRpcCall(DGMX_CONTRACTS.BONUS_GMX_TRACKER, SEL_CLAIMABLE + pad + vault.slice(2)), // bnGMX
                ]);

                const staked = parseInt(balHex || '0x0', 16) / 1e18;
                const gmxPending = parseInt(gmxRewardHex || '0x0', 16) / 1e18;
                const ethPending = parseInt(ethHex || '0x0', 16) / 1e18;
                const esgmxPending = parseInt(esgmxHex || '0x0', 16) / 1e18;
                const bnGmxPending = parseInt(bnGmxHex || '0x0', 16) / 1e18;

                if (staked < 0.01) {
                    console.log('dGMX: No GMX staked in trackers');
                    return null;
                }

                const rewards = [];
                if (gmxPending > 0.0001) rewards.push({ symbol: 'GMX', amount: gmxPending, address: DGMX_CONTRACTS.GMX_TOKEN });
                if (ethPending > 0.000001) rewards.push({ symbol: 'WETH', amount: ethPending, address: DGMX_CONTRACTS.WETH_ARB });
                if (esgmxPending > 0.0001) rewards.push({ symbol: 'esGMX', amount: esgmxPending, address: DGMX_CONTRACTS.ESGMX });

                const totalUsd = rewards.reduce((s, r) => {
                    const price = r.symbol === 'GMX' ? (earn_priceCache['arbitrum:' + DGMX_CONTRACTS.GMX_TOKEN.toLowerCase()] || 6.2)
                        : r.symbol === 'WETH' ? (earn_priceCache['arbitrum:' + DGMX_CONTRACTS.WETH_ARB.toLowerCase()] || 2000)
                        : r.symbol === 'esGMX' ? (earn_priceCache['arbitrum:' + DGMX_CONTRACTS.GMX_TOKEN.toLowerCase()] || 6.2)
                        : 0;
                    return s + r.amount * price;
                }, 0);

                const dgmxResult = { staked, rewards, totalUsd, vault };
                if (!earn_isLookupAddrCurrent(addr)) {
                    console.log('dGMX: stale response for', addr, '— globals not updated');
                    return dgmxResult;
                }
                earn_dgmxRewards = dgmxResult;
                earn_dgmxRewardsLoadedFor = addr;
                console.log(`dGMX Rewards: staked=${staked.toFixed(2)} sbfGMX, GMX=${gmxPending.toFixed(4)}, ETH=${ethPending.toFixed(6)}, esGMX=${esgmxPending.toFixed(4)}, bnGMX=${bnGmxPending.toFixed(4)}, total=$${totalUsd.toFixed(2)}`);
                return earn_dgmxRewards;
            })().catch(e => {
                console.warn('dGMX rewards fetch error:', e);
                if (earn_isLookupAddrCurrent(addr)) {
                    earn_dgmxRewards = null;
                    earn_dgmxRewardsLoadedFor = addr;
                }
                return null;
            });

            earn_rewardRequestCache.dgmx[addr] = request;
            try {
                return await request;
            } finally {
                delete earn_rewardRequestCache.dgmx[addr];
            }
        }

        function earn_getRpcRetryDelayMs(error, attempt) {
            const msg = String((error && error.message) || error || '').toLowerCase();
            if (msg.includes('429') || msg.includes('rate limit') || msg.includes('too many requests')) {
                return 800 * (attempt + 1);
            }
            if (msg.includes('abort') || msg.includes('timeout')) {
                return 400 * (attempt + 1);
            }
            return 0;
        }

        async function earn_sleep(ms) {
            return new Promise(resolve => setTimeout(resolve, Math.max(0, Number(ms) || 0)));
        }

        async function earn_rpcRequest(method, params, retries = 3) {
            for (let attempt = 0; attempt < retries; attempt++) {
                const rpcUrl = earn_nextRpc();
                if (!rpcUrl) throw new Error('No healthy RPC endpoint is available for this lookup');
                const ctrl = new AbortController();
                const timer = setTimeout(() => ctrl.abort(), 8000);
                try {
                    const resp = await fetch(rpcUrl, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        signal: ctrl.signal,
                        body: JSON.stringify({
                            jsonrpc: '2.0',
                            method,
                            params,
                            id: earn_rpcId++
                        })
                    });
                    clearTimeout(timer);
                    if (!resp.ok) {
                        const httpError = new Error(`RPC HTTP ${resp.status}`);
                        httpError.httpStatus = resp.status;
                        throw httpError;
                    }
                    const json = await resp.json();
                    if (json.error) {
                        const rpcError = new Error(json.error.message);
                        rpcError.rpcCode = json.error.code;
                        throw rpcError;
                    }
                    earn_rpcPolicy.recordSuccess(rpcUrl);
                    return json.result;
                } catch (e) {
                    clearTimeout(timer);
                    const failure = earn_rpcPolicy.recordFailure(rpcUrl, e);
                    if (failure && !failure.retryable) throw e;
                    if (attempt === retries - 1) throw e;
                    const delayMs = earn_getRpcRetryDelayMs(e, attempt);
                    if (delayMs > 0) {
                        await earn_sleep(delayMs);
                    }
                }
            }
        }

        function earn_withTimeout(promise, timeoutMs, label) {
            const safeTimeoutMs = Math.max(1000, Number(timeoutMs || 0));
            const timeoutLabel = String(label || 'Operation');
            return Promise.race([
                promise,
                new Promise((_, reject) => {
                    setTimeout(() => reject(new Error(`${timeoutLabel} timed out after ${safeTimeoutMs}ms`)), safeTimeoutMs);
                }),
            ]);
        }

        function earn_getReplayTimeouts(chainId) {
            const cid = String(chainId || '').trim().toLowerCase();
            if (cid === 'arbitrum') {
                return { subgraphMs: 35000, onchainMs: 90000, softOnchainMs: 15000 };
            }
            if (cid === 'polygonzkevm' || cid === 'xlayer') {
                return { subgraphMs: 20000, onchainMs: 30000, softOnchainMs: 2000 };
            }
            return { subgraphMs: 12000, onchainMs: 15000, softOnchainMs: 0 };
        }

        function earn_isRpcRangeError(message) {
            const msg = String(message || '').toLowerCase();
            return msg.includes('block range') ||
                msg.includes('query returned more than') ||
                msg.includes('too many results') ||
                msg.includes('response size exceeded') ||
                msg.includes('please limit') ||
                msg.includes('exceed') ||
                msg.includes('range');
        }

        async function earn_rpcCall(to, data, retries = 3, blockTag = 'latest') {
            return earn_rpcRequest('eth_call', [{ to, data }, blockTag || 'latest'], retries);
        }

        async function earn_rpcGetLogs(filter, opts) {
            opts = opts || {};
            const retries = opts.retries || 3;
            const fromBlock = Number(BigInt(filter.fromBlock));
            const toBlock = Number(BigInt(filter.toBlock));

            try {
                return await earn_rpcRequest('eth_getLogs', [filter], retries);
            } catch (e) {
                if (!earn_isRpcRangeError(e.message) || fromBlock >= toBlock) throw e;
            }

            const results = [];
            let chunkSize = opts.initialChunk || 250000;
            let current = fromBlock;
            while (current <= toBlock) {
                const end = Math.min(current + chunkSize - 1, toBlock);
                const chunkFilter = {
                    ...filter,
                    fromBlock: '0x' + current.toString(16),
                    toBlock: '0x' + end.toString(16),
                };
                try {
                    const chunkLogs = await earn_rpcRequest('eth_getLogs', [chunkFilter], retries);
                    if (Array.isArray(chunkLogs) && chunkLogs.length > 0) results.push(...chunkLogs);
                    current = end + 1;
                    if (chunkLogs.length < 8 && chunkSize < 2000000) {
                        chunkSize = Math.min(2000000, chunkSize * 2);
                    }
                } catch (e) {
                    if (!earn_isRpcRangeError(e.message) || chunkSize <= 1) throw e;
                    chunkSize = Math.max(1, Math.floor(chunkSize / 2));
                }
            }
            return results;
        }

        // Batch JSON-RPC: send multiple eth_call in a single HTTP request
        async function earn_rpcBatch(calls, retries = 3) {
            if (!calls || calls.length === 0) return [];
            const MAX_BATCH = 25;
            if (calls.length > MAX_BATCH) {
                const chainId = document.getElementById('earn-chain')?.value || '';
                const chunkConcurrency = String(chainId).toLowerCase() === 'arbitrum' ? 4 : 2;
                const chunks = [];
                for (let i = 0; i < calls.length; i += MAX_BATCH) {
                    chunks.push(calls.slice(i, i + MAX_BATCH));
                }
                const chunkResults = await earn_mapWithConcurrency(chunks, chunkConcurrency, async (chunk) => {
                    return earn_rpcBatch(chunk, retries);
                });
                return chunkResults.flat();
            }
            const batch = calls.map((c, i) => ({
                jsonrpc: '2.0',
                method: 'eth_call',
                params: [{ to: c.to, data: c.data }, c.blockTag || 'latest'],
                id: earn_rpcId++
            }));
            for (let attempt = 0; attempt < retries; attempt++) {
                const rpcUrl = earn_nextRpc();
                if (!rpcUrl) return calls.map(() => null);
                const ctrl = new AbortController();
                const timer = setTimeout(() => ctrl.abort(), 8000);
                try {
                    const resp = await fetch(rpcUrl, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        signal: ctrl.signal,
                        body: JSON.stringify(batch)
                    });
                    clearTimeout(timer);
                    if (!resp.ok) {
                        const httpError = new Error(`RPC HTTP ${resp.status}`);
                        httpError.httpStatus = resp.status;
                        throw httpError;
                    }
                    const results = await resp.json();
                    // Results may come in any order, sort by id
                    if (Array.isArray(results)) {
                        if (results.length === 0 && batch.length > 0) {
                            throw new Error('RPC batch returned empty array');
                        }
                        const map = {};
                        let errorCount = 0;
                        results.forEach(r => {
                            if (!r || r.id === undefined || r.id === null) return;
                            if (r.error) {
                                errorCount++;
                                map[r.id] = null;
                            } else {
                                map[r.id] = r.result || null;
                            }
                        });
                        const missingCount = batch.reduce((acc, b) => acc + (Object.prototype.hasOwnProperty.call(map, b.id) ? 0 : 1), 0);
                        if (missingCount > 0 || errorCount > 0) {
                            throw new Error(`RPC batch incomplete (missing=${missingCount}, errors=${errorCount})`);
                        }
                        earn_rpcPolicy.recordSuccess(rpcUrl);
                        return batch.map(b => map[b.id] || null);
                    }
                    // Some RPCs don't support batch, fall back to individual calls
                    console.warn('RPC batch not supported, falling back to individual calls');
                    earn_rpcPolicy.recordSuccess(rpcUrl);
                    const settledNoBatch = await Promise.allSettled(calls.map(c => earn_rpcCall(c.to, c.data, 1, c.blockTag || 'latest')));
                    return settledNoBatch.map(s => s.status === 'fulfilled' ? s.value : null);
                } catch (e) {
                    clearTimeout(timer);
                    const failure = earn_rpcPolicy.recordFailure(rpcUrl, e);
                    const batchCanFallback = /batch (?:incomplete|returned empty)/i.test(String(e && e.message || e));
                    if (failure && !failure.retryable && !batchCanFallback) {
                        return calls.map(() => null);
                    }
                    if (attempt === retries - 1) {
                        if (!batchCanFallback) return calls.map(() => null);
                        const settled = await Promise.allSettled(calls.map(c => earn_rpcCall(c.to, c.data, 1, c.blockTag || 'latest')));
                        return settled.map(s => s.status === 'fulfilled' ? s.value : null);
                    }
                    const delayMs = earn_getRpcRetryDelayMs(e, attempt);
                    if (delayMs > 0) {
                        await earn_sleep(delayMs);
                    }
                }
            }
        }

        // ABI helpers
        function earn_padAddr(addr) {
            return addr.toLowerCase().replace('0x', '').padStart(64, '0');
        }

        function earn_padUint(n) {
            return BigInt(n).toString(16).padStart(64, '0');
        }

        const EARN_ACTION_LOG_TOPICS = {
            deposit: '0x2bad8bc95088af2c247b30fa2b2e6a0886f88625e0945cd3051008e0e270198f',
            withdraw: '0xbc83c08f0b269b1726990c8348ffdf1ae1696244a14868d766e542a2f18cd7d4',
            transfer: '0x21281f8d59117d0399dc467dbdd321538ceffe3225e80e2bd4de6f1b3355cbc7',
            buy: '0x2e346762bf4ae4568971c30b51fcebd2138275aafcfe12d872956e9f3e120893',
            sell: '0xcc3330184b6d88cad87f9e9543b4d4110a6a3eaf20164ca5252d598d0acba3f1',
            trade: '0x54d4cc60cf7d570631cc1a58942812cb0fc461713613400f56932040c3497d19',
            liquidate: '0x1b9e65b359b871d74b1af1fc8b13b11635bfb097c4631b091eb762fda7e67dc7',
            vaporize: '0xefdcfda4e0be180f29bfeebc4bcb6de1e950d70b41e9ee813bff9882ee16ca91',
        };
        const EARN_ACTION_LOG_TOPICS_ALL = Object.values(EARN_ACTION_LOG_TOPICS);
        const EARN_ACTION_LOG_TOPICS_SECOND_OWNER = [
            EARN_ACTION_LOG_TOPICS.transfer,
            EARN_ACTION_LOG_TOPICS.trade,
            EARN_ACTION_LOG_TOPICS.liquidate,
            EARN_ACTION_LOG_TOPICS.vaporize,
        ];
        const EARN_INDEX_UPDATE_TOPICS = {
            default: '0x247e2f5b851dd23ef755d9ad527e801ee202c4097acd70c21e82dc5602cdd879',
            arbitrum: '0xf4626fd1187f91e6761ffb8a6ac3e8d9235a4a92da54e43feb0c57c4a4a322ab',
        };
        const EARN_SEL_GET_MARKET_CURRENT_INDEX = '0x56ea84b2';
        const EARN_SEL_GET_MARKET_TOKEN_ADDRESS = '0x062bd3e9';

        function earn_hexToBigInt(hex) {
            if (hex === undefined || hex === null) return 0n;
            const raw = String(hex);
            if (!raw || raw === '0x') return 0n;
            return BigInt(raw);
        }

        function earn_addrTopic(addr) {
            return '0x' + addr.toLowerCase().replace('0x', '').padStart(64, '0');
        }

        function earn_uintTopic(value) {
            return '0x' + BigInt(value).toString(16).padStart(64, '0');
        }

        function earn_splitHexWords(hex) {
            const raw = (hex || '0x').replace(/^0x/, '');
            const words = [];
            for (let i = 0; i < raw.length; i += 64) {
                words.push(raw.slice(i, i + 64).padStart(64, '0'));
            }
            return words;
        }

        function earn_decodeAddressWord(word) {
            return '0x' + String(word || '').slice(-40).toLowerCase();
        }

        function earn_decodeSignedBoolUint(signWord, valueWord) {
            const value = BigInt('0x' + (valueWord || '0'));
            if (value === 0n) return 0n;
            return BigInt('0x' + (signWord || '0')) !== 0n ? value : -value;
        }

        function earn_decodeBalanceUpdateWords(words, offset) {
            return {
                deltaWei: earn_decodeSignedBoolUint(words[offset], words[offset + 1]),
                newPar: earn_decodeSignedBoolUint(words[offset + 2], words[offset + 3]),
            };
        }

        function earn_logSortValue(log, field) {
            return Number(earn_hexToBigInt(log && log[field] ? log[field] : '0x0'));
        }

        function earn_compareLogs(a, b) {
            const blockDiff = earn_logSortValue(a, 'blockNumber') - earn_logSortValue(b, 'blockNumber');
            if (blockDiff !== 0) return blockDiff;
            const txDiff = earn_logSortValue(a, 'transactionIndex') - earn_logSortValue(b, 'transactionIndex');
            if (txDiff !== 0) return txDiff;
            return earn_logSortValue(a, 'logIndex') - earn_logSortValue(b, 'logIndex');
        }

        function earn_logKey(log) {
            return `${(log.transactionHash || '').toLowerCase()}:${earn_logSortValue(log, 'logIndex')}`;
        }

        async function earn_fetchUserActionLogs(addr, toBlockOverride) {
            const chain = earn_getChain();
            const chainId = document.getElementById('earn-chain').value;
            const ownerTopic = earn_addrTopic(addr);
            const latestHex = toBlockOverride || await earn_rpcRequest('eth_blockNumber', [], chainId === 'arbitrum' ? 5 : 3);
            const fromBlock = '0x' + BigInt(chain.logStartBlock || 0).toString(16);
            const baseFilter = {
                address: chain.margin,
                fromBlock,
                toBlock: latestHex,
            };
            const initialChunk = chainId === 'arbitrum' ? 250000 : 500000;
            const logRetries = chainId === 'arbitrum' ? 5 : 3;
            const topicOneLogs = await earn_rpcGetLogs({
                ...baseFilter,
                topics: [EARN_ACTION_LOG_TOPICS_ALL, ownerTopic],
            }, { initialChunk, retries: logRetries });
            const topicTwoLogs = await earn_rpcGetLogs({
                ...baseFilter,
                topics: [EARN_ACTION_LOG_TOPICS_SECOND_OWNER, null, ownerTopic],
            }, { initialChunk, retries: logRetries });

            const merged = [];
            const seen = new Set();
            [...(topicOneLogs || []), ...(topicTwoLogs || [])].forEach(log => {
                const key = earn_logKey(log);
                if (seen.has(key)) return;
                seen.add(key);
                merged.push(log);
            });
            merged.sort(earn_compareLogs);
            return merged;
        }

        async function earn_fetchIndexLogsForBlocks(blockMarketMap) {
            const chainId = document.getElementById('earn-chain').value;
            const chain = earn_getChain();
            const indexTopic = EARN_INDEX_UPDATE_TOPICS[chainId] || EARN_INDEX_UPDATE_TOPICS.default;
            const blocks = Array.from(blockMarketMap.keys()).sort((a, b) => a - b);
            const byBlock = {};
            const rpcConcurrency = chainId === 'arbitrum' ? 2 : 4;
            const logRetries = chainId === 'arbitrum' ? 5 : 3;

            for (let i = 0; i < blocks.length; i += 8) {
                const slice = blocks.slice(i, i + 8);
                const results = await earn_mapWithConcurrency(slice, rpcConcurrency, async blockNumber => {
                    const marketTopics = Array.from(blockMarketMap.get(blockNumber) || []).map(earn_uintTopic);
                    if (marketTopics.length === 0) return { blockNumber, logs: [] };
                    const blockHex = '0x' + blockNumber.toString(16);
                    const logs = await earn_rpcGetLogs({
                        address: chain.margin,
                        fromBlock: blockHex,
                        toBlock: blockHex,
                        topics: [indexTopic, marketTopics],
                    }, { initialChunk: 1, retries: logRetries });
                    return { blockNumber, logs: logs || [] };
                });

                results.forEach(({ blockNumber, logs }) => {
                    const perMarket = {};
                    (logs || []).sort(earn_compareLogs).forEach(log => {
                        const mid = earn_hexToBigInt(log.topics && log.topics[1] ? log.topics[1] : '0x0').toString();
                        const words = earn_splitHexWords(log.data);
                        if (words.length < 2) return;
                        if (!perMarket[mid]) perMarket[mid] = [];
                        perMarket[mid].push({
                            transactionIndex: earn_logSortValue(log, 'transactionIndex'),
                            logIndex: earn_logSortValue(log, 'logIndex'),
                            borrowIndex: BigInt('0x' + words[0]),
                            supplyIndex: BigInt('0x' + words[1]),
                        });
                    });
                    byBlock[blockNumber] = perMarket;
                });
            }

            return byBlock;
        }

        async function earn_fetchReplayMarketMeta(marketIds, opts) {
            opts = opts || {};
            const chain = earn_getChain();
            const chainId = document.getElementById('earn-chain').value;
            const blockTag = opts.blockTag || 'latest';
            const calls = [];
            const map = [];
            marketIds.forEach(mid => {
                calls.push({ to: chain.margin, data: EARN_SEL_GET_MARKET_TOKEN_ADDRESS + earn_padUint(mid), blockTag });
                map.push({ marketId: String(mid), type: 'token' });
                calls.push({ to: chain.margin, data: EARN_SEL_GET_MARKET_CURRENT_INDEX + earn_padUint(mid), blockTag });
                map.push({ marketId: String(mid), type: 'index' });
            });
            const results = calls.length ? await earn_rpcBatch(calls, chainId === 'arbitrum' ? 5 : 3) : [];
            const currentIndexMap = {};
            const tokenAddrByMarket = {};

            map.forEach((entry, idx) => {
                const result = results[idx];
                if (!result || result === '0x') return;
                if (entry.type === 'token') {
                    tokenAddrByMarket[entry.marketId] = '0x' + result.slice(-40).toLowerCase();
                } else {
                    const words = earn_splitHexWords(result);
                    currentIndexMap[entry.marketId] = {
                        borrowIndex: words[0] ? BigInt('0x' + words[0]) : null,
                        supplyIndex: words[1] ? BigInt('0x' + words[1]) : null,
                    };
                }
            });

            const uniqueAddrs = Array.from(new Set(Object.values(tokenAddrByMarket)));
            await Promise.all(uniqueAddrs.map(addr => earn_getTokenInfo(addr)));

            const marketMeta = {};
            Object.entries(tokenAddrByMarket).forEach(([mid, tokenAddr]) => {
                const key = document.getElementById('earn-chain').value + ':' + tokenAddr.toLowerCase();
                const info = earn_tokenCache[key] || KNOWN_TOKENS[key] || { symbol: 'UNK', decimals: 18, icon: null };
                marketMeta[mid] = {
                    tokenAddr,
                    symbol: info.symbol || 'UNK',
                    decimals: info.decimals || 18,
                    name: info.name || info.symbol || 'UNK',
                    icon: info.icon || null,
                };
            });

            return { currentIndexMap, marketMeta };
        }

        function earn_findEventIndexes(indexLogsByBlock, update, deltaPar) {
            const blockLogs = indexLogsByBlock[update.blockNumber];
            const marketLogs = blockLogs ? blockLogs[update.marketId] : null;
            let best = null;
            if (marketLogs && marketLogs.length > 0) {
                for (const entry of marketLogs) {
                    const beforeTx = entry.transactionIndex < update.transactionIndex;
                    const sameTxBeforeLog = entry.transactionIndex === update.transactionIndex && entry.logIndex < update.logIndex;
                    if (!beforeTx && !sameTxBeforeLog) break;
                    best = entry;
                }
            }

            let derivedIndex = null;
            if ((!best || (!best.supplyIndex && !best.borrowIndex)) && deltaPar !== 0n && update.deltaWei !== 0n) {
                const absPar = deltaPar < 0n ? -deltaPar : deltaPar;
                const absWei = update.deltaWei < 0n ? -update.deltaWei : update.deltaWei;
                if (absPar > 0n && absWei > 0n) {
                    derivedIndex = (absWei * (10n ** 18n)) / absPar;
                }
            }

            return {
                supplyIndex: best && best.supplyIndex ? best.supplyIndex : derivedIndex,
                borrowIndex: best && best.borrowIndex ? best.borrowIndex : derivedIndex,
            };
        }

        // Decode getAccountBalances result:
        // returns (uint256[] marketIds, address[] tokenAddresses, Types.Par[] pars, Types.Wei[] weis)
        // Types.Par = { bool sign, uint128 value }
        // Types.Wei = { bool sign, uint256 value }
        function earn_decodeBalances(hex) {
            if (!hex || hex === '0x') return [];
            const data = hex.replace('0x', '');
            const word = (i) => data.slice(i * 64, (i + 1) * 64);
            const toNum = (w) => BigInt('0x' + w);

            // 4 dynamic arrays, each starts with an offset
            const off0 = Number(toNum(word(0))); // marketIds offset
            const off1 = Number(toNum(word(1))); // tokenAddresses offset
            const off2 = Number(toNum(word(2))); // pars offset
            const off3 = Number(toNum(word(3))); // weis offset

            const readArrayAt = (byteOffset) => {
                const wordIdx = byteOffset / 32;
                const len = Number(toNum(word(wordIdx)));
                const items = [];
                for (let i = 0; i < len; i++) {
                    items.push(word(wordIdx + 1 + i));
                }
                return items;
            };

            // Read marketIds
            const marketIds = readArrayAt(off0).map(w => Number(toNum(w)));
            const count = marketIds.length;
            if (count === 0) return [];

            // Read token addresses
            const tokenAddrs = readArrayAt(off1).map(w => '0x' + w.slice(24));

            // Read Par structs (sign + value pairs)
            const parsWordIdx = off2 / 32;
            const parsLen = Number(toNum(word(parsWordIdx)));
            const pars = [];
            for (let i = 0; i < parsLen; i++) {
                const sign = toNum(word(parsWordIdx + 1 + i * 2)) !== 0n; // true = positive
                const value = toNum(word(parsWordIdx + 2 + i * 2));
                pars.push({ sign, value });
            }

            // Read Wei structs (sign + value pairs)
            const weisWordIdx = off3 / 32;
            const weisLen = Number(toNum(word(weisWordIdx)));
            const weis = [];
            for (let i = 0; i < weisLen; i++) {
                const sign = toNum(word(weisWordIdx + 1 + i * 2)) !== 0n;
                const value = toNum(word(weisWordIdx + 2 + i * 2));
                weis.push({ sign, value });
            }

            const results = [];
            for (let i = 0; i < count; i++) {
                const parVal = pars[i] ? (pars[i].sign ? pars[i].value : -pars[i].value) : 0n;
                const weiVal = weis[i] ? (weis[i].sign ? weis[i].value : -weis[i].value) : 0n;
                // Only include supply positions (positive balances)
                // Borrow positions are injected separately from subgraph data
                if (weiVal > 0n) {
                    results.push({
                        marketId: marketIds[i],
                        tokenAddr: tokenAddrs[i],
                        par: parVal,
                        wei: weiVal,
                        isBorrow: false,
                    });
                }
            }
            return results;
        }

        async function earn_fetchActiveSupplyBalances(addr, opts) {
            opts = opts || {};
            const chain = earn_getChain();
            const chainId = document.getElementById('earn-chain').value;
            const selector = '0x6a8194e7';
            const blockTag = opts.blockTag || earn_replayBlockTag || 'latest';
            const balanceRetryConcurrency = String(chainId).toLowerCase() === 'arbitrum' ? 12 : 4;
            const coverageRetryConcurrency = String(chainId).toLowerCase() === 'arbitrum' ? 8 : 4;
            earn_replayCurrentPositions = [];
            earn_replayCurrentBorrowAccounts = new Set();
            const fallbackAccountNum = String(document.getElementById('earn-account-num')?.value || '0');
            const getPositionKey = (accountNumber, marketId) => {
                // marketId is unique per chain, so tokenAddr mismatches from partial RPC decoding
                // should not create a duplicate snapshot supplement for the same account position.
                const normalizedAccount = accountNumber === undefined || accountNumber === null
                    ? '0'
                    : String(accountNumber);
                const normalizedMarket = marketId === undefined || marketId === null
                    ? ''
                    : String(marketId);
                return `${normalizedAccount}|${normalizedMarket}`;
            };
            const decodeAccountBalances = (hex, accountNumber) => {
                if (!hex || hex === '0x') return [];
                const data = hex.replace('0x', '');
                const word = (i) => data.slice(i * 64, (i + 1) * 64);
                const toNum = (w) => BigInt('0x' + w);
                const off0 = Number(toNum(word(0)));
                const off1 = Number(toNum(word(1)));
                const off2 = Number(toNum(word(2)));
                const off3 = Number(toNum(word(3)));
                const readArrayAt = (byteOffset) => {
                    const wordIdx = byteOffset / 32;
                    const len = Number(toNum(word(wordIdx)));
                    const items = [];
                    for (let i = 0; i < len; i++) items.push(word(wordIdx + 1 + i));
                    return items;
                };
                const marketIds = readArrayAt(off0).map(w => Number(toNum(w)));
                const tokenAddrs = readArrayAt(off1).map(w => '0x' + w.slice(24).toLowerCase());
                const parsWordIdx = off2 / 32;
                const parsLen = Number(toNum(word(parsWordIdx)));
                const pars = [];
                for (let i = 0; i < parsLen; i++) {
                    const sign = toNum(word(parsWordIdx + 1 + i * 2)) !== 0n;
                    const value = toNum(word(parsWordIdx + 2 + i * 2));
                    pars.push({ sign, value });
                }
                const weisWordIdx = off3 / 32;
                const weisLen = Number(toNum(word(weisWordIdx)));
                const weis = [];
                for (let i = 0; i < weisLen; i++) {
                    const sign = toNum(word(weisWordIdx + 1 + i * 2)) !== 0n;
                    const value = toNum(word(weisWordIdx + 2 + i * 2));
                    weis.push({ sign, value });
                }
                const positions = [];
                for (let i = 0; i < marketIds.length; i++) {
                    const parVal = pars[i] ? (pars[i].sign ? pars[i].value : -pars[i].value) : 0n;
                    const weiVal = weis[i] ? (weis[i].sign ? weis[i].value : -weis[i].value) : 0n;
                    if (weiVal === 0n && parVal === 0n) continue;
                    positions.push({
                        marketId: marketIds[i],
                        tokenAddr: tokenAddrs[i],
                        par: parVal,
                        wei: weiVal,
                        accountNumber,
                    });
                }
                return positions;
            };
            const countCoveredPositionKeys = (positions, expectedKeys) => {
                if (!expectedKeys || expectedKeys.size === 0) return 0;
                const positionKeys = new Set((positions || []).map(pos => getPositionKey(pos.accountNumber, pos.marketId, pos.tokenAddr)));
                let covered = 0;
                expectedKeys.forEach(key => {
                    if (positionKeys.has(key)) covered++;
                });
                return covered;
            };
            const retryMissingAccountCoverage = async (missingKeysByAccount) => {
                const recovered = {};
                const accounts = Object.keys(missingKeysByAccount || {});
                const rescueResults = await earn_mapWithConcurrency(accounts, coverageRetryConcurrency, async (accountNumber) => {
                    const expectedKeys = missingKeysByAccount[accountNumber];
                    if (!expectedKeys || expectedKeys.size === 0) return null;
                    let bestPositions = null;
                    let bestCoverage = 0;
                    for (let attempt = 0; attempt < 4; attempt++) {
                        try {
                            const result = await earn_rpcCall(
                                chain.margin,
                                selector + earn_padAddr(addr) + earn_padUint(accountNumber),
                                2,
                                blockTag
                            );
                            const decoded = decodeAccountBalances(result, accountNumber);
                            const coverage = countCoveredPositionKeys(decoded, expectedKeys);
                            if (coverage > bestCoverage) {
                                bestCoverage = coverage;
                                bestPositions = decoded;
                            }
                            if (coverage >= expectedKeys.size) break;
                        } catch (retryErr) {
                            console.warn('Active balance rescue retry failed for account', accountNumber, retryErr.message);
                        }
                    }
                    if (bestPositions && bestCoverage > 0) {
                        return { accountNumber, bestPositions };
                    }
                    return null;
                });
                rescueResults.forEach(entry => {
                    if (entry && entry.accountNumber) recovered[entry.accountNumber] = entry.bestPositions;
                });
                return recovered;
            };
            const retryMissingAccountBalanceResults = async (results) => {
                const nextResults = Array.isArray(results) ? results.slice() : [];
                const missingIndices = [];
                for (let idx = 0; idx < nextResults.length; idx++) {
                    if (nextResults[idx] === null) missingIndices.push(idx);
                }
                const retryAttempts = missingIndices.length > 96 ? 2 : 4;
                const recoveredEntries = await earn_mapWithConcurrency(missingIndices, balanceRetryConcurrency, async (idx) => {
                    const accountNumber = accountNumbers[idx];
                    let recoveredResult = null;
                    for (let attempt = 0; attempt < retryAttempts; attempt++) {
                        try {
                            const retried = await earn_rpcCall(
                                chain.margin,
                                selector + earn_padAddr(addr) + earn_padUint(accountNumber),
                                2,
                                blockTag
                            );
                            if (retried !== null && retried !== undefined) {
                                recoveredResult = retried;
                                break;
                            }
                        } catch (retryErr) {
                            console.warn('Active balance null-result retry failed for account', accountNumber, retryErr.message);
                        }
                    }
                    return { idx, recoveredResult };
                });
                let recovered = 0;
                recoveredEntries.forEach(entry => {
                    if (!entry) return;
                    if (entry.recoveredResult !== null && entry.recoveredResult !== undefined) {
                        nextResults[entry.idx] = entry.recoveredResult;
                        recovered += 1;
                    }
                });
                if (recovered > 0) {
                    console.log(`Active balance retry recovered ${recovered} incomplete account balance result(s).`);
                }
                return nextResults;
            };
            let subgraphSnapshot = null;
            const ensureSubgraphSnapshot = async () => {
                if (!subgraphSnapshot) subgraphSnapshot = await earn_fetchCurrentAccountsFromSubgraph(addr);
                return subgraphSnapshot;
            };
            let accountNumbers = [fallbackAccountNum];
            try {
                const snapshot = await ensureSubgraphSnapshot();
                // Current balance verification should only hit accounts that still have live positions.
                // Reusing all replay accounts here pulls in historical/empty account numbers, which can
                // make large RPC batches look incomplete and incorrectly downgrade healthy markets to PENDING.
                if (snapshot.accountNumbers && snapshot.accountNumbers.length > 0) {
                    accountNumbers = Array.from(new Set(snapshot.accountNumbers.map(v => String(v).trim()).filter(Boolean)));
                } else if (earn_replayAccountNumbers && earn_replayAccountNumbers.length > 0) {
                    accountNumbers = Array.from(new Set(earn_replayAccountNumbers.map(v => String(v).trim()).filter(Boolean)));
                }
            } catch (e) {
                console.warn('Subgraph account discovery failed:', e.message);
                if (earn_replayAccountNumbers && earn_replayAccountNumbers.length > 0) {
                    accountNumbers = Array.from(new Set(earn_replayAccountNumbers.map(v => String(v).trim()).filter(Boolean)));
                }
            }
            if (!accountNumbers.includes(fallbackAccountNum)) accountNumbers.unshift(fallbackAccountNum);

            let aggregatedSupply = {};
            let aggregatedCollateral = {};
            let aggregatedBorrow = {};
            let verificationSupply = {};
            let verificationCollateral = {};
            let verificationBorrow = {};
            let usedSubgraphFallback = false;
            let hiddenSupplyCount = 0;
            let supplementedFromSnapshot = 0;
            let missingResultAccounts = new Set();
            let incompleteCoverageAccounts = new Set();
            earn_hiddenCollateralSupplyMarkets = new Set();
            earn_replayVerificationIncompleteMarkets = new Set();
            try {
                const calls = accountNumbers.map(accountNum => ({
                    to: chain.margin,
                    data: selector + earn_padAddr(addr) + earn_padUint(accountNum),
                    blockTag,
                }));
                const initialResults = calls.length ? await earn_rpcBatch(calls) : [];
                const results = await retryMissingAccountBalanceResults(initialResults);
                const missingResults = results.reduce((acc, r) => acc + (r === null ? 1 : 0), 0);
                if (missingResults > 0) {
                    missingResultAccounts = new Set(
                        accountNumbers.filter((accountNumber, idx) => results[idx] === null).map(v => String(v))
                    );
                    incompleteCoverageAccounts = new Set(Array.from(missingResultAccounts));
                    console.warn(`Active balance lookup proceeding with ${missingResults} incomplete account balance result(s); missing account(s) will be supplemented from snapshot where possible.`);
                }
                const decodedByAccount = {};

                results.forEach((result, idx) => {
                    if (!result || result === '0x') return;
                    const accountNumber = accountNumbers[idx];
                    try {
                        decodedByAccount[accountNumber] = decodeAccountBalances(result, accountNumber);
                    } catch (e) {
                        console.warn('Active balance decode failed for account', accountNumbers[idx], e.message);
                        decodedByAccount[accountNumber] = [];
                    }
                });
                let decodedPositions = earn_coalesceCurrentPositions(Object.values(decodedByAccount).flat());

                // Seed borrow-account routing from explicit replay/subgraph overrides first,
                // then extend it with whatever the live current balances confirm onchain.
                const borrowAccounts = new Set(
                    Array.from(
                        earn_collectBorrowAccountsOverride(
                            earn_replayBorrowAccountsOverride,
                            earn_openBorrowAccounts
                        ) || []
                    )
                );
                decodedPositions.forEach(pos => {
                    const acct = String(pos.accountNumber || '0');
                    if (pos.wei < 0n || pos.par < 0n) borrowAccounts.add(acct);
                });

                // Some RPC providers omit specific balances in getAccountBalances responses.
                // Supplement missing per-account supply entries from the latest subgraph snapshot.
                let mergedPositions = decodedPositions;
                try {
                    const snapshot = await ensureSubgraphSnapshot();
                    const snapshotBorrowAccounts = new Set((snapshot.borrowAccountNumbers || []).map(v => String(v)));
                    snapshotBorrowAccounts.forEach(acct => borrowAccounts.add(acct));
                    (snapshot.positions || []).forEach(pos => {
                        const acct = String(pos.accountNumber || '0');
                        if (pos.wei < 0n || pos.par < 0n) borrowAccounts.add(acct);
                    });

                    let seenPositionKeys = new Set(decodedPositions.map(pos => getPositionKey(pos.accountNumber, pos.marketId, pos.tokenAddr)));
                    const missingKeysByAccount = {};
                    (snapshot.positions || []).forEach(pos => {
                        const acct = String(pos.accountNumber || '0');
                        const key = getPositionKey(acct, pos.marketId, pos.tokenAddr);
                        if (seenPositionKeys.has(key)) return;
                        if (!missingKeysByAccount[acct]) missingKeysByAccount[acct] = new Set();
                        missingKeysByAccount[acct].add(key);
                    });

                    const rescueAccounts = Object.keys(missingKeysByAccount);
                    if (rescueAccounts.length > 0) {
                        const rescuedByAccount = await retryMissingAccountCoverage(missingKeysByAccount);
                        let rescuedPositions = 0;
                        rescueAccounts.forEach(accountNumber => {
                            const rescued = rescuedByAccount[accountNumber];
                            if (!Array.isArray(rescued) || rescued.length === 0) return;
                            const existing = decodedByAccount[accountNumber] || [];
                            const existingCoverage = countCoveredPositionKeys(existing, missingKeysByAccount[accountNumber]);
                            const rescuedCoverage = countCoveredPositionKeys(rescued, missingKeysByAccount[accountNumber]);
                            if (rescuedCoverage <= existingCoverage) return;
                            decodedByAccount[accountNumber] = rescued;
                            rescuedPositions += rescuedCoverage - existingCoverage;
                        });
                        if (rescuedPositions > 0) {
                            decodedPositions = earn_coalesceCurrentPositions(Object.values(decodedByAccount).flat());
                            seenPositionKeys = new Set(decodedPositions.map(pos => getPositionKey(pos.accountNumber, pos.marketId, pos.tokenAddr)));
                            console.log(`Active balance rescue recovered ${rescuedPositions} missing position(s) from direct RPC retries.`);
                        }
                        rescueAccounts.forEach(accountNumber => {
                            const expectedKeys = missingKeysByAccount[accountNumber];
                            const finalCoverage = countCoveredPositionKeys(decodedByAccount[accountNumber] || [], expectedKeys);
                            if (finalCoverage < expectedKeys.size) incompleteCoverageAccounts.add(String(accountNumber));
                            else incompleteCoverageAccounts.delete(String(accountNumber));
                        });
                    }

                    const seenSupplyKeys = new Set();
                    decodedPositions.forEach(pos => {
                        if (!(pos.wei > 0n)) return;
                        seenSupplyKeys.add(getPositionKey(pos.accountNumber, pos.marketId, pos.tokenAddr));
                    });
                    const supplemental = [];
                    (snapshot.positions || []).forEach(pos => {
                        const acct = String(pos.accountNumber || '0');
                        const positionKey = getPositionKey(acct, pos.marketId, pos.tokenAddr);
                        const supplementEntireAccount = incompleteCoverageAccounts.has(acct);
                        if (!seenPositionKeys.has(positionKey)) {
                            earn_replayVerificationIncompleteMarkets.add(String(pos.marketId));
                        }
                        if (supplementEntireAccount) {
                            if (seenPositionKeys.has(positionKey)) return;
                        } else {
                            if (!(pos.wei > 0n)) return;
                            if (seenSupplyKeys.has(positionKey)) return;
                            seenSupplyKeys.add(positionKey);
                        }
                        supplemental.push({
                            ...pos,
                            accountNumber: acct,
                            marketId: pos.marketId,
                            tokenAddr: String(pos.tokenAddr || '').toLowerCase(),
                        });
                    });

                    if (supplemental.length > 0) {
                        mergedPositions = earn_coalesceCurrentPositions(decodedPositions.concat(supplemental));
                        supplementedFromSnapshot = supplemental.length;
                    }
                } catch (snapshotErr) {
                    console.warn('Snapshot supplement skipped:', snapshotErr.message);
                }

                const routedCurrent = earn_buildCurrentPositionBuckets(mergedPositions, {
                    knownBorrowAccounts: borrowAccounts,
                    borrowAccountsOverride: earn_replayBorrowAccountsOverride,
                });
                earn_reconcileReplayToCurrentPositions(mergedPositions, { borrowAccounts: routedCurrent.borrowAccounts });
                earn_openBorrowAccounts = routedCurrent.borrowAccounts;
                earn_replayCurrentPositions = mergedPositions.map(pos => ({ ...pos }));
                earn_replayCurrentBorrowAccounts = new Set(Array.from(routedCurrent.borrowAccounts));

                hiddenSupplyCount = routedCurrent.hiddenSupplyCount;
                earn_hiddenCollateralSupplyMarkets = routedCurrent.hiddenMarketIds;
                aggregatedSupply = routedCurrent.aggregatedSupply;
                aggregatedCollateral = routedCurrent.aggregatedCollateral;
                aggregatedBorrow = routedCurrent.aggregatedBorrow;

                // Build verification maps from the final merged position set so collateral/supply
                // classification stays in sync with any borrow accounts discovered via snapshot
                // supplementation. Missing supplemented markets are still marked unverified above.
                const verificationAggregated = earn_buildCurrentPositionBuckets(mergedPositions, {
                    knownBorrowAccounts: routedCurrent.borrowAccounts,
                    borrowAccountsOverride: earn_replayBorrowAccountsOverride,
                });
                verificationSupply = verificationAggregated.aggregatedSupply;
                verificationCollateral = verificationAggregated.aggregatedCollateral;
                verificationBorrow = verificationAggregated.aggregatedBorrow;
            } catch (rpcErr) {
                console.warn('RPC balance lookup failed, using subgraph fallback:', rpcErr.message);
                const snapshot = await ensureSubgraphSnapshot();
                // Subgraph fallback: derive open-borrow accounts from current snapshot only.
                const borrowAccounts = new Set(
                    Array.from(
                        earn_collectBorrowAccountsOverride(
                            earn_replayBorrowAccountsOverride,
                            earn_openBorrowAccounts,
                            snapshot.borrowAccountNumbers || []
                        ) || []
                    )
                );
                (snapshot.positions || []).forEach(pos => {
                    const acct = String(pos.accountNumber || '0');
                    if (pos.wei < 0n || pos.par < 0n) borrowAccounts.add(acct);
                });
                const routedSnapshot = earn_buildCurrentPositionBuckets(snapshot.positions || [], {
                    knownBorrowAccounts: borrowAccounts,
                    borrowAccountsOverride: earn_replayBorrowAccountsOverride,
                    snapshotBorrowAccounts: snapshot.borrowAccountNumbers || [],
                });
                earn_openBorrowAccounts = routedSnapshot.borrowAccounts;
                earn_replayCurrentPositions = (snapshot.positions || []).map(pos => ({ ...pos }));
                earn_replayCurrentBorrowAccounts = new Set(Array.from(routedSnapshot.borrowAccounts));
                hiddenSupplyCount = routedSnapshot.hiddenSupplyCount;
                earn_hiddenCollateralSupplyMarkets = routedSnapshot.hiddenMarketIds;
                aggregatedSupply = routedSnapshot.aggregatedSupply;
                aggregatedCollateral = routedSnapshot.aggregatedCollateral;
                aggregatedBorrow = routedSnapshot.aggregatedBorrow;
                verificationSupply = {};
                verificationCollateral = {};
                verificationBorrow = {};
                Object.keys(aggregatedSupply).forEach(mid => earn_replayVerificationIncompleteMarkets.add(String(mid)));
                Object.keys(aggregatedCollateral).forEach(mid => earn_replayVerificationIncompleteMarkets.add(String(mid)));
                Object.keys(aggregatedBorrow).forEach(mid => earn_replayVerificationIncompleteMarkets.add(String(mid)));
                usedSubgraphFallback = true;
            }

            earn_replayActualSupplyMap = verificationSupply;
            earn_replayActualBorrowMap = verificationBorrow;
            earn_replayActualCollateralMap = verificationCollateral;
            earn_buildReplayVerification(verificationSupply, verificationBorrow, verificationCollateral);

            const pruneGhostCurrentMarkets = (target) => {
                Object.keys(target || {}).forEach(mid => {
                    const entry = earn_replayVerificationData ? earn_replayVerificationData[String(mid)] : null;
                    if (earn_shouldHideGhostCurrentMarket(entry)) {
                        delete target[mid];
                    }
                });
            };
            pruneGhostCurrentMarkets(aggregatedSupply);
            pruneGhostCurrentMarkets(aggregatedCollateral);
            pruneGhostCurrentMarkets(aggregatedBorrow);

            earn_borrowMarkets = new Set(Object.keys(aggregatedBorrow));
            earn_borrowPositionData = Object.values(aggregatedBorrow).map(pos => {
                const meta = earn_subgraphTokens[String(pos.marketId)] || {};
                return {
                    ...pos,
                    isBorrow: true,
                    symbol: meta.symbol || 'UNK',
                    decimals: meta.decimals || 18,
                    icon: meta.icon || null,
                };
            });
            earn_collateralPositionData = Object.values(aggregatedCollateral).map(pos => {
                const meta = earn_subgraphTokens[String(pos.marketId)] || {};
                return {
                    ...pos,
                    isBorrow: false,
                    isCollateral: true,
                    symbol: meta.symbol || 'UNK',
                    decimals: meta.decimals || 18,
                    icon: meta.icon || null,
                };
            });

            console.log(`Active supply lookup: aggregated ${Object.keys(aggregatedSupply).length} visible supply markets, ${Object.keys(aggregatedCollateral).length} collateral supply markets and ${Object.keys(aggregatedBorrow).length} borrow markets across ${accountNumbers.length} account(s)${usedSubgraphFallback ? ' via subgraph fallback' : ''}${supplementedFromSnapshot > 0 ? ` · supplemented ${supplementedFromSnapshot} missing supply position(s) from snapshot` : ''}${hiddenSupplyCount > 0 ? ` · hidden ${hiddenSupplyCount} collateral supply position(s) from open borrow accounts` : ''}`);
            return Object.values(aggregatedSupply);
        }

