        async function earn_getTokenInfo(addr) {
            const chainId = document.getElementById('earn-chain').value;
            const key = chainId + ':' + addr.toLowerCase();
            if (earn_tokenCache[key]) return earn_tokenCache[key];

            // Check known tokens first (already lowercase keyed)
            if (KNOWN_TOKENS[key]) {
                const kt = { ...KNOWN_TOKENS[key] };
                // Fallback icon from SYMBOL_ICONS if KNOWN_TOKENS has no icon
                if (!kt.icon && kt.symbol) kt.icon = SYMBOL_ICONS[kt.symbol] || SYMBOL_ICONS[kt.symbol.toUpperCase()] || null;
                earn_tokenCache[key] = kt;
                return kt;
            }

            // Fetch symbol + decimals via RPC
            try {
                const [symHex, decHex] = await Promise.all([
                    earn_rpcCall(addr, '0x95d89b41'), // symbol()
                    earn_rpcCall(addr, '0x313ce567'), // decimals()
                ]);

                let symbol = 'UNK';
                if (symHex && symHex.length > 2) {
                    try {
                        const d = symHex.replace('0x', '');
                        if (d.length === 64) {
                            // bytes32 format — extract non-zero bytes
                            const bytes = [];
                            for (let j = 0; j < 64; j += 2) {
                                const byte = parseInt(d.substr(j, 2), 16);
                                if (byte > 0) bytes.push(byte);
                            }
                            symbol = String.fromCharCode(...bytes);
                        } else if (d.length >= 128) {
                            // Dynamic string: offset + length + data
                            const len = Number(BigInt('0x' + d.slice(64, 128)));
                            const bytes = d.slice(128, 128 + len * 2);
                            symbol = '';
                            for (let i = 0; i < bytes.length; i += 2) {
                                const c = parseInt(bytes.slice(i, i + 2), 16);
                                if (c > 0) symbol += String.fromCharCode(c);
                            }
                        }
                    } catch (e) { /* fallback */ }
                }

                const decimals = decHex ? Number(BigInt('0x' + decHex.replace('0x', ''))) : 18;

                // Try symbol-based icon fallback (raw symbol — icon map lookup)
                let icon = SYMBOL_ICONS[symbol] || null;

                // XSS guard: on-chain symbol() is deployer-controlled and the
                // cached value feeds innerHTML templates downstream.
                symbol = earn_escapeHtml(symbol);

                // If still no icon, try Trust Wallet assets CDN
                if (!icon) {
                    const chain = EARN_CHAINS[chainId];
                    if (chain && chain.twChain) {
                        // Checksum address for TW CDN (use original addr casing)
                        const twUrl = `https://raw.githubusercontent.com/trustwallet/assets/master/blockchains/${chain.twChain}/assets/${addr}/logo.png`;
                        try {
                            const probe = await fetch(twUrl, { method: 'HEAD' });
                            if (probe.ok) icon = twUrl;
                        } catch (_) { /* ignore */ }
                    }
                }

                const info = { symbol, decimals, icon };
                earn_tokenCache[key] = info;
                return info;
            } catch (e) {
                const info = { symbol: key.slice(0, 6) + '…', decimals: 18, icon: null };
                earn_tokenCache[key] = info;
                return info;
            }
        }

        // Fallback USD price estimates (used when CoinGecko is unavailable)
        const TOKEN_USD_FALLBACK = {
            'WBTC': 95000, 'BTC': 95000,
            'WETH': 2700, 'ETH': 2700, 'wstETH': 3100, 'weETH': 2800, 'rsETH': 2800, 'rETH': 3000, 'cbETH': 2800, 'sfrxETH': 2900,
            'WBERA': 7, 'iBERA': 7, 'BERA': 7,
            'USDC': 1, 'USDT': 1, 'DAI': 1, 'USDC.e': 1, 'USDe': 1, 'BYUSD': 1, 'NECT': 1, 'HONEY': 1, 'sUSDe': 1.05,
            'ARB': 0.5, 'GMX': 25, 'PENDLE': 4, 'LINK': 15, 'UNI': 8,
            'DOLO': 0.01, 'HENLO': 0.00001, 'YEET': 0.001,
            'iBGT': 4, 'wiBGT': 4, 'diBGT': 4,
            'esGMX': 25,
        };

        // ===== EARN UNIFIED VIEW =====
        let earn_showInactive = true; // show withdrawn/inactive by default
        let earn_withdrawnCollapsed = false; // expanded by default

        function earn_toggleWithdrawnSection() {
            earn_withdrawnCollapsed = !earn_withdrawnCollapsed;
            const body = document.getElementById('earn-withdrawn-body');
            if (body) body.style.display = earn_withdrawnCollapsed ? 'none' : '';
            const chevron = document.getElementById('earn-withdrawn-chevron-icon');
            if (chevron) chevron.style.transform = earn_withdrawnCollapsed ? '' : 'rotate(180deg)';
        }
        let earn_showDust = true;     // show dust positions by default
        let earn_historyData = null; // cached history results (inactive assets)

        function earn_switchMode(mode) {
            // Legacy — no-op for backward compat
        }

        function earn_toggleInactive() {
            earn_showInactive = !earn_showInactive;
            const btn = document.getElementById('earn-inactive-toggle');
            if (btn) {
                btn.classList.toggle('active', earn_showInactive);
                const label = btn.querySelector('.earn-filter-label');
                if (label) label.textContent = 'Past & Routed';
            }
            // Suppress row animations on toggle re-render
            const tbl = document.querySelector('.earn-asset-table');
            if (tbl) tbl.classList.add('no-animate');
            // Preserve scroll position across re-render
            const scrollY = window.scrollY;
            if (earn_cachedAssets.length > 0 || earn_historyData) {
                earn_renderResults(earn_cachedAssets, { skipSummary: true });
            }
            requestAnimationFrame(() => window.scrollTo(0, scrollY));
        }

        function earn_toggleDust() {
            earn_showDust = !earn_showDust;
            const btn = document.getElementById('earn-dust-toggle');
            if (btn) {
                // active = filter ON = dust HIDDEN (inverted from before)
                btn.classList.toggle('active', !earn_showDust);
                btn.setAttribute('aria-checked', String(!earn_showDust));
            }
            // Suppress row animations on toggle re-render
            const tbl = document.querySelector('.earn-asset-table');
            if (tbl) tbl.classList.add('no-animate');
            // Preserve scroll position across re-render
            const scrollY = window.scrollY;
            if (earn_cachedAssets.length > 0 || earn_historyData) {
                earn_renderResults(earn_cachedAssets, { skipSummary: true });
            }
            // Also re-render the standalone withdrawn section
            earn_renderWithdrawnAssets();
            requestAnimationFrame(() => window.scrollTo(0, scrollY));
        }

        async function earn_lookupHistory(opts) {
            opts = opts || {};
            const runId = opts.runId;
            const allowReplayRetry = opts.allowReplayRetry !== false;
            const addr = document.getElementById('earn-address').value.trim().toLowerCase();
            const chainId = document.getElementById('earn-chain').value;
            const chain = earn_getChain();
            if (!addr || chain.pending) return false;
            if (!earn_isLookupRunCurrent(runId)) return false;

            // Show loading state
            const tbody = document.getElementById('earn-history-tbody');
            if (tbody) tbody.innerHTML = '<tr><td colspan="4" style="text-align:center;padding:40px;color:var(--text-muted)"><div class="spinner" style="display:inline-block;width:24px;height:24px;border:2px solid rgba(255,255,255,0.1);border-top-color:#6366f1;border-radius:50%;animation:earnSpin 0.8s linear infinite"></div><br>Loading history...</td></tr>';

            // Step 1: Use subgraph netflow data (already loaded or load now)
            try {
                if (!earn_netflowData) {
                    if (!allowReplayRetry) {
                        if (!earn_isLookupRunCurrent(runId)) return false;
                        earn_historyData = [];
                        earn_renderHistory([]);
                        earn_renderWithdrawnAssets();
                        return false;
                    }
                    await earn_fetchNetflow(); // Will rebuild the onchain replay
                    if (!earn_isLookupRunCurrent(runId)) return false;
                }
                const addrFlows = earn_netflowData;
                if (!addrFlows || Object.keys(addrFlows).length === 0) {
                    if (tbody) tbody.innerHTML = '<tr><td colspan="4" style="text-align:center;padding:40px;color:var(--text-muted)">No deposit/withdrawal history found for this address</td></tr>';
                    return false;
                }

                // Step 2: Get all market IDs from netflow
                const marketIds = Array.from(new Set([
                    ...Object.keys(addrFlows || {}),
                    ...Object.keys(earn_interestYieldData || {}),
                ])).map(Number).sort((a, b) => a - b);

                // Step 3: Get active balances (current wei for each market)
                const activeBalances = {};
                const collateralBalances = {};
                if (earn_cachedAssets) {
                    for (const a of earn_cachedAssets) {
                        const target = a.isCollateral ? collateralBalances : activeBalances;
                        target[String(a.marketId)] = { wei: a.wei, par: a.par, tokenAddr: a.tokenAddr, decimals: a.decimals, symbol: a.symbol, icon: a.icon };
                    }
                }

                // Step 4: Resolve token info from subgraph cache (populated during earn_fetchNetflow)
                // No more need for complex RPC lookups — subgraph gives us everything
                const marketTokens = {};
                // Populate marketTokens from subgraph cache for tokens not in activeBalances
                for (const mid of marketIds) {
                    const midStr = String(mid);
                    if (!activeBalances[midStr] && earn_subgraphTokens[midStr]?.tokenAddr) {
                        marketTokens[midStr] = earn_subgraphTokens[midStr].tokenAddr;
                    }
                }

                // Step 6: Fetch CoinGecko prices
                const allAddrs = marketIds.map(mid => {
                    const midStr = String(mid);
                    return activeBalances[midStr]?.tokenAddr || collateralBalances[midStr]?.tokenAddr || marketTokens[midStr];
                }).filter(Boolean);
                await earn_fetchCoinGeckoPrices(allAddrs);
                if (!earn_isLookupRunCurrent(runId)) return false;

                // Step 7: Build history data
                const historyItems = [];
                for (const mid of marketIds) {
                    const midStr = String(mid);
                    const flowData = addrFlows[midStr];
                    const flowMeta = earn_parseNetflowEntry(flowData);
                    const netFlow = flowMeta ? flowMeta.netFlow : 0n;
                    const hasBreakdown = !!(flowMeta && flowMeta.hasBreakdown);
                    const totalDeposited = flowMeta ? flowMeta.totalDeposited : 0n;
                    const totalWithdrawn = flowMeta ? flowMeta.totalWithdrawn : 0n;
                    const totalBorrowed = flowMeta ? flowMeta.totalBorrowed : 0n;
                    const interestMeta = earn_interestYieldData && earn_interestYieldData[midStr];
                    const currentBorrowPar = interestMeta ? BigInt(interestMeta.currentBorrowPar || '0') : 0n;
                    const currentCollateralPar = interestMeta ? BigInt(interestMeta.currentCollateralSupplyPar || '0') : 0n;
                    const hasSupplyYield = interestMeta
                        ? !!interestMeta.hadSupply || BigInt(interestMeta.earnYield || '0') !== 0n
                        : false;
                    if (!flowMeta && !interestMeta) continue;

                    // Skip markets where user has NO supply deposits — these are borrow-only or
                    // swap-only positions where the netflow formula produces false "yield".
                    if (hasBreakdown && totalDeposited === 0n && totalBorrowed > 0n && !hasSupplyYield) continue;

                    const isActive = !!activeBalances[midStr];
                    const isCollateralized = !isActive && !!collateralBalances[midStr];
                    if (!isActive && currentBorrowPar > 0n && !hasSupplyYield) continue; // open borrow cost stays in Lending until closure
                    const currentPosition = activeBalances[midStr] || collateralBalances[midStr] || null;
                    const currentWei = currentPosition ? currentPosition.wei : 0n;

                    // Resolve token info — prioritize hardcoded map over RPC
                    let tokenAddr, symbol, decimals, icon, tokenName;
                    if (currentPosition) {
                        tokenAddr = currentPosition.tokenAddr;
                        symbol = currentPosition.symbol;
                        decimals = currentPosition.decimals;
                        icon = currentPosition.icon;
                        tokenName = earn_subgraphTokens[midStr]?.name || symbol;
                    } else {
                        // Use subgraph token cache (populated by earn_fetchNetflow)
                        const sgToken = earn_subgraphTokens[midStr];
                        tokenAddr = marketTokens[midStr] || '';
                        symbol = sgToken?.symbol || 'UNK';
                        decimals = sgToken?.decimals || 18;
                        tokenName = sgToken?.name || symbol;
                        icon = SYMBOL_ICONS[symbol] || SYMBOL_ICONS[symbol?.toUpperCase()] || null;
                    }

                    // Detect isolation mode tokens (Dolomite wrapper tokens)
                    const isIsolation = tokenName && (
                        tokenName.includes('Dolomite Isolation') ||
                        tokenName.includes('Dolomite: Fee') ||
                        tokenName.startsWith('Dolomite Isolation')
                    );

                    historyItems.push({
                        marketId: mid,
                        tokenAddr,
                        symbol,
                        decimals,
                        icon,
                        isActive,
                        isCollateralized,
                        isIsolation,
                        tokenName,
                        currentWei,
                        currentPar: currentPosition ? currentPosition.par : 0n,
                        yieldWei: 0n,
                        yieldUsdScaled: 0n,
                        yieldUsd: 0,
                        hasYieldData: false,
                        yieldMethod: null,
                        totalDeposited,
                        totalWithdrawn,
                        netFlow,
                        hasBreakdown,
                        hasOpenBorrow: currentBorrowPar > 0n || currentCollateralPar > 0n,
                    });
                }

                if (!earn_isLookupRunCurrent(runId)) return false;
                earn_historyData = historyItems;
                earn_refreshHistoryYieldData();
                earn_renderHistory(earn_historyData);
                earn_renderWithdrawnAssets(); // Populate withdrawn assets collapsible section
                return true;
            } catch (e) {
                if (!earn_isLookupRunCurrent(runId)) return false;
                console.error('History lookup failed:', e);
                if (tbody) tbody.innerHTML = `<tr><td colspan="4" style="text-align:center;padding:40px;color:var(--accent-rose)">Error loading history: ${earn_escapeHtml(e && e.message ? e.message : String(e))}</td></tr>`;
                return false;
            }
        }

        function earn_renderHistory(items) {
            // Filter out closed isolation positions and sub-$1 dust
            items = items.filter(item => {
                // Remove closed isolation mode positions entirely
                if (item.isIsolation && !item.isActive) return false;
                // Remove dust positions (balance value < $1)
                const chainId = document.getElementById('earn-chain').value;
                const balanceUsdScaled = earn_getTokenUsdScaled(item.currentWei, item.decimals, item.symbol, item.tokenAddr, chainId);
                const verifiedYieldUsdScaled = item.yieldTrustedForDisplay ? (item.yieldUsdScaled || 0n) : 0n;
                if (!earn_showDust && earn_isSubDollarYieldPair(balanceUsdScaled, verifiedYieldUsdScaled)) return false;
                return true;
            });

            // Total summary
            let totalYieldUsdScaled = 0n;
            let totalActive = 0;
            let totalWithdrawn = 0;
            items.forEach(item => {
                // Exclude isolation mode tokens from total yield
                if (!item.isIsolation && item.yieldTrustedForDisplay) {
                    totalYieldUsdScaled += BigInt(item.yieldUsdScaled || 0n);
                }
                if (item.isActive) totalActive++; else totalWithdrawn++;
            });

            const totalYieldUsd = earn_scaledUsdToNumber(totalYieldUsdScaled);
            const isPositive = totalYieldUsd >= 0;
            const totalFmt = totalYieldUsd >= 1000 ? '$' + (totalYieldUsd / 1000).toFixed(2) + 'K' :
                totalYieldUsd >= 1 ? '$' + totalYieldUsd.toFixed(2) :
                    '$' + totalYieldUsd.toFixed(4);

            const histTotalEl = document.getElementById('earn-hist-total');
            if (!histTotalEl) return; // unified view — skip legacy rendering
            histTotalEl.innerHTML = `
                <div class="earn-hist-total-item">
                    <div class="earn-hist-total-label">Total Yield Earned</div>
                    <div class="earn-hist-total-value ${isPositive ? 'positive' : 'negative'}">${isPositive ? '+' : ''}${totalFmt}</div>
                </div>
                <div class="earn-hist-total-item">
                    <div class="earn-hist-total-label">Assets Tracked</div>
                    <div class="earn-hist-total-value" style="color:var(--text-primary)">${items.length}</div>
                </div>
                <div class="earn-hist-total-item">
                    <div class="earn-hist-total-label">Active / Past</div>
                    <div class="earn-hist-total-value" style="color:var(--text-primary);font-size:18px">${totalActive} / ${totalWithdrawn}</div>
                </div>
            `;

            // Table rows
            const tbody = document.getElementById('earn-history-tbody');
            if (!tbody) return; // unified view — history rendered via earn_renderResults
            let html = '';

            // Get explorer URL
            const chain = earn_getChain();
            const explorerBase = chain.explorer || 'https://etherscan.io';

            items.forEach((item, idx) => {
                const delay = idx * 0.05;

                // Icon
                const _GS = new Set(['CRV', 'USD0', 'USD0++', 'deUSD', 'sdeUSD', 'MATIC', 'POL', 'stcUSD', 'cUSD', 'USDT', 'cbBTC']);
                const _gsF = _GS.has(item.symbol) ? ' style="filter:grayscale(1) brightness(1.5)"' : '';
                let iconHtml;
                if (item.icon) {
                    iconHtml = `<div class="earn-token-icon${earnTokenIconFrameClass(item.symbol)}"><img src="${item.icon}" alt="${item.symbol}"${_gsF} onerror="this.parentElement.textContent='${String(item.symbol || '?').replace(/[^A-Za-z0-9]/g, '').slice(0, 2) || '?'}'"></div>`;
                } else {
                    iconHtml = `<div class="earn-token-icon">${item.symbol.slice(0, 2)}</div>`;
                }

                // Status badge
                let badge;
                if (item.isIsolation && !item.isActive) {
                    badge = '<span class="earn-hist-badge isolation" data-tip="Dolomite Isolation Mode — internal wrapper token used as collateral in borrow positions">Isolation</span>';
                } else if (item.isCollateralized) {
                    badge = '<span class="earn-hist-badge earn-position-badge routed" data-tip="Asset is routed into a borrow subaccount as collateral, so it is not a withdrawn supply asset"><span class="earn-status-dot"></span>In Borrow Route</span>';
                } else if (item.isActive) {
                    badge = '';
                } else {
                    badge = '<span class="earn-hist-badge earn-position-badge withdrawn"><span class="earn-status-dot"></span>Exited Position</span>';
                }
                const verifyBadge = earn_renderVerificationBadge(item.marketId, item.symbol, item.decimals);

                // Deposit/Withdraw amounts
                let depFmt, wdFmt;
                if (item.hasBreakdown) {
                    depFmt = item.totalDeposited > 0n ? earn_formatAmount(item.totalDeposited, item.decimals, item.symbol) : '—';
                    wdFmt = item.totalWithdrawn > 0n ? earn_formatAmount(item.totalWithdrawn, item.decimals, item.symbol) : '—';
                } else {
                    // Old format — no d/w breakdown, show net flow
                    const absNet = item.netFlow < 0n ? -item.netFlow : item.netFlow;
                    const netFmt = earn_formatAmount(absNet, item.decimals, item.symbol);
                    if (item.netFlow > 0n) {
                        depFmt = '≥' + netFmt;
                        wdFmt = '—';
                    } else if (item.netFlow < 0n) {
                        depFmt = '—';
                        wdFmt = '≥' + netFmt;
                    } else {
                        depFmt = '—';
                        wdFmt = '—';
                    }
                }

                // Yield display
                const yieldPositive = item.yieldWei >= 0n;
                const yieldSign = yieldPositive && item.yieldWei > 0n ? '+' : '';
                const yieldColor = yieldPositive ? 'earn-yield-positive' : 'earn-yield-negative';
                const yieldFmt = earn_formatAmount(item.yieldWei, item.decimals, item.symbol);

                // For closed isolation positions with negative yield, show "Position Closed"
                const isClosedIsolation = item.isIsolation && !item.isActive && item.yieldWei < 0n;

                let yieldHtml;
                if (isClosedIsolation) {
                    yieldHtml = `<span class="earn-amount" style="color:var(--text-muted);font-size:13px" data-tip="This was an isolation mode wrapper token used as collateral. The position has been fully closed.">Position Closed</span>`;
                } else if (item.yieldTrustedForDisplay) {
                    const yieldUsdFmt = item.yieldUsd !== 0
                        ? `<div style="font-size:11px;color:var(--text-muted);margin-top:2px">${item.yieldUsd > 0 ? '+' : item.yieldUsd < 0 ? '-' : ''}$${Math.abs(item.yieldUsd).toFixed(2)}</div>`
                        : '';
                    yieldHtml = `<span class="earn-amount ${yieldColor}">${yieldSign}${yieldFmt}<span class="earn-amount-sym">${item.symbol}</span></span>${yieldUsdFmt}`;
                } else {
                    yieldHtml = '<span class="earn-amount" style="color:var(--text-muted)">—</span>';
                }

                // Explorer link for this token
                const explorerUrl = `${explorerBase}/address/${item.tokenAddr}`;
                // Use hist-row/hist-detail IDs to avoid colliding with active earn IDs
                const rowId = `earn-hist-row-${idx}`;
                const detailId = `earn-hist-detail-${idx}`;

                // Subtitle: show full token name for isolation tokens
                const subtitle = item.isIsolation && item.tokenName !== item.symbol
                    ? `<div style="font-size:10px;color:var(--text-muted);margin-top:1px;max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" data-tip="${earn_escapeHtml(item.tokenName)}">${earn_escapeHtml(item.tokenName.replace('Dolomite Isolation: ', '').replace('Dolomite: Fee + Staked ', ''))}</div>`
                    : '';

                html += `<tr class="earn-data-row" id="${rowId}" style="animation-delay:${delay}s">
                    <td>
                        <div class="earn-token-cell">
                            <div class="earn-token-left">
                                ${iconHtml}
                                <div class="earn-token-info">
                                    <div class="earn-token-name">${item.symbol}</div>
                                    ${subtitle}
                                    <div style="margin-top:3px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">${badge}${verifyBadge}</div>
                                </div>
                            </div>
                        </div>
                    </td>
                    <td><span class="earn-amount">${depFmt}<span class="earn-amount-sym">${item.symbol}</span></span></td>
                    <td><span class="earn-amount">${wdFmt}<span class="earn-amount-sym">${item.symbol}</span></span></td>
                    <td>
                        ${yieldHtml}
                    </td>
                </tr>`;

            });

            if (html === '') {
                html = '<tr><td colspan="4" style="text-align:center;padding:40px;color:var(--text-muted)">No history data found</td></tr>';
            }
            tbody.innerHTML = html;
        }

        // Fetch USD prices from DeFiLlama (free, no API key, CORS-friendly)
        let earn_priceCache = {}; // { 'chainId:addr' : usdPrice }
        async function earn_fetchCoinGeckoPrices(tokenAddrs) {
            const chain = earn_getChain();
            const chainId = document.getElementById('earn-chain').value;
            const llamaPlatform = chain.llamaPlatform;
            if (!llamaPlatform) {
                console.warn('No DeFiLlama platform for chain:', chainId);
                return;
            }
            try {
                const deduped = Array.from(new Set(
                    (tokenAddrs || [])
                        .map(a => String(a || '').toLowerCase())
                        .filter(Boolean)
                ));
                const missing = deduped.filter(addr => !earn_priceCache[chainId + ':' + addr]);
                if (missing.length === 0) return;
                // DeFiLlama accepts comma-separated "chain:address" pairs
                const coins = missing.map(a => `${llamaPlatform}:${a}`).join(',');
                const url = `https://coins.llama.fi/prices/current/${coins}`;
                const ctrl = new AbortController();
                const timer = setTimeout(() => ctrl.abort(), 8000);
                const resp = await fetch(url, { signal: ctrl.signal });
                clearTimeout(timer);
                if (!resp.ok) return;
                const data = await resp.json();
                let count = 0;
                for (const [key, info] of Object.entries(data.coins || {})) {
                    if (info && info.price) {
                        // Extract address from "chain:addr" format
                        const addr = key.split(':')[1];
                        earn_priceCache[chainId + ':' + addr.toLowerCase()] = info.price;
                        count++;
                    }
                }
                console.log(`DeFiLlama prices loaded: ${count}/${missing.length} missing tokens (${llamaPlatform})`);
            } catch (e) {
                console.warn('DeFiLlama price fetch failed, using fallback:', e.message);
            }
        }

        function earn_formatAmount(value, decimals, symbol) {
            if (typeof value !== 'bigint') value = BigInt(value);
            const isNeg = value < 0n;
            const abs = isNeg ? -value : value;
            const scale = earn_getPow10(decimals);
            const whole = abs / scale;
            const frac = abs % scale;
            const fracStr = frac.toString().padStart(decimals, '0');

            // Stablecoins: 1 decimal; others: 6 decimals
            const STABLES = new Set(['USDC', 'USDT', 'USDC.e', 'DAI', 'USDe', 'sUSDe', 'USD0', 'USD0++', 'deUSD', 'sdeUSD', 'HONEY', 'NECT', 'USDbC', 'FRAX', 'LUSD', 'crvUSD', 'GHO', 'USDS', 'sUSDS', 'USD1', 'stcUSD', 'cUSD']);
            const fracLen = STABLES.has(symbol) ? 1 : 6;
            const fracDisplay = fracStr.slice(0, fracLen).padEnd(fracLen, '0');

            const wholeStr = whole.toLocaleString('en-US');
            const result = `${wholeStr}.${fracDisplay}`;
            return isNeg ? '-' + result : result;
        }

        function earn_formatAmountOneDecimal(value, decimals) {
            const amount = typeof value === 'bigint' ? value : BigInt(value || 0);
            const negative = amount < 0n;
            const abs = negative ? -amount : amount;
            const scale = earn_getPow10(decimals);
            const tenths = (abs * 10n + (scale / 2n)) / scale;
            const whole = tenths / 10n;
            const fraction = tenths % 10n;
            return `${negative ? '-' : ''}${whole.toLocaleString('en-US')}.${fraction.toString()}`;
        }

        const EARN_USD_SCALE_DECIMALS = 8;
        const EARN_USD_SCALE = 10n ** BigInt(EARN_USD_SCALE_DECIMALS);
        const earn_pow10Cache = { 0: 1n, [EARN_USD_SCALE_DECIMALS]: EARN_USD_SCALE };

        function earn_getPow10(decimals) {
            const safeDecimals = Math.max(0, Number(decimals || 0));
            if (!Object.prototype.hasOwnProperty.call(earn_pow10Cache, safeDecimals)) {
                earn_pow10Cache[safeDecimals] = 10n ** BigInt(safeDecimals);
            }
            return earn_pow10Cache[safeDecimals];
        }

        function earn_bigIntToDecimalString(value, decimals, trimTrailingZeros) {
            const amount = typeof value === 'bigint' ? value : BigInt(value || '0');
            const safeDecimals = Math.max(0, Number(decimals || 0));
            const negative = amount < 0n;
            const abs = negative ? -amount : amount;
            const scale = earn_getPow10(safeDecimals);
            const whole = abs / scale;
            const frac = abs % scale;
            if (safeDecimals === 0) {
                return `${negative ? '-' : ''}${whole.toString()}`;
            }
            let fracStr = frac.toString().padStart(safeDecimals, '0');
            if (trimTrailingZeros) fracStr = fracStr.replace(/0+$/, '');
            return `${negative ? '-' : ''}${whole.toString()}${fracStr ? '.' + fracStr : ''}`;
        }

        function earn_bigIntToDecimalNumber(value, decimals) {
            return Number(earn_bigIntToDecimalString(value, decimals, true));
        }

        function earn_getUsdPrice(symbol, tokenAddr, chainId) {
            const cid = chainId || document.getElementById('earn-chain')?.value || 'ethereum';
            const priceKey = cid + ':' + ((tokenAddr || '').toLowerCase());
            return earn_priceCache[priceKey] || TOKEN_USD_FALLBACK[symbol] || 0;
        }

        function earn_formatMarketPrice(price) {
            const value = Number(price || 0);
            if (!Number.isFinite(value) || value <= 0) return '—';
            if (value >= 1000) return '$' + value.toLocaleString('en-US', { maximumFractionDigits: 0 });
            if (value >= 1) return '$' + value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
            return '$' + value.toLocaleString('en-US', { minimumFractionDigits: 4, maximumFractionDigits: 4 });
        }

        function earn_getUsdValueScaled(amountWei, decimals, price) {
            const amount = typeof amountWei === 'bigint' ? amountWei : BigInt(amountWei || '0');
            if (!amount || !price) return 0n;
            const tokenScale = earn_getPow10(decimals);
            const priceScaled = earn_decimalToBigInt(String(price || 0), EARN_USD_SCALE_DECIMALS);
            if (!priceScaled) return 0n;
            return (amount * priceScaled) / tokenScale;
        }

        function earn_getTokenUsdScaled(amountWei, decimals, symbol, tokenAddr, chainId) {
            return earn_getUsdValueScaled(amountWei, decimals, earn_getUsdPrice(symbol, tokenAddr, chainId));
        }

        function earn_scaledUsdToNumber(value) {
            return earn_bigIntToDecimalNumber(value, EARN_USD_SCALE_DECIMALS);
        }

        function earn_compareBigInt(a, b) {
            const left = typeof a === 'bigint' ? a : BigInt(a || '0');
            const right = typeof b === 'bigint' ? b : BigInt(b || '0');
            if (left === right) return 0;
            return left > right ? 1 : -1;
        }

        function earn_absUsdScaled(value) {
            return earn_absBigInt(typeof value === 'bigint' ? value : BigInt(value || '0'));
        }

        function earn_isSubDollarYieldPair(balanceUsdScaled, yieldUsdScaled) {
            return earn_absUsdScaled(balanceUsdScaled) < EARN_USD_SCALE
                && earn_absUsdScaled(yieldUsdScaled) < EARN_USD_SCALE;
        }

        function earn_decimalToBigInt(value, decimals) {
            const suppliedPlaces = Number(decimals || 0);
            const places = Number.isSafeInteger(suppliedPlaces) && suppliedPlaces >= 0 && suppliedPlaces <= 512
                ? suppliedPlaces
                : 0;
            let raw = String(value ?? '0').trim();
            if (!raw) return 0n;
            let negative = false;
            if (raw[0] === '+' || raw[0] === '-') {
                negative = raw[0] === '-';
                raw = raw.slice(1);
            }
            if (!raw) return 0n;
            const match = raw.match(/^(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/);
            if (!match) return 0n;

            const wholeDigits = match[1] || '';
            const fractionalDigits = match[2] || '';
            if (!wholeDigits && !fractionalDigits) return 0n;

            const exponent = match[3] === undefined ? 0 : Number(match[3]);
            if (!Number.isSafeInteger(exponent) || Math.abs(exponent) > 512) return 0n;

            const significantDigits = (wholeDigits + fractionalDigits).replace(/^0+/, '') || '0';
            const shift = places + exponent - fractionalDigits.length;
            if (shift > 512 || shift < -significantDigits.length) return 0n;

            const significant = BigInt(significantDigits);
            const result = shift >= 0
                ? significant * (10n ** BigInt(shift))
                : significant / (10n ** BigInt(-shift));
            return negative ? -result : result;
        }

        function earn_absBigInt(value) {
            return value < 0n ? -value : value;
        }

        function earn_getReplayPositionMode(par, accountHasBorrow) {
            if (par < 0n) return 'borrow';
            if (par > 0n && accountHasBorrow) return 'collateral';
            if (par > 0n) return 'earn';
            return 'flat';
        }

        function earn_addSettledYield(state, amount, positionPar) {
            const settled = BigInt(amount || 0n);
            const par = BigInt(positionPar || 0n);
            if (settled === 0n || par === 0n) return 0n;
            state.settledYield = BigInt(state.settledYield || 0n) + settled;
            state.settledSupplyYield = BigInt(state.settledSupplyYield || 0n);
            state.settledBorrowYield = BigInt(state.settledBorrowYield || 0n);
            if (par > 0n) state.settledSupplyYield += settled;
            if (par < 0n) state.settledBorrowYield += settled;
            return settled;
        }

        function earn_settleReducedExposureYield(state, nextPar) {
            const prevPar = BigInt(state && state.par ? state.par : 0n);
            const next = BigInt(nextPar || 0n);
            if (prevPar === 0n || state.liveYield === 0n) return 0n;

            if (prevPar > 0n && next >= 0n && next < prevPar) {
                const reducedPar = prevPar - next;
                const realizedYield = (state.liveYield * reducedPar) / prevPar;
                earn_addSettledYield(state, realizedYield, prevPar);
                state.liveYield -= realizedYield;
                return realizedYield;
            }

            if (prevPar < 0n && next <= 0n) {
                const prevDebt = -prevPar;
                const nextDebt = -next;
                if (nextDebt < prevDebt && prevDebt > 0n) {
                    const reducedDebt = prevDebt - nextDebt;
                    const realizedYield = (state.liveYield * reducedDebt) / prevDebt;
                    earn_addSettledYield(state, realizedYield, prevPar);
                    state.liveYield -= realizedYield;
                    return realizedYield;
                }
            }

            return 0n;
        }

        function earn_getVerification(mid) {
            return earn_replayVerificationData ? (earn_replayVerificationData[String(mid)] || null) : null;
        }

        function earn_getAlignedReplayWeiDriftAdjustment(entry) {
            if (!entry || entry.snapshotIncomplete || !entry.counted) return null;
            if (earn_absBigInt(entry.supplyParDiff) > entry.parTolerance) return null;
            if (earn_absBigInt(entry.collateralParDiff) > entry.parTolerance) return null;
            if (earn_absBigInt(entry.borrowParDiff) > entry.parTolerance) return null;

            const supplyExposureAligned = (entry.actualSupplyPar > 0n) === (entry.expectedSupplyPar > 0n);
            const collateralExposureAligned = (entry.actualCollateralPar > 0n) === (entry.expectedCollateralPar > 0n);
            const borrowExposureAligned = (entry.actualBorrowPar > 0n) === (entry.expectedBorrowPar > 0n);
            if (!supplyExposureAligned || !collateralExposureAligned || !borrowExposureAligned) return null;

            if (entry.actualSupplyPar === 0n && entry.expectedSupplyPar === 0n && entry.supplyWeiDiff !== 0n) return null;
            if (entry.actualCollateralPar === 0n && entry.expectedCollateralPar === 0n && entry.collateralWeiDiff !== 0n) return null;
            if (entry.actualBorrowPar === 0n && entry.expectedBorrowPar === 0n && entry.borrowWeiDiff !== 0n) return null;

            const totalYieldCorrection = entry.supplyWeiDiff + entry.collateralWeiDiff - entry.borrowWeiDiff;
            if (totalYieldCorrection === 0n) return null;

            return {
                totalYieldCorrection,
                supplyYieldCorrection: entry.supplyWeiDiff,
                collateralYieldCorrection: entry.collateralWeiDiff,
                borrowYieldCorrection: -entry.borrowWeiDiff,
            };
        }

        function earn_getStrictVerificationStatus(entry) {
            if (!entry || !entry.counted) return 'unverified';
            if (!entry.canVerify) return 'coverage_incomplete';
            if (entry.snapshotIncomplete || entry.subgraphReplayTruncated || entry.replayStateAdjusted) {
                return 'coverage_incomplete';
            }
            if (entry.rawVerified) {
                return 'verified';
            }
            return 'mismatch';
        }

        function earn_shouldHideGhostCurrentMarket(entry) {
            if (!entry || !entry.snapshotIncomplete || !entry.counted) return false;
            const actualAnyExposure = entry.actualSupplyPar > 0n
                || entry.actualSupplyWei > 0n
                || entry.actualCollateralPar > 0n
                || entry.actualCollateralWei > 0n
                || entry.actualBorrowPar > 0n
                || entry.actualBorrowWei > 0n;
            if (actualAnyExposure) return false;
            const expectedAnyExposure = entry.expectedSupplyPar > 0n
                || entry.expectedSupplyWei > 0n
                || entry.expectedCollateralPar > 0n
                || entry.expectedCollateralWei > 0n
                || entry.expectedBorrowPar > 0n
                || entry.expectedBorrowWei > 0n;
            return expectedAnyExposure;
        }

        function earn_getSnapshotLedgerPresentation(marketId, yieldCalc) {
            const hist = earn_totalYieldData ? earn_totalYieldData[String(marketId)] : null;
            if (!hist || !yieldCalc || !yieldCalc.hasData) return null;
            const method = String(yieldCalc.method || '');
            const publicLedgerMethod = method === 'all-netflow-verified'
                || method === 'all-netflow-pre-snapshot-carry'
                || method === 'recent-cycle-verified'
                || method === 'recent-cycle-pre-snapshot-carry';
            if (method !== 'snapshot' && method !== 'snapshot-partial' && !publicLedgerMethod) return null;
            if (hist.isLatestSnapshot === false) return null;
            const flowMeta = earn_parseNetflowEntry(earn_netflowData && earn_netflowData[String(marketId)]);
            const source = String(hist.source || '');
            const status = String(hist.verificationStatus || '').toLowerCase();
            const rawStatus = String(
                hist.rawVerificationStatus !== undefined
                    ? hist.rawVerificationStatus
                    : hist.verificationStatus || ''
            ).toLowerCase();
            const canonicalHistoryCoverageStatus = String(hist.canonicalHistoryCoverageStatus || '').toLowerCase();
            if (publicLedgerMethod && yieldCalc.publicLedgerInference) {
                const inferred = yieldCalc.publicLedgerInference;
                if (inferred.status === 'verified') {
                    return {
                        counted: true,
                        status: 'inferred',
                        label: 'Inferred',
                        title: 'Public netflow reconciles cleanly with historical snapshot data and fresh canonical subaccount history for this market. This is strong historical evidence, but not strict replay verification.',
                        rawStatus: inferred.status,
                        rawLabel: 'Netflow Match',
                        rawTitle: 'Public netflow and snapshot history reconcile exactly for this market.',
                        overridden: true,
                        entry: null,
                    };
                }
                return {
                    counted: true,
                    status: 'inferred',
                    label: inferred.status === 'pre_snapshot_carry' ? 'Inferred Carry' : 'Inferred',
                    title: inferred.status === 'pre_snapshot_carry'
                        ? 'This market can be inferred from public netflow plus snapshot history, but it is not treated as strict verification because part of the carry predates local coverage.'
                        : 'This market can be inferred from public netflow plus snapshot history, but it is not treated as strict verification.',
                    rawStatus: inferred.status,
                    rawLabel: inferred.status === 'pre_snapshot_carry' ? 'Pre-Snapshot Carry' : 'Verified',
                    rawTitle: inferred.status === 'pre_snapshot_carry'
                        ? 'Public netflow indicates older carry existed before local snapshot coverage began.'
                        : 'Public netflow reconciles cleanly with snapshot history.',
                    overridden: true,
                    entry: null,
                };
            }
            const snapshotOnly = rawStatus === 'no_netflow' || (!flowMeta && (source === 'verified-ledger' || source === 'snapshot-series' || !source));
            if (status === 'inferred' || rawStatus === 'pre_snapshot_carry') {
                const isPreSnapshotCarry = rawStatus === 'pre_snapshot_carry';
                return {
                    counted: true,
                    status: 'inferred',
                    label: isPreSnapshotCarry ? 'Inferred Carry' : 'Inferred',
                    title: isPreSnapshotCarry
                        ? 'Historical snapshot data suggests older carry existed before local coverage began. This is useful evidence, but not strict replay verification.'
                        : 'Snapshot and public netflow reconcile for this market, but principal can change between snapshots, so this remains historical evidence rather than strict replay verification.',
                    rawStatus: rawStatus || status,
                    rawLabel: isPreSnapshotCarry ? 'Pre-Snapshot Carry' : 'Netflow Match',
                    rawTitle: isPreSnapshotCarry
                        ? 'Replay yield includes carry accrued before the first locally captured snapshot for this market.'
                        : 'Snapshot and public netflow reconcile, but strict verification still requires replay-grade evidence.',
                    overridden: true,
                    entry: null,
                };
            }
            if (status === 'coverage_incomplete' && canonicalHistoryCoverageStatus && canonicalHistoryCoverageStatus !== 'fresh') {
                return {
                    counted: true,
                    status: 'coverage_incomplete',
                    label: 'Coverage Incomplete',
                    title: 'Historical ledger data exists, but canonical subaccount history is not fresh enough for strict replay-grade verification at this block.',
                    rawStatus: rawStatus || status,
                    rawLabel: 'Coverage Incomplete',
                    rawTitle: 'Canonical subaccount history is missing or stale for this market/address.',
                    overridden: true,
                    entry: null,
                };
            }
            if (snapshotOnly) {
                return {
                    counted: true,
                    status: 'snapshot',
                    label: 'SNAPSHOT ONLY',
                    title: 'Historical netflow/replay coverage is unavailable for this market, so yield is derived from the latest snapshot series only. Treat this as not fully verified.',
                    rawStatus: rawStatus || status || 'no_netflow',
                    rawLabel: 'Snapshot Only',
                    rawTitle: 'Historical netflow/replay coverage is unavailable for this market.',
                    overridden: true,
                    entry: null,
                };
            }
            return null;
        }

        function earn_getInterestLedgerTrust(mid, opts) {
            opts = opts || {};
            const requireVerifiedInterest = opts.requireVerifiedInterest !== false;
            const entry = earn_getVerification(mid);
            const strictStatus = earn_getStrictVerificationStatus(entry);
            if (!requireVerifiedInterest) {
                return {
                    trusted: true,
                    status: entry ? strictStatus : 'unchecked',
                    entry,
                };
            }
            if (!earn_replayVerificationReady && earn_interestYieldData && earn_interestYieldData[String(mid)] && earn_interestYieldData[String(mid)].earnYield !== undefined) {
                return {
                    trusted: false,
                    status: 'pending',
                    entry,
                };
            }
            if (!entry || !entry.counted) {
                return {
                    trusted: false,
                    status: 'unverified',
                    entry,
                };
            }
            return {
                trusted: strictStatus === 'verified',
                status: strictStatus,
                entry,
            };
        }

        function earn_hasSufficientSnapshotHistory(hist) {
            if (!hist) return false;
            if (String(hist.source || '') === 'verified-ledger') return true;
            const snapshotCount = Number(hist.snapshotCount || 0);
            if (snapshotCount >= 2) return true;
            const firstDate = String(hist.firstDate || '');
            const lastDate = String(hist.lastDate || '');
            return !!(firstDate && lastDate && firstDate !== lastDate);
        }

        function earn_getHistoricalYieldTolerance(decimals) {
            const safeDecimals = Math.max(0, Number(decimals || 18));
            return 10n ** BigInt(Math.max(0, safeDecimals - 12));
        }

        function earn_getPreSnapshotResidualTolerance(decimals) {
            const base = earn_getHistoricalYieldTolerance(decimals);
            return base * 4n > 1n ? base * 4n : 1n;
        }

        function earn_getPreSnapshotCarryMeta(snapshotYield, diff, firstPar, firstWei, lastPar, lastWei, baselineNetflow, decimals, hasStaticParWindow) {
            if (snapshotYield === null || diff === null) return null;
            if (firstPar <= 0n || firstWei < baselineNetflow) return null;

            const carry = firstWei - baselineNetflow;
            if (carry < 0n) return null;

            const residual = diff - carry;
            const postSnapshotDelta = lastWei - firstWei;
            const exactPostSnapshotWindow = snapshotYield === postSnapshotDelta;
            if (hasStaticParWindow && exactPostSnapshotWindow) {
                return {
                    carry,
                    residual,
                    tinyParDriftWindow: false,
                    windowType: 'exact_post_snapshot_window',
                };
            }

            const parDrift = lastPar > firstPar ? (lastPar - firstPar) : (firstPar - lastPar);
            if (parDrift > earn_getHistoricalYieldTolerance(decimals)) return null;
            if (postSnapshotDelta < 0n || snapshotYield < 0n) return null;
            if (earn_absBigInt(residual) > earn_getPreSnapshotResidualTolerance(decimals)) return null;

            return {
                carry,
                residual,
                tinyParDriftWindow: true,
                windowType: 'tiny_par_drift_window',
            };
        }

        function earn_buildPublicLedgerBaseline(name, baselineNetflow, snapshotYield, firstPar, firstWei, lastPar, lastWei, decimals, hasStaticParWindow) {
            if (snapshotYield === null || baselineNetflow === null) return null;
            const baselineYield = lastWei - baselineNetflow;
            const diff = baselineYield - snapshotYield;
            return {
                name,
                yield: baselineYield,
                diff,
                preSnapshotMeta: earn_getPreSnapshotCarryMeta(
                    snapshotYield,
                    diff,
                    firstPar,
                    firstWei,
                    lastPar,
                    lastWei,
                    baselineNetflow,
                    decimals,
                    hasStaticParWindow
                ),
            };
        }

        function earn_chooseBestPublicLedgerBaseline(baselines, decimals) {
            const tolerance = earn_getHistoricalYieldTolerance(decimals);
            const exact = [];
            const carry = [];
            for (const candidate of baselines) {
                if (!candidate) continue;
                if (earn_absBigInt(candidate.diff) <= tolerance) {
                    exact.push(candidate);
                    continue;
                }
                if (candidate.preSnapshotMeta) carry.push(candidate);
            }
            if (exact.length > 0) {
                exact.sort((left, right) => {
                    const leftDiff = earn_absBigInt(left.diff);
                    const rightDiff = earn_absBigInt(right.diff);
                    if (leftDiff !== rightDiff) return leftDiff < rightDiff ? -1 : 1;
                    return left.name === 'recent-cycle' ? -1 : 1;
                });
                return exact[0];
            }
            if (carry.length > 0) {
                carry.sort((left, right) => {
                    const leftTiny = left.preSnapshotMeta && left.preSnapshotMeta.tinyParDriftWindow ? 1 : 0;
                    const rightTiny = right.preSnapshotMeta && right.preSnapshotMeta.tinyParDriftWindow ? 1 : 0;
                    if (leftTiny !== rightTiny) return leftTiny - rightTiny;
                    const leftResidual = earn_absBigInt(left.preSnapshotMeta.residual);
                    const rightResidual = earn_absBigInt(right.preSnapshotMeta.residual);
                    if (leftResidual !== rightResidual) return leftResidual < rightResidual ? -1 : 1;
                    return left.name === 'recent-cycle' ? -1 : 1;
                });
                return carry[0];
            }
            return null;
        }

        function earn_getPublicLedgerInference(hist, flowMeta, decimals) {
            if (!hist || !flowMeta || !earn_hasSufficientSnapshotHistory(hist)) return null;

            const snapshotYield = hist.cumulativeYield !== undefined ? BigInt(hist.cumulativeYield || '0') : null;
            const firstPar = BigInt(hist.firstPar || '0');
            const firstWei = BigInt(hist.firstWei || '0');
            const lastPar = BigInt(hist.lastPar || '0');
            const lastWei = BigInt(hist.lastWei || '0');
            const hasStaticParWindow = !!hist.hasStaticParWindow;
            if (snapshotYield === null || lastWei < 0n) return null;

            const baselines = [
                earn_buildPublicLedgerBaseline(
                    'all-time-netflow',
                    flowMeta.netFlow,
                    snapshotYield,
                    firstPar,
                    firstWei,
                    lastPar,
                    lastWei,
                    decimals,
                    hasStaticParWindow
                )
            ];
            if (flowMeta.recentCycleNetFlow !== null) {
                baselines.push(
                    earn_buildPublicLedgerBaseline(
                        'recent-cycle',
                        flowMeta.recentCycleNetFlow,
                        snapshotYield,
                        firstPar,
                        firstWei,
                        lastPar,
                        lastWei,
                        decimals,
                        hasStaticParWindow
                    )
                );
            }

            const chosen = earn_chooseBestPublicLedgerBaseline(baselines, decimals);
            if (!chosen) return null;

            if (earn_absBigInt(chosen.diff) <= earn_getHistoricalYieldTolerance(decimals)) {
                return {
                    status: 'verified',
                    verificationBaseline: chosen.name,
                    canonicalYield: chosen.yield,
                };
            }
            if (chosen.preSnapshotMeta) {
                return {
                    status: 'pre_snapshot_carry',
                    verificationBaseline: chosen.name,
                    canonicalYield: chosen.yield,
                    preSnapshotCarry: chosen.preSnapshotMeta.carry,
                    preSnapshotResidual: chosen.preSnapshotMeta.residual,
                    preSnapshotWindowType: chosen.preSnapshotMeta.windowType || '',
                    hasTinyParDriftWindow: !!chosen.preSnapshotMeta.tinyParDriftWindow,
                };
            }
            return null;
        }

        function earn_shouldHoldActiveYieldForReplaySettlement(opts) {
            opts = opts || {};
            if (opts.requireVerifiedInterest === false) return false;
            if (!opts.isActivePosition) return false;
            const publicInferenceStatus = String((opts.publicLedgerInference && opts.publicLedgerInference.status) || '');
            if (opts.publicLedgerInference && publicInferenceStatus !== 'pre_snapshot_carry') return false;
            if (opts.canUseVerifiedInterest || opts.canOverrideMismatchedSnapshot) return false;

            const replayStillLoading = earn_replayStatus === 'loading' || earn_replayStatus === 'idle';
            if (!replayStillLoading) return false;

            const hasPotentialFallbackSource = !!(
                opts.hasSnapshotData ||
                opts.hasAllNetflow ||
                opts.hasAcct0Netflow ||
                opts.hasInterestYield ||
                opts.snapshotTrusted
            );
            if (!hasPotentialFallbackSource) return false;

            return true;
        }

        function earn_getResolvedTotalYieldSource(method, rawSource) {
            const normalizedMethod = String(method || '');
            const fallbackSource = String(rawSource || '');
            switch (normalizedMethod) {
                case 'interest-ledger':
                case 'interest-ledger-live-balance-adjusted':
                case 'interest-ledger-override':
                case 'interest-ledger-pending':
                case 'interest-ledger-unverified':
                    return 'replay-ledger';
                case 'all-netflow-verified':
                case 'all-netflow-pre-snapshot-carry':
                    return 'public-netflow';
                case 'recent-cycle-verified':
                case 'recent-cycle-pre-snapshot-carry':
                    return 'public-cycle';
                case 'all-netflow':
                case 'all-netflow-guarded':
                    return 'netflow-fallback';
                case 'recent-cycle':
                    return 'cycle-fallback';
                case 'acct0-netflow':
                    return 'acct0-fallback';
                default:
                    return fallbackSource || 'snapshot-series';
            }
        }

        function earn_isTrustedReplayYieldMethod(method) {
            return method === 'interest-ledger'
                || method === 'interest-ledger-override';
        }

        function earn_isTrustedReplayYieldStatus(status) {
            return status === 'verified';
        }

        function earn_isTrustedInterestLedgerYieldCalc(yieldCalc) {
            if (!yieldCalc || !yieldCalc.hasData || !yieldCalc.trustedForTotal) return false;
            if (!earn_isTrustedReplayYieldStatus(String(yieldCalc.verificationStatus || ''))) return false;
            const method = String(yieldCalc.method || '');
            return earn_isTrustedReplayYieldMethod(method);
        }

        function earn_buildResolvedTotalYieldEntry(marketId, yieldCalc) {
            const hist = earn_totalYieldData ? earn_totalYieldData[String(marketId)] : null;
            if (!hist && (!yieldCalc || !yieldCalc.hasData)) return null;

            const rawSource = hist ? String(hist.rawSource !== undefined ? hist.rawSource : (hist.source || '')) : '';
            const rawMethod = hist ? String(hist.rawMethod !== undefined ? hist.rawMethod : (hist.method || '')) : '';
            const rawVerificationStatus = hist ? String(hist.rawVerificationStatus !== undefined ? hist.rawVerificationStatus : (hist.verificationStatus || '')) : '';
            const rawCumulativeYield = hist ? String(hist.rawCumulativeYield !== undefined ? hist.rawCumulativeYield : (hist.cumulativeYield || '0')) : '0';

            let resolvedSource = hist ? String(hist.resolvedSource !== undefined ? hist.resolvedSource : rawSource) : rawSource;
            let resolvedMethod = hist ? String(hist.resolvedMethod !== undefined ? hist.resolvedMethod : rawMethod) : rawMethod;
            let resolvedVerificationStatus = hist ? String(hist.resolvedVerificationStatus !== undefined ? hist.resolvedVerificationStatus : rawVerificationStatus) : rawVerificationStatus;
            let resolvedCumulativeYield = hist ? String(hist.resolvedCumulativeYield !== undefined ? hist.resolvedCumulativeYield : rawCumulativeYield) : rawCumulativeYield;
            let resolvedTrustedForTotal = hist ? !!hist.resolvedTrustedForTotal : false;
            let resolvedCanonicalHistoryCoverageStatus = String(
                hist
                    ? (hist.resolvedCanonicalHistoryCoverageStatus !== undefined
                        ? hist.resolvedCanonicalHistoryCoverageStatus
                        : (hist.canonicalHistoryCoverageStatus || ''))
                    : ''
            );
            let resolvedCanonicalHistoryLastScannedBlock =
                hist
                    ? (hist.resolvedCanonicalHistoryLastScannedBlock !== undefined
                        ? hist.resolvedCanonicalHistoryLastScannedBlock
                        : (hist.canonicalHistoryLastScannedBlock !== undefined ? hist.canonicalHistoryLastScannedBlock : null))
                    : null;
            let resolvedCanonicalHistoryFreshForBorrowRouting =
                hist
                    ? (hist.resolvedCanonicalHistoryFreshForBorrowRouting !== undefined
                        ? !!hist.resolvedCanonicalHistoryFreshForBorrowRouting
                        : !!hist.canonicalHistoryFreshForBorrowRouting)
                    : false;

            if (yieldCalc && yieldCalc.hasData) {
                resolvedMethod = String(yieldCalc.method || resolvedMethod);
                resolvedSource = earn_getResolvedTotalYieldSource(resolvedMethod, rawSource);
                resolvedCumulativeYield = String(yieldCalc.totalYield || '0');
                resolvedTrustedForTotal = earn_isTrustedInterestLedgerYieldCalc(yieldCalc);
                resolvedCanonicalHistoryCoverageStatus = String(
                    yieldCalc.canonicalHistoryCoverageStatus || resolvedCanonicalHistoryCoverageStatus
                );
                resolvedCanonicalHistoryLastScannedBlock =
                    yieldCalc.canonicalHistoryLastScannedBlock !== undefined
                        ? yieldCalc.canonicalHistoryLastScannedBlock
                        : resolvedCanonicalHistoryLastScannedBlock;
                resolvedCanonicalHistoryFreshForBorrowRouting =
                    yieldCalc.canonicalHistoryFreshForBorrowRouting !== undefined
                        ? !!yieldCalc.canonicalHistoryFreshForBorrowRouting
                        : resolvedCanonicalHistoryFreshForBorrowRouting;

                if (yieldCalc.verificationStatus) {
                    resolvedVerificationStatus = String(yieldCalc.verificationStatus || resolvedVerificationStatus);
                }
            }

            return {
                ...(hist || {}),
                rawSource,
                rawMethod,
                rawVerificationStatus,
                rawCumulativeYield,
                resolvedSource,
                resolvedMethod,
                resolvedVerificationStatus,
                resolvedCumulativeYield,
                resolvedTrustedForTotal,
                resolvedCanonicalHistoryCoverageStatus,
                resolvedCanonicalHistoryLastScannedBlock,
                resolvedCanonicalHistoryFreshForBorrowRouting,
            };
        }

        function earn_getResolvedTotalYieldEntry(marketId) {
            const key = String(marketId);
            if (earn_resolvedTotalYieldData && earn_resolvedTotalYieldData[key]) {
                return earn_resolvedTotalYieldData[key];
            }
            return earn_buildResolvedTotalYieldEntry(key, null);
        }

        function earn_refreshResolvedTotalYieldData() {
            if (!earn_totalYieldData || typeof earn_totalYieldData !== 'object') {
                earn_resolvedTotalYieldData = {};
                return;
            }

            const nextResolved = {};
            Object.keys(earn_totalYieldData).forEach(mid => {
                const resolved = earn_buildResolvedTotalYieldEntry(mid, null);
                if (resolved) nextResolved[String(mid)] = resolved;
            });

            const activeMarketIds = new Set();
            (earn_cachedAssets || []).forEach(position => {
                if (!position || position.isBorrow || position.isCollateral) return;
                const mid = String(position.marketId);
                activeMarketIds.add(mid);
                if (!nextResolved[mid]) return;
                const resolved = earn_buildResolvedTotalYieldEntry(mid, earn_calculateYield(position));
                if (resolved) nextResolved[mid] = resolved;
            });

            (earn_collateralPositionData || []).forEach(position => {
                if (!position) return;
                const mid = String(position.marketId);
                activeMarketIds.add(mid);
                if (!nextResolved[mid]) return;
                const resolved = earn_buildResolvedTotalYieldEntry(mid, earn_calculateYield(position));
                if (resolved) nextResolved[mid] = resolved;
            });

            (earn_historyData || []).forEach(item => {
                if (!item) return;
                const mid = String(item.marketId);
                if (activeMarketIds.has(mid)) return;
                const resolved = earn_buildResolvedTotalYieldEntry(mid, earn_calculateYield({
                    marketId: item.marketId,
                    tokenAddr: item.tokenAddr,
                    symbol: item.symbol,
                    decimals: item.decimals,
                    currentWei: item.currentWei,
                    currentPar: item.currentPar,
                }, { applyHistoryGuards: true }));
                if (resolved) nextResolved[mid] = resolved;
            });

            earn_resolvedTotalYieldData = nextResolved;
            Object.keys(nextResolved).forEach(mid => {
                if (!earn_totalYieldData[mid]) return;
                earn_totalYieldData[mid] = {
                    ...earn_totalYieldData[mid],
                    rawSource: nextResolved[mid].rawSource,
                    rawMethod: nextResolved[mid].rawMethod,
                    rawVerificationStatus: nextResolved[mid].rawVerificationStatus,
                    rawCumulativeYield: nextResolved[mid].rawCumulativeYield,
                    resolvedSource: nextResolved[mid].resolvedSource,
                    resolvedMethod: nextResolved[mid].resolvedMethod,
                    resolvedVerificationStatus: nextResolved[mid].resolvedVerificationStatus,
                    resolvedCumulativeYield: nextResolved[mid].resolvedCumulativeYield,
                    resolvedTrustedForTotal: nextResolved[mid].resolvedTrustedForTotal,
                    resolvedCanonicalHistoryCoverageStatus: nextResolved[mid].resolvedCanonicalHistoryCoverageStatus,
                    resolvedCanonicalHistoryLastScannedBlock: nextResolved[mid].resolvedCanonicalHistoryLastScannedBlock,
                    resolvedCanonicalHistoryFreshForBorrowRouting: nextResolved[mid].resolvedCanonicalHistoryFreshForBorrowRouting,
                };
            });
        }

        function earn_getVerificationParTolerance() {
            return 1n;
        }

        function earn_getVerificationWeiTolerance(decimals, actualWei, expectedWei) {
            const safeDecimals = Math.max(0, Number(decimals || 18));
            const minTolerance = safeDecimals > 12 ? (10n ** BigInt(safeDecimals - 12)) : 1n;
            const actualAbs = earn_absBigInt(BigInt(actualWei || 0));
            const expectedAbs = earn_absBigInt(BigInt(expectedWei || 0));
            const referenceWei = actualAbs > expectedAbs ? actualAbs : expectedAbs;
            const relativeTolerance = referenceWei > 0n ? (referenceWei / 1000000n) : 0n; // 1 ppm drift allowance
            return relativeTolerance > minTolerance ? relativeTolerance : minTolerance;
        }

        function earn_parToWeiRoundHalfUp(par, index) {
            const scale = 10n ** 18n;
            return ((BigInt(par || 0) * BigInt(index || 0)) + (scale / 2n)) / scale;
        }

        function earn_normalizeMarketId(value) {
            if (value === undefined || value === null) return '';
            const normalized = String(value);
            return normalized === '' ? '' : normalized;
        }

        function earn_collectBorrowAccountsOverride(...sources) {
            const merged = new Set();
            sources.forEach(source => {
                if (!source || typeof source.forEach !== 'function') return;
                source.forEach(account => {
                    const normalized = String(account || '').trim();
                    if (normalized) merged.add(normalized);
                });
            });
            return merged.size > 0 ? merged : null;
        }

        function earn_pushUniqueAccount(list, account) {
            const normalized = String(account || '').trim();
            if (!normalized) return;
            if (!Array.isArray(list)) return;
            if (!list.includes(normalized)) list.push(normalized);
        }

        function earn_getCurrentPositionRoute(pos, accountHasBorrow) {
            const accountNumber = String(pos && pos.accountNumber !== undefined ? pos.accountNumber : '0');
            const explicitRoute = String(
                pos && (pos.positionRoute !== undefined ? pos.positionRoute : pos.positionKind) || ''
            ).trim().toLowerCase();
            if (explicitRoute === 'borrow') return 'borrow';
            if (explicitRoute === 'hidden-collateral' || explicitRoute === 'hidden_collateral' || explicitRoute === 'collateral') {
                return 'collateral';
            }
            if (
                (explicitRoute === 'visible-supply' || explicitRoute === 'visible_supply' || explicitRoute === 'supply' || explicitRoute === 'visible')
                && !accountHasBorrow.has(accountNumber)
            ) {
                return 'supply';
            }

            const wei = BigInt(pos && pos.wei !== undefined ? pos.wei : 0);
            const par = BigInt(pos && pos.par !== undefined ? pos.par : 0);
            if (wei < 0n || par < 0n) return 'borrow';
            if (wei > 0n && accountHasBorrow.has(accountNumber)) {
                return 'collateral';
            }
            if (wei > 0n || par > 0n) return 'supply';
            return null;
        }

        function earn_buildCurrentPositionBuckets(positions, opts) {
            opts = opts || {};
            const borrowAccounts = earn_collectBorrowAccountsOverride(
                opts.knownBorrowAccounts,
                opts.borrowAccountsOverride,
                opts.snapshotBorrowAccounts
            );
            const accountHasBorrow = new Set(borrowAccounts ? Array.from(borrowAccounts) : []);

            (positions || []).forEach(pos => {
                const wei = BigInt(pos && pos.wei !== undefined ? pos.wei : 0);
                const par = BigInt(pos && pos.par !== undefined ? pos.par : 0);
                if (wei < 0n || par < 0n) {
                    accountHasBorrow.add(String(pos && pos.accountNumber !== undefined ? pos.accountNumber : '0'));
                }
            });

            const aggregatedSupply = {};
            const aggregatedCollateral = {};
            const aggregatedBorrow = {};
            const hiddenMarketIds = new Set();
            let hiddenSupplyCount = 0;

            const appendPosition = (target, route, pos) => {
                const mid = earn_normalizeMarketId(pos.marketId);
                if (!mid) return;
                const accountNumber = String(pos.accountNumber || '0');
                const positionRoute = route === 'collateral'
                    ? 'hidden-collateral'
                    : route === 'borrow'
                        ? 'borrow'
                        : 'visible-supply';

                if (!target[mid]) {
                    target[mid] = {
                        ...pos,
                        marketId: mid,
                        isCollateral: route === 'collateral',
                        positionRoute,
                        accountNumbers: [],
                    };
                } else {
                    target[mid].wei += BigInt(pos.wei || 0);
                    target[mid].par += BigInt(pos.par || 0);
                }
                target[mid].positionRoute = positionRoute;
                target[mid].isCollateral = route === 'collateral';
                earn_pushUniqueAccount(target[mid].accountNumbers, accountNumber);
            };

            (positions || []).forEach(pos => {
                const route = earn_getCurrentPositionRoute(pos, accountHasBorrow);
                if (!route) return;
                if (route === 'borrow') {
                    appendPosition(aggregatedBorrow, route, pos);
                    return;
                }
                if (route === 'collateral') {
                    if (BigInt(pos.wei || 0) > 0n) {
                        hiddenSupplyCount += 1;
                        hiddenMarketIds.add(earn_normalizeMarketId(pos.marketId));
                    }
                    appendPosition(aggregatedCollateral, route, pos);
                    return;
                }
                appendPosition(aggregatedSupply, route, pos);
            });

            return {
                aggregatedSupply,
                aggregatedCollateral,
                aggregatedBorrow,
                borrowAccounts: accountHasBorrow,
                hiddenSupplyCount,
                hiddenMarketIds,
            };
        }

        function earn_coalesceCurrentPositions(positions) {
            const merged = {};
            (positions || []).forEach(pos => {
                if (!pos) return;
                const accountNumber = String(pos.accountNumber || '0');
                const marketId = earn_normalizeMarketId(pos.marketId);
                const tokenAddr = String(pos.tokenAddr || '').toLowerCase();
                if (!marketId) return;
                const key = `${accountNumber}|${marketId}|${tokenAddr}`;
                if (!merged[key]) {
                    merged[key] = {
                        ...pos,
                        accountNumber,
                        marketId,
                        tokenAddr,
                        par: BigInt(pos.par || 0),
                        wei: BigInt(pos.wei || 0),
                    };
                    return;
                }
                merged[key].par += BigInt(pos.par || 0);
                merged[key].wei += BigInt(pos.wei || 0);
            });
            return Object.values(merged).filter(pos => BigInt(pos.par || 0) !== 0n || BigInt(pos.wei || 0) !== 0n);
        }

        function earn_serializeReplayStateMap(states) {
            const serialized = {};
            Object.entries(states || {}).forEach(([key, state]) => {
                serialized[key] = {
                    account: String(state.account || ''),
                    marketId: earn_normalizeMarketId(state.marketId),
                    par: String(state.par || 0n),
                    lastIndex: state.lastIndex === null || state.lastIndex === undefined ? null : String(state.lastIndex),
                    settledYield: String(state.settledYield || 0n),
                    settledSupplyYield: String(state.settledSupplyYield || 0n),
                    settledBorrowYield: String(state.settledBorrowYield || 0n),
                    liveYield: String(state.liveYield || 0n),
                    hadSupply: !!state.hadSupply,
                    hadBorrow: !!state.hadBorrow,
                };
            });
            return serialized;
        }

        function earn_deserializeReplayStateMap(accountStateData) {
            const states = {};
            Object.entries(accountStateData || {}).forEach(([key, state]) => {
                states[key] = {
                    account: String(state.account || ''),
                    marketId: earn_normalizeMarketId(state.marketId),
                    par: BigInt(state.par || '0'),
                    lastIndex: state.lastIndex === null || state.lastIndex === undefined ? null : BigInt(state.lastIndex),
                    settledYield: BigInt(state.settledYield || '0'),
                    settledSupplyYield: BigInt(state.settledSupplyYield || '0'),
                    settledBorrowYield: BigInt(state.settledBorrowYield || '0'),
                    liveYield: BigInt(state.liveYield || '0'),
                    hadSupply: !!state.hadSupply,
                    hadBorrow: !!state.hadBorrow,
                };
            });
            return states;
        }

        function earn_reconcileReplayToCurrentPositions(positions, opts) {
            opts = opts || {};
            if (!earn_replayAccountStateData || Object.keys(earn_replayAccountStateData).length === 0) return 0;

            const currentParByKey = {};
            const currentBorrowAccounts = new Set(
                opts.borrowAccounts && typeof opts.borrowAccounts.forEach === 'function'
                    ? Array.from(opts.borrowAccounts, acct => String(acct || '').trim()).filter(Boolean)
                    : []
            );
            (positions || []).forEach(pos => {
                const account = String(pos.accountNumber || '0');
                const marketId = earn_normalizeMarketId(pos.marketId);
                if (!marketId) return;
                const key = `${account}|${marketId}`;
                currentParByKey[key] = (currentParByKey[key] || 0n) + BigInt(pos.par || 0);
                if (BigInt(pos.par || 0) < 0n || BigInt(pos.wei || 0) < 0n) {
                    currentBorrowAccounts.add(account);
                }
            });

            const states = earn_deserializeReplayStateMap(earn_replayAccountStateData);
            let adjustedStates = 0;
            const adjustedMarkets = new Set();

            Object.entries(states).forEach(([key, state]) => {
                const prevPar = BigInt(state.par || 0n);
                const currentPar = currentParByKey[key] !== undefined ? currentParByKey[key] : 0n;
                if (prevPar === currentPar) return;

                const sameSign = (prevPar > 0n && currentPar > 0n) || (prevPar < 0n && currentPar < 0n);
                const reducedExposure = sameSign && earn_absBigInt(currentPar) < earn_absBigInt(prevPar);
                const fullyClosed = currentPar === 0n;
                const flipsSign = prevPar !== 0n && currentPar !== 0n &&
                    ((prevPar > 0n && currentPar < 0n) || (prevPar < 0n && currentPar > 0n));
                if (!reducedExposure && !fullyClosed && !flipsSign) return;

                // If current state crossed through zero versus replay, settle the old side fully
                // and reopen the new side at the current index. That prevents stale ghost borrow
                // or ghost supply from surviving just because replay and latest balances disagree
                // on which side of zero this account/market key ended on.
                const settleTargetPar = flipsSign ? 0n : currentPar;
                earn_settleReducedExposureYield(state, settleTargetPar);
                state.par = currentPar;
                if (state.par > 0n) state.hadSupply = true;
                if (state.par < 0n) state.hadBorrow = true;
                if (state.par === 0n || flipsSign) {
                    earn_addSettledYield(state, state.liveYield, prevPar);
                    state.liveYield = 0n;
                }

                const idxMeta = earn_replayCurrentIndexMap ? earn_replayCurrentIndexMap[state.marketId] : null;
                const nextIndex = state.par > 0n
                    ? idxMeta?.supplyIndex
                    : state.par < 0n
                        ? idxMeta?.borrowIndex
                        : null;
                state.lastIndex = nextIndex === null || nextIndex === undefined ? null : BigInt(nextIndex);
                adjustedStates += 1;
                adjustedMarkets.add(String(state.marketId));
            });

            const serialized = earn_serializeReplayStateMap(states);
            const summary = earn_summarizeReplayAccountStates(
                serialized,
                earn_replayCurrentIndexMap || {},
                { borrowAccountsOverride: currentBorrowAccounts }
            );
            earn_replayAccountStateData = serialized;
            earn_interestYieldData = summary.interestYieldData || {};
            earn_replayStateData = summary.replayStateData || {};
            earn_openBorrowAccounts = new Set((summary.openBorrowAccounts || []).map(v => String(v)));
            if (adjustedStates > 0) {
                adjustedMarkets.forEach(mid => earn_replayReconciledMarkets.add(mid));
                console.log(`Reconciled ${adjustedStates} replay state(s) to current positions.`);
            } else {
                console.log(`Reclassified replay summary using ${currentBorrowAccounts.size} current borrow account(s).`);
            }
            return adjustedStates;
        }

        function earn_summarizeReplayAccountStates(accountStateData, currentIndexMap, opts) {
            opts = opts || {};
            const states = Object.values(accountStateData || {}).map(state => ({
                account: String(state.account || ''),
                marketId: earn_normalizeMarketId(state.marketId),
                par: BigInt(state.par || '0'),
                settledYield: BigInt(state.settledYield || '0'),
                settledSupplyYield: BigInt(state.settledSupplyYield || '0'),
                settledBorrowYield: BigInt(state.settledBorrowYield || '0'),
                liveYield: BigInt(state.liveYield || '0'),
                hadSupply: !!state.hadSupply,
                hadBorrow: !!state.hadBorrow,
            }));

            const borrowAccountsOverride = opts.borrowAccountsOverride && typeof opts.borrowAccountsOverride.forEach === 'function'
                ? new Set(Array.from(opts.borrowAccountsOverride, acct => String(acct || '').trim()).filter(Boolean))
                : null;
            const openBorrowAccounts = new Set();
            const accountHasOpenBorrow = {};
            states.forEach(state => {
                if (state.par < 0n) {
                    openBorrowAccounts.add(state.account);
                    accountHasOpenBorrow[state.account] = true;
                } else if (!Object.prototype.hasOwnProperty.call(accountHasOpenBorrow, state.account)) {
                    accountHasOpenBorrow[state.account] = false;
                }
            });
            if (borrowAccountsOverride) {
                states.forEach(state => {
                    accountHasOpenBorrow[state.account] = borrowAccountsOverride.has(state.account);
                });
                openBorrowAccounts.clear();
                borrowAccountsOverride.forEach(account => openBorrowAccounts.add(account));
            }

            const interestYieldData = {};
            const replayStateData = {};
            states.forEach(state => {
                if (!interestYieldData[state.marketId]) {
                    interestYieldData[state.marketId] = {
                        earnYield: 0n,
                        settledYield: 0n,
                        settledSupplyYield: 0n,
                        settledBorrowYield: 0n,
                        openBorrowYield: 0n,
                        openSupplyYield: 0n,
                        openCollateralYield: 0n,
                        currentBorrowPar: 0n,
                        currentSupplyPar: 0n,
                        currentCollateralSupplyPar: 0n,
                        hadSupply: false,
                        hadBorrow: false,
                    };
                }
                const entry = interestYieldData[state.marketId];
                entry.hadSupply = entry.hadSupply || state.hadSupply;
                entry.hadBorrow = entry.hadBorrow || state.hadBorrow;
                entry.settledSupplyYield += state.settledSupplyYield;
                entry.settledBorrowYield += state.settledBorrowYield;
                entry.settledYield += state.settledSupplyYield;

                if (!replayStateData[state.marketId]) {
                    replayStateData[state.marketId] = {
                        expectedSupplyPar: 0n,
                        expectedSupplyWei: 0n,
                        expectedCollateralSupplyPar: 0n,
                        expectedCollateralSupplyWei: 0n,
                        expectedBorrowPar: 0n,
                        expectedBorrowWei: 0n,
                        hadSupply: false,
                        hadBorrow: false,
                        canVerify: true,
                    };
                }
                const stateEntry = replayStateData[state.marketId];
                stateEntry.hadSupply = stateEntry.hadSupply || state.hadSupply;
                stateEntry.hadBorrow = stateEntry.hadBorrow || state.hadBorrow;

                if (state.par > 0n) {
                    entry.earnYield += state.settledSupplyYield + state.liveYield;
                    const isCollateralSupply = !!accountHasOpenBorrow[state.account];
                    if (isCollateralSupply) {
                        entry.openCollateralYield += state.liveYield;
                        entry.currentCollateralSupplyPar += state.par;
                        stateEntry.expectedCollateralSupplyPar += state.par;
                    } else {
                        entry.openSupplyYield += state.liveYield;
                        entry.currentSupplyPar += state.par;
                        stateEntry.expectedSupplyPar += state.par;
                    }
                    const idxMeta = currentIndexMap ? currentIndexMap[state.marketId] : null;
                    const supplyIndex = idxMeta && idxMeta.supplyIndex !== null && idxMeta.supplyIndex !== undefined
                        ? BigInt(idxMeta.supplyIndex)
                        : null;
                    if (supplyIndex === null) {
                        stateEntry.canVerify = false;
                    } else {
                        const expectedWei = earn_parToWeiRoundHalfUp(state.par, supplyIndex);
                        if (isCollateralSupply) stateEntry.expectedCollateralSupplyWei += expectedWei;
                        else stateEntry.expectedSupplyWei += expectedWei;
                    }
                } else if (state.par < 0n) {
                    entry.currentBorrowPar += (-state.par);
                    entry.openBorrowYield += state.liveYield;
                    entry.earnYield += state.settledSupplyYield;
                    const borrowPar = -state.par;
                    stateEntry.expectedBorrowPar += borrowPar;
                    const idxMeta = currentIndexMap ? currentIndexMap[state.marketId] : null;
                    const borrowIndex = idxMeta && idxMeta.borrowIndex !== null && idxMeta.borrowIndex !== undefined
                        ? BigInt(idxMeta.borrowIndex)
                        : null;
                    if (borrowIndex === null) {
                        stateEntry.canVerify = false;
                    } else {
                        stateEntry.expectedBorrowWei += earn_parToWeiRoundHalfUp(borrowPar, borrowIndex);
                    }
                } else {
                    entry.earnYield += state.settledSupplyYield;
                }
            });

            Object.values(interestYieldData).forEach(entry => {
                entry.earnYield = entry.earnYield.toString();
                entry.settledYield = entry.settledYield.toString();
                entry.settledSupplyYield = entry.settledSupplyYield.toString();
                entry.settledBorrowYield = entry.settledBorrowYield.toString();
                entry.openBorrowYield = entry.openBorrowYield.toString();
                entry.openSupplyYield = entry.openSupplyYield.toString();
                entry.openCollateralYield = entry.openCollateralYield.toString();
                entry.currentBorrowPar = entry.currentBorrowPar.toString();
                entry.currentSupplyPar = entry.currentSupplyPar.toString();
                entry.currentCollateralSupplyPar = entry.currentCollateralSupplyPar.toString();
            });
            Object.values(replayStateData).forEach(entry => {
                entry.expectedSupplyPar = entry.expectedSupplyPar.toString();
                entry.expectedSupplyWei = entry.expectedSupplyWei.toString();
                entry.expectedCollateralSupplyPar = entry.expectedCollateralSupplyPar.toString();
                entry.expectedCollateralSupplyWei = entry.expectedCollateralSupplyWei.toString();
                entry.expectedBorrowPar = entry.expectedBorrowPar.toString();
                entry.expectedBorrowWei = entry.expectedBorrowWei.toString();
            });

            return {
                interestYieldData,
                replayStateData,
                openBorrowAccounts: Array.from(openBorrowAccounts),
            };
        }

        function earn_advanceReplayAccountStateDataToCurrentIndexes(accountStateData, currentIndexMap) {
            const states = earn_deserializeReplayStateMap(accountStateData || {});
            let advancedStates = 0;

            Object.values(states).forEach(state => {
                const par = BigInt(state.par || 0n);
                if (par === 0n) return;

                const idxMeta = currentIndexMap ? currentIndexMap[state.marketId] : null;
                const nextIndexRaw = par > 0n
                    ? idxMeta?.supplyIndex
                    : idxMeta?.borrowIndex;
                if (nextIndexRaw === null || nextIndexRaw === undefined) return;

                const nextIndex = BigInt(nextIndexRaw);
                if (state.lastIndex === null || state.lastIndex === undefined) {
                    state.lastIndex = nextIndex;
                    return;
                }

                const lastIndex = BigInt(state.lastIndex);
                if (nextIndex <= lastIndex) {
                    state.lastIndex = nextIndex;
                    return;
                }

                const deltaIdx = nextIndex - lastIndex;
                const deltaWei = (earn_absBigInt(par) * deltaIdx) / (10n ** 18n);
                if (deltaWei !== 0n) {
                    state.liveYield += par >= 0n ? deltaWei : -deltaWei;
                    advancedStates++;
                }
                state.lastIndex = nextIndex;
            });

            return {
                accountStateData: earn_serializeReplayStateMap(states),
                advancedStates,
            };
        }

        async function earn_refreshReplayWithLiveCurrentIndexes(replay, opts) {
            opts = opts || {};
            if (!replay || !replay.accountStateData || Object.keys(replay.accountStateData).length === 0) {
                return replay;
            }

            const marketIds = Array.from(new Set([
                ...Object.keys(replay.currentIndexMap || {}),
                ...Object.keys(replay.marketMeta || {}),
                ...Object.keys(replay.interestYieldData || {}),
                ...Object.keys(replay.replayStateData || {}),
                ...Object.keys(replay.netflows || {}),
            ].map(mid => String(mid)).filter(Boolean)));
            if (marketIds.length === 0) return replay;

            try {
                const liveMeta = await earn_fetchReplayMarketMeta(marketIds, {
                    blockTag: opts.blockTag || earn_replayBlockTag || 'latest',
                });
                const liveCurrentIndexMap = {};
                Object.entries(liveMeta.currentIndexMap || {}).forEach(([mid, meta]) => {
                    liveCurrentIndexMap[String(mid)] = {
                        supplyIndex: meta && meta.supplyIndex !== null && meta.supplyIndex !== undefined
                            ? String(meta.supplyIndex)
                            : null,
                        borrowIndex: meta && meta.borrowIndex !== null && meta.borrowIndex !== undefined
                            ? String(meta.borrowIndex)
                            : null,
                    };
                });
                const mergedCurrentIndexMap = earn_mergeReplayCurrentIndexMap(
                    liveCurrentIndexMap,
                    replay.currentIndexMap || {}
                );

                const advanced = earn_advanceReplayAccountStateDataToCurrentIndexes(
                    replay.accountStateData,
                    mergedCurrentIndexMap
                );
                const borrowAccountsOverride = earn_collectBorrowAccountsOverride(
                    replay.borrowAccountsOverride,
                    replay.openBorrowAccounts
                );
                const refreshedSummary = earn_summarizeReplayAccountStates(
                    advanced.accountStateData,
                    mergedCurrentIndexMap,
                    { borrowAccountsOverride }
                );

                if (advanced.advancedStates > 0) {
                    console.log(`Advanced ${advanced.advancedStates} replay state(s) to live current indexes.`);
                }

                return {
                    ...replay,
                    interestYieldData: refreshedSummary.interestYieldData || replay.interestYieldData || {},
                    replayStateData: refreshedSummary.replayStateData || replay.replayStateData || {},
                    openBorrowAccounts: refreshedSummary.openBorrowAccounts || replay.openBorrowAccounts || [],
                    borrowAccountsOverride: borrowAccountsOverride ? Array.from(borrowAccountsOverride) : (replay.borrowAccountsOverride || replay.openBorrowAccounts || []),
                    accountStateData: advanced.accountStateData,
                    currentIndexMap: mergedCurrentIndexMap,
                    marketMeta: {
                        ...(replay.marketMeta || {}),
                        ...(liveMeta.marketMeta || {}),
                    },
                };
            } catch (error) {
                console.warn('Live replay index refresh failed:', error && error.message ? error.message : error);
                return replay;
            }
        }

        function earn_mergeReplayCurrentIndexMeta(primaryMeta, supplementMeta) {
            if (!primaryMeta && !supplementMeta) return null;
            return {
                supplyIndex: primaryMeta && primaryMeta.supplyIndex !== null && primaryMeta.supplyIndex !== undefined
                    ? primaryMeta.supplyIndex
                    : (supplementMeta && supplementMeta.supplyIndex !== null && supplementMeta.supplyIndex !== undefined
                        ? supplementMeta.supplyIndex
                        : null),
                borrowIndex: primaryMeta && primaryMeta.borrowIndex !== null && primaryMeta.borrowIndex !== undefined
                    ? primaryMeta.borrowIndex
                    : (supplementMeta && supplementMeta.borrowIndex !== null && supplementMeta.borrowIndex !== undefined
                        ? supplementMeta.borrowIndex
                        : null),
            };
        }

        function earn_mergeReplayCurrentIndexMap(primaryMap, supplementMap, predicate) {
            const merged = { ...(primaryMap || {}) };
            Object.entries(supplementMap || {}).forEach(([mid, meta]) => {
                if (predicate && !predicate(String(mid), meta)) return;
                merged[mid] = earn_mergeReplayCurrentIndexMeta(merged[mid] || null, meta || null);
            });
            return merged;
        }

        function earn_getReplayMarketsMissingCurrentIndexes(replay) {
            const missing = new Set();
            Object.entries((replay && replay.replayStateData) || {}).forEach(([mid, entry]) => {
                const state = entry || {};
                const idxMeta = (replay && replay.currentIndexMap && replay.currentIndexMap[mid]) || {};
                const expectedSupplyPar = BigInt(state.expectedSupplyPar || '0');
                const expectedCollateralPar = BigInt(state.expectedCollateralSupplyPar || '0');
                const expectedBorrowPar = BigInt(state.expectedBorrowPar || '0');
                const needsSupplyIndex = expectedSupplyPar > 0n || expectedCollateralPar > 0n;
                const needsBorrowIndex = expectedBorrowPar > 0n;
                if (needsSupplyIndex && (idxMeta.supplyIndex === null || idxMeta.supplyIndex === undefined)) {
                    missing.add(String(mid));
                    return;
                }
                if (needsBorrowIndex && (idxMeta.borrowIndex === null || idxMeta.borrowIndex === undefined)) {
                    missing.add(String(mid));
                }
            });
            return Array.from(missing);
        }

        function earn_supplementReplayCurrentIndexes(primaryReplay, supplementReplay, targetMarkets) {
            const targets = new Set((targetMarkets || []).map(v => String(v)));
            if (targets.size === 0) return primaryReplay;
            if (!supplementReplay || !supplementReplay.currentIndexMap) return primaryReplay;
            const mergedCurrentIndexMap = earn_mergeReplayCurrentIndexMap(
                primaryReplay.currentIndexMap || {},
                supplementReplay.currentIndexMap || {},
                mid => targets.has(String(mid))
            );
            const borrowAccountsOverride = earn_collectBorrowAccountsOverride(
                primaryReplay.borrowAccountsOverride,
                primaryReplay.openBorrowAccounts,
                supplementReplay.borrowAccountsOverride,
                supplementReplay.openBorrowAccounts
            );
            const mergedSummary = earn_summarizeReplayAccountStates(
                primaryReplay.accountStateData || {},
                mergedCurrentIndexMap,
                { borrowAccountsOverride }
            );
            return {
                ...primaryReplay,
                interestYieldData: mergedSummary.interestYieldData || primaryReplay.interestYieldData || {},
                replayStateData: mergedSummary.replayStateData || primaryReplay.replayStateData || {},
                openBorrowAccounts: mergedSummary.openBorrowAccounts || primaryReplay.openBorrowAccounts || [],
                borrowAccountsOverride: borrowAccountsOverride ? Array.from(borrowAccountsOverride) : (primaryReplay.borrowAccountsOverride || primaryReplay.openBorrowAccounts || []),
                currentIndexMap: mergedCurrentIndexMap,
                marketMeta: {
                    ...(supplementReplay.marketMeta || {}),
                    ...(primaryReplay.marketMeta || {}),
                },
            };
        }

        function earn_mergeReplayMissingAccounts(primaryReplay, supplementReplay, missingAccounts) {
            const missing = new Set((missingAccounts || []).map(v => String(v)));
            if (missing.size === 0) return primaryReplay;
            if (!supplementReplay || !supplementReplay.accountStateData) return primaryReplay;

            const mergedAccountStateData = { ...(primaryReplay.accountStateData || {}) };
            let addedStates = 0;
            Object.entries(supplementReplay.accountStateData || {}).forEach(([key, state]) => {
                const account = String(state.account || '');
                if (!missing.has(account)) return;
                if (mergedAccountStateData[key]) return;
                mergedAccountStateData[key] = state;
                addedStates++;
            });
            if (addedStates === 0) return primaryReplay;

            const mergedCurrentIndexMap = earn_mergeReplayCurrentIndexMap(
                primaryReplay.currentIndexMap || {},
                supplementReplay.currentIndexMap || {}
            );

            const borrowAccountsOverride = earn_collectBorrowAccountsOverride(
                primaryReplay.borrowAccountsOverride,
                primaryReplay.openBorrowAccounts,
                supplementReplay.borrowAccountsOverride,
                supplementReplay.openBorrowAccounts
            );
            const mergedSummary = earn_summarizeReplayAccountStates(
                mergedAccountStateData,
                mergedCurrentIndexMap,
                { borrowAccountsOverride }
            );
            const mergedNetflows = { ...(primaryReplay.netflows || {}) };
            Object.entries(supplementReplay.netflows || {}).forEach(([mid, entry]) => {
                if (!mergedNetflows[mid]) mergedNetflows[mid] = entry;
            });
            const mergedEventTrace = [
                ...(primaryReplay.eventTrace || []),
                ...(supplementReplay.eventTrace || []).filter(ev => missing.has(String(ev.account || ''))),
            ];

            return {
                ...primaryReplay,
                accountNumbers: Array.from(new Set([
                    ...(primaryReplay.accountNumbers || []),
                    ...(supplementReplay.accountNumbers || []),
                ])),
                netflows: mergedNetflows,
                interestYieldData: mergedSummary.interestYieldData,
                replayStateData: mergedSummary.replayStateData,
                marketMeta: {
                    ...(supplementReplay.marketMeta || {}),
                    ...(primaryReplay.marketMeta || {}),
                },
                openBorrowAccounts: mergedSummary.openBorrowAccounts,
                borrowAccountsOverride: borrowAccountsOverride ? Array.from(borrowAccountsOverride) : (primaryReplay.borrowAccountsOverride || primaryReplay.openBorrowAccounts || []),
                accountStateData: mergedAccountStateData,
                currentIndexMap: mergedCurrentIndexMap,
                eventTrace: mergedEventTrace,
                verificationIncomplete: !!primaryReplay.verificationIncomplete || !!supplementReplay.verificationIncomplete,
            };
        }

        function earn_mergeReplayMissingMarkets(primaryReplay, supplementReplay, missingMarkets) {
            const missing = new Set((missingMarkets || []).map(v => String(v)));
            if (missing.size === 0) return primaryReplay;
            if (!supplementReplay || !supplementReplay.accountStateData) return primaryReplay;

            const mergedAccountStateData = { ...(primaryReplay.accountStateData || {}) };
            let addedStates = 0;
            Object.entries(supplementReplay.accountStateData || {}).forEach(([key, state]) => {
                const marketId = earn_normalizeMarketId(state.marketId);
                if (!missing.has(marketId)) return;
                if (mergedAccountStateData[key]) return;
                mergedAccountStateData[key] = state;
                addedStates++;
            });
            if (addedStates === 0) return primaryReplay;

            const mergedCurrentIndexMap = earn_mergeReplayCurrentIndexMap(
                primaryReplay.currentIndexMap || {},
                supplementReplay.currentIndexMap || {},
                mid => missing.has(String(mid))
            );

            const borrowAccountsOverride = earn_collectBorrowAccountsOverride(
                primaryReplay.borrowAccountsOverride,
                primaryReplay.openBorrowAccounts,
                supplementReplay.borrowAccountsOverride,
                supplementReplay.openBorrowAccounts
            );
            const mergedSummary = earn_summarizeReplayAccountStates(
                mergedAccountStateData,
                mergedCurrentIndexMap,
                { borrowAccountsOverride }
            );
            const mergedNetflows = { ...(primaryReplay.netflows || {}) };
            Object.entries(supplementReplay.netflows || {}).forEach(([mid, entry]) => {
                if (!missing.has(String(mid))) return;
                if (!mergedNetflows[mid]) mergedNetflows[mid] = entry;
            });

            const mergedAcct0Netflows = (primaryReplay.acct0Netflows || supplementReplay.acct0Netflows)
                ? { ...(primaryReplay.acct0Netflows || {}) }
                : null;
            if (mergedAcct0Netflows) {
                Object.entries(supplementReplay.acct0Netflows || {}).forEach(([mid, entry]) => {
                    if (!missing.has(String(mid))) return;
                    if (mergedAcct0Netflows[mid] === undefined) mergedAcct0Netflows[mid] = entry;
                });
            }

            const mergedEventTrace = [
                ...(primaryReplay.eventTrace || []),
                ...(supplementReplay.eventTrace || []).filter(ev => missing.has(earn_normalizeMarketId(ev.marketId))),
            ];

            return {
                ...primaryReplay,
                accountNumbers: Array.from(new Set([
                    ...(primaryReplay.accountNumbers || []),
                    ...(supplementReplay.accountNumbers || []),
                ])),
                netflows: mergedNetflows,
                acct0Netflows: mergedAcct0Netflows,
                interestYieldData: mergedSummary.interestYieldData,
                replayStateData: mergedSummary.replayStateData,
                marketMeta: {
                    ...(supplementReplay.marketMeta || {}),
                    ...(primaryReplay.marketMeta || {}),
                },
                openBorrowAccounts: mergedSummary.openBorrowAccounts,
                borrowAccountsOverride: borrowAccountsOverride ? Array.from(borrowAccountsOverride) : (primaryReplay.borrowAccountsOverride || primaryReplay.openBorrowAccounts || []),
                accountStateData: mergedAccountStateData,
                currentIndexMap: mergedCurrentIndexMap,
                eventTrace: mergedEventTrace,
                verificationIncomplete: !!primaryReplay.verificationIncomplete || !!supplementReplay.verificationIncomplete,
            };
        }

        function earn_buildVerificationTitle(entry, symbol, decimals) {
            if (!entry) return '';
            if (entry.status === 'verified') {
                return 'Replay reconciles with onchain current balances.';
            }
            if (entry.status === 'coverage_incomplete' || entry.status === 'unverified') {
                if (entry.snapshotIncomplete) {
                    if (entry.subgraphReplayTruncated) {
                        return 'Subgraph fallback returned only part of this market\'s event history, so replay verification is withheld until onchain replay is complete.';
                    }
                    if (entry.replayStateAdjusted) {
                        return 'Replay state was adjusted to match the latest position, so verification is withheld until complete ordered replay confirms the missing transition.';
                    }
                    return 'Current onchain balance snapshot was incomplete for this market, so replay verification is temporarily withheld instead of flagging a mismatch.';
                }
                if (entry.usdDriftVerified) {
                    return `Replay is close but not strictly verified because there is still residual drift. Largest bucket drift: ${earn_formatUsdDrift(entry.maxUsdDrift)}.`;
                }
                return 'Replay could not be fully reconciled for this market.';
            }
            const parts = [];
            const addPart = (label, diff) => {
                if (diff === 0n) return;
                const sign = diff > 0n ? '+' : '-';
                parts.push(`${label} ${sign}${earn_formatAmount(earn_absBigInt(diff), decimals, symbol)}`);
            };
            addPart('Supply par Δ', entry.supplyParDiff);
            addPart('Supply wei Δ', entry.supplyWeiDiff);
            addPart('Collateral par Δ', entry.collateralParDiff);
            addPart('Collateral wei Δ', entry.collateralWeiDiff);
            addPart('Borrow par Δ', entry.borrowParDiff);
            addPart('Borrow wei Δ', entry.borrowWeiDiff);
            const driftPart = entry.hasUsdDrift
                ? `Largest bucket drift: ${earn_formatUsdDrift(entry.maxUsdDrift)}. `
                : '';
            return parts.length > 0
                ? `Replay mismatch vs onchain balances. ${driftPart}${parts.join(' · ')}`
                : 'Replay mismatch vs onchain balances.';
        }

        function earn_getVerificationPresentation(marketId, yieldCalc, symbol, decimals) {
            const entry = earn_getVerification(marketId);
            const snapshotLedgerPresentation = earn_getSnapshotLedgerPresentation(marketId, yieldCalc);
            const fallbackTitle = entry
                ? earn_buildVerificationTitle(entry, symbol || 'UNK', decimals ?? 18)
                : 'Ledger check unavailable.';
            const fallbackStatus = !entry || !entry.counted
                ? 'unverified'
                : (entry.strictStatus || entry.status || 'unverified');
            const fallbackLabel = !entry || !entry.counted
                ? 'Unverified'
                : fallbackStatus === 'verified'
                    ? 'Verified'
                    : fallbackStatus === 'mismatch'
                        ? 'Mismatch'
                        : fallbackStatus === 'coverage_incomplete'
                            ? 'Incomplete'
                            : 'Unverified';

            if (snapshotLedgerPresentation) {
                return snapshotLedgerPresentation;
            }

            if (fallbackStatus === 'verified') {
                const yieldQualityPresentation = earn_getYieldQualityPresentation(yieldCalc);
                if (yieldQualityPresentation) return yieldQualityPresentation;
            }

            if (entry && entry.counted && (fallbackStatus === 'unverified' || fallbackStatus === 'coverage_incomplete')) {
                const fallbackMethods = new Set(['snapshot', 'snapshot-partial', 'acct0-netflow', 'all-netflow', 'all-netflow-guarded', 'recent-cycle']);
                const incompleteTitle = entry.subgraphReplayTruncated
                    ? 'Subgraph fallback returned only part of this market\'s event history, so verification remains pending until onchain replay is complete.'
                    : entry.replayStateAdjusted
                        ? 'Replay state was adjusted to match the latest position, so verification remains pending until complete ordered replay confirms the missing transition.'
                    : 'Current balance reconciliation is incomplete for this market because missing live balances were supplemented from snapshot data. Verification will remain pending until a full RPC response is available.';
                const usesFallbackSource = !!(
                    earn_replayUsedSubgraphFallback ||
                    entry.snapshotIncomplete ||
                    (yieldCalc && fallbackMethods.has(String(yieldCalc.method || '')))
                );
                const label = entry.snapshotIncomplete || fallbackStatus === 'coverage_incomplete'
                    ? 'Pending'
                    : usesFallbackSource
                        ? 'Fallback'
                        : 'Checking';
                const status = entry.snapshotIncomplete || fallbackStatus === 'coverage_incomplete'
                    ? 'coverage_incomplete'
                    : usesFallbackSource
                        ? 'fallback'
                        : 'checking';
                const title = entry.snapshotIncomplete
                    ? incompleteTitle
                    : usesFallbackSource
                        ? 'This market is currently using fallback balance or yield data because live replay verification is unavailable.'
                        : 'Replay verification for this market is still in progress.';
                return {
                    counted: true,
                    status,
                    label,
                    title,
                    rawStatus: entry.status || 'unverified',
                    rawLabel: 'Unverified',
                    rawTitle: fallbackTitle,
                    overridden: false,
                    entry,
                };
            }

            return {
                counted: !!(entry && entry.counted),
                status: fallbackStatus === 'verified'
                    ? 'verified'
                    : fallbackStatus === 'mismatch'
                        ? 'mismatch'
                        : fallbackStatus === 'coverage_incomplete'
                            ? 'coverage_incomplete'
                        : 'unverified',
                label: fallbackLabel,
                title: fallbackTitle,
                rawStatus: entry ? (entry.strictStatus || entry.status || 'unverified') : 'unverified',
                rawLabel: fallbackLabel === 'Unverified'
                    ? 'Unverified'
                    : fallbackLabel === 'Verified'
                        ? 'Verified'
                        : fallbackLabel === 'Incomplete'
                            ? 'Incomplete'
                            : 'Mismatch',
                rawTitle: fallbackTitle,
                overridden: false,
                entry,
            };
        }

        function earn_getYieldQualityPresentation(yieldCalc) {
            if (!yieldCalc || !yieldCalc.hasData) return null;
            if (yieldCalc.trustedForTotal && earn_isTrustedReplayYieldStatus(String(yieldCalc.verificationStatus || ''))) return null;

            const method = String(yieldCalc.method || '');
            const status = String(yieldCalc.verificationStatus || '').toLowerCase();

            if (method === 'all-netflow-verified' || method === 'recent-cycle-verified' || method === 'all-netflow-pre-snapshot-carry' || method === 'recent-cycle-pre-snapshot-carry' || status === 'inferred') {
                return {
                    counted: true,
                    status: 'inferred',
                    label: (method === 'all-netflow-pre-snapshot-carry' || method === 'recent-cycle-pre-snapshot-carry') ? 'Inferred Carry' : 'Inferred',
                    title: (method === 'all-netflow-pre-snapshot-carry' || method === 'recent-cycle-pre-snapshot-carry')
                        ? 'This yield can be inferred from public netflow plus snapshot history, but it is not strict replay verification because part of the carry predates local coverage.'
                        : 'This yield reconciles through public netflow plus snapshot history, but it is not strict replay verification.',
                    rawStatus: status || 'inferred',
                    rawLabel: (method === 'all-netflow-pre-snapshot-carry' || method === 'recent-cycle-pre-snapshot-carry') ? 'Inferred Carry' : 'Inferred',
                    rawTitle: 'Useful historical evidence, but not strict replay verification.',
                    overridden: true,
                    entry: null,
                };
            }

            if (method === 'snapshot' || method === 'snapshot-partial') {
                return {
                    counted: true,
                    status: 'snapshot',
                    label: method === 'snapshot-partial' ? 'Snapshot Partial' : 'Snapshot',
                    title: 'Yield is derived from snapshot history instead of strict replay verification.',
                    rawStatus: status || 'snapshot',
                    rawLabel: 'Snapshot',
                    rawTitle: 'Snapshot-backed yield is useful, but not strict replay verification.',
                    overridden: true,
                    entry: null,
                };
            }

            if (method === 'acct0-netflow' || method === 'all-netflow' || method === 'all-netflow-guarded' || method === 'recent-cycle') {
                return {
                    counted: true,
                    status: 'fallback',
                    label: 'Fallback',
                    title: 'This market is using a guarded fallback yield source because strict replay verification is unavailable.',
                    rawStatus: status || 'fallback',
                    rawLabel: 'Fallback',
                    rawTitle: 'Fallback yield source.',
                    overridden: true,
                    entry: null,
                };
            }

            if (status === 'coverage_incomplete' || status === 'pending' || method === 'interest-ledger-pending') {
                return {
                    counted: true,
                    status: 'coverage_incomplete',
                    label: 'Pending',
                    title: 'Strict replay verification is still waiting for complete canonical subaccount history or final replay reconciliation.',
                    rawStatus: status || 'coverage_incomplete',
                    rawLabel: 'Pending',
                    rawTitle: 'Strict replay verification is not complete yet.',
                    overridden: true,
                    entry: null,
                };
            }

            if (method === 'interest-ledger-live-balance-adjusted' || method === 'interest-ledger-unverified') {
                return {
                    counted: true,
                    status: 'coverage_incomplete',
                    label: 'Adjusted',
                    title: 'Replay data was adjusted or is not fully verified yet, so this yield is not treated as strict verification.',
                    rawStatus: status || 'coverage_incomplete',
                    rawLabel: 'Adjusted',
                    rawTitle: 'Replay yield is not strict verified.',
                    overridden: true,
                    entry: null,
                };
            }

            return null;
        }

        function earn_renderVerificationBadge(marketId, symbol, decimals, yieldCalc) {
            if (!earn_replayVerificationReady) return '';
            const presentation = earn_getVerificationPresentation(marketId, yieldCalc, symbol, decimals);
            if (!presentation || !presentation.counted) return '';
            return `<span class="earn-verify-badge ${presentation.status}" data-tip="${earn_escapeHtml(presentation.title)}"><span class="earn-status-dot"></span>${earn_escapeHtml(presentation.label)}</span>`;
        }

        function earn_escapeHtml(value) {
            return String(value ?? '')
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#39;');
        }

        function earn_getYieldMethodMeta(method) {
            switch (method) {
                case 'interest-ledger':
                    return { label: 'History replay', cls: 'replay', title: 'Verification method: local subaccount history was replayed and reconciled with current onchain balances.' };
                case 'interest-ledger-live-balance-adjusted':
                    return { label: 'History replay', cls: 'replay', title: 'Verification method: replay ledger reconciled with current onchain balances after a live balance drift adjustment.' };
                case 'interest-ledger-override':
                    return { label: 'History replay', cls: 'replay', title: 'Verification method: strict local history replay was used because the snapshot/netflow path was stale or mismatched.' };
                case 'interest-ledger-pending':
                    return { label: 'History replay pending', cls: 'unverified', title: 'Verification method: local history replay is available, but final reconciliation is still in progress.' };
                case 'interest-ledger-unverified':
                    return { label: 'History replay pending', cls: 'unverified', title: 'Verification method: local history replay is available, but this market is not fully verified yet.' };
                case 'snapshot':
                    return { label: 'Snapshot', cls: 'snapshot', title: 'Yield source: snapshot history plus current live balance adjustment. Not treated as strict verification.' };
                case 'snapshot-partial':
                    return { label: 'Snapshot Partial', cls: 'snapshot', title: 'Yield source: partial snapshot history only. Not treated as strict verification.' };
                case 'acct0-netflow':
                    return { label: 'Acct0 Fallback', cls: 'fallback', title: 'Yield source: legacy acct0 netflow fallback.' };
                case 'all-netflow':
                case 'all-netflow-guarded':
                    return { label: 'Netflow Fallback', cls: 'fallback', title: 'Yield source: full historical netflow fallback.' };
                case 'all-netflow-verified':
                    return { label: 'Netflow Inferred', cls: 'snapshot', title: 'Yield source: public netflow inferred from snapshot history. Not treated as strict verification.' };
                case 'all-netflow-pre-snapshot-carry':
                    return { label: 'Carry Inferred', cls: 'snapshot', title: 'Yield source: public netflow plus inferred pre-snapshot carry from snapshot history. Not treated as strict verification.' };
                case 'recent-cycle':
                    return { label: 'Cycle Fallback', cls: 'fallback', title: 'Yield source: recent-cycle netflow fallback.' };
                case 'recent-cycle-verified':
                    return { label: 'Cycle Inferred', cls: 'snapshot', title: 'Yield source: recent-cycle netflow inferred from snapshot history. Not treated as strict verification.' };
                case 'recent-cycle-pre-snapshot-carry':
                    return { label: 'Cycle Carry', cls: 'snapshot', title: 'Yield source: recent-cycle netflow plus inferred pre-snapshot carry from snapshot history. Not treated as strict verification.' };
                default:
                    return { label: method ? method.replace(/-/g, ' ') : 'No Data', cls: 'unverified', title: 'Yield source unavailable for this market.' };
            }
        }

        function earn_isReplayYieldMethod(method) {
            return [
                'interest-ledger',
                'interest-ledger-live-balance-adjusted',
                'interest-ledger-override',
                'interest-ledger-pending',
                'interest-ledger-unverified',
            ].includes(String(method || ''));
        }

        function earn_renderYieldSourceBadge(yieldCalc, opts) {
            opts = opts || {};
            if (!yieldCalc || !yieldCalc.hasData) return '';
            if (opts.openBorrowRouteYield) {
                const title = 'This yield is accrued inside an open borrow route because the asset is being used as collateral. It is shown separately from normal earned yield until the route is closed or collateral is withdrawn.';
                return `<span class="earn-debug-badge routed" data-tip="${earn_escapeHtml(title)}"><span class="earn-status-dot"></span>Open Route Yield</span>`;
            }
            if (earn_isReplayYieldMethod(yieldCalc.method)) return '';
            const meta = earn_getYieldMethodMeta(yieldCalc.method);
            return `<span class="earn-debug-badge ${meta.cls}" data-tip="${earn_escapeHtml(meta.title)}"><span class="earn-status-dot"></span>${earn_escapeHtml(meta.label)}</span>`;
        }

        function earn_getCompactQualityLabel(label) {
            const value = String(label || '');
            if (value.includes('Netflow')) return 'Netflow';
            if (value.includes('Snapshot')) return 'Snapshot';
            if (value.includes('Inferred')) return 'Inferred';
            if (value.includes('Cycle')) return 'Cycle';
            if (value.includes('Acct0')) return 'Acct0';
            if (value.includes('History replay')) return 'Replay';
            return 'Fallback';
        }

        function earn_renderSupplyQualityCell(marketId, symbol, decimals, yieldCalc, opts) {
            opts = opts || {};
            const markers = [];
            if (opts.positionStatus) {
                markers.push(opts.positionStatus);
            }
            if (earn_replayVerificationReady) {
                const verification = earn_getVerificationPresentation(marketId, yieldCalc, symbol, decimals);
                if (verification && verification.counted) {
                    markers.push({
                        cls: verification.status,
                        label: verification.label,
                        title: verification.title,
                    });
                }
            }
            if (yieldCalc && yieldCalc.hasData && !earn_isReplayYieldMethod(yieldCalc.method)) {
                const source = earn_getYieldMethodMeta(yieldCalc.method);
                const label = earn_getCompactQualityLabel(source.label);
                if (!markers.some(marker => marker.cls === source.cls && marker.label === label)) {
                    markers.push({ cls: source.cls, label, title: source.title });
                }
            }
            if (!markers.length) return '<span class="earn-quality-empty">—</span>';
            return `<div class="earn-quality-cell">${markers.map(marker =>
                `<span class="earn-quality-marker ${marker.cls}" data-tip="${earn_escapeHtml(marker.title)}"><span class="earn-status-dot"></span>${earn_escapeHtml(marker.label)}</span>`
            ).join('')}</div>`;
        }

        function earn_renderDetailsButton(toggleExpression) {
            const chevron = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>';
            return `<button type="button" class="earn-row-details-button" onclick="event.stopPropagation();${toggleExpression}" aria-label="Toggle details"><span class="earn-details-label-show">Details</span><span class="earn-details-label-hide">Hide</span>${chevron}</button>`;
        }

        function earn_formatDebugDelta(value, decimals, symbol) {
            const diff = typeof value === 'bigint' ? value : BigInt(value || '0');
            if (diff === 0n) return '0';
            const sign = diff > 0n ? '+' : '-';
            const abs = earn_absBigInt(diff);
            return `${sign}${earn_formatAmount(abs, decimals, symbol)} ${symbol} · raw ${diff.toString()}`;
        }

        function earn_formatUsdDrift(value) {
            if (value === null || value === undefined) return 'Unavailable';
            const num = Number(value || 0);
            if (!Number.isFinite(num)) return 'Unavailable';
            if (num <= 0) return '$0.00';
            const abs = Math.abs(num);
            const decimals = abs >= 1000 ? 0 : abs >= 1 ? 2 : abs >= 0.01 ? 4 : 6;
            return '$' + abs.toLocaleString('en-US', {
                minimumFractionDigits: decimals,
                maximumFractionDigits: decimals,
            });
        }

        function earn_getSupplyRateData(position) {
            const chainId = document.getElementById('earn-chain')?.value || 'ethereum';
            const tokenAddr = String(position?.tokenAddr || '').toLowerCase();
            const symbolKey = 'sym:' + String(position?.symbol || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
            return earn_marketRates[chainId + ':' + tokenAddr] || earn_marketRates[symbolKey] || null;
        }

        function earn_getRewardTokenUsdPrice(symbol, tokenAddr, chainId) {
            const upper = String(symbol || '').toUpperCase();
            const rewardTokenAddr = String(tokenAddr || '').toLowerCase();
            if (rewardTokenAddr) {
                const directPrice = earn_priceCache[String(chainId || '') + ':' + rewardTokenAddr];
                if (Number.isFinite(directPrice) && directPrice > 0) return directPrice;
            }
            const fallbackPrice = TOKEN_USD_FALLBACK[symbol] || TOKEN_USD_FALLBACK[upper] || 0;
            return Number.isFinite(fallbackPrice) ? fallbackPrice : 0;
        }

        function earn_formatRewardAmountCompact(amount) {
            const value = Number(amount || 0);
            if (!Number.isFinite(value) || value <= 0) return '0';
            if (value >= 1000) return (value / 1000).toFixed(2) + 'K';
            if (value >= 1) return value.toFixed(2);
            if (value >= 0.01) return value.toFixed(4);
            return value.toFixed(6);
        }

        function earn_getRewardUnclaimedForToken(rewardData, tokenAddr, earnedAmount) {
            const addr = String(tokenAddr || '').toLowerCase();
            const earned = Number(earnedAmount || 0);
            const direct = Number(rewardData?.unclaimedPerToken?.[addr] || 0);
            if (direct > 0 || Object.prototype.hasOwnProperty.call(rewardData?.unclaimedPerToken || {}, addr)) {
                return Math.max(0, Math.min(earned, direct));
            }
            const totalAccumulated = Number(rewardData?.accumulated || 0);
            const totalUnclaimed = Number(rewardData?.unclaimed || 0);
            if (!(earned > 0) || !(totalAccumulated > 0) || !(totalUnclaimed > 0)) return 0;
            return Math.max(0, Math.min(earned, totalUnclaimed * (earned / totalAccumulated)));
        }

        function earn_getOdoloChainKey(chainId) {
            const numericId = EARN_DOLO_CHAIN_IDS[String(chainId || '')];
            return numericId ? String(numericId) : '';
        }

        function earn_getOdoloRewardScore(position, rateData) {
            const rewardRate = Math.max(0, Number(rateData?.rewards || 0));
            const usdValue = Math.max(0, Number(position?.usdValue || 0));
            if (!(rewardRate > 0) || !(usdValue > 0)) return 0;
            return rewardRate * usdValue;
        }

        function earn_getOdoloEstimateForPosition(position, rateData, chainId) {
            const chainKey = earn_getOdoloChainKey(chainId);
            if (!chainKey) return null;
            const chainAllocation = parseFloat(earn_odoloAmountPerNetwork?.[chainKey] || '0') || 0;
            if (!(chainAllocation > 0)) return null;
            const positionScore = earn_getOdoloRewardScore(position, rateData);
            if (!(positionScore > 0)) return null;

            let totalScore = 0;
            (earn_cachedAssets || []).forEach(asset => {
                if (!asset || asset.isBorrow || asset.isCollateral) return;
                const assetRateData = earn_getSupplyRateData(asset);
                totalScore += earn_getOdoloRewardScore(asset, assetRateData);
            });
            if (!(totalScore > 0)) totalScore = positionScore;

            const generated = chainAllocation * (positionScore / totalScore);
            if (!(generated > 0.000001)) return null;
            const totalWalletAllocation = Number(earn_odoloCumulative || 0);
            const claimedRatio = totalWalletAllocation > 0
                ? Math.max(0, Math.min(1, Number(earn_odoloClaimed || 0) / totalWalletAllocation))
                : 0;
            const unclaimedRatio = totalWalletAllocation > 0
                ? Math.max(0, Math.min(1, Number(earn_odoloUnclaimed || 0) / totalWalletAllocation))
                : 0;
            return {
                generated,
                claimed: generated * claimedRatio,
                unclaimed: generated * unclaimedRatio,
            };
        }

        function earn_buildSupplyRewardsCard(position) {
            const rateData = earn_getSupplyRateData(position);
            const tokenAddr = String(position?.tokenAddr || '').toLowerCase();
            const chainId = document.getElementById('earn-chain')?.value || 'ethereum';
            const assetSymbol = String(position?.symbol || 'asset');
            const rateLabel = earn_showApy ? 'APY' : 'APR';
            const rowsBySymbol = {};

            const ensureRow = (symbol, defaults) => {
                const key = String(symbol || defaults?.label || 'Reward');
                if (!rowsBySymbol[key]) {
                    rowsBySymbol[key] = {
                        symbol: key,
                        label: defaults?.label || key,
                        icon: defaults?.icon || '',
                        claimUrl: defaults?.claimUrl || '',
                        aprPct: 0,
                        earnedAmount: 0,
                        earnedUsd: 0,
                        hasEarnedData: false,
                        claimedAmount: 0,
                        unclaimedAmount: 0,
                        hasClaimData: false,
                        claimPrecision: 'exact',
                        note: defaults?.note || '',
                        sourceLabel: defaults?.sourceLabel || '',
                        assetSymbol: defaults?.assetSymbol || '',
                    };
                } else {
                    if (!rowsBySymbol[key].icon && defaults?.icon) rowsBySymbol[key].icon = defaults.icon;
                    if (!rowsBySymbol[key].claimUrl && defaults?.claimUrl) rowsBySymbol[key].claimUrl = defaults.claimUrl;
                    if (!rowsBySymbol[key].note && defaults?.note) rowsBySymbol[key].note = defaults.note;
                    if (!rowsBySymbol[key].sourceLabel && defaults?.sourceLabel) rowsBySymbol[key].sourceLabel = defaults.sourceLabel;
                    if (!rowsBySymbol[key].assetSymbol && defaults?.assetSymbol) rowsBySymbol[key].assetSymbol = defaults.assetSymbol;
                }
                return rowsBySymbol[key];
            };

            if (rateData && Array.isArray(rateData.rewardParts)) {
                rateData.rewardParts.forEach(part => {
                    const rewardSymbol = String(part?.symbol || part?.label || 'Reward');
                    const rewardAprPct = Math.max(0, Number(part?.apr || 0) * 100);
                    const icon = SYMBOL_ICONS[rewardSymbol] || SYMBOL_ICONS[rewardSymbol.toUpperCase()] || '';
                    const row = ensureRow(rewardSymbol, {
                        label: rewardSymbol,
                        icon,
                        claimUrl: part?.claimUrl || 'https://app.merkl.xyz/',
                        sourceLabel: part?.sourceLabel || part?.label || '',
                        assetSymbol,
                    });
                    row.aprPct += rewardAprPct;
                });
            }

            Object.entries(earn_merklRewards || {}).forEach(([rewardSymbol, rewardData]) => {
                const exactEarned = rewardData && rewardData.perToken ? Number(rewardData.perToken[tokenAddr] || 0) : 0;
                if (!(exactEarned > 0.000001)) return;
                const rewardTokenAddr = rewardData && rewardData.token ? String(rewardData.token).toLowerCase() : '';
                const icon = SYMBOL_ICONS[rewardSymbol] || SYMBOL_ICONS[rewardSymbol.toUpperCase()] || '';
                const row = ensureRow(rewardSymbol, {
                    label: rewardSymbol,
                    icon,
                    claimUrl: 'https://app.merkl.xyz/',
                    sourceLabel: 'Merkl',
                    assetSymbol,
                });
                row.earnedAmount = exactEarned;
                row.earnedUsd = exactEarned * earn_getRewardTokenUsdPrice(rewardSymbol, rewardTokenAddr, chainId);
                row.hasEarnedData = true;
                row.unclaimedAmount = earn_getRewardUnclaimedForToken(rewardData, tokenAddr, exactEarned);
                row.claimedAmount = Math.max(0, exactEarned - row.unclaimedAmount);
                row.hasClaimData = true;
                row.claimPrecision = 'exact';
            });

            if (rateData && Number(rateData.rewards || 0) > 0) {
                const odoloRow = ensureRow('oDOLO', {
                    label: 'oDOLO',
                    icon: 'odolo-logo-official.svg',
                    claimUrl: 'https://app.dolomite.io/rewards',
                    note: 'Current supplier incentive',
                    assetSymbol,
                });
                odoloRow.aprPct += Math.max(0, Number(rateData.rewards || 0));
                const odoloEstimate = earn_getOdoloEstimateForPosition(position, rateData, chainId);
                if (odoloEstimate) {
                    const DOLO_ADDR = '0x0f81001ef0a83ecce5ccebf63eb302c70a39a654';
                    odoloRow.earnedAmount = odoloEstimate.generated;
                    odoloRow.earnedUsd = odoloEstimate.generated * earn_getRewardTokenUsdPrice('DOLO', DOLO_ADDR, chainId);
                    odoloRow.hasEarnedData = true;
                    odoloRow.claimedAmount = odoloEstimate.claimed;
                    odoloRow.unclaimedAmount = odoloEstimate.unclaimed;
                    odoloRow.hasClaimData = true;
                    odoloRow.claimPrecision = 'estimate';
                    odoloRow.note = 'Estimated generated by this asset';
                }
            }

            const rewardRows = Object.values(rowsBySymbol);
            if (rewardRows.length === 0) return '';

            const rewardPriority = symbol => {
                if (symbol === 'WLFI') return 0;
                if (symbol === 'oDOLO') return 1;
                return 2;
            };
            rewardRows.sort((a, b) => {
                const priorityDiff = rewardPriority(a.symbol) - rewardPriority(b.symbol);
                if (priorityDiff !== 0) return priorityDiff;
                const earnedDiff = (b.earnedUsd || 0) - (a.earnedUsd || 0);
                if (Math.abs(earnedDiff) > 0.0001) return earnedDiff;
                return (b.aprPct || 0) - (a.aprPct || 0);
            });

            const rewardRowsHtml = rewardRows.map(row => {
                const iconHtml = row.icon
                    ? `<img src="${earn_escapeHtml(row.icon)}" alt="${earn_escapeHtml(row.label)}" class="earn-reward-icon" onerror="this.style.display='none'">`
                    : '';
                const displayRate = row.aprPct > 0 ? (earn_showApy ? aprToApy(row.aprPct) : row.aprPct) : 0;
                const rateHtml = row.aprPct > 0.01
                    ? `<span class="earn-reward-rate-positive">+${displayRate.toFixed(2)}% ${rateLabel}</span>`
                    : '<span class="earn-reward-rate-muted">—</span>';

                let sublineHtml = '';
                const statusHtml = row.hasClaimData
                    ? `<div class="earn-reward-state-line">
                        <span class="earn-reward-state-chip claimed"><span>${row.claimPrecision === 'estimate' ? 'Claimed est.' : 'Claimed'}</span><strong>${earn_escapeHtml(earn_formatRewardAmountCompact(row.claimedAmount))}</strong></span>
                        <span class="earn-reward-state-chip unclaimed"><span>${row.claimPrecision === 'estimate' ? 'Unclaimed est.' : 'Unclaimed'}</span><strong>${earn_escapeHtml(earn_formatRewardAmountCompact(row.unclaimedAmount))}</strong></span>
                    </div>`
                    : '';

                if (row.symbol === 'oDOLO' && row.hasEarnedData) {
                    const usdSuffix = row.earnedUsd > 0.01 ? ` · <span class="earn-reward-usd-hint">~${earn_escapeHtml(earn_formatUSD(row.earnedUsd))}</span>` : '';
                    const assetPrefix = row.assetSymbol ? `${earn_escapeHtml(row.assetSymbol)} generated: ~` : 'Generated ~';
                    sublineHtml = `<div class="earn-reward-subline">${assetPrefix}${earn_escapeHtml(earn_formatRewardAmountCompact(row.earnedAmount))} ${earn_escapeHtml(row.label)}${usdSuffix}</div>`;
                } else if (row.symbol === 'oDOLO') {
                    sublineHtml = `<div class="earn-reward-subline note">${earn_escapeHtml(row.note || 'Current supplier incentive')}</div>`;
                } else if (row.hasEarnedData) {
                    const usdSuffix = row.earnedUsd > 0.01 ? ` · <span class="earn-reward-usd-hint">~${earn_escapeHtml(earn_formatUSD(row.earnedUsd))}</span>` : '';
                    const assetPrefix = row.assetSymbol ? `${earn_escapeHtml(row.assetSymbol)} allocation: ` : 'Earned ';
                    sublineHtml = `<div class="earn-reward-subline">${assetPrefix}${earn_escapeHtml(earn_formatRewardAmountCompact(row.earnedAmount))} ${earn_escapeHtml(row.label)}${usdSuffix}</div>`;
                } else if (row.assetSymbol && row.sourceLabel) {
                    sublineHtml = `<div class="earn-reward-subline note">${earn_escapeHtml(row.sourceLabel)} for ${earn_escapeHtml(row.assetSymbol)}</div>`;
                }

                return `<div class="earn-reward-row">
                    <div class="earn-reward-row-top">
                        <div class="earn-reward-identity">
                            ${iconHtml}
                            <span class="earn-reward-name">${earn_escapeHtml(row.label)}</span>
                        </div>
                        <div class="earn-reward-rate">${rateHtml}</div>
                    </div>
                    ${sublineHtml}
                    ${statusHtml}
                </div>`;
            }).join('');

            return `<div class="earn-detail-panel rewards">
                <div class="earn-detail-panel-glow"></div>
                <div class="earn-detail-panel-head">
                    <div class="earn-detail-panel-titlewrap">
                        <div class="earn-detail-panel-icon">
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fbbf24" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v20"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7H14.5a3.5 3.5 0 0 1 0 7H6"/></svg>
                        </div>
                        <div class="earn-detail-panel-label">Reward Yield</div>
                    </div>
                </div>
                <div class="earn-reward-list">${rewardRowsHtml}</div>
            </div>`;
        }

        function earn_buildSupplyDetailRow(idx, position, yieldCalc, explorerUrl, opts) {
            opts = opts || {};
            const decimals = position.decimals ?? 18;
            const symbol = position.symbol || 'UNK';
            const marketId = String(position.marketId);
            const tokenAddr = String(position.tokenAddr || '');
            const methodMeta = earn_getYieldMethodMeta(yieldCalc && yieldCalc.method);
            const verificationPresentation = earn_replayVerificationReady
                ? earn_getVerificationPresentation(marketId, yieldCalc, symbol, decimals)
                : null;
            const verificationStatusLabel = verificationPresentation && verificationPresentation.counted
                ? verificationPresentation.label
                : 'Not checked';
            const verificationStatusClass = verificationPresentation && verificationPresentation.counted
                ? verificationPresentation.status
                : 'unverified';
            const verificationStatusTip = verificationPresentation && verificationPresentation.counted
                ? verificationPresentation.title
                : 'Strict replay verification was not available for this detail row.';
            const rewardsCardHtml = opts.includeRewards === false ? '' : earn_buildSupplyRewardsCard(position);
            const detailId = `${opts.idPrefix || 'earn'}-detail-${idx}`;
            const colSpan = Number(opts.colSpan || 7);
            const isOpenBorrowRouteYield = !!opts.openBorrowRouteYield;
            const yieldPanelLabel = isOpenBorrowRouteYield ? 'Borrow Route Yield' : 'Yield Performance';
            const yieldHeroLabel = isOpenBorrowRouteYield ? 'Open Borrow Collateral Yield' : 'Total Net Yield';
            const hasVerifiedYield = earn_isTrustedInterestLedgerYieldCalc(yieldCalc);
            const heroYield = hasVerifiedYield
                ? (isOpenBorrowRouteYield ? BigInt(yieldCalc.openCollateralYield || '0') : BigInt(yieldCalc.totalYield || '0'))
                : 0n;
            const heroYieldAbs = heroYield < 0n ? -heroYield : heroYield;
            const heroYieldClass = !hasVerifiedYield
                ? ''
                : heroYield >= 0n
                    ? 'positive'
                    : 'negative';
            const heroYieldSign = heroYield > 0n ? '+' : heroYield < 0n ? '-' : '';
            const heroYieldFmt = earn_formatAmount(heroYieldAbs, decimals, symbol);
            const liveEarnClass = hasVerifiedYield
                ? (yieldCalc.openSupplyYield >= 0n ? 'positive' : 'negative')
                : '';
            const settledClass = hasVerifiedYield
                ? (yieldCalc.settledYield >= 0n ? 'positive' : 'negative')
                : '';
            const parkedBorrowClass = hasVerifiedYield
                ? (yieldCalc.openCollateralYield >= 0n ? 'positive' : 'negative')
                : '';

            const metaChips = [];
            if (isOpenBorrowRouteYield) {
                metaChips.push(`<span class="earn-detail-chip routed" data-tip="${earn_escapeHtml('This yield is still inside an open borrow route and is not treated as free/closed Total Yield Earned until collateral leaves the route.')}">Open Route</span>`);
            } else if (yieldCalc && yieldCalc.openBorrowRouteYieldExcluded) {
                metaChips.push(`<span class="earn-detail-chip routed" data-tip="${earn_escapeHtml('Open borrow-route collateral yield is separated from Total Yield Earned while the route remains open.')}">Route Separated</span>`);
            }
            if (verificationPresentation && verificationPresentation.counted) {
                metaChips.push(`<span class="earn-detail-chip ${verificationStatusClass}" data-tip="${earn_escapeHtml(verificationStatusTip)}">${earn_escapeHtml(verificationStatusLabel)}</span>`);
            }

            const copySvg = '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"></path></svg>';
            const detailAddress = tokenAddr
                ? `<div class="earn-ca-line">
                        <a href="${earn_escapeHtml(explorerUrl)}" target="_blank" rel="noopener" class="earn-ca-addr addr-tooltip-wrap" data-full-addr="${earn_escapeHtml(tokenAddr)}" onclick="event.stopPropagation()">${earn_escapeHtml(vedolo_shortAddr(tokenAddr))}</a>
                        <span class="copy-addr-icon" onclick="event.stopPropagation();earn_copyAddr('${earn_escapeHtml(tokenAddr)}',this)">${copySvg}</span>
                        <a href="${earn_escapeHtml(explorerUrl)}" target="_blank" rel="noopener" class="earn-ca-explorer" onclick="event.stopPropagation()">
                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>
                        </a>
                    </div>`
                : '<span style="color:var(--text-muted)">Unavailable</span>';

            const breakdownHtml = earn_buildBreakdown(marketId, decimals, symbol);

            return `<tr class="earn-detail-row" id="${detailId}" data-earn-layout-detail>
                <td colspan="${colSpan}">
                    <div class="earn-detail-stack">
                        <div class="earn-detail-panels">
                            <div class="earn-detail-panel metrics">
                                <div class="earn-detail-panel-head">
                                    <div class="earn-detail-panel-titlewrap">
                                        <div class="earn-detail-panel-icon">
                                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.6)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"></rect><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"></path></svg>
                                        </div>
                                        <div class="earn-detail-panel-label">Asset Metrics</div>
                                    </div>
                                </div>

                                <div class="earn-detail-rowline">
                                    <span class="earn-detail-rowline-label">Token address</span>
                                    <span class="earn-detail-rowline-value" style="font-family:inherit">${detailAddress}</span>
                                </div>
                                <div class="earn-detail-rowline">
                                    <span class="earn-detail-rowline-label">Market id</span>
                                    <span class="earn-detail-rowline-value" style="font-family:var(--font-mono); color:var(--text-muted)">#${earn_escapeHtml(marketId)}</span>
                                </div>
                                <div class="earn-detail-rowline">
                                    <span class="earn-detail-rowline-label">Visible balance</span>
                                    <span class="earn-detail-rowline-value" style="color:#fff;font-weight:500;">${earn_escapeHtml(earn_formatAmount(position.wei, decimals, symbol))} <span style="font-size:11px;color:var(--text-muted)">${earn_escapeHtml(symbol)}</span></span>
                                </div>
                                <div class="earn-detail-rowline">
                                    <span class="earn-detail-rowline-label">Current Usd value</span>
                                    <span class="earn-detail-rowline-value" style="color:rgba(255,255,255,0.72);font-weight:500;">≈ $${Number(position.usdValue || 0).toLocaleString('en-US', { minimumFractionDigits: Number(position.usdValue || 0) >= 1 ? 2 : 4, maximumFractionDigits: Number(position.usdValue || 0) >= 1 ? 2 : 4 })}</span>
                                </div>
                                <div class="earn-detail-rowline">
                                    <span class="earn-detail-rowline-label">Verification status</span>
                                    <span class="earn-detail-rowline-value ${verificationStatusClass}" data-tip="${earn_escapeHtml(verificationStatusTip)}">${earn_escapeHtml(verificationStatusLabel)}</span>
                                </div>
                                <div class="earn-detail-rowline">
                                    <span class="earn-detail-rowline-label">Verification method</span>
                                    <span class="earn-detail-rowline-value" data-tip="${earn_escapeHtml(methodMeta.title)}">${yieldCalc && yieldCalc.hasData ? earn_escapeHtml(methodMeta.label) : 'Unavailable'}</span>
                                </div>
                            </div>

                            <div class="earn-detail-panel primary">
                                <div class="earn-detail-panel-glow"></div>
                                <div class="earn-detail-panel-head">
                                    <div class="earn-detail-panel-titlewrap">
                                        <div class="earn-detail-panel-icon">
                                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#34d399" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"></polyline><polyline points="17 6 23 6 23 12"></polyline></svg>
                                        </div>
                                        <div class="earn-detail-panel-label">${yieldPanelLabel}</div>
                                    </div>
                                    <div class="earn-detail-meta">${metaChips.join('')}</div>
                                </div>

                                <div class="earn-detail-hero">
                                    <div class="earn-detail-hero-label">${yieldHeroLabel}</div>
                                    <div class="earn-detail-hero-value ${heroYieldClass}">${hasVerifiedYield ? `${heroYieldSign}${heroYieldFmt} <span style="font-size:12px;color:currentColor;opacity:0.72;font-weight:600">${symbol}</span>` : '—'}</div>
                                </div>

                                <div class="earn-detail-rowline">
                                    <span class="earn-detail-rowline-label" style="color:rgba(255,255,255,0.5)">Settled before moves</span>
                                    <span class="earn-detail-rowline-value ${settledClass}">${hasVerifiedYield ? `${yieldCalc.settledYield > 0n ? '+' : yieldCalc.settledYield < 0n ? '-' : ''}${earn_formatAmount(earn_absBigInt(yieldCalc.settledYield), decimals, symbol)} ${symbol}` : '—'}</span>
                                </div>
                                <div class="earn-detail-rowline">
                                    <span class="earn-detail-rowline-label" style="color:rgba(255,255,255,0.5)">Live in active earn</span>
                                    <span class="earn-detail-rowline-value ${liveEarnClass}">${hasVerifiedYield ? `${yieldCalc.openSupplyYield > 0n ? '+' : yieldCalc.openSupplyYield < 0n ? '-' : ''}${earn_formatAmount(earn_absBigInt(yieldCalc.openSupplyYield), decimals, symbol)} ${symbol}` : '—'}</span>
                                </div>
                                <div class="earn-detail-rowline">
                                    <span class="earn-detail-rowline-label" style="color:rgba(255,255,255,0.5)">Open borrow collateral yield</span>
                                    <span class="earn-detail-rowline-value ${parkedBorrowClass}">${hasVerifiedYield ? `${yieldCalc.openCollateralYield > 0n ? '+' : yieldCalc.openCollateralYield < 0n ? '-' : ''}${earn_formatAmount(earn_absBigInt(yieldCalc.openCollateralYield), decimals, symbol)} ${symbol}` : '—'}</span>
                                </div>
                            </div>
                            ${rewardsCardHtml}
                        </div>
                        ${breakdownHtml}
                    </div>
                </td>
            </tr>`;
        }

        function earn_buildReplayVerification(actualSupplyMap, actualBorrowMap, actualCollateralMap) {
            actualSupplyMap = actualSupplyMap || {};
            actualBorrowMap = actualBorrowMap || {};
            actualCollateralMap = actualCollateralMap || {};

            const verificationData = {};
            const summary = { total: 0, verified: 0, mismatch: 0, unverified: 0 };
            let hasReplayVerificationInputs = false;
            const marketIds = new Set([
                ...Object.keys(earn_replayStateData || {}),
                ...Object.keys(earn_interestYieldData || {}),
                ...Object.keys(actualSupplyMap || {}),
                ...Object.keys(actualBorrowMap || {}),
                ...Object.keys(actualCollateralMap || {}),
            ]);

            marketIds.forEach(mid => {
                const replay = (earn_replayStateData && earn_replayStateData[mid]) || {};
                const interest = (earn_interestYieldData && earn_interestYieldData[mid]) || {};
                const actualSupply = actualSupplyMap[mid] || null;
                const actualBorrow = actualBorrowMap[mid] || null;
                const actualCollateral = actualCollateralMap[mid] || null;
                const meta = earn_subgraphTokens[mid] || {};
                const decimals = meta.decimals || 18;
                const symbol = actualSupply?.symbol || actualCollateral?.symbol || actualBorrow?.symbol || meta.symbol || 'UNK';
                const tokenAddr = actualSupply?.tokenAddr || actualCollateral?.tokenAddr || actualBorrow?.tokenAddr || meta.tokenAddr || '';
                const chainId = document.getElementById('earn-chain')?.value || 'ethereum';

                const expectedSupplyPar = BigInt(replay.expectedSupplyPar || '0');
                const expectedSupplyWei = BigInt(replay.expectedSupplyWei || '0');
                const expectedCollateralPar = BigInt(replay.expectedCollateralSupplyPar || '0');
                const expectedCollateralWei = BigInt(replay.expectedCollateralSupplyWei || '0');
                const expectedBorrowPar = BigInt(replay.expectedBorrowPar || '0');
                const expectedBorrowWei = BigInt(replay.expectedBorrowWei || '0');
                const actualSupplyPar = actualSupply ? BigInt(actualSupply.par || '0') : 0n;
                const actualSupplyWei = actualSupply ? BigInt(actualSupply.wei || '0') : 0n;
                const actualCollateralPar = actualCollateral ? BigInt(actualCollateral.par || '0') : 0n;
                const actualCollateralWei = actualCollateral ? BigInt(actualCollateral.wei || '0') : 0n;
                const actualBorrowPar = actualBorrow ? earn_absBigInt(BigInt(actualBorrow.par || '0')) : 0n;
                const actualBorrowWei = actualBorrow ? earn_absBigInt(BigInt(actualBorrow.wei || '0')) : 0n;
                const settledYield = BigInt(interest.settledYield || '0');
                const hasReplayData = replay.expectedSupplyPar !== undefined ||
                    replay.expectedBorrowPar !== undefined ||
                    interest.earnYield !== undefined;
                if (hasReplayData) hasReplayVerificationInputs = true;
                const hasEarnExposure = !!(
                    replay.hadSupply ||
                    expectedSupplyPar > 0n ||
                    expectedCollateralPar > 0n ||
                    actualSupplyPar > 0n ||
                    actualCollateralPar > 0n ||
                    actualSupplyWei > 0n ||
                    actualCollateralWei > 0n ||
                    settledYield !== 0n
                );

                const supplyParDiff = actualSupplyPar - expectedSupplyPar;
                const supplyWeiDiff = actualSupplyWei - expectedSupplyWei;
                const collateralParDiff = actualCollateralPar - expectedCollateralPar;
                const collateralWeiDiff = actualCollateralWei - expectedCollateralWei;
                const borrowParDiff = actualBorrowPar - expectedBorrowPar;
                const borrowWeiDiff = actualBorrowWei - expectedBorrowWei;
                const parTolerance = earn_getVerificationParTolerance();
                const supplyWeiTolerance = earn_getVerificationWeiTolerance(decimals, actualSupplyWei, expectedSupplyWei);
                const collateralWeiTolerance = earn_getVerificationWeiTolerance(decimals, actualCollateralWei, expectedCollateralWei);
                const borrowWeiTolerance = earn_getVerificationWeiTolerance(decimals, actualBorrowWei, expectedBorrowWei);
                const canVerify = hasReplayData && replay.canVerify !== false;
                const rawVerified = canVerify &&
                    earn_absBigInt(supplyParDiff) <= parTolerance &&
                    earn_absBigInt(collateralParDiff) <= parTolerance &&
                    earn_absBigInt(borrowParDiff) <= parTolerance &&
                    earn_absBigInt(supplyWeiDiff) <= supplyWeiTolerance &&
                    earn_absBigInt(collateralWeiDiff) <= collateralWeiTolerance &&
                    earn_absBigInt(borrowWeiDiff) <= borrowWeiTolerance;
                const priceUsd = earn_getUsdPrice(symbol, tokenAddr, chainId);
                const hasUsdDrift = Number.isFinite(priceUsd) && priceUsd > 0;
                const scale = Math.pow(10, Math.max(0, Number(decimals || 18)));
                const supplyUsdDrift = hasUsdDrift && scale > 0 ? (Number(earn_absBigInt(supplyWeiDiff)) / scale) * priceUsd : null;
                const collateralUsdDrift = hasUsdDrift && scale > 0 ? (Number(earn_absBigInt(collateralWeiDiff)) / scale) * priceUsd : null;
                const borrowUsdDrift = hasUsdDrift && scale > 0 ? (Number(earn_absBigInt(borrowWeiDiff)) / scale) * priceUsd : null;
                const maxUsdDrift = hasUsdDrift ? Math.max(supplyUsdDrift || 0, collateralUsdDrift || 0, borrowUsdDrift || 0) : null;
                const usdVerificationThreshold = 1;
                const usdDriftVerified = canVerify && hasUsdDrift && maxUsdDrift < usdVerificationThreshold;
                const subgraphReplayTruncated = earn_replaySubgraphHistoryIncomplete
                    || earn_replayTruncatedSubgraphMarkets.has(String(mid));
                const replayStateAdjusted = earn_replayReconciledMarkets.has(String(mid));
                const snapshotIncomplete = earn_replayVerificationIncompleteMarkets.has(String(mid))
                    || subgraphReplayTruncated
                    || replayStateAdjusted;

                verificationData[mid] = {
                    status: 'unverified',
                    strictStatus: 'unverified',
                    counted: hasEarnExposure,
                    canVerify,
                    decimals,
                    expectedSupplyPar,
                    expectedSupplyWei,
                    expectedCollateralPar,
                    expectedCollateralWei,
                    expectedBorrowPar,
                    expectedBorrowWei,
                    actualSupplyPar,
                    actualSupplyWei,
                    actualCollateralPar,
                    actualCollateralWei,
                    actualBorrowPar,
                    actualBorrowWei,
                    supplyParDiff,
                    supplyWeiDiff,
                    collateralParDiff,
                    collateralWeiDiff,
                    borrowParDiff,
                    borrowWeiDiff,
                    parTolerance,
                    supplyWeiTolerance,
                    collateralWeiTolerance,
                    borrowWeiTolerance,
                    rawVerified,
                    strictVerified: canVerify && !snapshotIncomplete && rawVerified,
                    hasUsdDrift,
                    usdDriftVerified,
                    snapshotIncomplete,
                    subgraphReplayTruncated,
                    replayStateAdjusted,
                    usdVerificationThreshold,
                    supplyUsdDrift,
                    collateralUsdDrift,
                    borrowUsdDrift,
                    maxUsdDrift,
                };
                const strictStatus = earn_getStrictVerificationStatus(verificationData[mid]);
                verificationData[mid].strictStatus = strictStatus;
                verificationData[mid].status = !hasEarnExposure ? 'unverified' : strictStatus;
                verificationData[mid].strictVerified = strictStatus === 'verified';

                if (!hasEarnExposure) return;
                summary.total++;
                summary[verificationData[mid].status] = (summary[verificationData[mid].status] || 0) + 1;
            });

            earn_replayVerificationData = verificationData;
            earn_replayVerificationSummary = summary;
            earn_replayVerificationReady = hasReplayVerificationInputs;
        }

        function earn_refreshReplayVerificationFromCachedPositions() {
            if (
                Object.keys(earn_replayActualSupplyMap || {}).length > 0 ||
                Object.keys(earn_replayActualBorrowMap || {}).length > 0 ||
                Object.keys(earn_replayActualCollateralMap || {}).length > 0
            ) {
                earn_buildReplayVerification(
                    earn_replayActualSupplyMap,
                    earn_replayActualBorrowMap,
                    earn_replayActualCollateralMap
                );
                return;
            }
            const actualSupplyMap = {};
            const actualBorrowMap = {};
            const actualCollateralMap = {};

            (earn_cachedAssets || []).forEach(pos => {
                const mid = String(pos.marketId);
                if (pos.isBorrow) {
                    actualBorrowMap[mid] = {
                        ...pos,
                        par: pos.par,
                        wei: pos.wei,
                    };
                } else if (pos.isCollateral) {
                    actualCollateralMap[mid] = {
                        ...pos,
                        par: pos.par,
                        wei: pos.wei,
                    };
                } else if (!pos.isCollateral) {
                    actualSupplyMap[mid] = {
                        ...pos,
                        par: pos.par,
                        wei: pos.wei,
                    };
                }
            });

            (earn_borrowPositionData || []).forEach(pos => {
                const mid = String(pos.marketId);
                if (!actualBorrowMap[mid]) {
                    actualBorrowMap[mid] = {
                        ...pos,
                        par: pos.par,
                        wei: pos.wei,
                    };
                }
            });

            (earn_collateralPositionData || []).forEach(pos => {
                const mid = String(pos.marketId);
                if (!actualCollateralMap[mid]) {
                    actualCollateralMap[mid] = {
                        ...pos,
                        par: pos.par,
                        wei: pos.wei,
                    };
                }
            });

            earn_buildReplayVerification(actualSupplyMap, actualBorrowMap, actualCollateralMap);
        }

        function earn_reconcileReplayToCachedCurrentPositions() {
            if (!earn_replayCurrentPositions || earn_replayCurrentPositions.length === 0) return 0;
            return earn_reconcileReplayToCurrentPositions(
                earn_replayCurrentPositions,
                { borrowAccounts: earn_replayCurrentBorrowAccounts || new Set() }
            );
        }

        function earn_parseNetflowEntry(flowData) {
            if (flowData === undefined || flowData === null) return null;
            if (typeof flowData === 'string') {
                return {
                    netFlow: BigInt(flowData),
                    hasBreakdown: false,
                    totalDeposited: 0n,
                    totalWithdrawn: 0n,
                    totalBorrowed: 0n,
                    totalSwapped: 0n,
                    totalTransferred: 0n,
                    totalLiquidated: 0n,
                    totalVaporized: 0n,
                    recentCycleNetFlow: null,
                    resetPar: null,
                    endingPar: null,
                };
            }
            return {
                netFlow: BigInt(flowData.t || '0'),
                hasBreakdown: true,
                totalDeposited: BigInt(flowData.d || '0'),
                totalWithdrawn: BigInt(flowData.w || '0'),
                totalBorrowed: BigInt(flowData.b || '0'),
                totalSwapped: BigInt(flowData.s || '0'),
                totalTransferred: BigInt(flowData.x || '0'),
                totalLiquidated: BigInt(flowData.l || '0'),
                totalVaporized: BigInt(flowData.v || '0'),
                recentCycleNetFlow: flowData.recentNetFlow !== undefined ? BigInt(flowData.recentNetFlow || '0') : null,
                resetPar: flowData.resetPar !== undefined ? BigInt(flowData.resetPar || '0') : null,
                endingPar: flowData.endingPar !== undefined ? BigInt(flowData.endingPar || '0') : null,
            };
        }

        function earn_calculateYield(position, opts) {
            opts = opts || {};

            const mid = String(position.marketId);
            const symbol = position.symbol || earn_subgraphTokens[mid]?.symbol || 'UNK';
            const decimals = position.decimals ?? earn_subgraphTokens[mid]?.decimals ?? 18;
            const tokenAddr = position.tokenAddr || earn_subgraphTokens[mid]?.tokenAddr || '';
            const chainId = opts.chainId || document.getElementById('earn-chain')?.value || 'ethereum';
            const weiSource = position.currentWei !== undefined ? position.currentWei : position.wei;
            const wei = typeof weiSource === 'bigint' ? weiSource : BigInt(weiSource || '0');

            const parSource = position.currentPar !== undefined ? position.currentPar : position.par;
            const hasPar = parSource !== undefined && parSource !== null;
            const par = hasPar ? (typeof parSource === 'bigint' ? parSource : BigInt(parSource || '0')) : null;

            const acct0Raw = earn_acct0NetflowData && earn_acct0NetflowData[mid] !== undefined
                ? earn_acct0NetflowData[mid]
                : null;
            const hasAcct0Netflow = acct0Raw !== null;

            const flowMeta = earn_parseNetflowEntry(earn_netflowData && earn_netflowData[mid]);
            const hasAllNetflow = !!flowMeta;
            const interestMeta = earn_interestYieldData && earn_interestYieldData[mid];
            const hasInterestYield = !!(interestMeta && interestMeta.earnYield !== undefined);
            const requireVerifiedInterest = opts.requireVerifiedInterest !== false;
            const interestTrust = earn_getInterestLedgerTrust(mid, { requireVerifiedInterest });

            const hist = earn_totalYieldData && earn_totalYieldData[mid];
            const hasSnapshotData = hist && hist.cumulativeYield !== undefined;
            const snapshotStatus = hasSnapshotData ? String(hist.verificationStatus || '') : '';
            const snapshotMismatch = snapshotStatus === 'mismatch';
            const snapshotIsLatest = hasSnapshotData ? (hist.isLatestSnapshot !== false) : true;
            const snapshotHasHistory = hasSnapshotData ? earn_hasSufficientSnapshotHistory(hist) : false;
            const snapshotTrusted = !!(hasSnapshotData && snapshotHasHistory && snapshotIsLatest && (
                !snapshotStatus ||
                snapshotStatus === 'verified' ||
                snapshotStatus === 'pre_snapshot_carry' ||
                snapshotStatus === 'no_netflow'
            ));
            const publicLedgerInference = earn_getPublicLedgerInference(hist, flowMeta, decimals);

            let totalYield = null;
            let method = null;
            const isActivePosition = wei > 0n;
            const allowAcct0Netflow = !!opts.allowAcct0Netflow;

            const isReasonableActiveYield = (candidate) => {
                if (!isActivePosition) return true;
                const absCandidate = candidate < 0n ? -candidate : candidate;
                const rawUnit = 10n ** BigInt(Math.min(decimals, 6));
                const maxReasonable = wei * 10n + rawUnit * 100n;
                return absCandidate <= maxReasonable;
            };

            let snapshotCandidate = null;
            let snapshotMethod = null;
            if (hasSnapshotData && snapshotHasHistory) {
                const baseSnapshotYield = BigInt(hist.cumulativeYield);
                const lastPar = BigInt(hist.lastPar || '0');
                const lastWei = BigInt(hist.lastWei || '0');
                if (par !== null && par !== 0n && lastPar !== 0n) {
                    const parDiff = lastPar > par ? lastPar - par : par - lastPar;
                    const canApplyLive = parDiff * 20n <= lastPar;
                    if (canApplyLive) {
                        snapshotCandidate = baseSnapshotYield;
                        const liveYield = (lastPar * wei - lastWei * par) / par;
                        snapshotCandidate += liveYield;
                        snapshotMethod = 'snapshot';
                    }
                } else {
                    snapshotCandidate = baseSnapshotYield;
                    snapshotMethod = 'snapshot-partial';
                }
            }

            const allNetflowCandidate = hasAllNetflow ? (wei - flowMeta.netFlow) : null;
            const recentCycleCandidate = (isActivePosition && hasAllNetflow && flowMeta.recentCycleNetFlow !== null)
                ? (wei - flowMeta.recentCycleNetFlow)
                : null;
            const interestYieldCandidate = hasInterestYield ? BigInt(interestMeta.earnYield || '0') : null;
            const canUseVerifiedInterest = interestYieldCandidate !== null && interestTrust.trusted;
            const canOverrideMismatchedSnapshot = canUseVerifiedInterest && snapshotMismatch;
            const canUseUnverifiedInterest = interestYieldCandidate !== null && !interestTrust.trusted && !requireVerifiedInterest;
            const replayVerificationPending = interestTrust.status === 'pending';
            const alignedReplayWeiDrift = earn_getAlignedReplayWeiDriftAdjustment(interestTrust.entry);
            const adjustedInterestYieldCandidate = interestYieldCandidate !== null && alignedReplayWeiDrift
                ? interestYieldCandidate + alignedReplayWeiDrift.totalYieldCorrection
                : interestYieldCandidate;
            const hasComplexNetflow = !!(flowMeta && flowMeta.hasBreakdown && (
                flowMeta.totalBorrowed !== 0n ||
                flowMeta.totalSwapped !== 0n ||
                flowMeta.totalTransferred !== 0n ||
                flowMeta.totalLiquidated !== 0n ||
                flowMeta.totalVaporized !== 0n
            ));
            const allowHistoricalNetflowFallback = !(opts.applyHistoryGuards && !isActivePosition && hasComplexNetflow);
            const shouldDeferFallbackUntilReplaySettles = requireVerifiedInterest
                && earn_totalYieldStatus === 'loading'
                && !publicLedgerInference;
            const shouldBlockProvisionalFallback = requireVerifiedInterest
                && replayVerificationPending
                && interestYieldCandidate !== null
                && !canUseVerifiedInterest
                && !canOverrideMismatchedSnapshot
                && !publicLedgerInference;
            const shouldHoldActiveYieldForReplay = earn_shouldHoldActiveYieldForReplaySettlement({
                requireVerifiedInterest,
                isActivePosition,
                publicLedgerInference,
                canUseVerifiedInterest,
                canOverrideMismatchedSnapshot,
                hasSnapshotData,
                hasAllNetflow,
                hasAcct0Netflow,
                hasInterestYield,
                snapshotTrusted,
            });

            if (shouldDeferFallbackUntilReplaySettles || shouldBlockProvisionalFallback || shouldHoldActiveYieldForReplay) {
                return {
                    hasData: false,
                    method: 'interest-ledger-pending',
                    totalYield: 0n,
                    yieldUsdScaled: 0n,
                    yieldUsd: 0,
                    symbol,
                    decimals,
                    tokenAddr,
                    verificationStatus: 'pending',
                };
            }

            if (canUseVerifiedInterest || canOverrideMismatchedSnapshot) {
                totalYield = adjustedInterestYieldCandidate;
                method = alignedReplayWeiDrift
                    ? 'interest-ledger-live-balance-adjusted'
                    : (canOverrideMismatchedSnapshot ? 'interest-ledger-override' : 'interest-ledger');
            } else if (publicLedgerInference && publicLedgerInference.status === 'verified') {
                totalYield = publicLedgerInference.canonicalYield;
                method = publicLedgerInference.verificationBaseline === 'recent-cycle'
                    ? 'recent-cycle-verified'
                    : 'all-netflow-verified';
            } else if (publicLedgerInference && publicLedgerInference.status === 'pre_snapshot_carry') {
                totalYield = publicLedgerInference.canonicalYield;
                method = publicLedgerInference.verificationBaseline === 'recent-cycle'
                    ? 'recent-cycle-pre-snapshot-carry'
                    : 'all-netflow-pre-snapshot-carry';
            } else if (snapshotTrusted && snapshotCandidate !== null && isReasonableActiveYield(snapshotCandidate)) {
                totalYield = snapshotCandidate;
                method = snapshotMethod;
            } else if (allowAcct0Netflow && hasAcct0Netflow) {
                totalYield = wei - BigInt(acct0Raw);
                method = 'acct0-netflow';
            } else if (allowHistoricalNetflowFallback && allNetflowCandidate !== null && isReasonableActiveYield(allNetflowCandidate)) {
                totalYield = allNetflowCandidate;
                method = 'all-netflow';
            } else if (allowHistoricalNetflowFallback && recentCycleCandidate !== null && isReasonableActiveYield(recentCycleCandidate)) {
                totalYield = recentCycleCandidate;
                method = 'recent-cycle';
            } else if (canUseUnverifiedInterest) {
                // Last resort for diagnostics-only paths where caller explicitly allows it.
                totalYield = interestYieldCandidate;
                method = 'interest-ledger-unverified';
            }

            if (totalYield === null) {
                return {
                    hasData: false,
                    method: null,
                    totalYield: 0n,
                    yieldUsdScaled: 0n,
                    yieldUsd: 0,
                    symbol,
                    decimals,
                    tokenAddr,
                    verificationStatus: interestTrust.status,
                };
            }

            if (opts.applyHistoryGuards && method === 'all-netflow' && flowMeta && flowMeta.hasBreakdown && flowMeta.totalWithdrawn > flowMeta.totalDeposited) {
                totalYield = 0n;
                method = 'all-netflow-guarded';
            }

            const settledYield = interestMeta ? BigInt(interestMeta.settledYield || '0') : 0n;
            let openSupplyYield = interestMeta ? BigInt(interestMeta.openSupplyYield || '0') : 0n;
            let openCollateralYield = interestMeta ? BigInt(interestMeta.openCollateralYield || '0') : 0n;
            let openBorrowYield = interestMeta ? BigInt(interestMeta.openBorrowYield || '0') : 0n;
            if (alignedReplayWeiDrift && method === 'interest-ledger-live-balance-adjusted') {
                openSupplyYield += alignedReplayWeiDrift.supplyYieldCorrection;
                openCollateralYield += alignedReplayWeiDrift.collateralYieldCorrection;
                openBorrowYield += alignedReplayWeiDrift.borrowYieldCorrection;
            }

            const rawTotalYield = totalYield;
            const replayMethodHasOpenRouteBuckets = (
                method === 'interest-ledger'
                || method === 'interest-ledger-override'
                || method === 'interest-ledger-live-balance-adjusted'
            );
            const openBorrowRouteYieldExcluded = replayMethodHasOpenRouteBuckets && openCollateralYield !== 0n;
            if (openBorrowRouteYieldExcluded) {
                totalYield -= openCollateralYield;
            }

            const price = earn_getUsdPrice(symbol, tokenAddr, chainId);
            const yieldUsdScaled = earn_getUsdValueScaled(totalYield, decimals, price);
            const rawYieldUsdScaled = earn_getUsdValueScaled(rawTotalYield, decimals, price);
            const openCollateralYieldUsdScaled = earn_getUsdValueScaled(openCollateralYield, decimals, price);
            const yieldUsd = earn_scaledUsdToNumber(yieldUsdScaled);
            const rawYieldUsd = earn_scaledUsdToNumber(rawYieldUsdScaled);
            const openCollateralYieldUsd = earn_scaledUsdToNumber(openCollateralYieldUsdScaled);
            const absYield = totalYield < 0n ? -totalYield : totalYield;
            const canonicalHistoryCoverageStatus = earn_getCanonicalSubaccountHistoryCoverageStatus();
            const requiresCanonicalHistoryForReplay = (
                method === 'interest-ledger'
                || method === 'interest-ledger-override'
                || method === 'interest-ledger-live-balance-adjusted'
            ) && earn_positionRequiresCanonicalBorrowRouting(position);
            const canonicalHistoryCoverageIncomplete = requiresCanonicalHistoryForReplay
                && canonicalHistoryCoverageStatus !== 'fresh';
            const strictVerificationStatus = (method === 'interest-ledger' || method === 'interest-ledger-override')
                ? (canonicalHistoryCoverageIncomplete ? 'coverage_incomplete' : (interestTrust.status || 'unverified'))
                : method === 'interest-ledger-live-balance-adjusted'
                    ? 'coverage_incomplete'
                    : publicLedgerInference
                        ? (
                            publicLedgerInference.status === 'verified'
                                ? (canonicalHistoryCoverageIncomplete ? 'coverage_incomplete' : 'inferred')
                                : 'inferred'
                        )
                        : (method === 'snapshot' || method === 'snapshot-partial')
                            ? 'coverage_incomplete'
                            : (method === 'all-netflow' || method === 'all-netflow-guarded' || method === 'recent-cycle' || method === 'acct0-netflow')
                                ? 'fallback'
                                : (interestTrust.status || snapshotStatus || 'unverified');
            const strictTrustedForTotal = earn_isTrustedReplayYieldStatus(strictVerificationStatus);

            return {
                hasData: true,
                method,
                totalYield,
                rawTotalYield,
                absYield,
                yieldUsdScaled,
                rawYieldUsdScaled,
                yieldUsd,
                rawYieldUsd,
                settledYield,
                openSupplyYield,
                openCollateralYield,
                openCollateralYieldUsdScaled,
                openCollateralYieldUsd,
                openBorrowYield,
                countableYield: totalYield,
                countableYieldUsdScaled: yieldUsdScaled,
                countableYieldUsd: yieldUsd,
                openBorrowRouteYieldExcluded,
                yieldPositive: totalYield >= 0n,
                yieldSign: totalYield > 0n ? '+' : totalYield < 0n ? '-' : '',
                yieldColor: totalYield >= 0n ? 'earn-yield-positive' : 'earn-yield-negative',
                yieldFmt: earn_formatAmount(absYield, decimals, symbol),
                symbol,
                decimals,
                tokenAddr,
                publicLedgerInference,
                verificationStatus: strictVerificationStatus,
                trustedForTotal: strictTrustedForTotal,
                canonicalHistoryCoverageStatus,
                canonicalHistoryRequiresFreshForBorrowRouting: requiresCanonicalHistoryForReplay,
                canonicalHistoryLastScannedBlock: earn_canonicalSubaccountHistoryLastScannedBlock === null
                    ? null
                    : String(earn_canonicalSubaccountHistoryLastScannedBlock),
                canonicalHistoryFreshForBorrowRouting: !!earn_canonicalSubaccountHistoryFreshForBorrowRouting,
            };
        }

        function earn_createVerifiedYieldCalcCache() {
            const cache = new WeakMap();
            return position => {
                if (!cache.has(position)) {
                    cache.set(position, earn_calculateYield(position, { requireVerifiedInterest: true }));
                }
                return cache.get(position);
            };
        }

        function earn_refreshHistoryYieldData() {
            if (!earn_historyData || earn_historyData.length === 0) {
                earn_refreshResolvedTotalYieldData();
                return;
            }

            earn_historyData.forEach(item => {
                const calc = earn_calculateYield({
                    marketId: item.marketId,
                    tokenAddr: item.tokenAddr,
                    symbol: item.symbol,
                    decimals: item.decimals,
                    currentWei: item.currentWei,
                    currentPar: item.currentPar,
                }, { applyHistoryGuards: true });
                const displayYieldWei = item.isCollateralized && calc.openCollateralYield !== undefined
                    ? BigInt(calc.openCollateralYield || '0')
                    : BigInt(calc.totalYield || '0');
                const displayYieldUsdScaled = item.isCollateralized && calc.openCollateralYieldUsdScaled !== undefined
                    ? BigInt(calc.openCollateralYieldUsdScaled || '0')
                    : BigInt(calc.yieldUsdScaled || '0');

                item.hasYieldData = calc.hasData;
                item.yieldMethod = calc.method;
                item.yieldTrustedForDisplay = earn_isTrustedInterestLedgerYieldCalc(calc);
                item.yieldWei = calc.hasData ? displayYieldWei : 0n;
                item.yieldUsdScaled = calc.hasData ? displayYieldUsdScaled : 0n;
                item.yieldUsd = calc.hasData ? earn_scaledUsdToNumber(displayYieldUsdScaled) : 0;
                item.countableYieldWei = calc.countableYield !== undefined ? calc.countableYield : calc.totalYield;
                item.rawTotalYieldWei = calc.rawTotalYield !== undefined ? calc.rawTotalYield : calc.totalYield;
                item.openCollateralYieldWei = calc.openCollateralYield !== undefined ? calc.openCollateralYield : 0n;
            });

            earn_historyData.sort((a, b) => earn_compareBigInt(b.yieldUsdScaled || 0n, a.yieldUsdScaled || 0n));
            earn_refreshResolvedTotalYieldData();
        }

        function earn_showError(msg) {
            earn_lookupLoading = false;
            earn_lookupUsingCachedSnapshot = false;
            document.getElementById('earn-results').classList.remove('visible');
            document.getElementById('earn-empty').classList.remove('visible');
            const el = document.getElementById('earn-error');
            document.getElementById('earn-error-msg').textContent = msg;
            el.classList.add('visible');
            earn_updateLookupRefreshBadge();
        }

        // Period state
        let earn_currentPeriod = '1';
        let earn_cachedAssets = null;
        let earn_sortKey = 'balance'; // 'balance' or 'yield' or 'apr'
        let earn_sortDesc = true; // true = descending (largest first)
        let earn_marketRates = {}; // { addr: { apy, lendingApr, rewards, yieldSources, extYieldApr } }
        let earn_marketRatesCache = {}; // { chainId: { savedAt, rates } }
        const EARN_MARKET_RATES_TTL_MS = 5 * 60 * 1000;
        let earn_excludeOdolo = false;
        let earn_excludeYield = false;
        let earn_excludeLending = false;
        let earn_showApy = false; // false=APR, true=APY
        const EARN_DOLO_CHAIN_IDS = { ethereum: 1, berachain: 80094, arbitrum: 42161, polygonzkevm: 1101, mantle: 5000, xlayer: 196 };
        const EARN_MERKL_REWARD_SYMBOL_BY_CAMPAIGN = {
            ethereum: {
                '576387d3d84237f5': 'WLFI', // USD1 net lending rewards
                '2ed15ca6f6a47991': 'WLFI', // USDC net lending rewards
            },
        };
        const EARN_MERKL_REWARD_TOKEN_BY_SYMBOL = {
            ethereum: {
                WLFI: '0xda5e1988097297dcdc1f90d4dfe7909e847cbef6',
            },
        };

        function earn_normalizeMerklCampaignId(value) {
            return String(value || '').trim().toLowerCase().replace(/^0x/, '');
        }

        function earn_getKnownMerklRewardSymbol(chainId, campaignId) {
            const chainMap = EARN_MERKL_REWARD_SYMBOL_BY_CAMPAIGN[String(chainId || '').toLowerCase()] || {};
            return chainMap[earn_normalizeMerklCampaignId(campaignId)] || '';
        }

        function earn_getMerklRewardTokenAddrForSymbol(chainId, symbol) {
            const chainMap = EARN_MERKL_REWARD_TOKEN_BY_SYMBOL[String(chainId || '').toLowerCase()] || {};
            return chainMap[String(symbol || '').toUpperCase()] || '';
        }

        function earn_getMerklRewardSymbolForPart(chainId, part) {
            const explicitSymbol = String(part?.rewardToken?.symbol || part?.symbol || '').trim();
            if (explicitSymbol) return explicitSymbol;
            const label = String(part?.label || '');
            const labelTokenMatch = label.match(/\b(WLFI|IBGT|WIBGT|HONEY|GMX|ESGMX)\b/i);
            if (labelTokenMatch) return labelTokenMatch[1].toUpperCase();
            const campaignSymbol = earn_getKnownMerklRewardSymbol(chainId, part?.merklData?.campaignIdentifier);
            if (campaignSymbol) return campaignSymbol;
            return '';
        }

        function earn_normalizeEvmAddress(value) {
            const match = String(value || '').match(/0x[a-fA-F0-9]{40}/);
            return match ? match[0].toLowerCase() : '';
        }

        function earn_resolveMerklReasonTokenAddress(chainId, reasonKey, reward, campaignTokenMap) {
            const key = String(reasonKey || '');
            if (key.startsWith('Dolomite_')) {
                return earn_normalizeEvmAddress(key.replace(/^Dolomite_/, ''));
            }
            if (!key.startsWith('MultiLogPerAdditionalParam_')) return '';
            const directAddress = earn_normalizeEvmAddress(reward && reward.mainParameter);
            if (directAddress) return directAddress;
            const opportunityId = String(reward && reward.opportunityId ? reward.opportunityId : '').trim();
            const opportunityTokenMap = earn_getMerklOpportunityTokenMap(chainId);
            if (opportunityId && opportunityTokenMap[opportunityId]) {
                return opportunityTokenMap[opportunityId].toLowerCase();
            }
            const campaignId = earn_normalizeMerklCampaignId(reward && (reward.mainParameter || reward.campaignId));
            if (!campaignId) return '';
            return (campaignTokenMap[campaignId] || campaignTokenMap['0x' + campaignId] || '').toLowerCase();
        }

        function earn_getCachedMarketRates(chainId) {
            const entry = earn_marketRatesCache[String(chainId || '')];
            if (!entry || !entry.savedAt || !entry.rates) return null;
            if ((Date.now() - entry.savedAt) > EARN_MARKET_RATES_TTL_MS) {
                delete earn_marketRatesCache[String(chainId || '')];
                return null;
            }
            return entry.rates;
        }

        function earn_cleanSupplyAprLabel(label) {
            return String(label || '')
                .replace(/\s*\(APR\)\s*/g, '')
                .replace(/\s+APR$/i, '')
                .replace(/\s+APY$/i, '')
                .replace(/\s+\([^)]*\)$/g, '')
                .trim();
        }

        function earn_buildMarketRatesMap(chainId, json) {
            const rates = {};
            if (!json || !json.interestRates) return rates;
            json.interestRates.forEach(r => {
                const addr = (r.token.tokenAddress || '').toLowerCase();
                const rate = parseFloat(r.totalSupplyInterestRate) || 0;
                const baseLending = parseFloat(r.supplyInterestRate) || 0;
                let odoloRewards = 0;
                const yieldSources = [];
                const rewardParts = [];
                (r.outsideSupplyInterestRateParts || []).forEach(p => {
                    if (p.label && p.label.includes('oDOLO') && p.interestRate) {
                        odoloRewards += parseFloat(p.interestRate) || 0;
                    } else if (p.category === 'rewards' && p.interestRate) {
                        const yr = parseFloat(p.interestRate) || 0;
                        if (yr > 0) {
                            const rewardSymbol = earn_getMerklRewardSymbolForPart(chainId, p);
                            const rewardTokenAddr = String(
                                p.rewardToken?.id || earn_getMerklRewardTokenAddrForSymbol(chainId, rewardSymbol) || ''
                            ).toLowerCase();
                            const sourceLabel = earn_cleanSupplyAprLabel(p.label);
                            yieldSources.push({ label: sourceLabel, rate: yr * 100, rewardSymbol });
                            rewardParts.push({
                                label: rewardSymbol || sourceLabel || p.label,
                                sourceLabel,
                                apr: yr,
                                symbol: rewardSymbol,
                                tokenAddr: rewardTokenAddr,
                                claimUrl: p.rewardClaimUrl || '',
                                merklCampaignId: earn_normalizeMerklCampaignId(p.merklData?.campaignIdentifier),
                            });
                        }
                    } else if (p.category === 'nativeYield' && p.interestRate) {
                        const yr = parseFloat(p.interestRate) || 0;
                        if (yr > 0) yieldSources.push({ label: earn_cleanSupplyAprLabel(p.label), rate: yr * 100 });
                    }
                });
                let extYieldApr = 0;
                yieldSources.forEach(ys => { extYieldApr += ys.rate; });
                const borrowRate = parseFloat(r.totalBorrowInterestRate || r.borrowInterestRate || '0');
                const entry = {
                    apy: rate * 100,
                    lendingApr: baseLending * 100,
                    rewards: odoloRewards * 100,
                    rewardParts,
                    yieldSources,
                    extYieldApr,
                    borrowApr: borrowRate * 100,
                };
                if (addr) rates[chainId + ':' + addr] = entry;
                const sym = (r.token.tokenSymbol || '').toUpperCase();
                if (sym) rates['sym:' + sym] = entry;
            });
            return rates;
        }

        function earn_getHistoricalMerklCampaignTokenMap(chainId) {
            const historicalMaps = {
                ethereum: {
                    // Historical WLFI Merkl campaigns no longer exposed in the live
                    // interest-rates payload, but their accumulated rewards still need
                    // to resolve back to the underlying Dolomite market for token detail views.
                    '576387d3d84237f5': '0x8d0d000ee44948fc98c9b98a4fa4921476f08b0d', // USD1
                    '2ed15ca6f6a47991': '0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48', // USDC
                },
            };
            return historicalMaps[String(chainId || '').toLowerCase()] || {};
        }

        function earn_getMerklOpportunityTokenMap(chainId) {
            const historicalMaps = {
                ethereum: {
                    '4237566951584909094': '0x8d0d000ee44948fc98c9b98a4fa4921476f08b0d', // USD1
                    '8510007982293035752': '0x8d0d000ee44948fc98c9b98a4fa4921476f08b0d', // USD1 account-number campaign
                    '13418763536600599808': '0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48', // USDC
                },
            };
            return historicalMaps[String(chainId || '').toLowerCase()] || {};
        }

        function earn_getMerklCampaignTokenMap(chainId) {
            const map = { ...earn_getHistoricalMerklCampaignTokenMap(chainId) };
            Object.entries(earn_marketRates || {}).forEach(([key, entry]) => {
                if (!key.startsWith(chainId + ':') || !entry || !Array.isArray(entry.rewardParts)) return;
                const marketTokenAddr = (key.slice(chainId.length + 1) || '').toLowerCase();
                if (!marketTokenAddr) return;
                entry.rewardParts.forEach(part => {
                    const campaignId = earn_normalizeMerklCampaignId(part && part.merklCampaignId ? part.merklCampaignId : '');
                    if (campaignId) map[campaignId] = marketTokenAddr;
                });
            });
            return map;
        }

        async function earn_fetchMarketRates(chainId) {
            const cached = earn_getCachedMarketRates(chainId);
            if (cached) {
                earn_marketRates = cached;
                return cached;
            }

            const requestKey = String(chainId || '');
            if (earn_marketRatesRequestCache[requestKey]) {
                const inflight = await earn_marketRatesRequestCache[requestKey];
                earn_marketRates = inflight || {};
                return inflight || {};
            }

            const doloChainId = EARN_DOLO_CHAIN_IDS[String(chainId || '')];
            if (!doloChainId) {
                earn_marketRates = {};
                return {};
            }

            const request = (async () => {
                const resp = await fetch(`https://api.dolomite.io/tokens/${doloChainId}/interest-rates?exclude-odolo=false`);
                const json = resp.ok ? await resp.json() : null;
                const rates = earn_buildMarketRatesMap(chainId, json);
                if (Object.keys(rates).length > 0) {
                    earn_marketRatesCache[String(chainId || '')] = {
                        savedAt: Date.now(),
                        rates,
                    };
                }
                return rates;
            })().catch(e => {
                console.warn('Dolomite APY fetch:', e);
                return earn_getCachedMarketRates(chainId) || {};
            });

            earn_marketRatesRequestCache[requestKey] = request;
            try {
                const rates = await request;
                earn_marketRates = rates || {};
                return rates || {};
            } finally {
                delete earn_marketRatesRequestCache[requestKey];
            }
        }

        function earn_toggleAprApy() {
            earn_showApy = !earn_showApy;
            document.getElementById('earn-apr-opt').classList.toggle('active', !earn_showApy);
            document.getElementById('earn-apy-opt').classList.toggle('active', earn_showApy);
            const slider = document.getElementById('earn-apr-pill-slider');
            if (slider) slider.classList.toggle('right', earn_showApy);
            const tbl = document.querySelector('.earn-asset-table');
            if (tbl) tbl.classList.add('no-animate');
            if (earn_cachedAssets) earn_renderResults(earn_cachedAssets, { skipSummary: true });
        }

        function earn_updateSortHeaders(selector, activeKey, descending) {
            const ascending = !descending;
            document.querySelectorAll(selector).forEach(th => {
                const isActive = th.dataset.sort === activeKey;
                th.classList.toggle('sort-active', isActive);
                th.setAttribute('aria-sort', isActive ? (ascending ? 'ascending' : 'descending') : 'none');
                const arrow = th.querySelector('.earn-sort-arrow');
                if (arrow) arrow.textContent = isActive ? (ascending ? '\u25b2' : '\u25bc') : '';
            });
        }

        // Sort assets and re-render
        function earn_sortAssets(key) {
            if (!earn_cachedAssets || earn_cachedAssets.length === 0) return;
            if (earn_sortKey === key) {
                earn_sortDesc = !earn_sortDesc; // toggle direction
            } else {
                earn_sortKey = key;
                earn_sortDesc = key !== 'token'; // text starts A-Z; numeric columns start high-low
            }

            earn_updateSortHeaders('#earn-supply-section .earn-asset-table thead th[data-sort]', earn_sortKey, earn_sortDesc);

            // Sort
            if (key === 'token') {
                earn_cachedAssets.sort((a, b) => {
                    const diff = String(a.symbol || '').localeCompare(String(b.symbol || ''), undefined, { sensitivity: 'base' });
                    return earn_sortDesc ? -diff : diff;
                });
            } else if (key === 'balance') {
                earn_cachedAssets.sort((a, b) => {
                    const diff = a.usdValue - b.usdValue;
                    return earn_sortDesc ? -diff : diff;
                });
            } else if (key === 'price') {
                const cid = document.getElementById('earn-chain').value;
                earn_cachedAssets.sort((a, b) => {
                    const diff = earn_getUsdPrice(a.symbol, a.tokenAddr, cid) - earn_getUsdPrice(b.symbol, b.tokenAddr, cid);
                    return earn_sortDesc ? -diff : diff;
                });
            } else if (key === 'yield') {
                // Schwartzian transform: earn_calculateYield is ~270 lines of BigInt + DOM
                // reads. Computing it inside the comparator ran it twice per comparison
                // (O(n·log n) full recalcs); precompute the key once per asset instead.
                const yieldKeyByAsset = new Map();
                const yieldKeyOf = (asset) => {
                    if (!yieldKeyByAsset.has(asset)) yieldKeyByAsset.set(asset, earn_calculateYield(asset).yieldUsdScaled || 0n);
                    return yieldKeyByAsset.get(asset);
                };
                earn_cachedAssets.sort((a, b) => {
                    const diff = earn_compareBigInt(yieldKeyOf(a), yieldKeyOf(b));
                    return earn_sortDesc ? -diff : diff;
                });
            } else if (key === 'apr') {
                const cid = document.getElementById('earn-chain').value;
                earn_cachedAssets.sort((a, b) => {
                    const rA = earn_marketRates[cid + ':' + (a.tokenAddr || '').toLowerCase()] ||
                        earn_marketRates['sym:' + (a.symbol || '').toUpperCase().replace(/[^A-Z0-9]/g, '')] || {};
                    const rB = earn_marketRates[cid + ':' + (b.tokenAddr || '').toLowerCase()] ||
                        earn_marketRates['sym:' + (b.symbol || '').toUpperCase().replace(/[^A-Z0-9]/g, '')] || {};
                    let aprA = rA.apy || 0;
                    let aprB = rB.apy || 0;
                    if (earn_excludeOdolo) { aprA -= (rA.rewards || 0); aprB -= (rB.rewards || 0); }
                    if (earn_excludeYield) { aprA -= (rA.extYieldApr || 0); aprB -= (rB.extYieldApr || 0); }
                    if (earn_excludeLending) { aprA -= (rA.lendingApr || 0); aprB -= (rB.lendingApr || 0); }
                    const diff = aprA - aprB;
                    return earn_sortDesc ? -diff : diff;
                });
            }

            // Suppress row animations on re-sort and skip summary rebuild
            const table = document.querySelector('.earn-asset-table');
            if (table) table.classList.add('no-animate');
            earn_renderResults(earn_cachedAssets, { skipSummary: true });
            if (table) requestAnimationFrame(() => table.classList.remove('no-animate'));
        }

        // Toggle oDOLO rewards in earn Supply APR column
        function earn_toggleOdolo() {
            earn_excludeOdolo = !earn_excludeOdolo;
            const wrap = document.getElementById('earn-odolo-toggle');
            if (wrap) wrap.classList.toggle('active', earn_excludeOdolo);
            // Suppress row animations on toggle re-render
            const tbl = document.querySelector('.earn-asset-table');
            if (tbl) tbl.classList.add('no-animate');
            if (earn_cachedAssets) earn_renderResults(earn_cachedAssets, { skipSummary: true });
        }

        // Toggle external yield in earn Supply APR column
        function earn_toggleYield() {
            earn_excludeYield = !earn_excludeYield;
            const wrap = document.getElementById('earn-yield-toggle');
            if (wrap) wrap.classList.toggle('active', earn_excludeYield);
            // Suppress row animations on toggle re-render
            const tbl = document.querySelector('.earn-asset-table');
            if (tbl) tbl.classList.add('no-animate');
            if (earn_cachedAssets) earn_renderResults(earn_cachedAssets, { skipSummary: true });
        }

        // Toggle lending APR in earn Supply APR column
        function earn_toggleLending() {
            earn_excludeLending = !earn_excludeLending;
            const wrap = document.getElementById('earn-lending-toggle');
            if (wrap) wrap.classList.toggle('active', earn_excludeLending);
            // Suppress row animations on toggle re-render
            const tbl = document.querySelector('.earn-asset-table');
            if (tbl) tbl.classList.add('no-animate');
            if (earn_cachedAssets) earn_renderResults(earn_cachedAssets, { skipSummary: true });
        }

        // Historical snapshot cache: { '2026-02-11': { snapshots: { arbitrum: { ... } } } }
        const earn_snapshotCache = {};
        let earn_snapshotRequestCache = {}; // { '2026-02-11': Promise<snapshot|null> }
        let earn_historicalData = null; // current period's historical data for the looked-up address
        let earn_totalYieldData = null; // raw historical total-yield snapshot data (basis for replay/snapshot inference)
        let earn_resolvedTotalYieldData = null; // final per-market total-yield metadata after replay/netflow inference
        let earn_totalYieldDays = 0; // number of days the total yield spans
        let earn_interestYieldData = null; // { marketId: { earnYield, settledYield, openBorrowYield, openSupplyYield, openCollateralYield, currentBorrowPar, currentSupplyPar } }
        let earn_replayAccountStateData = {}; // serialized per-account replay states before current-state reconciliation
        let earn_replayCurrentIndexMap = {}; // { marketId: { supplyIndex, borrowIndex } } for replay summary rebuilds

        const EARN_DATA_BASE = ((window.location.protocol === 'http:' || window.location.protocol === 'https:')
            ? new URL('data/', document.baseURI || window.location.href).href.replace(/\/$/, '')
            : 'https://twojekrypto.github.io/Dolomite-dashboard/data');
        const SNAPSHOT_BASE = `${EARN_DATA_BASE}/earn-snapshots`;
        const NETFLOW_BASE = `${EARN_DATA_BASE}/earn-netflow`;
        const VERIFIED_LEDGER_BASE = `${EARN_DATA_BASE}/earn-verified-ledger`;
        const VERIFIED_LEDGER_SHARD_BASE = `${EARN_DATA_BASE}/earn-verified-ledger-shards`;
        const LIQUIDATION_RISK_SHARD_BASE = `${EARN_DATA_BASE}/liquidation-risk`;
        const EARN_MERKL_REWARDS_BASE = `${EARN_DATA_BASE}/earn-merkl-rewards`;
        const SUBACCOUNT_HISTORY_BASE = `${EARN_DATA_BASE}/earn-subaccount-history`;
        const EARN_FRESHNESS_STATUS_URL = `${EARN_DATA_BASE}/earn-freshness/status.json`;
        let earn_netflowData = null; // { marketId: netFlowWei (string) } for current address+chain
        let earn_acct0NetflowData = null; // { marketId: weiString } account-0-only supply netflow (for borrow markets)
        let earn_subgraphTokens = {}; // { marketId: { symbol, decimals, name } } — token metadata from subgraph
        let earn_verifiedLedgerCache = {}; // { "chain:address" : payload|null }
        let earn_verifiedLedgerRequestCache = {}; // { "chain:address" : Promise<payload|null> }
        let earn_verifiedLedgerShardRequestCache = {}; // { "chain:prefix" : Promise<shard|null> }
        let earn_publishedResolvedInterestLedger = null; // last strict static replay fast path for the active lookup
        let earn_subaccountHistoryCache = {}; // { "chain:address" : payload|null }
        let earn_subaccountHistoryRequestCache = {}; // { "chain:address" : Promise<payload|null> }
        let earn_marketRatesRequestCache = {}; // { chainId : Promise<rates> }
        let earn_cachedMerklRewardsCache = {}; // { "chain:address" : rewards|null }
        let earn_cachedMerklRewardsRequestCache = {}; // { "chain:address" : Promise<rewards|null> }

        // Snapshot manifest: { dates: [...], chains: { date: [chains] } }
        let earn_snapshotManifest = null;
        let earn_snapshotManifestRequest = null;
        let earn_freshnessStatus = null;
        let earn_freshnessStatusRequest = null;
        let earn_customSnapshotDate = null; // date string for custom selection

        function earn_formatFreshnessLag(minutes) {
            const value = Number(minutes || 0);
            if (!Number.isFinite(value) || value <= 0) return '';
            if (value < 90) return `${Math.round(value)}m lag`;
            return `${(value / 60).toFixed(value >= 600 ? 0 : 1)}h lag`;
        }

        function earn_formatFreshnessAge(minutes) {
            const value = Number(minutes || 0);
            if (!Number.isFinite(value) || value < 1) return 'now';
            if (value < 90) return `${Math.round(value)}m ago`;
            return `${(value / 60).toFixed(value >= 600 ? 0 : 1)}h ago`;
        }

        function earn_formatCanonicalCoverageLabel(coverage, useBackfill = false) {
            const count = Number(useBackfill
                ? (coverage?.backfilledWalletCount ?? coverage?.freshWalletCount)
                : (coverage?.headFreshWalletCount ?? coverage?.freshWalletCount));
            const known = Number(coverage?.knownAddressCount);
            if (!Number.isFinite(count) || !Number.isFinite(known) || known <= 0) return '';
            return `${Math.max(0, Math.min(count, known))}/${known} wallets`;
        }

        function earn_updateFreshnessPill() {
            const pill = document.getElementById('earn-data-freshness-pill');
            if (!pill) return;
            const chainId = String(document.getElementById('earn-chain')?.value || 'ethereum').trim().toLowerCase();
            const chainStatus = earn_freshnessStatus && earn_freshnessStatus.chains
                ? earn_freshnessStatus.chains[chainId]
                : null;
            const freshnessModes = chainStatus ? [
                chainStatus.refreshMode,
                chainStatus.canonical?.refreshMode,
                chainStatus.netflow?.refreshMode
            ].map(mode => String(mode || '').toLowerCase()) : [];
            const isVerifiedBackground = chainStatus
                && String(chainStatus.status || '').toLowerCase() === 'verified'
                && freshnessModes.includes('background');
            const canonicalCoverage = chainStatus?.canonical?.coverage || null;
            const canonicalCoverageCatchup = chainStatus?.canonical?.coverageCatchup === true;
            const canonicalCoverageBacklog = chainStatus?.canonical?.coverageBacklog === true;
            const canonicalLag = Number(chainStatus?.canonical?.estimatedLagMinutes || 0);
            const netflowLag = Number(chainStatus?.netflow?.estimatedLagMinutes || 0);
            const lagLabel = earn_formatFreshnessLag(Math.max(canonicalLag, netflowLag));
            const ageLabel = earn_formatFreshnessAge(Math.max(canonicalLag, netflowLag));
            const recencyStatus = String(chainStatus?.canonical?.recencyStatus || chainStatus?.canonical?.status || '').toLowerCase();
            const blockLag = Number(chainStatus?.canonical?.blockLag);
            const verifiedBlockLag = Number(chainStatus?.canonical?.verifiedBlockLag);
            const recencyFresh = ['verified', 'ahead'].includes(recencyStatus)
                || (Number.isFinite(blockLag) && Number.isFinite(verifiedBlockLag) && verifiedBlockLag > 0 && blockLag <= verifiedBlockLag);
            if (canonicalCoverageCatchup || canonicalCoverageBacklog) {
                const coverageLabel = earn_formatCanonicalCoverageLabel(canonicalCoverage, canonicalCoverageBacklog);
                const liveCopy = recencyFresh
                    ? `Live data · ${ageLabel}`
                    : `Live data syncing${lagLabel ? ` · ${lagLabel}` : ''}`;
                const historyCopy = coverageLabel
                    ? `Historical verification · ${coverageLabel}`
                    : (canonicalCoverageCatchup ? 'Historical verification · syncing' : 'Historical verification · backfill pending');
                pill.innerHTML = `<span class="earn-freshness-live">${liveCopy}</span><span class="earn-freshness-separator" aria-hidden="true"></span><span class="earn-freshness-history">${historyCopy}</span>`;
                pill.classList.add('visible');
                pill.setAttribute('aria-hidden', 'false');
                pill.setAttribute('aria-label', `${liveCopy}. ${historyCopy}`);
                return;
            }
            if (!isVerifiedBackground) {
                pill.classList.remove('visible');
                pill.setAttribute('aria-hidden', 'true');
                pill.textContent = '';
                return;
            }
            pill.textContent = recencyFresh
                ? `Live data · ${ageLabel}`
                : `Live data syncing${lagLabel ? ` · ${lagLabel}` : ''}`;
            pill.classList.add('visible');
            pill.setAttribute('aria-hidden', 'false');
        }

        async function earn_loadFreshnessStatus() {
            if (earn_freshnessStatus) return earn_freshnessStatus;
            if (earn_freshnessStatusRequest) return earn_freshnessStatusRequest;
            earn_freshnessStatusRequest = (async () => {
                try {
                    const resp = await fetch(EARN_FRESHNESS_STATUS_URL, { cache: 'no-cache' });
                    if (!resp.ok) return null;
                    earn_freshnessStatus = await resp.json();
                    earn_updateFreshnessPill();
                    return earn_freshnessStatus;
                } catch (e) {
                    console.warn('Failed to load EARN freshness status:', e);
                    return null;
                } finally {
                    earn_freshnessStatusRequest = null;
                }
            })();
            return earn_freshnessStatusRequest;
        }

        function earn_getLatestSnapshotDateForChain(chainId) {
            if (!earn_snapshotManifest || !Array.isArray(earn_snapshotManifest.dates)) return null;
            const targetChain = String(chainId || '').trim().toLowerCase();
            if (!targetChain) return null;
            for (let i = earn_snapshotManifest.dates.length - 1; i >= 0; i--) {
                const dateStr = earn_snapshotManifest.dates[i];
                const chains = earn_snapshotManifest.chains && earn_snapshotManifest.chains[dateStr];
                if (Array.isArray(chains) && chains.map(v => String(v || '').toLowerCase()).includes(targetChain)) {
                    return dateStr;
                }
            }
            return null;
        }

        function earn_getSnapshotFreshness(chainId) {
            const latestDate = earn_getLatestSnapshotDateForChain(chainId);
            if (!latestDate) return null;
            const today = new Date();
            today.setUTCHours(0, 0, 0, 0);
            const snapshotDate = new Date(latestDate + 'T00:00:00Z');
            const ageDays = Math.max(0, Math.round((today - snapshotDate) / 86400000));
            return {
                latestDate,
                ageDays,
                stale: ageDays > EARN_SNAPSHOT_STALE_DAYS,
            };
        }

        function earn_hasBorrowOnlyEarnContext() {
            const activeSupplyCount = (earn_cachedAssets || []).filter(a => {
                return a
                    && !a.isBorrow
                    && !a.isCollateral
                    && Number(a.usdValue || 0) >= 0.01;
            }).length;
            const hasHistoricalEarnContext = Array.isArray(earn_historyData)
                && earn_historyData.some(item => item && !item.isActive && !item.isIsolation);
            const hasBorrowRoutedExposure = (earn_collateralPositionData || []).length > 0
                || (earn_borrowPositionData || []).length > 0
                || (earn_replayBorrowAccountsOverride && earn_replayBorrowAccountsOverride.size > 0)
                || (earn_lendingPositions || []).length > 0;
            return activeSupplyCount === 0 && !hasHistoricalEarnContext && hasBorrowRoutedExposure;
        }

        function earn_renderNotices() {
            const noticesEl = document.getElementById('earn-notices');
            if (!noticesEl) return;
            if (earn_globalEmptyState) {
                noticesEl.innerHTML = '';
                noticesEl.classList.remove('visible');
                return;
            }

            const notices = [];
            const chainId = document.getElementById('earn-chain')?.value || 'ethereum';
            const chainName = EARN_CHAINS[chainId]?.name || chainId;
            const snapshotFreshness = earn_getSnapshotFreshness(chainId);

            if (snapshotFreshness && snapshotFreshness.stale) {
                notices.push({
                    tone: 'warn',
                    title: 'Stale History Snapshots',
                    body: `Latest ${chainName} snapshot: ${snapshotFreshness.latestDate} (${snapshotFreshness.ageDays} days old). Period shortcuts and historical yield comparisons may be incomplete.`,
                });
            }

            if (earn_totalYieldStatus === 'loading') {
                notices.push({
                    tone: 'info',
                    title: 'Verified Yield Is Loading',
                    body: 'Balances are already visible. Total Yield Earned and ledger verification are still loading from replay + snapshot data and will update automatically.',
                });
            } else if (earn_replayStatus === 'loading') {
                notices.push({
                    tone: 'info',
                    title: 'Ledger Check Is Loading',
                    body: 'Balances and yield are already visible. Final replay reconciliation is still running in the background and will update automatically.',
                });
            } else if (earn_totalYieldStatus === 'error') {
                notices.push({
                    tone: 'warn',
                    title: 'Verified Yield Could Not Be Loaded',
                    body: 'The page could not complete verified Total Yield calculation for this lookup. Balance data is still shown, but historical yield may be incomplete until the next refresh succeeds.',
                });
            } else if (earn_replayStatus === 'error') {
                notices.push({
                    tone: 'warn',
                    title: 'Ledger Check Could Not Be Completed',
                    body: 'Yield and balances are still shown, but final replay reconciliation did not complete for this lookup. Snapshot-backed values remain available.',
                });
            }

            if (earn_merklFetchStatus === 'error') {
                notices.push({
                    tone: 'warn',
                    title: 'WLFI Rewards Unavailable',
                    body: 'MERKL API did not respond for this lookup. External rewards cards and WLFI attribution may be temporarily undercounted.',
                });
            }

            const canonicalHistoryCoverageStatus = earn_getCanonicalSubaccountHistoryCoverageStatus();
            const hasCurrentBorrowRoutedExposure = (earn_collateralPositionData || []).length > 0
                || (earn_borrowPositionData || []).length > 0
                || (earn_lendingPositions || []).length > 0
                || (earn_cachedAssets || []).some(position => earn_positionRequiresCanonicalBorrowRouting(position));
            const hasCoverageIncompleteYield = Object.values(earn_resolvedTotalYieldData || {}).some(entry => {
                if (!entry || typeof entry !== 'object') return false;
                return [
                    entry.resolvedVerificationStatus,
                    entry.verificationStatus,
                    entry.strictStatus,
                    entry.status,
                ].some(status => String(status || '').trim().toLowerCase() === 'coverage_incomplete');
            });
            const hasBorrowRoutedExposure = hasCurrentBorrowRoutedExposure
                || (!!(earn_replayBorrowAccountsOverride && earn_replayBorrowAccountsOverride.size > 0) && hasCoverageIncompleteYield);
            const hasBorrowOnlyContext = earn_hasBorrowOnlyEarnContext();
            if (hasBorrowRoutedExposure && canonicalHistoryCoverageStatus !== 'fresh' && !hasBorrowOnlyContext) {
                const coverageLabel = canonicalHistoryCoverageStatus === 'missing' ? 'missing' : 'stale';
                const blockText = earn_canonicalSubaccountHistoryLastScannedBlock === null
                    ? 'none'
                    : String(earn_canonicalSubaccountHistoryLastScannedBlock);
                const replayBlockText = earn_replayBlockTag
                    ? String(earn_parseBlockNumberLike(earn_replayBlockTag) || '')
                    : '';
                const blockDetail = replayBlockText
                    ? ` Local history is ${coverageLabel}: last scanned block ${blockText}; lookup block ${replayBlockText}.`
                    : ` Local history is ${coverageLabel}: last scanned block ${blockText}.`;
                notices.push({
                    tone: 'info',
                    title: 'Borrow Route Verification Is Catching Up',
                    body: `This wallet has borrow-route / hidden-collateral activity, so strict verification waits for fresh local subaccount history. Visible balances and verified market rows are still shown normally.${blockDetail}`,
                });
            }

            if (notices.length === 0) {
                noticesEl.innerHTML = '';
                noticesEl.classList.remove('visible');
                return;
            }

            noticesEl.innerHTML = notices.map(notice => `
                <div class="earn-notice ${notice.tone}">
                    <svg class="earn-notice-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                        <path d="M12 9v4"></path>
                        <path d="M12 17h.01"></path>
                        <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path>
                    </svg>
                    <div class="earn-notice-copy">
                        <div class="earn-notice-title">${earn_escapeHtml(notice.title)}</div>
                        <div class="earn-notice-body">${earn_escapeHtml(notice.body)}</div>
                    </div>
                </div>
            `).join('');
            noticesEl.classList.add('visible');
        }

        function earn_setMerklFetchState(status, errorMessage, address, chainId) {
            const currentAddr = String(document.getElementById('earn-address')?.value || '').trim().toLowerCase();
            const currentChainId = String(document.getElementById('earn-chain')?.value || '').trim().toLowerCase();
            const targetAddr = String(address || '').trim().toLowerCase();
            const targetChainId = String(chainId || '').trim().toLowerCase();
            if (targetAddr && currentAddr && targetAddr !== currentAddr) return;
            if (targetChainId && currentChainId && targetChainId !== currentChainId) return;
            earn_merklFetchStatus = status || 'idle';
            earn_merklFetchError = errorMessage || '';
            earn_renderNotices();
        }

        function earn_softRefreshRewardsUi(address, chainId) {
            const currentAddr = String(document.getElementById('earn-address')?.value || '').trim().toLowerCase();
            const currentChainId = String(document.getElementById('earn-chain')?.value || '').trim().toLowerCase();
            const targetAddr = String(address || '').trim().toLowerCase();
            const targetChainId = String(chainId || '').trim().toLowerCase();
            if (!targetAddr || !targetChainId) return;
            if (!currentAddr || !currentChainId) return;
            if (targetAddr !== currentAddr || targetChainId !== currentChainId) return;

            if (earn_cachedAssets && earn_cachedAssets.length > 0) {
                const tblRef = document.querySelector('.earn-asset-table');
                if (tblRef) tblRef.classList.add('no-animate');
                earn_renderResults(earn_cachedAssets, { skipSummary: true, softRefresh: true });
            }

            if (Array.isArray(earn_lendingPositions) && earn_lendingPositions.length > 0) {
                earn_reRenderLendingRows();
            }
        }

        async function earn_loadManifest() {
            if (earn_snapshotManifest) return earn_snapshotManifest;
            if (earn_snapshotManifestRequest) return earn_snapshotManifestRequest;

            const request = (async () => {
                try {
                    const resp = await fetch(`${SNAPSHOT_BASE}/manifest.json`);
                    if (!resp.ok) return null;
                    const parsed = await resp.json();
                    // Validate before assigning: a malformed manifest (no dates array) would
                    // otherwise assign successfully and make every later earn_buildPeriodButtons()
                    // — e.g. from earnChainSelect — throw an uncaught TypeError, killing the
                    // period buttons after a chain switch.
                    if (!parsed || !Array.isArray(parsed.dates)) {
                        console.warn('Snapshot manifest malformed (missing dates array); ignoring');
                        return null;
                    }
                    earn_snapshotManifest = parsed;
                    earn_buildPeriodButtons();
                    earn_renderNotices();
                    console.log('Snapshot manifest loaded:', earn_snapshotManifest.dates.length, 'dates');
                    return earn_snapshotManifest;
                } catch (e) {
                    console.warn('Failed to load snapshot manifest:', e);
                    return null;
                }
            })();

            earn_snapshotManifestRequest = request;
            try {
                return await request;
            } finally {
                earn_snapshotManifestRequest = null;
            }
        }

        // Build period buttons dynamically from manifest (no-op if period bar removed)
        function earn_buildPeriodButtons() {
            if (!earn_snapshotManifest || !Array.isArray(earn_snapshotManifest.dates)) return;
            const bar = document.getElementById('earn-period-bar');
            if (!bar) return;

            // Remove any previously generated dynamic buttons
            bar.querySelectorAll('.earn-period-btn[data-generated]').forEach(b => b.remove());

            const today = new Date();
            today.setUTCHours(0, 0, 0, 0);
            const chainId = document.getElementById('earn-chain')?.value || '';

            // Smart period shortcuts — find closest available snapshot for each target
            const targets = [1, 3, 7, 14, 21, 28];
            const availDates = earn_snapshotManifest.dates
                .filter(d => {
                    const chains = earn_snapshotManifest.chains[d] || [];
                    return !chainId || chains.includes(chainId);
                })
                .filter(d => d !== today.toISOString().slice(0, 10))
                .sort();

            let generatedCount = 0;

            targets.forEach(targetDays => {
                const targetDate = new Date(today);
                targetDate.setUTCDate(targetDate.getUTCDate() - targetDays);
                const targetStr = targetDate.toISOString().slice(0, 10);

                // Find closest available snapshot (prefer exact, then ±1 day)
                let bestDate = null;
                let bestDiff = Infinity;
                availDates.forEach(d => {
                    const diff = Math.abs(Math.round((new Date(d + 'T00:00:00Z') - targetDate) / 86400000));
                    if (diff < bestDiff && diff <= 1) {
                        bestDiff = diff;
                        bestDate = d;
                    }
                });

                if (!bestDate) return;

                const snapshotDate = new Date(bestDate + 'T00:00:00Z');
                const actualDays = Math.round((today - snapshotDate) / 86400000);
                if (actualDays < 1) return;

                const btn = document.createElement('button');
                btn.className = 'earn-period-btn';
                // Mark 1D as active by default
                if (targetDays === 1) btn.classList.add('active');
                btn.dataset.period = String(actualDays);
                btn.dataset.snapshotDate = bestDate;
                btn.dataset.generated = 'true';
                btn.textContent = targetDays + 'D';
                btn.onclick = () => earn_setPeriod(String(actualDays), bestDate);

                bar.appendChild(btn);
                generatedCount++;
            });

            bar.classList.toggle('visible', generatedCount > 0);
        }


        const EARN_SNAPSHOT_TIMEOUT_MS = 12000;
        const EARN_CANONICAL_LOOKUP_BLOCK_LAG_TOLERANCE_BY_CHAIN = {
            ethereum: 600n, // ~2h at 12s blocks
            berachain: 3600n, // ~2h at 2s blocks
            arbitrum: 28800n, // ~2h at ~0.25s blocks
            botanix: 1200n, // ~2h at 6s blocks
            mantle: 3600n, // ~2h at 2s blocks
            polygonzkevm: 2250n, // ~2h at ~3.2s blocks
            xlayer: 7200n, // ~2h at 1s blocks
            default: 64n,
        };

        async function earn_fetchSnapshot(dateStr) {
            if (earn_snapshotCache[dateStr]) return earn_snapshotCache[dateStr];
            if (earn_snapshotRequestCache[dateStr]) return earn_snapshotRequestCache[dateStr];

            const request = (async () => {
                const timeoutMs = Math.max(
                    1000,
                    Number(globalThis.__EARN_SNAPSHOT_FETCH_TIMEOUT_OVERRIDE__ || EARN_SNAPSHOT_TIMEOUT_MS)
                );
                const ctrl = new AbortController();
                const timer = setTimeout(() => ctrl.abort(), timeoutMs);
                try {
                    const resp = await fetch(`${SNAPSHOT_BASE}/${dateStr}.json`, {
                        cache: 'no-store',
                        signal: ctrl.signal,
                    });
                    if (!resp.ok) return null;
                    const data = await resp.json();
                    earn_snapshotCache[dateStr] = data;
                    return data;
                } catch (e) {
                    console.warn('Snapshot fetch failed for', dateStr, e);
                    return null;
                } finally {
                    clearTimeout(timer);
                }
            })();

            earn_snapshotRequestCache[dateStr] = request;
            try {
                return await request;
            } finally {
                delete earn_snapshotRequestCache[dateStr];
            }
        }

        async function earn_mapWithConcurrency(items, limit, worker) {
            const list = Array.isArray(items) ? items : [];
            const maxWorkers = Math.max(1, Math.min(Number(limit) || 1, list.length || 1));
            const results = new Array(list.length);
            let nextIndex = 0;

            const runners = Array.from({ length: maxWorkers }, async () => {
                while (nextIndex < list.length) {
                    const currentIndex = nextIndex++;
                    results[currentIndex] = await worker(list[currentIndex], currentIndex);
                }
            });

            await Promise.all(runners);
            return results;
        }

        function earn_parseBlockNumberLike(value) {
            if (value === undefined || value === null) return null;
            const raw = String(value).trim();
            if (!raw) return null;
            try {
                return BigInt(raw);
            } catch (e) {
                return null;
            }
        }

        function earn_formatBlockTagFromBigInt(value) {
            if (typeof value !== 'bigint' || value < 0n) return null;
            return '0x' + value.toString(16);
        }

        function earn_getCanonicalLookupBlockLagTolerance(chainId) {
            const key = String(chainId || document.getElementById('earn-chain')?.value || '').trim().toLowerCase();
            return EARN_CANONICAL_LOOKUP_BLOCK_LAG_TOLERANCE_BY_CHAIN[key]
                || EARN_CANONICAL_LOOKUP_BLOCK_LAG_TOLERANCE_BY_CHAIN.default;
        }

        function earn_resetCanonicalSubaccountHistoryState() {
            earn_canonicalSubaccountHistoryLastScannedBlock = null;
            earn_canonicalSubaccountHistoryFreshForBorrowRouting = false;
        }

        function earn_setCanonicalSubaccountHistoryState(lastScannedBlock, freshForBorrowRouting) {
            const parsedLastScannedBlock = earn_parseBlockNumberLike(lastScannedBlock);
            if (parsedLastScannedBlock !== null) {
                earn_canonicalSubaccountHistoryLastScannedBlock = parsedLastScannedBlock;
            }
            earn_canonicalSubaccountHistoryFreshForBorrowRouting = !!freshForBorrowRouting;
        }

        function earn_updateCanonicalSubaccountHistoryStateFromHints(historyHints) {
            if (!historyHints || typeof historyHints !== 'object') return;
            earn_setCanonicalSubaccountHistoryState(
                historyHints.lastScannedBlock,
                historyHints.freshForBorrowRouting
            );
        }

        function earn_updateCanonicalSubaccountHistoryStateFromReplay(replay) {
            if (!replay || typeof replay !== 'object') return;
            earn_setCanonicalSubaccountHistoryState(
                replay.canonicalSubaccountHistoryLastScannedBlock,
                replay.canonicalSubaccountHistoryFreshForBorrowRouting
            );
        }

        function earn_getCanonicalSubaccountHistoryCoverageStatus() {
            if (earn_canonicalSubaccountHistoryLastScannedBlock === null) return 'missing';
            return earn_canonicalSubaccountHistoryFreshForBorrowRouting ? 'fresh' : 'stale';
        }

        function earn_positionRequiresCanonicalBorrowRouting(position) {
            if (!position || typeof position !== 'object') return false;
            if (position.isCollateral || position.isBorrow) return true;
            const route = String(
                position.positionRoute !== undefined
                    ? position.positionRoute
                    : (position.positionKind !== undefined ? position.positionKind : '')
            ).trim().toLowerCase();
            return route === 'hidden-collateral'
                || route === 'hidden_collateral'
                || route === 'collateral'
                || route === 'borrow'
                || route === 'borrow_only';
        }

        function earn_extractSubaccountHistoryHints(history, opts) {
            opts = opts || {};
            if (!history || typeof history !== 'object') {
                return {
                    accountNumbers: [],
                    borrowAccountNumbers: [],
                    marketRoutes: {},
                    lastScannedBlock: null,
                    freshForBorrowRouting: false,
                };
            }

            const blockTag = earn_parseBlockNumberLike(opts.blockTag);
            const lastScannedBlock = earn_parseBlockNumberLike(history.lastScannedBlock);
            const freshForBorrowRouting = blockTag !== null && lastScannedBlock !== null && lastScannedBlock >= blockTag;
            const accountNumbers = [];
            const borrowAccountNumbers = [];
            const marketRoutes = {};

            Object.values(history.accounts || {}).forEach(accountState => {
                const account = String(accountState && accountState.account !== undefined ? accountState.account : '').trim();
                if (!account || account === 'legacy-unknown' || accountState.accountKnown === false) return;
                earn_pushUniqueAccount(accountNumbers, account);

                const hasBorrow = !!accountState.hasBorrow;
                if (freshForBorrowRouting && hasBorrow) {
                    earn_pushUniqueAccount(borrowAccountNumbers, account);
                }
                if (!freshForBorrowRouting) return;

                Object.values(accountState.markets || {}).forEach(marketState => {
                    const marketId = earn_normalizeMarketId(
                        marketState && marketState.marketId !== undefined ? marketState.marketId : ''
                    );
                    if (!marketId) return;
                    const latestParRaw = marketState ? marketState.latestPar : null;
                    if (latestParRaw === null || latestParRaw === undefined) return;
                    const latestPar = BigInt(latestParRaw || '0');
                    if (latestPar < 0n) {
                        marketRoutes[`${account}|${marketId}`] = 'borrow';
                    } else if (latestPar > 0n) {
                        marketRoutes[`${account}|${marketId}`] = hasBorrow ? 'collateral' : 'supply';
                    }
                });
            });

            return {
                accountNumbers,
                borrowAccountNumbers,
                marketRoutes,
                lastScannedBlock,
                freshForBorrowRouting,
            };
        }

        function earn_supplementReplayAccountStateDataFromHistory(accountStateData, history, historyHints) {
            if (
                !historyHints
                || !historyHints.freshForBorrowRouting
                || !history
                || typeof history !== 'object'
            ) {
                return {
                    accountStateData,
                    addedStates: 0,
                };
            }

            const states = earn_deserializeReplayStateMap(accountStateData || {});
            let addedStates = 0;

            Object.values(history.accounts || {}).forEach(accountState => {
                const account = String(
                    accountState && accountState.account !== undefined ? accountState.account : ''
                ).trim();
                if (!account || account === 'legacy-unknown' || accountState.accountKnown === false) return;

                Object.values(accountState.markets || {}).forEach(marketState => {
                    const marketId = earn_normalizeMarketId(
                        marketState && marketState.marketId !== undefined ? marketState.marketId : ''
                    );
                    if (!marketId) return;
                    const latestParRaw = marketState ? marketState.latestPar : null;
                    if (latestParRaw === null || latestParRaw === undefined) return;
                    const latestPar = BigInt(latestParRaw || '0');
                    if (latestPar <= 0n) return;

                    const route = historyHints.marketRoutes[`${account}|${marketId}`] || '';
                    if (route !== 'collateral' && route !== 'supply') return;

                    const key = `${account}|${marketId}`;
                    const existingState = states[key];
                    if (existingState && existingState.par !== 0n) return;

                    states[key] = {
                        account,
                        marketId,
                        par: latestPar,
                        lastIndex: existingState ? existingState.lastIndex : null,
                        settledYield: existingState ? existingState.settledYield : 0n,
                        settledSupplyYield: existingState ? existingState.settledSupplyYield : 0n,
                        settledBorrowYield: existingState ? existingState.settledBorrowYield : 0n,
                        liveYield: existingState ? existingState.liveYield : 0n,
                        hadSupply: true,
                        hadBorrow: existingState ? !!existingState.hadBorrow : false,
                    };
                    addedStates += 1;
                });
            });

            if (addedStates === 0) {
                return {
                    accountStateData,
                    addedStates: 0,
                };
            }

            return {
                accountStateData: earn_serializeReplayStateMap(states),
                addedStates,
            };
        }

        function earn_applySubaccountHistoryToReplay(replay, history, opts) {
            if (!replay || typeof replay !== 'object') return replay;
            const historyHints = earn_extractSubaccountHistoryHints(history, opts);
            const replayAccountNumbers = Array.isArray(replay.accountNumbers)
                ? replay.accountNumbers.map(v => String(v || '').trim()).filter(Boolean)
                : [];
            const nextAccountNumbers = replayAccountNumbers.length > 0
                ? Array.from(new Set(replayAccountNumbers))
                : historyHints.accountNumbers;

            const priorBorrowAccounts = earn_collectBorrowAccountsOverride(
                replay.borrowAccountsOverride,
                replay.openBorrowAccounts
            );
            const mergedBorrowAccounts = historyHints.freshForBorrowRouting
                ? earn_collectBorrowAccountsOverride(
                    replay.borrowAccountsOverride,
                    replay.openBorrowAccounts,
                    historyHints.borrowAccountNumbers
                )
                : priorBorrowAccounts;

            const borrowAccountsChanged = (() => {
                const previous = priorBorrowAccounts || new Set();
                const next = mergedBorrowAccounts || new Set();
                if (previous.size !== next.size) return true;
                for (const account of next) {
                    if (!previous.has(account)) return true;
                }
                return false;
            })();
            const replayStateSupplement = earn_supplementReplayAccountStateDataFromHistory(
                replay.accountStateData || {},
                history,
                historyHints
            );
            const supplementedAccountStateData = replayStateSupplement.accountStateData || replay.accountStateData || {};
            const supplementedStates = replayStateSupplement.addedStates || 0;

            const nextReplay = {
                ...replay,
                accountNumbers: nextAccountNumbers,
                canonicalSubaccountHistoryLastScannedBlock: historyHints.lastScannedBlock === null
                    ? null
                    : String(historyHints.lastScannedBlock),
                canonicalSubaccountHistoryFreshForBorrowRouting: !!historyHints.freshForBorrowRouting,
            };

            if (!mergedBorrowAccounts || (!borrowAccountsChanged && supplementedStates === 0)) {
                return nextReplay;
            }

            if (!supplementedAccountStateData || Object.keys(supplementedAccountStateData).length === 0) {
                return {
                    ...nextReplay,
                    openBorrowAccounts: Array.from(mergedBorrowAccounts),
                    borrowAccountsOverride: Array.from(mergedBorrowAccounts),
                };
            }

            const mergedSummary = earn_summarizeReplayAccountStates(
                supplementedAccountStateData,
                replay.currentIndexMap || {},
                { borrowAccountsOverride: mergedBorrowAccounts }
            );
            return {
                ...nextReplay,
                interestYieldData: mergedSummary.interestYieldData || replay.interestYieldData || {},
                replayStateData: mergedSummary.replayStateData || replay.replayStateData || {},
                openBorrowAccounts: mergedSummary.openBorrowAccounts || replay.openBorrowAccounts || [],
                borrowAccountsOverride: Array.from(mergedBorrowAccounts),
                accountStateData: supplementedAccountStateData,
            };
        }

        async function earn_fetchSubaccountHistoryForAddress(chainId, address) {
            const addr = String(address || '').trim().toLowerCase();
            if (!addr || !/^0x[a-f0-9]{40}$/.test(addr)) return null;
            const cacheKey = `${chainId}:${addr}`;
            if (Object.prototype.hasOwnProperty.call(earn_subaccountHistoryCache, cacheKey)) {
                return earn_subaccountHistoryCache[cacheKey];
            }
            if (earn_subaccountHistoryRequestCache[cacheKey]) {
                return earn_subaccountHistoryRequestCache[cacheKey];
            }
            const request = (async () => {
                const resp = await fetch(`${SUBACCOUNT_HISTORY_BASE}/${chainId}/${addr}.json`, {
                    cache: 'no-store',
                });
                if (!resp.ok) {
                    // Only treat 404 as a permanent "no history" (cache it). A transient
                    // 5xx/429 must NOT be cached as null for the whole session, or one
                    // network hiccup permanently marks the wallet unverified until reload.
                    if (resp.status === 404) earn_subaccountHistoryCache[cacheKey] = null;
                    return null;
                }
                const data = await resp.json();
                if (!data || typeof data !== 'object' || !data.accounts || typeof data.accounts !== 'object') {
                    earn_subaccountHistoryCache[cacheKey] = null;
                    return null;
                }
                earn_subaccountHistoryCache[cacheKey] = data;
                return data;
            })().catch(e => {
                // Network/abort error: return null WITHOUT caching so it can be retried.
                console.warn('Subaccount history fetch failed:', e.message || e);
                return null;
            });
            earn_subaccountHistoryRequestCache[cacheKey] = request;
            try {
                return await request;
            } finally {
                delete earn_subaccountHistoryRequestCache[cacheKey];
            }
        }

        async function earn_fetchVerifiedLedgerForAddress(chainId, address) {
            const addr = String(address || '').trim().toLowerCase();
            if (!addr || !/^0x[a-f0-9]{40}$/.test(addr)) return null;
            const cacheKey = `${chainId}:${addr}`;
            if (Object.prototype.hasOwnProperty.call(earn_verifiedLedgerCache, cacheKey)) {
                return earn_verifiedLedgerCache[cacheKey];
            }
            if (earn_verifiedLedgerRequestCache[cacheKey]) {
                return earn_verifiedLedgerRequestCache[cacheKey];
            }
            const request = (async () => {
                let data = null;
                const prefix = addr.slice(2, 4);
                const shardKey = `${chainId}:${prefix}`;
                if (!earn_verifiedLedgerShardRequestCache[shardKey]) {
                    earn_verifiedLedgerShardRequestCache[shardKey] = fetch(
                        `${VERIFIED_LEDGER_SHARD_BASE}/${chainId}/${prefix}.json`,
                        { cache: 'no-store' }
                    ).then(shardResp => shardResp.ok ? shardResp.json() : null).catch(() => null);
                }
                const shard = await earn_verifiedLedgerShardRequestCache[shardKey];
                const shardEntry = shard && shard.ledgers ? (shard.ledgers[addr] || null) : null;
                if (Array.isArray(shardEntry) && shardEntry.length >= 2) {
                    const fields = (shard.schema && shard.schema.market) || [];
                    const markets = {};
                    Object.entries(shardEntry[1] || {}).forEach(([marketId, values]) => {
                        markets[marketId] = {};
                        fields.forEach((field, index) => {
                            if (Array.isArray(values) && values[index] !== null && values[index] !== undefined) {
                                markets[marketId][field] = values[index];
                            }
                        });
                    });
                    data = {
                        snapshotDate: String(shardEntry[0] || shard.snapshotDate || ''),
                        markets,
                        resolvedInterestLedger: shardEntry[2] && typeof shardEntry[2] === 'object'
                            ? shardEntry[2]
                            : undefined,
                    };
                } else if (shardEntry && typeof shardEntry === 'object') {
                    data = shardEntry;
                }

                // Compatibility fallback for chains that have not published shards yet.
                if (!data) {
                    const resp = await fetch(`${VERIFIED_LEDGER_BASE}/${chainId}/${addr}.json`, {
                        cache: 'no-store',
                    });
                    if (resp.ok) {
                        data = await resp.json();
                    } else if (resp.status === 404) {
                        earn_verifiedLedgerCache[cacheKey] = null;
                    } else {
                        // Transient errors stay uncached so the lookup can retry.
                        return null;
                    }
                }
                if (!data || typeof data !== 'object' || !data.markets || typeof data.markets !== 'object') {
                    earn_verifiedLedgerCache[cacheKey] = null;
                    return null;
                }
                const latestSnapshotDate = earn_getLatestSnapshotDateForChain(chainId);
                const ledgerSnapshotDate = String(data.snapshotDate || '').trim();
                if (latestSnapshotDate && ledgerSnapshotDate && ledgerSnapshotDate < latestSnapshotDate) {
                    console.info('Ignoring stale verified ledger in favor of fresher snapshots:', {
                        chainId,
                        address: addr,
                        ledgerSnapshotDate,
                        latestSnapshotDate,
                    });
                    earn_verifiedLedgerCache[cacheKey] = null;
                    return null;
                }
                earn_verifiedLedgerCache[cacheKey] = data;
                return data;
            })().catch(e => {
                // Network/abort error: return null WITHOUT caching so it can be retried.
                console.warn('Verified ledger fetch failed:', e.message || e);
                return null;
            });
            earn_verifiedLedgerRequestCache[cacheKey] = request;
            try {
                return await request;
            } finally {
                delete earn_verifiedLedgerRequestCache[cacheKey];
            }
        }

        function earn_canUseVerifiedLedgerMarketEntry(entry) {
            if (!entry || typeof entry !== 'object') return false;
            const status = String(entry.strictStatus || entry.status || '').trim().toLowerCase();
            const rawStatus = String(entry.status || '').trim().toLowerCase();
            const method = String(entry.strictMethod || entry.method || '').trim().toLowerCase();
            const canonicalCoverage = String(entry.canonicalHistoryCoverageStatus || '').trim().toLowerCase();
            if (earn_isTrustedReplayYieldStatus(status)) return true;
            if (
                status === 'inferred'
                && canonicalCoverage === 'fresh'
                && method !== 'snapshot-fallback'
                && (
                    rawStatus === 'pre_snapshot_carry'
                    || (
                        rawStatus === 'verified'
                        && (method === 'netflow+snapshot' || method === 'recent-cycle+snapshot')
                    )
                )
            ) return true;
            if (
                status === 'mismatch'
                || status === 'unverified'
                || status === 'pending'
                || status === 'coverage_incomplete'
                || status === 'fallback'
            ) return false;
            if (method === 'snapshot-fallback') return false;
            return !status;
        }

        function earn_validatePublishedResolvedInterestLedger(ledger) {
            const resolved = ledger && ledger.resolvedInterestLedger;
            if (!resolved || typeof resolved !== 'object') return null;
            if (String(resolved.snapshotDate || '') !== String(ledger.snapshotDate || '')) return null;
            if (String(resolved.strictStatus || '').toLowerCase() !== 'verified') return null;
            const method = String(resolved.strictMethod || '').toLowerCase();
            if (method !== 'interest-ledger' && method !== 'interest-ledger-override') return null;
            if (String(resolved.canonicalHistoryCoverageStatus || '').toLowerCase() !== 'fresh') return null;
            const comparisonBlock = earn_parseBlockNumberLike(resolved.comparisonBlock);
            if (comparisonBlock === null || comparisonBlock <= 0n) return null;
            const markets = resolved.markets;
            const verification = resolved.replayVerificationData;
            if (!markets || typeof markets !== 'object' || Object.keys(markets).length === 0) return null;
            if (!verification || typeof verification !== 'object') return null;
            const requiredIntegerFields = [
                'earnYield', 'settledYield', 'settledSupplyYield', 'settledBorrowYield',
                'openBorrowYield', 'openSupplyYield', 'openCollateralYield',
                'currentBorrowPar', 'currentSupplyPar', 'currentCollateralSupplyPar',
            ];
            for (const [marketId, market] of Object.entries(markets)) {
                if (!/^\d+$/.test(String(marketId)) || !market || typeof market !== 'object') return null;
                if (String(market.strictStatus || '').toLowerCase() !== 'verified') return null;
                const marketMethod = String(market.strictMethod || '').toLowerCase();
                if (marketMethod !== 'interest-ledger' && marketMethod !== 'interest-ledger-override') return null;
                if (requiredIntegerFields.some(field => !/^-?\d+$/.test(String(market[field] ?? '')))) return null;
                const check = verification[String(marketId)];
                if (!check || typeof check !== 'object') return null;
                if (
                    String(check.status || '').toLowerCase() !== 'verified'
                    || check.counted !== true
                    || check.canVerify !== true
                    || check.rawVerified !== true
                    || check.snapshotIncomplete !== false
                ) return null;
            }
            const countedMarketIds = Object.entries(verification)
                .filter(([, check]) => check && typeof check === 'object' && check.counted === true)
                .map(([marketId]) => String(marketId))
                .sort();
            const publishedMarketIds = Object.keys(markets).map(String).sort();
            if (
                countedMarketIds.length !== publishedMarketIds.length
                || countedMarketIds.some((marketId, index) => marketId !== publishedMarketIds[index])
            ) return null;
            return resolved;
        }

        function earn_applyPublishedResolvedInterestLedger(verifiedLedger) {
            if (earn_replayVerificationReady || earn_replayStatus === 'ready') return false;
            const resolved = earn_validatePublishedResolvedInterestLedger(verifiedLedger);
            if (!resolved) return false;
            const comparisonBlock = earn_parseBlockNumberLike(resolved.comparisonBlock);
            if (comparisonBlock === null) return false;

            earn_publishedResolvedInterestLedger = verifiedLedger;
            earn_interestYieldData = resolved.markets || {};
            earn_replayVerificationData = resolved.replayVerificationData || {};
            earn_replayVerificationSummary = Object.values(earn_replayVerificationData).reduce((summary, entry) => {
                summary.total += 1;
                if (String(entry.status || '').toLowerCase() === 'verified') summary.verified += 1;
                else if (String(entry.status || '').toLowerCase() === 'mismatch') summary.mismatch += 1;
                else summary.unverified += 1;
                return summary;
            }, { total: 0, verified: 0, mismatch: 0, unverified: 0 });
            earn_replayVerificationReady = earn_replayVerificationSummary.total > 0
                && earn_replayVerificationSummary.verified === earn_replayVerificationSummary.total;
            earn_replayAccountStateData = resolved.accountStateData || {};
            earn_replayCurrentIndexMap = resolved.currentIndexMap || {};
            earn_replayStateData = resolved.replayStateData || {};
            earn_openBorrowAccounts = new Set((resolved.openBorrowAccounts || []).map(value => String(value)));
            earn_replayBorrowAccountsOverride = new Set((resolved.borrowAccountsOverride || resolved.openBorrowAccounts || []).map(value => String(value)));
            earn_setCanonicalSubaccountHistoryState(comparisonBlock, true);
            earn_refreshResolvedTotalYieldData();
            return true;
        }

        // Get historical market data for a specific address from a snapshot
        function earn_getHistoricalMarkets(snapshot, chainId, address) {
            if (!snapshot || !snapshot.snapshots) return null;
            const chainData = snapshot.snapshots[chainId];
            if (!chainData) return null;
            // Try exact match (lowercase)
            const addrLower = address.toLowerCase();
            return chainData[addrLower] ? chainData[addrLower].markets : null;
        }

        // Compute cumulative yield using index-based pairwise method
        // For consecutive snapshots: yield = (par_prev × wei_curr - wei_prev × par_curr) / par_curr
        // This correctly isolates yield from swaps/trades/deposits/withdrawals
        async function earn_fetchTotalYield(opts) {
            opts = opts || {};
            const suppressRender = !!opts.suppressRender;
            const runId = opts.runId;
            const activeMarketIds = Array.isArray(opts.activeMarketIds) ? opts.activeMarketIds : [];
            const allowSnapshotFallback = opts.allowSnapshotFallback !== false;
            if (!earn_isLookupRunCurrent(runId)) return false;
            earn_totalYieldStatus = 'loading';
            earn_renderNotices();
            const nextTotalYieldData = {};
            let nextTotalYieldDays = 0;
            if (!earn_snapshotManifest) await earn_loadManifest();
            if (!earn_isLookupRunCurrent(runId)) return false;
            if (!earn_snapshotManifest) {
                earn_totalYieldStatus = 'error';
                earn_renderNotices();
                return false;
            }

            const chainId = document.getElementById('earn-chain').value;
            const addr = document.getElementById('earn-address').value.trim();
            const sortedDates = [...earn_snapshotManifest.dates].sort(); // oldest first
            const chainDates = sortedDates.filter(d => {
                const chains = earn_snapshotManifest.chains[d] || [];
                return !chainId || chains.includes(chainId);
            });

            const yieldHeader = document.getElementById('earn-total-yield-header');
            if (yieldHeader) yieldHeader.textContent = 'Loading...';

            // Needed markets come from active assets discovered in the current lookup plus any
            // replay/netflow history that identifies withdrawn markets for this wallet.
            const neededMarkets = new Set(activeMarketIds.map(mid => String(mid)));
            (earn_collateralPositionData || []).forEach(position => {
                if (!position) return;
                neededMarkets.add(earn_normalizeMarketId(position.marketId));
            });
            Object.keys(earn_netflowData || {}).forEach(mid => neededMarkets.add(String(mid)));

            // Preferred source: precomputed verified ledger for this exact address+chain.
            const verifiedLedger = await earn_fetchVerifiedLedgerForAddress(chainId, addr);
            earn_applyPublishedResolvedInterestLedger(verifiedLedger);
            let loadedLedgerMarkets = 0;
            let strictLedgerMarkets = 0;
            let deferredLedgerMarkets = 0;
            const deferredLedgerMetaByMarket = {};
            const historicalYieldHeader = allYieldDataStrict => allYieldDataStrict
                ? 'Total Yield Earned ✓ Historical'
                : 'Total Yield Earned · Historical evidence';
            if (verifiedLedger && verifiedLedger.markets && Object.keys(verifiedLedger.markets).length > 0) {
                if (!earn_isLookupRunCurrent(runId)) return false;
                Object.entries(verifiedLedger.markets).forEach(([mid, m]) => {
                    if (!earn_canUseVerifiedLedgerMarketEntry(m)) {
                        if (neededMarkets.has(String(mid))) {
                            deferredLedgerMarkets++;
                            nextTotalYieldData[String(mid)] = {
                                cumulativeYield: String(m.cumulativeYield || '0'),
                                days: Number(m.days || 0),
                                firstDate: m.firstDate || '',
                                firstPar: String(m.firstPar || '0'),
                                firstWei: String(m.firstWei || '0'),
                                lastDate: m.lastDate || '',
                                lastPar: String(m.lastPar || '0'),
                                lastWei: String(m.lastWei || '0'),
                                hasStaticParWindow: !!m.hasStaticParWindow,
                                verificationStatus: String(m.strictStatus || m.status || 'unverified'),
                                rawVerificationStatus: String(m.status || ''),
                                isLatestSnapshot: m.isLatestSnapshot !== false,
                                source: 'verified-ledger-deferred',
                                method: String(m.strictMethod || m.method || ''),
                                rawMethod: String(m.method || ''),
                                snapshotCount: (m.firstDate && m.lastDate && m.firstDate !== m.lastDate) ? 2 : 1,
                                canonicalHistoryCoverageStatus: String(m.canonicalHistoryCoverageStatus || ''),
                                canonicalHistoryLastScannedBlock: m.canonicalHistoryLastScannedBlock == null ? null : String(m.canonicalHistoryLastScannedBlock),
                                canonicalHistoryFreshForBorrowRouting: String(m.canonicalHistoryCoverageStatus || '').toLowerCase() === 'fresh',
                                historicalYieldUsd: String(m.historicalYieldUsd || '0'),
                                historicalYieldEligibleIntervals: Number(m.historicalYieldEligibleIntervals || 0),
                                historicalYieldPricedIntervals: Number(m.historicalYieldPricedIntervals || 0),
                                historicalYieldSkippedFlowIntervals: Number(m.historicalYieldSkippedFlowIntervals || 0),
                                historicalYieldMissingPriceIntervals: Number(m.historicalYieldMissingPriceIntervals || 0),
                                historicalYieldValuationStatus: String(m.historicalYieldValuationStatus || 'unavailable'),
                                historicalYieldValuationMethod: String(m.historicalYieldValuationMethod || ''),
                            };
                            nextTotalYieldDays = Math.max(nextTotalYieldDays, Number(m.days || 0));
                            deferredLedgerMetaByMarket[String(mid)] = {
                                verificationStatus: String(m.strictStatus || m.status || 'unverified'),
                                rawVerificationStatus: String(m.status || ''),
                                isLatestSnapshot: m.isLatestSnapshot !== false,
                                source: 'verified-ledger-deferred',
                                method: String(m.strictMethod || m.method || ''),
                                rawMethod: String(m.method || ''),
                                canonicalHistoryCoverageStatus: String(m.canonicalHistoryCoverageStatus || ''),
                                canonicalHistoryLastScannedBlock: m.canonicalHistoryLastScannedBlock == null ? null : String(m.canonicalHistoryLastScannedBlock),
                                canonicalHistoryFreshForBorrowRouting: String(m.canonicalHistoryCoverageStatus || '').toLowerCase() === 'fresh',
                            };
                        }
                        return;
                    }
                    nextTotalYieldData[String(mid)] = {
                        cumulativeYield: String(m.cumulativeYield || '0'),
                        days: Number(m.days || 0),
                        firstDate: m.firstDate || '',
                        firstPar: String(m.firstPar || '0'),
                        firstWei: String(m.firstWei || '0'),
                        lastDate: m.lastDate || '',
                        lastPar: String(m.lastPar || '0'),
                        lastWei: String(m.lastWei || '0'),
                        hasStaticParWindow: !!m.hasStaticParWindow,
                        verificationStatus: String(m.strictStatus || m.status || ''),
                        rawVerificationStatus: String(m.status || ''),
                        isLatestSnapshot: m.isLatestSnapshot !== false,
                        source: 'verified-ledger',
                        method: String(m.strictMethod || m.method || ''),
                        rawMethod: String(m.method || ''),
                        snapshotCount: (m.firstDate && m.lastDate && m.firstDate !== m.lastDate) ? 2 : 1,
                        canonicalHistoryCoverageStatus: String(m.canonicalHistoryCoverageStatus || ''),
                        canonicalHistoryLastScannedBlock: m.canonicalHistoryLastScannedBlock == null ? null : String(m.canonicalHistoryLastScannedBlock),
                        canonicalHistoryFreshForBorrowRouting: String(m.canonicalHistoryCoverageStatus || '').toLowerCase() === 'fresh',
                        historicalYieldUsd: String(m.historicalYieldUsd || '0'),
                        historicalYieldEligibleIntervals: Number(m.historicalYieldEligibleIntervals || 0),
                        historicalYieldPricedIntervals: Number(m.historicalYieldPricedIntervals || 0),
                        historicalYieldSkippedFlowIntervals: Number(m.historicalYieldSkippedFlowIntervals || 0),
                        historicalYieldMissingPriceIntervals: Number(m.historicalYieldMissingPriceIntervals || 0),
                        historicalYieldValuationStatus: String(m.historicalYieldValuationStatus || 'unavailable'),
                        historicalYieldValuationMethod: String(m.historicalYieldValuationMethod || ''),
                    };
                    loadedLedgerMarkets++;
                    if (earn_isTrustedReplayYieldStatus(String(m.strictStatus || m.status || ''))) {
                        strictLedgerMarkets++;
                    }
                    nextTotalYieldDays = Math.max(nextTotalYieldDays, Number(m.days || 0));
                });
                if (loadedLedgerMarkets > 0) {
                    console.log(
                        'Total yield: loaded historical ledger entries for',
                        loadedLedgerMarkets,
                        'markets',
                        deferredLedgerMarkets > 0 ? `(deferred ${deferredLedgerMarkets} markets to snapshot series)` : ''
                    );
                }
            }
            const marketsToCompute = new Set(Array.from(neededMarkets).filter(mid => !Object.prototype.hasOwnProperty.call(nextTotalYieldData, String(mid))));
            if (marketsToCompute.size === 0 && loadedLedgerMarkets > 0) {
                if (!earn_isLookupRunCurrent(runId)) return false;
                earn_totalYieldData = nextTotalYieldData;
                earn_totalYieldDays = nextTotalYieldDays;
                earn_totalYieldStatus = 'ready';
                if (yieldHeader) {
                    yieldHeader.textContent = historicalYieldHeader(strictLedgerMarkets === loadedLedgerMarkets);
                }
                earn_refreshHistoryYieldData();
                if (!suppressRender) {
                    earn_renderHistory(earn_historyData || []);
                    earn_renderWithdrawnAssets();
                    if (earn_cachedAssets) earn_renderResults(earn_cachedAssets, { skipSummary: true });
                }
                earn_renderNotices();
                return true;
            }

            if (!allowSnapshotFallback) {
                if (!earn_isLookupRunCurrent(runId)) return false;
                earn_totalYieldData = nextTotalYieldData;
                earn_totalYieldDays = nextTotalYieldDays;
                earn_totalYieldStatus = 'ready';
                if (yieldHeader) {
                    yieldHeader.textContent = loadedLedgerMarkets > 0
                        ? historicalYieldHeader(strictLedgerMarkets === loadedLedgerMarkets && marketsToCompute.size === 0)
                        : 'Total Yield Earned';
                }
                earn_refreshHistoryYieldData();
                if (!suppressRender) {
                    earn_renderHistory(earn_historyData || []);
                    earn_renderWithdrawnAssets();
                    if (earn_cachedAssets) earn_renderResults(earn_cachedAssets, { skipSummary: true });
                }
                if (marketsToCompute.size > 0) {
                    console.log(
                        'Total yield: fast ledger/replay path deferred snapshot fallback for',
                        marketsToCompute.size,
                        'markets'
                    );
                }
                earn_renderNotices();
                return Object.keys(nextTotalYieldData).length > 0;
            }

            // Load snapshots concurrently so Total Yield does not wait on a long
            // chain of sequential JSON fetches. Each snapshot is cached in-session.
            const marketHistory = {};
            for (const mid of marketsToCompute) marketHistory[mid] = [];

            const snapshotRows = await earn_mapWithConcurrency(chainDates, 6, async (dateStr) => {
                if (!earn_isLookupRunCurrent(runId)) return null;
                const snapshot = await earn_fetchSnapshot(dateStr);
                if (!snapshot || !earn_isLookupRunCurrent(runId)) return null;
                const markets = earn_getHistoricalMarkets(snapshot, chainId, addr);
                if (!markets) return null;
                return { date: dateStr, markets };
            });
            if (!earn_isLookupRunCurrent(runId)) return false;

            snapshotRows.forEach(row => {
                if (!row || !row.markets) return;
                marketsToCompute.forEach(mid => {
                    if (!row.markets[mid]) return;
                    marketHistory[mid].push({
                        date: row.date,
                        par: BigInt(row.markets[mid].par),
                        wei: BigInt(row.markets[mid].wei),
                    });
                });
            });

            // Compute pairwise index-based yield per market
            let marketsWithData = 0;
            for (const mid of marketsToCompute) {
                const history = marketHistory[mid];
                if (history.length < 2) continue;

                let cumulativeYield = 0n;
                for (let i = 1; i < history.length; i++) {
                    const prev = history[i - 1];
                    const curr = history[i];
                    // Skip if par is zero (edge case)
                    if (curr.par === 0n || prev.par === 0n) continue;
                    // yield = (par_prev * wei_curr - wei_prev * par_curr) / par_curr
                    const dailyYield = (prev.par * curr.wei - prev.wei * curr.par) / curr.par;
                    cumulativeYield += dailyYield;
                }

                const first = history[0];
                const last = history[history.length - 1];
                const sd = new Date(first.date + 'T00:00:00Z');
                const ld = new Date(last.date + 'T00:00:00Z');
                const days = Math.max(1, Math.round((ld - sd) / 86400000));
                const deferredMeta = deferredLedgerMetaByMarket[String(mid)] || null;

                nextTotalYieldData[mid] = {
                    cumulativeYield: cumulativeYield.toString(),
                    days: days,
                    firstDate: first.date,
                    firstPar: first.par.toString(),
                    firstWei: first.wei.toString(),
                    lastDate: last.date,
                    lastPar: last.par.toString(),
                    lastWei: last.wei.toString(),
                    hasStaticParWindow: history.every(point => point.par === first.par),
                    snapshotCount: history.length,
                    verificationStatus: deferredMeta ? String(deferredMeta.verificationStatus || 'unverified') : '',
                    rawVerificationStatus: deferredMeta ? String(deferredMeta.rawVerificationStatus || '') : '',
                    isLatestSnapshot: deferredMeta ? deferredMeta.isLatestSnapshot !== false : true,
                    source: deferredMeta ? deferredMeta.source : 'snapshot-series',
                    method: deferredMeta ? (deferredMeta.method || 'snapshot-fallback') : 'snapshot-series',
                    rawMethod: deferredMeta ? String(deferredMeta.rawMethod || '') : '',
                    canonicalHistoryCoverageStatus: deferredMeta ? String(deferredMeta.canonicalHistoryCoverageStatus || '') : '',
                    canonicalHistoryLastScannedBlock: deferredMeta ? deferredMeta.canonicalHistoryLastScannedBlock : null,
                    canonicalHistoryFreshForBorrowRouting: deferredMeta ? !!deferredMeta.canonicalHistoryFreshForBorrowRouting : false,
                };
                nextTotalYieldDays = Math.max(nextTotalYieldDays, days);
                marketsWithData++;
            }

            if (!earn_isLookupRunCurrent(runId)) return false;
            earn_totalYieldData = nextTotalYieldData;
            earn_totalYieldDays = nextTotalYieldDays;
            earn_totalYieldStatus = 'ready';
            const allYieldDataStrict = strictLedgerMarkets > 0
                && strictLedgerMarkets === loadedLedgerMarkets
                && marketsToCompute.size === 0
                && marketsWithData === 0;
            if (loadedLedgerMarkets > 0 && marketsWithData === 0) {
                if (yieldHeader) yieldHeader.textContent = historicalYieldHeader(allYieldDataStrict);
            } else if (marketsWithData > 0 || loadedLedgerMarkets > 0) {
                if (yieldHeader) yieldHeader.textContent = historicalYieldHeader(allYieldDataStrict);
                console.log(
                    'Total yield: computed index-based yield for',
                    marketsWithData,
                    'markets',
                    loadedLedgerMarkets > 0 ? `after keeping ${loadedLedgerMarkets} historical ledger markets` : ''
                );
            } else {
                if (yieldHeader) yieldHeader.textContent = 'Total Yield Earned';
            }

            earn_refreshHistoryYieldData();
            if (!suppressRender) {
                earn_renderHistory(earn_historyData || []);
                earn_renderWithdrawnAssets();
                if (earn_cachedAssets) earn_renderResults(earn_cachedAssets, { skipSummary: true });
            }
            earn_renderNotices();
            return true;
        }

        // === External Rewards: MERKL WLFI + oDOLO per-position ===
        let earn_merklRewards = {}; // { symbol: { accumulated, unclaimed, token, perToken, unclaimedPerToken, perAccountToken, unclaimedPerAccountToken, assignedPerToken, assignedUnclaimedPerToken } }
        let earn_merklRewardsLoaded = false;
        let earn_odoloMeta = null;  // { allChainWeights, currentEpochRewards, ... }

        function earn_createRewardBucket(decimals, tokenAddr) {
            return {
                accumulated: 0,
                unclaimed: 0,
                decimals,
                token: tokenAddr,
                perToken: {},
                unclaimedPerToken: {},
                perAccountToken: {},
                unclaimedPerAccountToken: {},
                assignedPerToken: {},
                assignedUnclaimedPerToken: {},
            };
        }

        function earn_parseMerklRawAmount(value) {
            try {
                const parsed = BigInt(String(value ?? '0'));
                return parsed > 0n ? parsed : 0n;
            } catch (_) {
                return 0n;
            }
        }

        function earn_getMerklV4AccumulatedRaw(reward) {
            return earn_parseMerklRawAmount(reward && reward.amount)
                + earn_parseMerklRawAmount(reward && reward.pending);
        }

        function earn_getMerklV4UnclaimedRaw(reward) {
            const amount = earn_parseMerklRawAmount(reward && reward.amount);
            const claimed = earn_parseMerklRawAmount(reward && reward.claimed);
            const pending = earn_parseMerklRawAmount(reward && reward.pending);
            return (amount > claimed ? amount - claimed : 0n) + pending;
        }

        function earn_parseMerklV4Rewards(chainId, numericId, payload, campaignTokenMap) {
            if (!Array.isArray(payload)) return {};
            const dolomiteRewards = {};
            for (const chainEntry of payload) {
                if (!chainEntry || String(chainEntry.chain && chainEntry.chain.id) !== String(numericId)) continue;
                for (const reward of (chainEntry.rewards || [])) {
                    if (!reward || typeof reward !== 'object') continue;
                    const tokenMeta = reward.token && typeof reward.token === 'object' ? reward.token : {};
                    const symbol = String(tokenMeta.symbol || reward.symbol || '').trim();
                    const decimals = Number(tokenMeta.decimals ?? reward.decimals ?? 18);
                    const tokenAddr = String(tokenMeta.address || reward.token || '');
                    if (!symbol || !Number.isSafeInteger(decimals) || decimals < 0 || decimals > 512) continue;

                    for (const breakdown of (reward.breakdowns || [])) {
                        if (!breakdown || typeof breakdown !== 'object') continue;
                        const reasonKey = String(breakdown.reason || '');
                        const marketTokenAddr = earn_resolveMerklReasonTokenAddress(chainId, reasonKey, breakdown, campaignTokenMap);
                        if (!marketTokenAddr) continue;

                        const bucket = dolomiteRewards[symbol] || (dolomiteRewards[symbol] = earn_createRewardBucket(decimals, tokenAddr));
                        const accumulated = earn_bigIntToDecimalNumber(earn_getMerklV4AccumulatedRaw(breakdown), decimals);
                        const unclaimed = earn_bigIntToDecimalNumber(earn_getMerklV4UnclaimedRaw(breakdown), decimals);
                        bucket.accumulated += accumulated;
                        bucket.unclaimed += unclaimed;
                        bucket.perToken[marketTokenAddr] = (bucket.perToken[marketTokenAddr] || 0) + accumulated;
                        bucket.unclaimedPerToken[marketTokenAddr] = (bucket.unclaimedPerToken[marketTokenAddr] || 0) + unclaimed;

                        const accountMatch = reasonKey.match(/^MultiLogPerAdditionalParam_accountNumber_([^_]+)_/);
                        if (!accountMatch) continue;
                        const accountNumber = String(accountMatch[1]);
                        const accountRewards = bucket.perAccountToken[accountNumber] || (bucket.perAccountToken[accountNumber] = {});
                        const accountUnclaimed = bucket.unclaimedPerAccountToken[accountNumber] || (bucket.unclaimedPerAccountToken[accountNumber] = {});
                        accountRewards[marketTokenAddr] = (accountRewards[marketTokenAddr] || 0) + accumulated;
                        accountUnclaimed[marketTokenAddr] = (accountUnclaimed[marketTokenAddr] || 0) + unclaimed;
                        bucket.assignedPerToken[marketTokenAddr] = (bucket.assignedPerToken[marketTokenAddr] || 0) + accumulated;
                        bucket.assignedUnclaimedPerToken[marketTokenAddr] = (bucket.assignedUnclaimedPerToken[marketTokenAddr] || 0) + unclaimed;
                    }
                }
            }
            return dolomiteRewards;
        }

        function earn_applyMerklRewardsResult(dolomiteRewards, userAddr, chainId, requestKey) {
            // Stale-response guard: never let wallet A's late Merkl result
            // overwrite globals while wallet B's lookup is on screen.
            if (!earn_isLookupAddrCurrent(userAddr)) {
                console.log('MERKL: stale response for', userAddr, '— globals not updated');
                return dolomiteRewards || {};
            }
            const rewardTokenAddrs = Array.from(new Set(
                Object.values(dolomiteRewards || {})
                    .map(entry => String(entry && entry.token ? entry.token : '').toLowerCase())
                    .filter(Boolean)
            ));
            earn_merklRewards = dolomiteRewards || {};
            earn_merklRewardsLoaded = true;
            earn_merklRewardsLoadedFor = requestKey;
            earn_setMerklFetchState('success', '', userAddr, chainId);
            earn_softRefreshRewardsUi(userAddr, chainId);
            if (rewardTokenAddrs.length > 0) {
                void earn_fetchCoinGeckoPrices(rewardTokenAddrs)
                    .then(() => {
                        earn_softRefreshRewardsUi(userAddr, chainId);
                    })
                    .catch(e => {
                        console.warn('MERKL reward price refresh failed:', e);
                    });
            }
            return earn_merklRewards;
        }

        function earn_normalizeCachedMerklRewards(payload) {
            const rewards = payload && payload.rewards ? payload.rewards : payload;
            if (!rewards || typeof rewards !== 'object' || Array.isArray(rewards)) return null;
            return Object.keys(rewards).length > 0 ? rewards : null;
        }

        async function earn_fetchCachedMerklRewards(userAddr, chainId) {
            const addr = String(userAddr || '').trim().toLowerCase();
            const chain = String(chainId || '').trim().toLowerCase();
            const cacheKey = earn_getRemoteLookupKey(chain, addr);
            if (!cacheKey) return null;
            if (Object.prototype.hasOwnProperty.call(earn_cachedMerklRewardsCache, cacheKey)) {
                return earn_cachedMerklRewardsCache[cacheKey];
            }
            if (earn_cachedMerklRewardsRequestCache[cacheKey]) {
                return earn_cachedMerklRewardsRequestCache[cacheKey];
            }
            const request = (async () => {
                const resp = await fetch(`${EARN_MERKL_REWARDS_BASE}/${chain}/${addr}.json`, { cache: 'no-store' });
                if (!resp.ok) return null;
                const payload = await resp.json();
                return earn_normalizeCachedMerklRewards(payload);
            })().catch(e => {
                console.warn('Cached MERKL rewards fetch failed:', e);
                return null;
            });
            earn_cachedMerklRewardsRequestCache[cacheKey] = request;
            try {
                const rewards = await request;
                earn_cachedMerklRewardsCache[cacheKey] = rewards;
                return rewards;
            } finally {
                delete earn_cachedMerklRewardsRequestCache[cacheKey];
            }
        }

        // Fetch MERKL rewards (exact WLFI earned) for a wallet on a specific chain
        async function earn_fetchMerklRewards(userAddr, chainId) {
            const CHAIN_IDS = { ethereum: 1, berachain: 80094, arbitrum: 42161, mantle: 5000 };
            const numericId = CHAIN_IDS[chainId];
            if (!numericId) return {};
            const addr = String(userAddr || '').trim().toLowerCase();
            const requestKey = earn_getRemoteLookupKey(chainId, addr);
            if (!requestKey) return {};
            if (earn_merklRewardsLoadedFor === requestKey && earn_merklRewardsLoaded) {
                earn_setMerklFetchState('success', '', userAddr, chainId);
                return earn_merklRewards || {};
            }
            if (earn_rewardRequestCache.merkl[requestKey]) {
                return earn_rewardRequestCache.merkl[requestKey];
            }

            earn_setMerklFetchState('loading', '', userAddr, chainId);
            const request = (async () => {
                const cachedMerklRewardsPromise = earn_fetchCachedMerklRewards(addr, chainId);
                const merklRatesReady = earn_fetchMarketRates(chainId).catch(e => {
                    console.warn('MERKL campaign map rate prefetch failed:', e);
                    return null;
                });
                const url = `https://api.merkl.xyz/v4/users/${encodeURIComponent(addr)}/protocols/dolomite/rewards?chainId=${numericId}`;
                // 10s timeout via AbortController — a hung api.merkl.xyz must not block the
                // whole lending section forever (every other fetch wrapper has this guard).
                const merklCtrl = new AbortController();
                const merklTimer = setTimeout(() => merklCtrl.abort(), 10000);
                let resp;
                try {
                    resp = await fetch(url, { signal: merklCtrl.signal });
                } finally {
                    clearTimeout(merklTimer);
                }
                if (!resp.ok) {
                    const cachedRewards = await cachedMerklRewardsPromise;
                    if (cachedRewards) {
                        return earn_applyMerklRewardsResult(cachedRewards, userAddr, chainId, requestKey);
                    }
                    earn_setMerklFetchState('error', `HTTP ${resp.status}`, userAddr, chainId);
                    earn_merklRewards = {};
                    earn_merklRewardsLoaded = true;
                    earn_merklRewardsLoadedFor = requestKey;
                    return {};
                }
                const data = await resp.json();
                await merklRatesReady;
                const campaignTokenMap = earn_getMerklCampaignTokenMap(chainId);
                const dolomiteRewards = earn_parseMerklV4Rewards(chainId, numericId, data, campaignTokenMap);
                return earn_applyMerklRewardsResult(dolomiteRewards, userAddr, chainId, requestKey);
            })().catch(e => {
                console.warn('MERKL rewards fetch failed:', e);
                return earn_fetchCachedMerklRewards(addr, chainId).then(cachedRewards => {
                    if (cachedRewards) {
                        return earn_applyMerklRewardsResult(cachedRewards, userAddr, chainId, requestKey);
                    }
                    earn_setMerklFetchState('error', e && e.message ? e.message : String(e), userAddr, chainId);
                    earn_merklRewards = {};
                    earn_merklRewardsLoaded = true;
                    earn_merklRewardsLoadedFor = requestKey;
                    return {};
                });
            }).catch(e => {
                console.warn('Cached MERKL rewards fallback failed:', e);
                earn_setMerklFetchState('error', e && e.message ? e.message : String(e), userAddr, chainId);
                earn_merklRewards = {};
                earn_merklRewardsLoaded = true;
                earn_merklRewardsLoadedFor = requestKey;
                return {};
            });

            earn_rewardRequestCache.merkl[requestKey] = request;
            try {
                return await request;
            } finally {
                delete earn_rewardRequestCache.merkl[requestKey];
            }
        }

        // Fetch oDOLO metadata (per-token weekly allocation)
        async function earn_fetchOdoloMetadata() {
            if (earn_odoloMetaLoaded) return earn_odoloMeta;
            if (earn_rewardRequestCache.odoloMeta) return earn_rewardRequestCache.odoloMeta;

            const request = (async () => {
                const resp = await fetch('https://api.dolomite.io/liquidity-mining/odolo/metadata');
                if (!resp.ok) {
                    earn_odoloMeta = null;
                    earn_odoloMetaLoaded = true;
                    return null;
                }
                const data = await resp.json();
                earn_odoloMeta = data.metadata || null;
                earn_odoloMetaLoaded = true;
                return earn_odoloMeta;
            })().catch(e => {
                console.warn('oDOLO metadata fetch failed:', e);
                earn_odoloMeta = null;
                earn_odoloMetaLoaded = true;
                return null;
            });

            earn_rewardRequestCache.odoloMeta = request;
            try {
                return await request;
            } finally {
                earn_rewardRequestCache.odoloMeta = null;
            }
        }

        // === Dolomite Subgraph endpoints (free, via Goldsky) ===
        const SUBGRAPH_ENDPOINTS = {
            arbitrum: 'https://api.goldsky.com/api/public/project_clyuw4gvq4d5801tegx0aafpu/subgraphs/dolomite-arbitrum/latest/gn',
            berachain: 'https://api.goldsky.com/api/public/project_clyuw4gvq4d5801tegx0aafpu/subgraphs/dolomite-berachain-mainnet/latest/gn',
            ethereum: 'https://api.goldsky.com/api/public/project_clyuw4gvq4d5801tegx0aafpu/subgraphs/dolomite-ethereum/latest/gn',
            mantle: 'https://subgraph.api.dolomite.io/api/public/1301d2d1-7a9d-4be4-9e9a-061cb8611549/subgraphs/dolomite-mantle/latest/gn',
        };

        const EARN_SUBGRAPH_TIMEOUT_MS = 8000;

        // GraphQL query helper with timeout + retry so a hung subgraph request
        // cannot block the whole replay / verified-yield pipeline forever.
        async function earn_subgraphQuery(endpoint, query, variables, opts) {
            opts = opts || {};
            const retries = Math.max(1, Number(opts.retries || 2));
            const timeoutMs = Math.max(1000, Number(opts.timeoutMs || EARN_SUBGRAPH_TIMEOUT_MS));
            let lastError = null;

            for (let attempt = 0; attempt < retries; attempt++) {
                const ctrl = new AbortController();
                const timer = setTimeout(() => ctrl.abort(), timeoutMs);
                try {
                    const resp = await fetch(endpoint, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        signal: ctrl.signal,
                        body: JSON.stringify({ query, variables }),
                    });
                    clearTimeout(timer);
                    if (!resp.ok) throw new Error(`Subgraph HTTP ${resp.status}`);
                    const json = await resp.json();
                    if (json.errors) throw new Error(json.errors[0].message);
                    return json.data;
                } catch (e) {
                    clearTimeout(timer);
                    lastError = e && e.name === 'AbortError'
                        ? new Error(`Subgraph timeout after ${timeoutMs}ms`)
                        : e;
                    if (attempt === retries - 1) break;
                }
            }

            throw lastError || new Error('Subgraph query failed');
        }

        // Paginate through all results for a given entity (max 1000 per query)
        async function earn_subgraphPaginateAll(endpoint, entityName, whereClause, fields) {
            const PAGE_SIZE = 1000;
            let allResults = [];
            let cursorId = '';
            const baseWhere = String(whereClause || '')
                .trim()
                .replace(/^\{\s*|\s*\}$/g, '');

            while (true) {
                const escapedCursor = cursorId.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
                const cursorFilter = cursorId ? `${baseWhere ? ', ' : ''}id_gt: "${escapedCursor}"` : '';
                const query = `{ ${entityName}(first: ${PAGE_SIZE}, orderBy: id, orderDirection: asc, where: { ${baseWhere}${cursorFilter} }) { id ${fields} } }`;
                const data = await earn_subgraphQuery(endpoint, query);
                const batch = data[entityName] || [];
                allResults = allResults.concat(batch);
                if (batch.length < PAGE_SIZE) break;

                const nextCursorId = String(batch[batch.length - 1]?.id || '');
                if (!nextCursorId || nextCursorId === cursorId) {
                    // Never continue with a partial replay if a provider omits a stable cursor.
                    console.warn(`earn_subgraphPaginateAll: ${entityName} stopped without a valid cursor after ${allResults.length} rows.`);
                    allResults.truncated = true;
                    break;
                }
                cursorId = nextCursorId;
            }
            return allResults;
        }

        async function earn_fetchCurrentAccountsFromSubgraph(addr) {
            const chainId = document.getElementById('earn-chain').value;
            const address = String(addr || '').trim().toLowerCase();
            if (!address) return { accountNumbers: [], borrowAccountNumbers: [], positions: [] };
            const historyTargetBlockTag = String(earn_replayBlockTag || '').trim();
            if (earn_subgraphAccountSnapshot &&
                earn_subgraphAccountSnapshot.chainId === chainId &&
                earn_subgraphAccountSnapshot.address === address) {
                const snapshotTargetBlockTag = String(earn_subgraphAccountSnapshot.historyTargetBlockTag || '').trim();
                const needsHistoryRefresh = !!(
                    historyTargetBlockTag &&
                    (
                        !earn_subgraphAccountSnapshot.historyBorrowFresh ||
                        snapshotTargetBlockTag !== historyTargetBlockTag
                    )
                );
                if (!needsHistoryRefresh) {
                    return earn_subgraphAccountSnapshot;
                }
            }
            const requestKey = `${chainId}:${address}:${historyTargetBlockTag || 'no-blocktag'}`;
            if (earn_subgraphAccountSnapshotRequests[requestKey]) {
                return earn_subgraphAccountSnapshotRequests[requestKey];
            }

            const endpoint = SUBGRAPH_ENDPOINTS[chainId];
            if (!endpoint) {
                const empty = {
                    chainId,
                    address,
                    accountNumbers: [],
                    borrowAccountNumbers: [],
                    historicalAccountNumbers: [],
                    positions: [],
                    historyTargetBlockTag,
                    historyBorrowFresh: false,
                    historyLastScannedBlock: null,
                };
                earn_subgraphAccountSnapshot = empty;
                return empty;
            }

            const request = (async () => {
                const query = `{
                marginAccounts(first: 1000, where: { effectiveUser: "${address}" }) {
                    accountNumber
                    tokenValues {
                        token { id marketId symbol decimals name }
                        valuePar
                    }
                }
                interestIndexes(first: 1000) { id supplyIndex borrowIndex }
            }`;
                const data = await earn_subgraphQuery(endpoint, query);
                const indexMap = {};
                (data.interestIndexes || []).forEach(ix => {
                    const tokenAddr = (ix.id || '').toLowerCase();
                    indexMap[tokenAddr] = {
                        supplyIndex: earn_decimalToBigInt(ix.supplyIndex || '1', 18),
                        borrowIndex: earn_decimalToBigInt(ix.borrowIndex || '1', 18),
                    };
                });

                const accountNumbers = [];
                const borrowAccountNumbers = [];
                const positions = [];
                (data.marginAccounts || []).forEach(ma => {
                    const accountNumber = String(ma.accountNumber || '0');
                    let accountHasOpenPosition = false;
                    let accountHasOpenBorrow = false;
                    (ma.tokenValues || []).forEach(tv => {
                        const token = tv.token || {};
                        const tokenAddr = (token.id || '').toLowerCase();
                        const decimals = Number(token.decimals || 18);
                        const marketId = earn_normalizeMarketId(token.marketId);
                        if (!tokenAddr || !marketId) return;
                        const par = earn_decimalToBigInt(tv.valuePar || '0', decimals);
                        if (par === 0n) return;
                        accountHasOpenPosition = true;
                        const indexes = indexMap[tokenAddr] || { supplyIndex: 10n ** 18n, borrowIndex: 10n ** 18n };
                        const absPar = earn_absBigInt(par);
                        const idx = par > 0n ? indexes.supplyIndex : indexes.borrowIndex;
                        const absWei = (absPar * idx) / (10n ** 18n);
                        const wei = par > 0n ? absWei : -absWei;
                        if (par < 0n || wei < 0n) accountHasOpenBorrow = true;

                        // XSS guard: subgraph symbol/name are deployer-controlled and
                        // these objects feed innerHTML templates. Escape once here
                        // (raw values still used for the icon lookups just below);
                        // previously-stored values are already escaped — don't re-escape.
                        const safeSgSymbol = token.symbol ? earn_escapeHtml(token.symbol) : null;
                        const safeSgName = token.name ? earn_escapeHtml(token.name) : null;
                        earn_subgraphTokens[marketId] = {
                            symbol: safeSgSymbol || earn_subgraphTokens[marketId]?.symbol || 'UNK',
                            decimals,
                            name: safeSgName || safeSgSymbol || earn_subgraphTokens[marketId]?.name || 'UNK',
                            tokenAddr,
                            icon: earn_subgraphTokens[marketId]?.icon || SYMBOL_ICONS[token.symbol] || SYMBOL_ICONS[(token.symbol || '').toUpperCase()] || null,
                        };
                        earn_tokenCache[chainId + ':' + tokenAddr] = {
                            symbol: earn_subgraphTokens[marketId].symbol,
                            decimals,
                            icon: earn_subgraphTokens[marketId].icon,
                            name: earn_subgraphTokens[marketId].name,
                        };

                        positions.push({
                            marketId,
                            tokenAddr,
                            par,
                            wei,
                            accountNumber,
                        });
                    });
                    if (accountHasOpenPosition && !accountNumbers.includes(accountNumber)) {
                        accountNumbers.push(accountNumber);
                    }
                    if (accountHasOpenBorrow && !borrowAccountNumbers.includes(accountNumber)) {
                        borrowAccountNumbers.push(accountNumber);
                    }
                });

                const coalescedPositions = earn_coalesceCurrentPositions(positions);

                const subaccountHistory = await earn_fetchSubaccountHistoryForAddress(chainId, address);
                const historyHints = earn_extractSubaccountHistoryHints(subaccountHistory, {
                    blockTag: historyTargetBlockTag || null,
                });
                earn_updateCanonicalSubaccountHistoryStateFromHints(historyHints);
                const borrowAccountSet = new Set([
                    ...borrowAccountNumbers.map(v => String(v)),
                    ...historyHints.borrowAccountNumbers.map(v => String(v)),
                ]);
                coalescedPositions.forEach(pos => {
                    const historyRoute = historyHints.marketRoutes[`${String(pos.accountNumber || '0')}|${earn_normalizeMarketId(pos.marketId)}`];
                    if (historyRoute === 'borrow' || pos.par < 0n || pos.wei < 0n) {
                        pos.positionKind = 'borrow';
                    } else if (historyRoute === 'collateral') {
                        pos.positionKind = 'hidden-collateral';
                    } else if (historyRoute === 'supply') {
                        pos.positionKind = 'visible-supply';
                    } else if (borrowAccountSet.has(String(pos.accountNumber || '0'))) {
                        pos.positionKind = 'hidden-collateral';
                    } else {
                        pos.positionKind = 'visible-supply';
                    }
                });

                const snapshot = {
                    chainId,
                    address,
                    accountNumbers,
                    borrowAccountNumbers: Array.from(borrowAccountSet),
                    historicalAccountNumbers: historyHints.accountNumbers,
                    positions: coalescedPositions,
                    historyTargetBlockTag,
                    historyBorrowFresh: !!historyHints.freshForBorrowRouting,
                    historyLastScannedBlock: historyHints.lastScannedBlock === null
                        ? null
                        : String(historyHints.lastScannedBlock),
                };
                earn_subgraphAccountSnapshot = snapshot;
                return snapshot;
            })();

            earn_subgraphAccountSnapshotRequests[requestKey] = request;
            try {
                return await request;
            } finally {
                delete earn_subgraphAccountSnapshotRequests[requestKey];
            }
        }

        function earn_decodeUserActionLog(log, userAddr) {
            const topic0 = (log.topics && log.topics[0] ? log.topics[0] : '').toLowerCase();
            const owner1 = log.topics && log.topics[1] ? earn_decodeAddressWord(log.topics[1]) : null;
            const owner2 = log.topics && log.topics[2] ? earn_decodeAddressWord(log.topics[2]) : null;
            const words = earn_splitHexWords(log.data);
            const updates = [];
            const pushUpdate = (owner, accountWord, marketWord, update, flowType) => {
                if (!owner || owner !== userAddr) return;
                updates.push({
                    marketId: earn_hexToBigInt('0x' + (marketWord || '0')).toString(),
                    accountNumber: earn_hexToBigInt('0x' + (accountWord || '0')).toString(),
                    deltaWei: update.deltaWei,
                    newPar: update.newPar,
                    flowType,
                    blockNumber: earn_logSortValue(log, 'blockNumber'),
                    transactionIndex: earn_logSortValue(log, 'transactionIndex'),
                    logIndex: earn_logSortValue(log, 'logIndex'),
                });
            };

            if (topic0 === EARN_ACTION_LOG_TOPICS.deposit) {
                if (words.length >= 6) pushUpdate(owner1, words[0], words[1], earn_decodeBalanceUpdateWords(words, 2), 'd');
            } else if (topic0 === EARN_ACTION_LOG_TOPICS.withdraw) {
                if (words.length >= 6) pushUpdate(owner1, words[0], words[1], earn_decodeBalanceUpdateWords(words, 2), 'w');
            } else if (topic0 === EARN_ACTION_LOG_TOPICS.transfer) {
                if (words.length >= 11) {
                    pushUpdate(owner1, words[0], words[2], earn_decodeBalanceUpdateWords(words, 3), 'x');
                    pushUpdate(owner2, words[1], words[2], earn_decodeBalanceUpdateWords(words, 7), 'x');
                }
            } else if (topic0 === EARN_ACTION_LOG_TOPICS.buy || topic0 === EARN_ACTION_LOG_TOPICS.sell) {
                if (words.length >= 11) {
                    pushUpdate(owner1, words[0], words[1], earn_decodeBalanceUpdateWords(words, 3), 's');
                    pushUpdate(owner1, words[0], words[2], earn_decodeBalanceUpdateWords(words, 7), 's');
                }
            } else if (topic0 === EARN_ACTION_LOG_TOPICS.trade) {
                if (words.length >= 20) {
                    pushUpdate(owner1, words[0], words[2], earn_decodeBalanceUpdateWords(words, 4), 's');
                    pushUpdate(owner1, words[0], words[3], earn_decodeBalanceUpdateWords(words, 8), 's');
                    pushUpdate(owner2, words[1], words[2], earn_decodeBalanceUpdateWords(words, 12), 's');
                    pushUpdate(owner2, words[1], words[3], earn_decodeBalanceUpdateWords(words, 16), 's');
                }
            } else if (topic0 === EARN_ACTION_LOG_TOPICS.liquidate) {
                if (words.length >= 20) {
                    pushUpdate(owner1, words[0], words[2], earn_decodeBalanceUpdateWords(words, 4), 'l');
                    pushUpdate(owner1, words[0], words[3], earn_decodeBalanceUpdateWords(words, 8), 'l');
                    pushUpdate(owner2, words[1], words[2], earn_decodeBalanceUpdateWords(words, 12), 'l');
                    pushUpdate(owner2, words[1], words[3], earn_decodeBalanceUpdateWords(words, 16), 'l');
                }
            } else if (topic0 === EARN_ACTION_LOG_TOPICS.vaporize) {
                if (words.length >= 16) {
                    pushUpdate(owner1, words[0], words[2], earn_decodeBalanceUpdateWords(words, 4), 'v');
                    pushUpdate(owner1, words[0], words[3], earn_decodeBalanceUpdateWords(words, 8), 'v');
                    pushUpdate(owner2, words[1], words[3], earn_decodeBalanceUpdateWords(words, 12), 'v');
                }
            }

            return updates;
        }

        async function earn_shouldUseSubgraphReplay(addr, onchainReplay) {
            try {
                const snapshot = await earn_fetchCurrentAccountsFromSubgraph(addr);
                const activeAccounts = Array.from(new Set(
                    (snapshot.positions || [])
                        .map(pos => String(pos.accountNumber || '0'))
                        .filter(Boolean)
                ));
                if (activeAccounts.length === 0) {
                    return { shouldFallback: false, reason: null, missingAccounts: [], missingMarkets: [] };
                }

                const replayAccounts = new Set((onchainReplay.accountNumbers || []).map(v => String(v)));
                const missingAccounts = activeAccounts.filter(ac => !replayAccounts.has(ac));
                if (missingAccounts.length > 0) {
                    return {
                        shouldFallback: true,
                        reason: 'missing-active-accounts',
                        missingAccounts,
                        missingMarkets: [],
                    };
                }

                const activeMarkets = Array.from(new Set(
                    (snapshot.positions || [])
                        .map(pos => earn_normalizeMarketId(pos.marketId))
                        .filter(Boolean)
                ));
                const replayMarkets = new Set(Object.keys(onchainReplay.interestYieldData || {}));
                const missingMarkets = activeMarkets.filter(mid => !replayMarkets.has(mid));
                if (missingMarkets.length > 0) {
                    return {
                        shouldFallback: true,
                        reason: 'missing-active-markets',
                        missingAccounts: [],
                        missingMarkets,
                    };
                }

                return { shouldFallback: false, reason: null, missingAccounts: [], missingMarkets: [] };
            } catch (e) {
                console.warn('Replay coverage check failed:', e.message || e);
                return { shouldFallback: false, reason: null, missingAccounts: [], missingMarkets: [] };
            }
        }

        async function earn_buildSubgraphReplay(addr) {
            const chainId = document.getElementById('earn-chain').value;
            const endpoint = SUBGRAPH_ENDPOINTS[chainId];
            if (!endpoint) {
                return {
                    accountNumbers: [],
                    netflows: {},
                    acct0Netflows: null,
                    interestYieldData: {},
                    replayStateData: {},
                    marketMeta: {},
                };
            }

            const userAddr = String(addr || '').trim().toLowerCase();
            if (!userAddr) {
                return {
                    accountNumbers: [],
                    netflows: {},
                    acct0Netflows: null,
                    interestYieldData: {},
                    replayStateData: {},
                    marketMeta: {},
                };
            }

            const netflows = {};
            const acct0Netflows = {};
            const marketEvents = {};
            const interestEvents = [];
            const replayEventTrace = [];
            const marketDecimals = {};
            const accountNumbers = new Set();
            const explicitBorrowAccounts = new Set();
            const INDEX_SCALE = 10n ** 18n;

            const toAmount = (rawValue, decimals) => {
                const dec = Math.max(0, Number(decimals || 18));
                return earn_decimalToBigInt(String(rawValue || '0'), dec);
            };
            const negStr = (value) => {
                if (value === undefined || value === null) return '0';
                const s = String(value);
                if (s === '0' || s === '0.0') return '0';
                return s.startsWith('-') ? s.slice(1) : '-' + s;
            };
            const parseDecimals = (value) => {
                const parsed = Number(value || 18);
                return Number.isFinite(parsed) && parsed >= 0 ? parsed : 18;
            };
            const ensureFlowEntry = (marketId) => {
                const mid = String(marketId);
                if (!netflows[mid]) {
                    netflows[mid] = { t: 0n, d: 0n, w: 0n, s: 0n, x: 0n, l: 0n, b: 0n, v: 0n };
                }
                return netflows[mid];
            };
            const addFlow = (marketId, deltaStr, flowType, decimals) => {
                const mid = String(marketId);
                const dec = parseDecimals(decimals);
                marketDecimals[mid] = dec;
                const entry = ensureFlowEntry(mid);
                const delta = toAmount(deltaStr, dec);
                if (delta === 0n) return;
                entry.t += delta;
                const absDelta = delta < 0n ? -delta : delta;
                entry[flowType] += absDelta;
            };
            const addAcct0Flow = (marketId, deltaStr, decimals) => {
                const mid = String(marketId);
                const dec = parseDecimals(decimals);
                marketDecimals[mid] = dec;
                if (!acct0Netflows[mid]) acct0Netflows[mid] = 0n;
                const delta = toAmount(deltaStr, dec);
                if (delta === 0n) return;
                acct0Netflows[mid] += delta;
            };
            const addMarketEvent = (marketId, serialId, parDeltaStr, weiDeltaStr, decimals) => {
                if (serialId === undefined || serialId === null) return;
                const mid = String(marketId);
                const dec = parseDecimals(decimals);
                marketDecimals[mid] = dec;
                const parDelta = toAmount(parDeltaStr, dec);
                const weiDelta = toAmount(weiDeltaStr, dec);
                if (parDelta === 0n && weiDelta === 0n) return;
                if (!marketEvents[mid]) marketEvents[mid] = [];
                marketEvents[mid].push({
                    serial: Number(serialId),
                    parDelta,
                    weiDelta,
                });
            };
            const addInterestEvent = (accountNumber, marketId, serialId, parDeltaStr, weiDeltaStr, indexStr, decimals, flowType) => {
                if (accountNumber === undefined || accountNumber === null || serialId === undefined || serialId === null) return;
                const account = String(accountNumber);
                if (!account) return;
                accountNumbers.add(account);
                const mid = String(marketId);
                const dec = parseDecimals(decimals);
                marketDecimals[mid] = dec;
                const parDelta = toAmount(parDeltaStr, dec);
                if (parDelta === 0n) return;
                const parAbs = parDelta < 0n ? -parDelta : parDelta;
                let index = null;
                if (indexStr !== undefined && indexStr !== null && String(indexStr) !== '') {
                    index = earn_decimalToBigInt(String(indexStr), 18);
                } else {
                    const weiDelta = toAmount(weiDeltaStr, dec);
                    const weiAbs = weiDelta < 0n ? -weiDelta : weiDelta;
                    if (weiAbs > 0n && parAbs > 0n) {
                        index = (weiAbs * INDEX_SCALE) / parAbs;
                    }
                }
                if (!index || index <= 0n) return;
                interestEvents.push({
                    serial: Number(serialId),
                    account,
                    marketId: mid,
                    parDelta,
                    index,
                    weiDelta: toAmount(weiDeltaStr, dec),
                    flowType: flowType || 'u',
                });
            };
            const computeRecentCycleSummary = (events) => {
                if (!events || events.length === 0) return null;
                const ordered = [...events].sort((a, b) => a.serial - b.serial);
                let runningPar = 0n;
                let peakPar = 0n;
                const balances = [];
                ordered.forEach(ev => {
                    runningPar += ev.parDelta;
                    if (runningPar > peakPar) peakPar = runningPar;
                    balances.push({ serial: ev.serial, balance: runningPar });
                });
                if (runningPar <= 0n || peakPar <= 0n) return { endingPar: runningPar.toString() };

                const resetThreshold = runningPar / 5n;
                let suffixMin = runningPar;
                let resetIdx = -1;
                for (let i = balances.length - 1; i >= 0; i--) {
                    const bal = balances[i].balance;
                    if (bal < suffixMin) suffixMin = bal;
                    if (bal === suffixMin && bal > 0n && bal <= resetThreshold) {
                        resetIdx = i;
                        break;
                    }
                }
                if (resetIdx === -1 || resetIdx >= ordered.length - 1) return { endingPar: runningPar.toString() };

                let recentNetFlow = 0n;
                for (let i = resetIdx + 1; i < ordered.length; i++) {
                    recentNetFlow += ordered[i].weiDelta;
                }
                return {
                    endingPar: runningPar.toString(),
                    resetPar: balances[resetIdx].balance.toString(),
                    recentNetFlow: recentNetFlow.toString(),
                    lastResetSerial: String(balances[resetIdx].serial),
                };
            };
            const buildInterestYieldSummary = (currentIndexMap) => {
                const states = {};
                const accountBorrowCounts = {};
                const ensureState = (account, marketId) => {
                    const key = account + '|' + marketId;
                    if (!states[key]) {
                        states[key] = {
                            account,
                            marketId,
                            par: 0n,
                            lastIndex: null,
                            settledYield: 0n,
                            settledSupplyYield: 0n,
                            settledBorrowYield: 0n,
                            liveYield: 0n,
                            hadSupply: false,
                            hadBorrow: false,
                        };
                    }
                    return states[key];
                };
                const accrueTo = (state, nextIndex) => {
                    if (state.lastIndex === null || nextIndex === null || nextIndex <= state.lastIndex || state.par === 0n) {
                        if (state.lastIndex === null && nextIndex !== null && state.par !== 0n) state.lastIndex = nextIndex;
                        return;
                    }
                    const deltaIdx = nextIndex - state.lastIndex;
                    const deltaWei = ((state.par < 0n ? -state.par : state.par) * deltaIdx) / INDEX_SCALE;
                    state.liveYield += state.par >= 0n ? deltaWei : -deltaWei;
                    state.lastIndex = nextIndex;
                };

                [...interestEvents].sort((a, b) => a.serial - b.serial).forEach(ev => {
                    const state = ensureState(ev.account, ev.marketId);
                    if (state.lastIndex === null && state.par !== 0n) state.lastIndex = ev.index;
                    accrueTo(state, ev.index);
                    const prevPar = state.par;
                    const accountBorrowBefore = (accountBorrowCounts[ev.account] || 0) > 0;
                    const nextPar = prevPar + ev.parDelta;
                    const realizedYield = earn_settleReducedExposureYield(state, nextPar);
                    const flipsSign = prevPar !== 0n && nextPar !== 0n &&
                        ((prevPar > 0n && nextPar < 0n) || (prevPar < 0n && nextPar > 0n));
                    const prevBorrowCount = accountBorrowCounts[ev.account] || 0;
                    const nextBorrowCount = prevBorrowCount - (prevPar < 0n ? 1 : 0) + (nextPar < 0n ? 1 : 0);
                    accountBorrowCounts[ev.account] = nextBorrowCount > 0 ? nextBorrowCount : 0;
                    const accountBorrowAfter = (accountBorrowCounts[ev.account] || 0) > 0;
                    replayEventTrace.push({
                        order: ev.serial,
                        account: ev.account,
                        marketId: ev.marketId,
                        flowType: ev.flowType || 'u',
                        parBefore: prevPar.toString(),
                        parAfter: nextPar.toString(),
                        parDelta: ev.parDelta.toString(),
                        weiDelta: BigInt(ev.weiDelta || 0n).toString(),
                        index: ev.index.toString(),
                        modeBefore: earn_getReplayPositionMode(prevPar, accountBorrowBefore),
                        modeAfter: earn_getReplayPositionMode(nextPar, accountBorrowAfter),
                        realizedYield: realizedYield.toString(),
                    });
                    state.par = nextPar;
                    if (state.par > 0n) state.hadSupply = true;
                    if (state.par < 0n) state.hadBorrow = true;
                    if (state.par === 0n || flipsSign) {
                        earn_addSettledYield(state, state.liveYield, prevPar);
                        state.liveYield = 0n;
                    }
                    state.lastIndex = state.par === 0n ? null : ev.index;
                });

                Object.values(states).forEach(state => {
                    if (state.par === 0n) return;
                    const idxMeta = currentIndexMap[state.marketId];
                    const nextIndex = state.par > 0n ? idxMeta?.supplyIndex : idxMeta?.borrowIndex;
                    if (nextIndex) accrueTo(state, nextIndex);
                });
                const accountStateData = earn_serializeReplayStateMap(states);
                const borrowAccountsOverride = explicitBorrowAccounts.size > 0 ? explicitBorrowAccounts : null;
                const summary = earn_summarizeReplayAccountStates(
                    accountStateData,
                    currentIndexMap,
                    { borrowAccountsOverride }
                );
                return {
                    byMarket: summary.interestYieldData,
                    replayStateData: summary.replayStateData,
                    openBorrowAccounts: summary.openBorrowAccounts,
                    borrowAccountsOverride: borrowAccountsOverride ? Array.from(borrowAccountsOverride) : [],
                    accountStateData,
                    eventTrace: replayEventTrace,
                };
            };

            const [deposits, withdrawals, takerTrades, makerTrades, transfersFrom, transfersTo, liqsSolid, liqsLiquid, borrowPositions, allTransfersFrom, allTransfersTo, vapSolid, vapVapor] = await Promise.all([
                earn_subgraphPaginateAll(endpoint, 'deposits',
                    `{ effectiveUser: "${userAddr}" }`,
                    'serialId token { marketId decimals } amountDeltaWei amountDeltaPar interestIndex marginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'withdrawals',
                    `{ effectiveUser: "${userAddr}" }`,
                    'serialId token { marketId decimals } amountDeltaWei amountDeltaPar interestIndex marginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'trades',
                    `{ takerEffectiveUser: "${userAddr}" }`,
                    'serialId takerToken { marketId decimals } makerToken { marketId decimals } takerTokenDeltaWei makerTokenDeltaWei takerInputTokenDeltaPar takerOutputTokenDeltaPar takerInterestIndex makerInterestIndex takerMarginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'trades',
                    `{ makerEffectiveUser: "${userAddr}", takerEffectiveUser_not: "${userAddr}" }`,
                    'serialId takerToken { marketId decimals } makerToken { marketId decimals } takerTokenDeltaWei makerTokenDeltaWei makerInputTokenDeltaPar makerOutputTokenDeltaPar takerInterestIndex makerInterestIndex makerMarginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'transfers',
                    `{ fromEffectiveUser: "${userAddr}", toEffectiveUser_not: "${userAddr}" }`,
                    'serialId token { marketId decimals } amountDeltaWei fromAmountDeltaPar interestIndex fromMarginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'transfers',
                    `{ toEffectiveUser: "${userAddr}", fromEffectiveUser_not: "${userAddr}" }`,
                    'serialId token { marketId decimals } amountDeltaWei toAmountDeltaPar interestIndex toMarginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'liquidations',
                    `{ solidEffectiveUser: "${userAddr}" }`,
                    'serialId heldToken { marketId decimals } borrowedToken { marketId decimals } heldTokenAmountDeltaWei borrowedTokenAmountDeltaWei solidHeldTokenAmountDeltaPar solidBorrowedTokenAmountDeltaPar heldInterestIndex borrowedInterestIndex solidMarginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'liquidations',
                    `{ liquidEffectiveUser: "${userAddr}" }`,
                    'serialId heldToken { marketId decimals } borrowedToken { marketId decimals } heldTokenAmountDeltaWei borrowedTokenAmountDeltaWei liquidHeldTokenAmountDeltaPar liquidBorrowedTokenAmountDeltaPar heldInterestIndex borrowedInterestIndex liquidMarginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'borrowPositions',
                    `{ effectiveUser: "${userAddr}", status: "OPEN" }`,
                    'marginAccount { accountNumber } amounts { token { marketId decimals } amountPar }'
                ),
                earn_subgraphPaginateAll(endpoint, 'transfers',
                    `{ fromEffectiveUser: "${userAddr}" }`,
                    'serialId token { marketId decimals } amountDeltaWei fromAmountDeltaPar toAmountDeltaPar interestIndex fromEffectiveUser { id } toEffectiveUser { id } fromMarginAccount { accountNumber } toMarginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'transfers',
                    `{ toEffectiveUser: "${userAddr}", fromEffectiveUser_not: "${userAddr}" }`,
                    'serialId token { marketId decimals } amountDeltaWei toAmountDeltaPar interestIndex toMarginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'vaporizations',
                    `{ solidEffectiveUser: "${userAddr}" }`,
                    'serialId heldToken { marketId decimals } borrowedToken { marketId decimals } heldTokenAmountDeltaWei borrowedTokenAmountDeltaWei solidHeldTokenAmountDeltaPar solidBorrowedTokenAmountDeltaPar heldInterestIndex borrowedInterestIndex solidMarginAccount { accountNumber }'
                ),
                earn_subgraphPaginateAll(endpoint, 'vaporizations',
                    `{ vaporEffectiveUser: "${userAddr}" }`,
                    'serialId heldToken { marketId decimals } borrowedToken { marketId decimals } heldTokenAmountDeltaWei borrowedTokenAmountDeltaWei vaporBorrowedTokenAmountDeltaPar heldInterestIndex borrowedInterestIndex vaporMarginAccount { accountNumber }'
                ),
            ]);
            const replayTruncated = [
                deposits, withdrawals, takerTrades, makerTrades, transfersFrom, transfersTo,
                liqsSolid, liqsLiquid, borrowPositions, allTransfersFrom, allTransfersTo,
                vapSolid, vapVapor,
            ].some(rows => !!(rows && rows.truncated));
            if (replayTruncated) {
                console.warn('Subgraph replay is incomplete because at least one event query exceeded the pagination limit. Yield verification will remain pending until onchain replay covers this address.');
            }

            deposits.forEach(dep => {
                const dec = parseDecimals(dep.token && dep.token.decimals);
                addFlow(dep.token.marketId, dep.amountDeltaWei, 'd', dec);
                addMarketEvent(dep.token.marketId, dep.serialId, dep.amountDeltaPar, dep.amountDeltaWei, dec);
                const acct = dep.marginAccount && dep.marginAccount.accountNumber;
                addInterestEvent(acct, dep.token.marketId, dep.serialId, dep.amountDeltaPar, dep.amountDeltaWei, dep.interestIndex, dec, 'd');
                if (String(acct || '') === '0') addAcct0Flow(dep.token.marketId, dep.amountDeltaWei, dec);
            });
            withdrawals.forEach(w => {
                const dec = parseDecimals(w.token && w.token.decimals);
                addFlow(w.token.marketId, negStr(w.amountDeltaWei), 'w', dec);
                addMarketEvent(w.token.marketId, w.serialId, w.amountDeltaPar, negStr(w.amountDeltaWei), dec);
                const acct = w.marginAccount && w.marginAccount.accountNumber;
                addInterestEvent(acct, w.token.marketId, w.serialId, w.amountDeltaPar, w.amountDeltaWei, w.interestIndex, dec, 'w');
                if (String(acct || '') === '0') addAcct0Flow(w.token.marketId, negStr(w.amountDeltaWei), dec);
            });
            takerTrades.forEach(t => {
                const tdec = parseDecimals(t.takerToken && t.takerToken.decimals);
                const mdec = parseDecimals(t.makerToken && t.makerToken.decimals);
                addFlow(t.takerToken.marketId, negStr(t.takerTokenDeltaWei), 's', tdec);
                addFlow(t.makerToken.marketId, t.makerTokenDeltaWei, 's', mdec);
                addMarketEvent(t.takerToken.marketId, t.serialId, t.takerInputTokenDeltaPar, negStr(t.takerTokenDeltaWei), tdec);
                addMarketEvent(t.makerToken.marketId, t.serialId, t.takerOutputTokenDeltaPar, t.makerTokenDeltaWei, mdec);
                const acct = t.takerMarginAccount && t.takerMarginAccount.accountNumber;
                addInterestEvent(acct, t.takerToken.marketId, t.serialId, t.takerInputTokenDeltaPar, t.takerTokenDeltaWei, t.takerInterestIndex, tdec, 's');
                addInterestEvent(acct, t.makerToken.marketId, t.serialId, t.takerOutputTokenDeltaPar, t.makerTokenDeltaWei, t.makerInterestIndex, mdec, 's');
                if (String(acct || '') === '0') {
                    addAcct0Flow(t.takerToken.marketId, negStr(t.takerTokenDeltaWei), tdec);
                    addAcct0Flow(t.makerToken.marketId, t.makerTokenDeltaWei, mdec);
                }
            });
            makerTrades.forEach(t => {
                const mdec = parseDecimals(t.makerToken && t.makerToken.decimals);
                const tdec = parseDecimals(t.takerToken && t.takerToken.decimals);
                addFlow(t.makerToken.marketId, negStr(t.makerTokenDeltaWei), 's', mdec);
                addFlow(t.takerToken.marketId, t.takerTokenDeltaWei, 's', tdec);
                addMarketEvent(t.makerToken.marketId, t.serialId, t.makerInputTokenDeltaPar, negStr(t.makerTokenDeltaWei), mdec);
                addMarketEvent(t.takerToken.marketId, t.serialId, t.makerOutputTokenDeltaPar, t.takerTokenDeltaWei, tdec);
                const acct = t.makerMarginAccount && t.makerMarginAccount.accountNumber;
                addInterestEvent(acct, t.makerToken.marketId, t.serialId, t.makerInputTokenDeltaPar, t.makerTokenDeltaWei, t.makerInterestIndex, mdec, 's');
                addInterestEvent(acct, t.takerToken.marketId, t.serialId, t.makerOutputTokenDeltaPar, t.takerTokenDeltaWei, t.takerInterestIndex, tdec, 's');
                if (String(acct || '') === '0') {
                    addAcct0Flow(t.makerToken.marketId, negStr(t.makerTokenDeltaWei), mdec);
                    addAcct0Flow(t.takerToken.marketId, t.takerTokenDeltaWei, tdec);
                }
            });
            transfersFrom.forEach(xf => {
                const dec = parseDecimals(xf.token && xf.token.decimals);
                addFlow(xf.token.marketId, negStr(xf.amountDeltaWei), 'x', dec);
                addMarketEvent(xf.token.marketId, xf.serialId, xf.fromAmountDeltaPar, negStr(xf.amountDeltaWei), dec);
            });
            transfersTo.forEach(xf => {
                const dec = parseDecimals(xf.token && xf.token.decimals);
                addFlow(xf.token.marketId, xf.amountDeltaWei, 'x', dec);
                addMarketEvent(xf.token.marketId, xf.serialId, xf.toAmountDeltaPar, xf.amountDeltaWei, dec);
            });
            // Use the full transfer queries below as the single source of truth for interest replay.
            // The external-only transfer queries above are kept for netflow accounting, but if we also
            // append their interest events here, external transfers are double-counted and can leave
            // phantom negative pars on otherwise healthy accounts.
            allTransfersFrom.forEach(xf => {
                const dec = parseDecimals(xf.token && xf.token.decimals);
                const fromAcct = xf.fromMarginAccount && xf.fromMarginAccount.accountNumber;
                const toAcct = xf.toMarginAccount && xf.toMarginAccount.accountNumber;
                addInterestEvent(fromAcct, xf.token.marketId, xf.serialId, xf.fromAmountDeltaPar, xf.amountDeltaWei, xf.interestIndex, dec, 'x');
                if (xf.toEffectiveUser && xf.toEffectiveUser.id === userAddr) {
                    addInterestEvent(toAcct, xf.token.marketId, xf.serialId, xf.toAmountDeltaPar, xf.amountDeltaWei, xf.interestIndex, dec, 'x');
                }
                if (String(fromAcct || '') === '0') addAcct0Flow(xf.token.marketId, negStr(xf.amountDeltaWei), dec);
                if (String(toAcct || '') === '0') addAcct0Flow(xf.token.marketId, xf.amountDeltaWei, dec);
            });
            allTransfersTo.forEach(xf => {
                const dec = parseDecimals(xf.token && xf.token.decimals);
                const toAcct = xf.toMarginAccount && xf.toMarginAccount.accountNumber;
                addInterestEvent(toAcct, xf.token.marketId, xf.serialId, xf.toAmountDeltaPar, xf.amountDeltaWei, xf.interestIndex, dec, 'x');
                if (String(toAcct || '') === '0') addAcct0Flow(xf.token.marketId, xf.amountDeltaWei, dec);
            });
            liqsSolid.forEach(liq => {
                const hdec = parseDecimals(liq.heldToken && liq.heldToken.decimals);
                const bdec = parseDecimals(liq.borrowedToken && liq.borrowedToken.decimals);
                addFlow(liq.heldToken.marketId, liq.heldTokenAmountDeltaWei, 'l', hdec);
                addFlow(liq.borrowedToken.marketId, negStr(liq.borrowedTokenAmountDeltaWei), 'l', bdec);
                addMarketEvent(liq.heldToken.marketId, liq.serialId, liq.solidHeldTokenAmountDeltaPar, liq.heldTokenAmountDeltaWei, hdec);
                addMarketEvent(liq.borrowedToken.marketId, liq.serialId, liq.solidBorrowedTokenAmountDeltaPar, negStr(liq.borrowedTokenAmountDeltaWei), bdec);
                const acct = liq.solidMarginAccount && liq.solidMarginAccount.accountNumber;
                addInterestEvent(acct, liq.heldToken.marketId, liq.serialId, liq.solidHeldTokenAmountDeltaPar, liq.heldTokenAmountDeltaWei, liq.heldInterestIndex, hdec, 'l');
                addInterestEvent(acct, liq.borrowedToken.marketId, liq.serialId, liq.solidBorrowedTokenAmountDeltaPar, liq.borrowedTokenAmountDeltaWei, liq.borrowedInterestIndex, bdec, 'l');
                if (String(acct || '') === '0') {
                    addAcct0Flow(liq.heldToken.marketId, liq.heldTokenAmountDeltaWei, hdec);
                    addAcct0Flow(liq.borrowedToken.marketId, negStr(liq.borrowedTokenAmountDeltaWei), bdec);
                }
            });
            liqsLiquid.forEach(liq => {
                const hdec = parseDecimals(liq.heldToken && liq.heldToken.decimals);
                const bdec = parseDecimals(liq.borrowedToken && liq.borrowedToken.decimals);
                addFlow(liq.heldToken.marketId, negStr(liq.heldTokenAmountDeltaWei), 'l', hdec);
                addFlow(liq.borrowedToken.marketId, liq.borrowedTokenAmountDeltaWei, 'l', bdec);
                addMarketEvent(liq.heldToken.marketId, liq.serialId, liq.liquidHeldTokenAmountDeltaPar, negStr(liq.heldTokenAmountDeltaWei), hdec);
                addMarketEvent(liq.borrowedToken.marketId, liq.serialId, liq.liquidBorrowedTokenAmountDeltaPar, liq.borrowedTokenAmountDeltaWei, bdec);
                const acct = liq.liquidMarginAccount && liq.liquidMarginAccount.accountNumber;
                addInterestEvent(acct, liq.heldToken.marketId, liq.serialId, liq.liquidHeldTokenAmountDeltaPar, liq.heldTokenAmountDeltaWei, liq.heldInterestIndex, hdec, 'l');
                addInterestEvent(acct, liq.borrowedToken.marketId, liq.serialId, liq.liquidBorrowedTokenAmountDeltaPar, liq.borrowedTokenAmountDeltaWei, liq.borrowedInterestIndex, bdec, 'l');
                if (String(acct || '') === '0') {
                    addAcct0Flow(liq.heldToken.marketId, negStr(liq.heldTokenAmountDeltaWei), hdec);
                    addAcct0Flow(liq.borrowedToken.marketId, liq.borrowedTokenAmountDeltaWei, bdec);
                }
            });
            vapSolid.forEach(vap => {
                const hdec = parseDecimals(vap.heldToken && vap.heldToken.decimals);
                const bdec = parseDecimals(vap.borrowedToken && vap.borrowedToken.decimals);
                addFlow(vap.heldToken.marketId, vap.heldTokenAmountDeltaWei, 'v', hdec);
                addFlow(vap.borrowedToken.marketId, negStr(vap.borrowedTokenAmountDeltaWei), 'v', bdec);
                addMarketEvent(vap.heldToken.marketId, vap.serialId, vap.solidHeldTokenAmountDeltaPar, vap.heldTokenAmountDeltaWei, hdec);
                addMarketEvent(vap.borrowedToken.marketId, vap.serialId, vap.solidBorrowedTokenAmountDeltaPar, negStr(vap.borrowedTokenAmountDeltaWei), bdec);
                const acct = vap.solidMarginAccount && vap.solidMarginAccount.accountNumber;
                addInterestEvent(acct, vap.heldToken.marketId, vap.serialId, vap.solidHeldTokenAmountDeltaPar, vap.heldTokenAmountDeltaWei, vap.heldInterestIndex, hdec, 'v');
                addInterestEvent(acct, vap.borrowedToken.marketId, vap.serialId, vap.solidBorrowedTokenAmountDeltaPar, vap.borrowedTokenAmountDeltaWei, vap.borrowedInterestIndex, bdec, 'v');
                if (String(acct || '') === '0') {
                    addAcct0Flow(vap.heldToken.marketId, vap.heldTokenAmountDeltaWei, hdec);
                    addAcct0Flow(vap.borrowedToken.marketId, negStr(vap.borrowedTokenAmountDeltaWei), bdec);
                }
            });
            vapVapor.forEach(vap => {
                const hdec = parseDecimals(vap.heldToken && vap.heldToken.decimals);
                const bdec = parseDecimals(vap.borrowedToken && vap.borrowedToken.decimals);
                addFlow(vap.heldToken.marketId, negStr(vap.heldTokenAmountDeltaWei), 'v', hdec);
                addFlow(vap.borrowedToken.marketId, vap.borrowedTokenAmountDeltaWei, 'v', bdec);
                addMarketEvent(vap.borrowedToken.marketId, vap.serialId, vap.vaporBorrowedTokenAmountDeltaPar, vap.borrowedTokenAmountDeltaWei, bdec);
                const acct = vap.vaporMarginAccount && vap.vaporMarginAccount.accountNumber;
                addInterestEvent(acct, vap.borrowedToken.marketId, vap.serialId, vap.vaporBorrowedTokenAmountDeltaPar, vap.borrowedTokenAmountDeltaWei, vap.borrowedInterestIndex, bdec, 'v');
                if (String(acct || '') === '0') {
                    addAcct0Flow(vap.heldToken.marketId, negStr(vap.heldTokenAmountDeltaWei), hdec);
                    addAcct0Flow(vap.borrowedToken.marketId, vap.borrowedTokenAmountDeltaWei, bdec);
                }
            });
            borrowPositions.forEach(bp => {
                const borrowAccount = bp.marginAccount && bp.marginAccount.accountNumber;
                if (borrowAccount !== undefined && borrowAccount !== null && String(borrowAccount).trim() !== '') {
                    explicitBorrowAccounts.add(String(borrowAccount));
                }
                (bp.amounts || []).forEach(amt => {
                    const amountPar = Number(amt.amountPar || '0');
                    if (!(amountPar < 0)) return;
                    const dec = parseDecimals(amt.token && amt.token.decimals);
                    addFlow(amt.token.marketId, amt.amountPar, 'b', dec);
                });
            });

            const allMarketIds = Array.from(new Set([
                ...Object.keys(netflows),
                ...interestEvents.map(ev => ev.marketId),
            ]));
            let interestYieldData = {};
            let replayStateData = {};
            let replayOpenBorrowAccounts = [];
            let replayAccountStateData = {};
            let replayCurrentIndexMap = {};
            let replayBorrowAccountsOverride = [];
            const marketMeta = {};

            if (allMarketIds.length > 0) {
                const marketIdsLiteral = allMarketIds.map(mid => `"${mid}"`).join(',');
                const tokensData = await earn_subgraphQuery(endpoint,
                    `{ tokens(first: 1000, where: { marketId_in: [${marketIdsLiteral}] }) { id marketId symbol name decimals } }`
                );
                const tokens = tokensData.tokens || [];
                const tokenIds = tokens.map(t => `"${String(t.id || '').toLowerCase()}"`);
                const currentIndexMap = {};

                tokens.forEach(t => {
                    const mid = String(t.marketId);
                    const tokenAddr = String(t.id || '').toLowerCase();
                    const symbol = t.symbol || 'UNK';
                    const decimals = parseDecimals(t.decimals);
                    const icon = SYMBOL_ICONS[symbol] || SYMBOL_ICONS[symbol.toUpperCase()] || null;
                    marketMeta[mid] = {
                        tokenAddr,
                        symbol,
                        decimals,
                        name: t.name || symbol,
                        icon,
                    };
                    marketDecimals[mid] = decimals;
                });

                if (tokenIds.length > 0) {
                    const indexesData = await earn_subgraphQuery(endpoint,
                        `{ interestIndexes(first: 1000, where: { id_in: [${tokenIds.join(',')}] }) { id supplyIndex borrowIndex } }`
                    );
                    const indexMap = {};
                    (indexesData.interestIndexes || []).forEach(ix => {
                        indexMap[String(ix.id || '').toLowerCase()] = {
                            supplyIndex: earn_decimalToBigInt(ix.supplyIndex || '0', 18),
                            borrowIndex: earn_decimalToBigInt(ix.borrowIndex || '0', 18),
                        };
                    });
                    allMarketIds.forEach(mid => {
                        const tokenAddr = marketMeta[mid] ? marketMeta[mid].tokenAddr : null;
                        const idx = tokenAddr ? indexMap[tokenAddr] : null;
                        currentIndexMap[mid] = {
                            supplyIndex: idx ? idx.supplyIndex : null,
                            borrowIndex: idx ? idx.borrowIndex : null,
                        };
                    });
                    const summary = buildInterestYieldSummary(currentIndexMap);
                    interestYieldData = summary.byMarket || {};
                    replayStateData = summary.replayStateData || {};
                    replayOpenBorrowAccounts = summary.openBorrowAccounts || [];
                    replayBorrowAccountsOverride = summary.borrowAccountsOverride || [];
                    replayAccountStateData = summary.accountStateData || {};
                    replayEventTrace.splice(0, replayEventTrace.length, ...(summary.eventTrace || []));
                    replayCurrentIndexMap = {};
                    Object.entries(currentIndexMap).forEach(([mid, idx]) => {
                        replayCurrentIndexMap[mid] = {
                            supplyIndex: idx && idx.supplyIndex !== null && idx.supplyIndex !== undefined ? String(idx.supplyIndex) : null,
                            borrowIndex: idx && idx.borrowIndex !== null && idx.borrowIndex !== undefined ? String(idx.borrowIndex) : null,
                        };
                    });
                }
            }

            Object.entries(netflows).forEach(([mid, entry]) => {
                const cycleSummary = computeRecentCycleSummary(marketEvents[mid]);
                if (cycleSummary && cycleSummary.recentNetFlow !== undefined) {
                    entry.recentNetFlow = cycleSummary.recentNetFlow;
                    entry.resetPar = cycleSummary.resetPar;
                }
                if (cycleSummary && cycleSummary.endingPar !== undefined) {
                    entry.endingPar = cycleSummary.endingPar;
                }
                for (const key of ['t', 'd', 'w', 's', 'x', 'l', 'b', 'v']) {
                    entry[key] = entry[key].toString();
                }
            });
            Object.keys(acct0Netflows).forEach(mid => {
                acct0Netflows[mid] = acct0Netflows[mid].toString();
            });

            const snapshot = await earn_fetchCurrentAccountsFromSubgraph(userAddr).catch(() => null);
            const activeAccountNumbers = snapshot
                ? Array.from(new Set((snapshot.positions || []).map(pos => String(pos.accountNumber || '0')).filter(Boolean)))
                : [];
            activeAccountNumbers.forEach(ac => accountNumbers.add(ac));
            const openBorrowAccountsSet = new Set(replayOpenBorrowAccounts.map(v => String(v)));
            (snapshot && snapshot.positions ? snapshot.positions : []).forEach(pos => {
                if ((pos.par !== undefined && pos.par < 0n) || (pos.wei !== undefined && pos.wei < 0n)) {
                    openBorrowAccountsSet.add(String(pos.accountNumber || '0'));
                }
            });

            return {
                accountNumbers: Array.from(accountNumbers),
                netflows,
                acct0Netflows: Object.keys(acct0Netflows).length > 0 ? acct0Netflows : null,
                interestYieldData,
                replayStateData,
                marketMeta,
                openBorrowAccounts: Array.from(openBorrowAccountsSet),
                borrowAccountsOverride: replayBorrowAccountsOverride,
                accountStateData: replayAccountStateData,
                currentIndexMap: replayCurrentIndexMap,
                eventTrace: replayEventTrace,
                verificationIncomplete: replayTruncated,
            };
        }

        async function earn_buildOnchainReplay(addr, opts) {
            opts = opts || {};
            const userAddr = addr.toLowerCase();
            const blockTag = opts.blockTag || earn_replayBlockTag || null;
            const rawLogs = await earn_fetchUserActionLogs(userAddr, blockTag);
            const updates = [];
            const accountNumbers = new Set();
            const marketIds = new Set();
            const blockMarketMap = new Map();
            const netflows = {};
            const INDEX_SCALE = 10n ** 18n;

            function ensureFlowEntry(mid) {
                if (!netflows[mid]) netflows[mid] = { t: 0n, d: 0n, w: 0n, s: 0n, x: 0n, l: 0n, b: 0n, v: 0n };
                return netflows[mid];
            }

            function addFlow(mid, deltaWei, flowType) {
                const entry = ensureFlowEntry(mid);
                if (deltaWei === 0n) return;
                entry.t += deltaWei;
                const absDelta = deltaWei < 0n ? -deltaWei : deltaWei;
                entry[flowType] += absDelta;
            }

            rawLogs.forEach(log => {
                const decoded = earn_decodeUserActionLog(log, userAddr);
                decoded.forEach(update => {
                    updates.push(update);
                    accountNumbers.add(update.accountNumber);
                    marketIds.add(update.marketId);
                    addFlow(update.marketId, update.deltaWei, update.flowType);
                    if (!blockMarketMap.has(update.blockNumber)) blockMarketMap.set(update.blockNumber, new Set());
                    blockMarketMap.get(update.blockNumber).add(update.marketId);
                });
            });

            if (updates.length === 0) {
                return {
                    accountNumbers: [],
                    netflows: {},
                    interestYieldData: {},
                    marketMeta: {},
                };
            }

            const { currentIndexMap, marketMeta } = await earn_fetchReplayMarketMeta(Array.from(marketIds), { blockTag });
            Object.entries(marketMeta).forEach(([mid, meta]) => {
                earn_subgraphTokens[mid] = {
                    symbol: meta.symbol,
                    decimals: meta.decimals,
                    name: meta.name || meta.symbol,
                    tokenAddr: meta.tokenAddr,
                    icon: meta.icon || null,
                };
            });

            const indexLogsByBlock = await earn_fetchIndexLogsForBlocks(blockMarketMap);
            const states = {};
            const replayEventTrace = [];
            const accountBorrowCounts = {};

            const ensureState = (account, marketId) => {
                const key = account + '|' + marketId;
                if (!states[key]) {
                    states[key] = {
                        account,
                        marketId,
                        par: 0n,
                        lastIndex: null,
                        settledYield: 0n,
                        settledSupplyYield: 0n,
                        settledBorrowYield: 0n,
                        liveYield: 0n,
                        hadSupply: false,
                        hadBorrow: false,
                    };
                }
                return states[key];
            };

            const accrueTo = (state, nextIndex) => {
                if (state.lastIndex === null || nextIndex === null || nextIndex <= state.lastIndex || state.par === 0n) {
                    if (state.lastIndex === null && nextIndex !== null && state.par !== 0n) state.lastIndex = nextIndex;
                    return;
                }
                const deltaIdx = nextIndex - state.lastIndex;
                const parAbs = state.par < 0n ? -state.par : state.par;
                const deltaWei = (parAbs * deltaIdx) / INDEX_SCALE;
                state.liveYield += state.par >= 0n ? deltaWei : -deltaWei;
                state.lastIndex = nextIndex;
            };

            updates.sort((a, b) => {
                if (a.blockNumber !== b.blockNumber) return a.blockNumber - b.blockNumber;
                if (a.transactionIndex !== b.transactionIndex) return a.transactionIndex - b.transactionIndex;
                return a.logIndex - b.logIndex;
            });

            updates.forEach(update => {
                const state = ensureState(update.accountNumber, update.marketId);
                const prevPar = state.par;
                const accountBorrowBefore = (accountBorrowCounts[update.accountNumber] || 0) > 0;
                const deltaPar = update.newPar - prevPar;
                const idxMeta = earn_findEventIndexes(indexLogsByBlock, update, deltaPar);
                const eventIndex = prevPar > 0n
                    ? idxMeta.supplyIndex
                    : prevPar < 0n
                        ? idxMeta.borrowIndex
                        : update.newPar < 0n
                            ? idxMeta.borrowIndex
                            : idxMeta.supplyIndex;

                accrueTo(state, eventIndex);
                const realizedYield = earn_settleReducedExposureYield(state, update.newPar);

                const prevDebt = prevPar < 0n ? -prevPar : 0n;
                const nextDebt = update.newPar < 0n ? -update.newPar : 0n;
                if (nextDebt > prevDebt) {
                    ensureFlowEntry(update.marketId).b += (update.deltaWei < 0n ? -update.deltaWei : update.deltaWei);
                }

                const flipsSign = prevPar !== 0n && update.newPar !== 0n &&
                    ((prevPar > 0n && update.newPar < 0n) || (prevPar < 0n && update.newPar > 0n));
                const prevBorrowCount = accountBorrowCounts[update.accountNumber] || 0;
                const nextBorrowCount = prevBorrowCount - (prevPar < 0n ? 1 : 0) + (update.newPar < 0n ? 1 : 0);
                accountBorrowCounts[update.accountNumber] = nextBorrowCount > 0 ? nextBorrowCount : 0;
                const accountBorrowAfter = (accountBorrowCounts[update.accountNumber] || 0) > 0;
                replayEventTrace.push({
                    order: `${update.blockNumber}:${update.transactionIndex}:${update.logIndex}`,
                    account: update.accountNumber,
                    marketId: update.marketId,
                    flowType: update.flowType || 'u',
                    parBefore: prevPar.toString(),
                    parAfter: update.newPar.toString(),
                    parDelta: deltaPar.toString(),
                    weiDelta: update.deltaWei.toString(),
                    index: eventIndex ? eventIndex.toString() : null,
                    modeBefore: earn_getReplayPositionMode(prevPar, accountBorrowBefore),
                    modeAfter: earn_getReplayPositionMode(update.newPar, accountBorrowAfter),
                    realizedYield: realizedYield.toString(),
                });
                state.par = update.newPar;
                if (prevPar > 0n || state.par > 0n) state.hadSupply = true;
                if (prevPar < 0n || state.par < 0n) state.hadBorrow = true;
                if (state.par === 0n || flipsSign) {
                    earn_addSettledYield(state, state.liveYield, prevPar);
                    state.liveYield = 0n;
                }
                state.lastIndex = state.par > 0n ? idxMeta.supplyIndex : state.par < 0n ? idxMeta.borrowIndex : null;
            });

            Object.values(states).forEach(state => {
                if (state.par === 0n) return;
                const idxMeta = currentIndexMap[state.marketId];
                const nextIndex = state.par > 0n ? idxMeta?.supplyIndex : idxMeta?.borrowIndex;
                accrueTo(state, nextIndex || null);
            });
            const replayCurrentIndexMap = {};
            Object.entries(currentIndexMap || {}).forEach(([mid, idx]) => {
                replayCurrentIndexMap[mid] = {
                    supplyIndex: idx && idx.supplyIndex !== null && idx.supplyIndex !== undefined ? String(idx.supplyIndex) : null,
                    borrowIndex: idx && idx.borrowIndex !== null && idx.borrowIndex !== undefined ? String(idx.borrowIndex) : null,
                };
            });
            const accountStateData = earn_serializeReplayStateMap(states);
            const summarizedReplay = earn_summarizeReplayAccountStates(accountStateData, replayCurrentIndexMap);
            const interestYieldData = summarizedReplay.interestYieldData;
            const replayStateData = summarizedReplay.replayStateData;

            Object.entries(netflows).forEach(([mid, entry]) => {
                for (const key of ['t', 'd', 'w', 's', 'x', 'l', 'b', 'v']) {
                    entry[key] = entry[key].toString();
                }
            });

            return {
                accountNumbers: Array.from(accountNumbers),
                netflows,
                interestYieldData,
                replayStateData,
                marketMeta,
                openBorrowAccounts: summarizedReplay.openBorrowAccounts || [],
                borrowAccountsOverride: summarizedReplay.openBorrowAccounts || [],
                accountStateData,
                currentIndexMap: replayCurrentIndexMap,
                eventTrace: replayEventTrace,
            };
        }

        // Fetch yield data directly from onchain logs and market getters.
        async function earn_fetchNetflow(opts) {
            opts = opts || {};
            const replayRunId = Number(opts.runId || earn_activeLookupRunId || 0);
            const onAsyncReplayUpdate = typeof opts.onAsyncReplayUpdate === 'function'
                ? opts.onAsyncReplayUpdate
                : null;
            earn_netflowData = null;
            earn_acct0NetflowData = null;
            earn_interestYieldData = null;
            earn_replayAccountStateData = {};
            earn_replayCurrentIndexMap = {};
            earn_collateralPositionData = [];
            earn_replayAccountNumbers = [];
            earn_replayUsedSubgraphFallback = false;
            earn_openBorrowAccounts = new Set();
            earn_hiddenCollateralSupplyMarkets = new Set();
            earn_replayStateData = {};
            earn_replayEventData = [];
            earn_replayVerificationData = {};
            earn_replayVerificationSummary = { total: 0, verified: 0, mismatch: 0, unverified: 0 };
            earn_replayVerificationReady = false;
            earn_replayBlockTag = opts.blockTag || earn_replayBlockTag || null;
            earn_replayVerificationIncompleteMarkets = new Set();
            earn_replayTruncatedSubgraphMarkets = new Set();
            earn_replaySubgraphHistoryIncomplete = false;
            earn_replayReconciledMarkets = new Set();
            earn_replayActualSupplyMap = {};
            earn_replayActualBorrowMap = {};
            earn_replayActualCollateralMap = {};
            earn_replayCurrentPositions = [];
            earn_replayCurrentBorrowAccounts = new Set();
            earn_replayBorrowAccountsOverride = new Set();
            earn_subgraphTokens = {};

            const addr = document.getElementById('earn-address').value.trim().toLowerCase();
            if (!addr) return;
            const chainId = document.getElementById('earn-chain').value;
            const canonicalSubaccountHistoryPromise = earn_fetchSubaccountHistoryForAddress(chainId, addr).catch(() => null);

            const hasReplayData = replay => !!(
                replay && (
                    Object.keys(replay.netflows || {}).length > 0 ||
                    Object.keys(replay.interestYieldData || {}).length > 0
                )
            );
            const settleReplay = promise => promise.then(
                value => ({ status: 'fulfilled', value }),
                reason => ({ status: 'rejected', reason })
            );
            const hydrateReplayWithCanonicalHistory = async (replay) => {
                if (!replay) return replay;
                const subaccountHistory = await canonicalSubaccountHistoryPromise;
                return earn_applySubaccountHistoryToReplay(replay, subaccountHistory, {
                    blockTag: earn_replayBlockTag,
                });
            };

            const applyReplayResult = (replay, useSubgraphMode) => {
                earn_replayReconciledMarkets = new Set();
                earn_updateCanonicalSubaccountHistoryStateFromReplay(replay);
                Object.entries(replay.marketMeta || {}).forEach(([mid, meta]) => {
                    // XSS guard: replay metadata carries subgraph-sourced
                    // (deployer-controlled) symbols/names into innerHTML paths.
                    earn_subgraphTokens[mid] = {
                        symbol: earn_escapeHtml(meta.symbol || 'UNK'),
                        decimals: meta.decimals || 18,
                        name: earn_escapeHtml(meta.name || meta.symbol || 'UNK'),
                        tokenAddr: (meta.tokenAddr || '').toLowerCase(),
                        icon: meta.icon || null,
                    };
                    if (meta.tokenAddr) {
                        const cacheKey = document.getElementById('earn-chain').value + ':' + String(meta.tokenAddr).toLowerCase();
                        earn_tokenCache[cacheKey] = {
                            symbol: earn_subgraphTokens[mid].symbol,
                            decimals: earn_subgraphTokens[mid].decimals,
                            icon: earn_subgraphTokens[mid].icon,
                            name: earn_subgraphTokens[mid].name,
                        };
                    }
                });

                earn_replayUsedSubgraphFallback = !!useSubgraphMode;
                earn_replaySubgraphHistoryIncomplete = !!replay.verificationIncomplete;
                earn_replayTruncatedSubgraphMarkets = replay.verificationIncomplete
                    ? new Set([
                        ...Object.keys(replay.netflows || {}),
                        ...Object.keys(replay.interestYieldData || {}),
                        ...Object.keys(replay.replayStateData || {}),
                    ].map(mid => String(mid)))
                    : new Set();
                earn_replayAccountNumbers = replay.accountNumbers || [];
                earn_netflowData = replay.netflows || {};
                earn_interestYieldData = replay.interestYieldData || {};
                earn_acct0NetflowData = replay.acct0Netflows || null;
                earn_openBorrowAccounts = new Set((replay.openBorrowAccounts || []).map(v => String(v)));
                earn_replayBorrowAccountsOverride = new Set((replay.borrowAccountsOverride || replay.openBorrowAccounts || []).map(v => String(v)));
                earn_replayStateData = replay.replayStateData || {};
                earn_replayEventData = replay.eventTrace || [];
                earn_replayAccountStateData = replay.accountStateData || {};
                earn_replayCurrentIndexMap = replay.currentIndexMap || {};
                const hasCurrentVerificationInputs =
                    Object.keys(earn_replayActualSupplyMap || {}).length > 0 ||
                    Object.keys(earn_replayActualBorrowMap || {}).length > 0 ||
                    Object.keys(earn_replayActualCollateralMap || {}).length > 0 ||
                    (earn_cachedAssets || []).length > 0 ||
                    (earn_borrowPositionData || []).length > 0 ||
                    (earn_collateralPositionData || []).length > 0;
                if (hasCurrentVerificationInputs) {
                    earn_refreshReplayVerificationFromCachedPositions();
                    earn_refreshResolvedTotalYieldData();
                }
                console.log(
                    `${useSubgraphMode ? 'Subgraph' : 'Onchain'} replay: ${Object.keys(earn_netflowData).length} markets, ${earn_replayAccountNumbers.length} account(s) for ${addr}`
                );
            };

            const finalizeReplaySelection = async (subgraphResult, onchainResult) => {
                const subgraphReplay = subgraphResult && subgraphResult.status === 'fulfilled'
                    ? subgraphResult.value
                    : null;
                const subgraphError = subgraphResult && subgraphResult.status === 'rejected'
                    ? subgraphResult.reason
                    : null;
                const hasSubgraphData = hasReplayData(subgraphReplay);

                let onchainReplay = null;
                if (onchainResult && onchainResult.status === 'fulfilled') {
                    onchainReplay = onchainResult.value;
                } else {
                    const onchainErr = onchainResult ? onchainResult.reason : null;
                    if (subgraphReplay) {
                        let replay = subgraphReplay;
                        replay = await earn_refreshReplayWithLiveCurrentIndexes(replay, {
                            blockTag: earn_replayBlockTag,
                        });
                        replay = await hydrateReplayWithCanonicalHistory(replay);
                        return { replay, useSubgraphMode: true };
                    }
                    if (subgraphError) throw subgraphError;
                    throw onchainErr || new Error('Replay unavailable');
                }

                let replay = onchainReplay;
                if (subgraphReplay) {
                    const onchainHasData = hasReplayData(onchainReplay);
                    if (!onchainHasData && hasSubgraphData) {
                        replay = subgraphReplay;
                        console.warn(
                            'Onchain replay returned no data; switched to subgraph replay fallback.'
                        );
                    } else if (hasSubgraphData && onchainHasData) {
                        const coverage = await earn_shouldUseSubgraphReplay(addr, onchainReplay);
                        if (coverage.shouldFallback) {
                            if (coverage.reason === 'missing-active-accounts') {
                                const supplementedReplay = earn_mergeReplayMissingAccounts(
                                    onchainReplay,
                                    subgraphReplay,
                                    coverage.missingAccounts || []
                                );
                                if (supplementedReplay !== onchainReplay) {
                                    replay = supplementedReplay;
                                    console.warn(
                                        `Coverage gap detected (${coverage.reason}); supplemented onchain replay with subgraph state for missing active accounts.`,
                                        {
                                            missingAccounts: coverage.missingAccounts || [],
                                            missingMarkets: coverage.missingMarkets || [],
                                        }
                                    );
                                } else {
                                    console.warn(
                                        `Coverage gap detected (${coverage.reason}); no supplementable subgraph state found, keeping onchain replay.`,
                                        {
                                            missingAccounts: coverage.missingAccounts || [],
                                            missingMarkets: coverage.missingMarkets || [],
                                        }
                                    );
                                }
                            } else if (coverage.reason === 'missing-active-markets') {
                                const supplementedReplay = earn_mergeReplayMissingMarkets(
                                    onchainReplay,
                                    subgraphReplay,
                                    coverage.missingMarkets || []
                                );
                                if (supplementedReplay !== onchainReplay) {
                                    replay = supplementedReplay;
                                    console.warn(
                                        `Coverage gap detected (${coverage.reason}); supplemented onchain replay with subgraph state for missing active markets.`,
                                        {
                                            missingAccounts: coverage.missingAccounts || [],
                                            missingMarkets: coverage.missingMarkets || [],
                                        }
                                    );
                                } else {
                                    console.warn(
                                        `Coverage gap detected (${coverage.reason}); no supplementable subgraph state found, keeping onchain replay.`,
                                        {
                                            missingAccounts: coverage.missingAccounts || [],
                                            missingMarkets: coverage.missingMarkets || [],
                                        }
                                    );
                                }
                            } else {
                                console.warn(
                                    `Coverage gap detected (${coverage.reason}); keeping onchain replay in accuracy-first mode.`,
                                    {
                                        missingAccounts: coverage.missingAccounts || [],
                                        missingMarkets: coverage.missingMarkets || [],
                                    }
                                );
                            }
                        } else {
                            console.log('Using onchain replay (coverage OK, subgraph kept as emergency fallback).');
                        }
                        const missingIndexMarkets = earn_getReplayMarketsMissingCurrentIndexes(replay);
                        if (missingIndexMarkets.length > 0) {
                            const supplementedReplay = earn_supplementReplayCurrentIndexes(
                                replay,
                                subgraphReplay,
                                missingIndexMarkets
                            );
                            if (supplementedReplay !== replay) {
                                replay = supplementedReplay;
                                console.warn(
                                    'Supplemented replay with subgraph current indexes for markets missing live supply/borrow indexes.',
                                    { missingMarkets: missingIndexMarkets }
                                );
                            }
                        }
                    }
                }

                if (replay && replay !== onchainReplay) {
                    replay = await earn_refreshReplayWithLiveCurrentIndexes(replay, {
                        blockTag: earn_replayBlockTag,
                    });
                }

                replay = await hydrateReplayWithCanonicalHistory(replay);

                return {
                    replay,
                    useSubgraphMode: replay === subgraphReplay,
                };
            };

            const replayStartTs = (typeof performance !== 'undefined' && performance.now)
                ? performance.now()
                : Date.now();
            const replayTimeouts = earn_getReplayTimeouts(document.getElementById('earn-chain')?.value || '');
            const subgraphSettledPromise = settleReplay(
                earn_withTimeout(
                    earn_buildSubgraphReplay(addr),
                    replayTimeouts.subgraphMs,
                    'Subgraph replay'
                )
            );
            const onchainSettledPromise = settleReplay(
                earn_withTimeout(
                    earn_buildOnchainReplay(addr, { blockTag: earn_replayBlockTag }),
                    replayTimeouts.onchainMs,
                    'Onchain replay'
                )
            );

            let subgraphResult = null;
            let onchainResult = null;

            const firstSettled = await Promise.race([
                subgraphSettledPromise.then(result => ({ source: 'subgraph', result })),
                onchainSettledPromise.then(result => ({ source: 'onchain', result })),
            ]);

            if (firstSettled.source === 'subgraph') {
                subgraphResult = firstSettled.result;
                if (subgraphResult.status === 'rejected') {
                    console.warn('Subgraph replay failed:', subgraphResult.reason);
                }
                const subgraphReplay = subgraphResult.status === 'fulfilled' ? subgraphResult.value : null;
                if (
                    hasReplayData(subgraphReplay) &&
                    replayTimeouts.softOnchainMs &&
                    replayTimeouts.softOnchainMs < replayTimeouts.onchainMs
                ) {
                    const replayElapsedMs = Math.max(
                        0,
                        (((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - replayStartTs)
                    );
                    const softWaitMs = Math.max(0, replayTimeouts.softOnchainMs - replayElapsedMs);
                    const softOnchainResult = await Promise.race([
                        onchainSettledPromise.then(result => ({ kind: 'settled', result })),
                        earn_sleep(softWaitMs).then(() => ({ kind: 'soft-timeout' })),
                    ]);

                    if (softOnchainResult.kind === 'settled') {
                        onchainResult = softOnchainResult.result;
                    } else {
                        let provisionalReplay = subgraphReplay;
                        provisionalReplay = await earn_refreshReplayWithLiveCurrentIndexes(provisionalReplay, {
                            blockTag: earn_replayBlockTag,
                        });
                        provisionalReplay = await hydrateReplayWithCanonicalHistory(provisionalReplay);
                        applyReplayResult(provisionalReplay, true);
                        console.warn(
                            `Onchain replay exceeded soft deadline (${replayTimeouts.softOnchainMs}ms); using subgraph replay while onchain continues in background.`
                        );
                        onchainSettledPromise.then(async settled => {
                            if (!earn_isLookupRunCurrent(replayRunId)) return;
                            if (settled.status === 'rejected') return;
                            try {
                                const finalSelection = await finalizeReplaySelection(subgraphResult, settled);
                                if (!finalSelection || !finalSelection.replay) return;
                                finalSelection.replay = await hydrateReplayWithCanonicalHistory(finalSelection.replay);
                                const replayChanged = finalSelection.replay !== provisionalReplay || !finalSelection.useSubgraphMode;
                                if (!replayChanged) return;
                                applyReplayResult(finalSelection.replay, finalSelection.useSubgraphMode);
                                console.log(
                                    `Replay upgraded in background after ${Math.round((((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - replayStartTs))}ms.`
                                );
                                if (onAsyncReplayUpdate) {
                                    await onAsyncReplayUpdate({
                                        source: finalSelection.useSubgraphMode ? 'subgraph' : 'onchain',
                                    });
                                }
                            } catch (upgradeErr) {
                                console.warn('Background replay upgrade failed:', upgradeErr);
                            }
                        }).catch(() => {});
                        console.log(
                            `Replay settled in ${Math.round((((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - replayStartTs))}ms (subgraph soft fallback).`
                        );
                        return;
                    }
                }
            } else {
                onchainResult = firstSettled.result;
            }

            if (subgraphResult === null) {
                subgraphResult = await subgraphSettledPromise;
                if (subgraphResult.status === 'rejected') {
                    console.warn('Subgraph replay failed:', subgraphResult.reason);
                }
            }
            if (onchainResult === null) {
                onchainResult = await onchainSettledPromise;
            }

            const finalSelection = await finalizeReplaySelection(subgraphResult, onchainResult);
            finalSelection.replay = await hydrateReplayWithCanonicalHistory(finalSelection.replay);
            applyReplayResult(finalSelection.replay, finalSelection.useSubgraphMode);
            console.log(`Replay settled in ${Math.round((((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - replayStartTs))}ms.`);
        }


        async function earn_setPeriod(p, snapshotDateOverride) {
            earn_currentPeriod = p;
            // Update active button
            document.querySelectorAll('.earn-period-btn').forEach(btn => {
                btn.classList.toggle('active', btn.dataset.period === p);
            });

            // Reset custom date when switching to a non-custom period
            if (p !== 'custom') {
                earn_customSnapshotDate = snapshotDateOverride || null;
            }

            // Try to fetch historical snapshot for periods with real data
            earn_historicalData = null;
            let hasRealData = false;
            let periodDays = Number(p);

            // Determine which snapshot date to fetch
            let dateStr = null;
            if (p === 'custom' && earn_customSnapshotDate) {
                dateStr = earn_customSnapshotDate;
                const today = new Date();
                today.setUTCHours(0, 0, 0, 0);
                const sd = new Date(earn_customSnapshotDate + 'T00:00:00Z');
                periodDays = Math.round((today - sd) / 86400000);
            } else if (p !== 'all' && snapshotDateOverride) {
                dateStr = snapshotDateOverride;
            } else if (p !== 'all' && periodDays > 0) {
                // Find the matching snapshot date from manifest
                const today = new Date();
                today.setUTCHours(0, 0, 0, 0);
                const target = new Date(today);
                target.setUTCDate(target.getUTCDate() - periodDays);
                dateStr = target.toISOString().slice(0, 10);
            }

            if (dateStr && earn_cachedAssets) {
                const chainId = document.getElementById('earn-chain').value;
                const addr = document.getElementById('earn-address').value.trim();

                // Show loading state on header
                const yh = document.getElementById('earn-yield-header');
                if (yh) yh.textContent = 'Loading...';

                const snapshot = await earn_fetchSnapshot(dateStr);
                if (snapshot) {
                    const markets = earn_getHistoricalMarkets(snapshot, chainId, addr);
                    if (markets) {
                        earn_historicalData = markets;
                        hasRealData = true;
                    }
                }
            }

            // Update header label
            const yh2 = document.getElementById('earn-yield-header');
            if (hasRealData) {
                if (yh2) yh2.textContent = periodDays + 'D Yield Value ✓';
            } else {
                if (yh2) yh2.textContent = periodDays + 'D Yield Value';
            }

            // Re-render if we have cached data
            if (earn_cachedAssets) earn_renderResults(earn_cachedAssets);
        }

        // Calendar state
        let earn_calMonth = new Date().getUTCMonth();
        let earn_calYear = new Date().getUTCFullYear();

        function earn_openCustomDate() {
            // Start calendar on current month
            const now = new Date();
            earn_calMonth = now.getUTCMonth();
            earn_calYear = now.getUTCFullYear();
            earn_calRender();
            document.getElementById('earn-custom-date-overlay').classList.add('visible');
        }

        function earn_closeCustomDate() {
            document.getElementById('earn-custom-date-overlay').classList.remove('visible');
        }

        function earn_calNavigate(dir) {
            earn_calMonth += dir;
            if (earn_calMonth < 0) { earn_calMonth = 11; earn_calYear--; }
            if (earn_calMonth > 11) { earn_calMonth = 0; earn_calYear++; }
            earn_calRender();
        }

        function earn_calRender() {
            const monthNames = ['January', 'February', 'March', 'April', 'May', 'June',
                'July', 'August', 'September', 'October', 'November', 'December'];
            document.getElementById('earn-cal-month-label').textContent =
                monthNames[earn_calMonth] + ' ' + earn_calYear;

            const grid = document.getElementById('earn-cal-grid');
            grid.innerHTML = '';

            const chainId = document.getElementById('earn-chain') ?
                document.getElementById('earn-chain').value : '';

            // Build set of available dates for this chain
            const availableDates = new Set();
            if (earn_snapshotManifest) {
                earn_snapshotManifest.dates.forEach(d => {
                    const chains = earn_snapshotManifest.chains[d] || [];
                    if (!chainId || chains.includes(chainId)) {
                        availableDates.add(d);
                    }
                });
            }

            // Today (UTC)
            const now = new Date();
            const todayStr = now.toISOString().slice(0, 10);

            // First day of month (Monday-based: 0=Mon, 6=Sun)
            const firstDay = new Date(Date.UTC(earn_calYear, earn_calMonth, 1));
            let startDay = firstDay.getUTCDay() - 1; // JS: 0=Sun → we want Mon=0
            if (startDay < 0) startDay = 6;

            const daysInMonth = new Date(Date.UTC(earn_calYear, earn_calMonth + 1, 0)).getUTCDate();

            // Empty cells before first day
            for (let i = 0; i < startDay; i++) {
                const cell = document.createElement('div');
                cell.className = 'earn-cal-day empty';
                grid.appendChild(cell);
            }

            // Day cells
            for (let day = 1; day <= daysInMonth; day++) {
                const dateStr = `${earn_calYear}-${String(earn_calMonth + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
                const cell = document.createElement('div');
                cell.className = 'earn-cal-day';
                cell.textContent = day;

                const isToday = dateStr === todayStr;
                const isFuture = dateStr > todayStr;
                const isAvailable = availableDates.has(dateStr) && !isFuture && !isToday;
                const isSelected = dateStr === earn_customSnapshotDate;

                if (isToday) cell.classList.add('today');
                if (isFuture) cell.classList.add('future');
                if (isAvailable) {
                    cell.classList.add('available');
                    if (isSelected) cell.classList.add('selected');
                    cell.onclick = () => earn_calSelectDate(dateStr);
                }

                grid.appendChild(cell);
            }
        }

        function earn_calSelectDate(dateStr) {
            earn_customSnapshotDate = dateStr;
            earn_closeCustomDate();

            // Set custom period with this date
            earn_currentPeriod = 'custom';
            document.querySelectorAll('.earn-period-btn').forEach(b => {
                b.classList.toggle('active', b.dataset.period === 'custom');
            });
            earn_setPeriod('custom');
        }


