        function earn_hideAll(opts) {
            opts = opts || {};
            const preserveResults = !!opts.preserveResults;
            if (!preserveResults) earn_clearLookupLoadingUi();
            earn_globalEmptyState = false;
            earn_lookupLoading = false;
            earn_lookupUsingCachedSnapshot = false;
            document.getElementById('earn-error').classList.remove('visible');
            document.getElementById('earn-empty').classList.remove('visible');
            const results = document.getElementById('earn-results');
            if (results) {
                results.classList.toggle('visible', preserveResults);
                results.classList.remove('is-refreshing');
            }
            document.getElementById('earn-mode-toggle').classList.remove('visible');
            // Hide summary card
            const summary = document.getElementById('earn-summary-card');
            if (summary && !preserveResults) {
                summary.classList.remove('visible', 'skeleton', 'no-animate');
                summary.innerHTML = '';
            }
            const notices = document.getElementById('earn-notices');
            if (notices && !preserveResults) {
                notices.classList.remove('visible');
                notices.innerHTML = '';
            }
            // Hide filter bar and reset toggles to defaults (active)
            const filterBar = document.getElementById('earn-filter-bar');
            if (filterBar) filterBar.style.display = 'none';
            const supplyEmptyState = document.getElementById('earn-supply-empty-state');
            if (supplyEmptyState) {
                supplyEmptyState.style.display = 'none';
                supplyEmptyState.innerHTML = '';
            }
            const supplyTableShell = document.querySelector('#earn-supply-section .earn-section-table-shell');
            if (supplyTableShell) supplyTableShell.style.display = '';
            const inactiveToggle = document.getElementById('earn-inactive-toggle');
            if (inactiveToggle) inactiveToggle.classList.add('active');
            const dustToggle = document.getElementById('earn-dust-toggle');
            if (dustToggle) dustToggle.classList.remove('active'); // earn_showDust=true → filter off → no active
            earn_showInactive = true;
            earn_showDust = true;
            // Reset history state
            earn_historyData = null;
            earn_updateLookupRefreshBadge();
        }

