        function earn_updateLookupRefreshBadge() {
            const badge = document.getElementById('earn-live-refresh-badge');
            if (!badge) return;
            const results = document.getElementById('earn-results');
            const softRefreshing = !!results
                && results.classList.contains('visible')
                && results.classList.contains('is-refreshing')
                && !results.classList.contains('loading-gate');
            const warmRefreshing = !!earn_lookupUsingCachedSnapshot && !!earn_lookupLoading && !earn_isLookupLoadingGateActive();
            const preservedTrustedResult = earn_preservedTrustedMarketIds.size > 0;
            const shouldShow = softRefreshing || warmRefreshing || preservedTrustedResult;
            badge.classList.toggle('visible', shouldShow);
            badge.classList.toggle('is-soft', softRefreshing);
            badge.setAttribute('aria-hidden', shouldShow ? 'false' : 'true');
            badge.innerHTML = shouldShow
                ? `<span class="earn-live-refresh-dot"></span><span>${
                    preservedTrustedResult && !softRefreshing && !warmRefreshing
                        ? 'Last verified yield · live check incomplete'
                        : (softRefreshing ? 'Refreshing verification...' : 'Refreshing live...')
                }</span>`
                : '';
        }

        function earn_showLookupLoadingState(message, opts) {
            opts = opts || {};
            earn_lookupLoading = true;
            earn_lookupUsingCachedSnapshot = !!opts.cached;
            earn_setResultsRefreshing(false);
            earn_startLookupLoadingUi({
                runId: opts.runId,
                chainId: opts.chainId,
                cached: !!opts.cached,
                headline: message || 'Loading verified Earn data...',
                detail: opts.detail || (opts.cached
                    ? 'A cached verified snapshot was found. Live balances are being recomputed now, and the final dashboard will appear once the full view is stable.'
                    : 'Balances, replay verification, rewards and total yield are being prepared. The dashboard appears only once the verified view is complete.'),
            });
            earn_updateLookupRefreshBadge();
        }

        function earn_getLookupCacheKey(chainId, address) {
            const cid = String(chainId || '').trim().toLowerCase();
            const addr = String(address || '').trim().toLowerCase();
            if (!cid || !addr) return '';
            return `${cid}:${addr}`;
        }

        function earn_encodeCacheValue(value) {
            if (typeof value === 'bigint') {
                return { __earnType: 'bigint', value: value.toString() };
            }
            if (value instanceof Set) {
                return { __earnType: 'set', value: Array.from(value) };
            }
            if (Array.isArray(value)) {
                return value.map(earn_encodeCacheValue);
            }
            if (value && typeof value === 'object') {
                const out = {};
                Object.entries(value).forEach(([k, v]) => {
                    out[k] = earn_encodeCacheValue(v);
                });
                return out;
            }
            return value;
        }

        function earn_decodeCacheValue(value) {
            if (Array.isArray(value)) {
                return value.map(earn_decodeCacheValue);
            }
            if (value && typeof value === 'object') {
                if (value.__earnType === 'bigint') {
                    return BigInt(value.value || '0');
                }
                if (value.__earnType === 'set') {
                    return new Set((value.value || []).map(v => String(v)));
                }
                const out = {};
                Object.entries(value).forEach(([k, v]) => {
                    out[k] = earn_decodeCacheValue(v);
                });
                return out;
            }
            return value;
        }

        function earn_cloneLookupSnapshot(snapshot) {
            return snapshot ? earn_decodeCacheValue(earn_encodeCacheValue(snapshot)) : null;
        }

        function earn_loadLookupCache(chainId, address) {
            const cacheKey = earn_getLookupCacheKey(chainId, address);
            if (!cacheKey) return null;
            const now = Date.now();
            const inMemory = earn_lookupResultCache[cacheKey];
            if (inMemory && inMemory.savedAt && (now - inMemory.savedAt) <= EARN_LOOKUP_CACHE_TTL_MS) {
                return earn_cloneLookupSnapshot(inMemory);
            }
            try {
                const raw = sessionStorage.getItem(`earn-lookup:${cacheKey}`);
                if (!raw) return null;
                const parsed = earn_decodeCacheValue(JSON.parse(raw));
                if (!parsed || parsed.version !== EARN_LOOKUP_CACHE_VERSION) return null;
                if (!parsed.savedAt || (now - parsed.savedAt) > EARN_LOOKUP_CACHE_TTL_MS) return null;
                earn_lookupResultCache[cacheKey] = parsed;
                return earn_cloneLookupSnapshot(parsed);
            } catch (e) {
                console.warn('Lookup cache read failed:', e.message || e);
                return null;
            }
        }

        function earn_saveLookupCache(chainId, address) {
            const cacheKey = earn_getLookupCacheKey(chainId, address);
            if (!cacheKey || !earn_cachedAssets || earn_cachedAssets.length === 0) return;
            const candidate = {
                version: EARN_LOOKUP_CACHE_VERSION,
                savedAt: Date.now(),
                chainId: String(chainId || '').trim().toLowerCase(),
                address: String(address || '').trim().toLowerCase(),
                cachedAssets: earn_cachedAssets || [],
                historyData: earn_historyData || [],
                totalYieldData: earn_totalYieldData || {},
                resolvedTotalYieldData: earn_resolvedTotalYieldData || {},
                interestYieldData: earn_interestYieldData || {},
                replayVerificationData: earn_replayVerificationData || {},
                replayVerificationSummary: earn_replayVerificationSummary || { total: 0, verified: 0, mismatch: 0, unverified: 0 },
                replayVerificationReady: !!earn_replayVerificationReady,
                replayUsedSubgraphFallback: !!earn_replayUsedSubgraphFallback,
                subgraphTokens: earn_subgraphTokens || {},
                marketRates: earn_marketRates || {},
                borrowPositionData: earn_borrowPositionData || [],
                collateralPositionData: earn_collateralPositionData || [],
                openBorrowAccounts: Array.from(earn_openBorrowAccounts || []),
                replayBorrowAccountsOverride: Array.from(earn_replayBorrowAccountsOverride || []),
                canonicalSubaccountHistoryLastScannedBlock: earn_canonicalSubaccountHistoryLastScannedBlock === null
                    ? null
                    : String(earn_canonicalSubaccountHistoryLastScannedBlock),
                canonicalSubaccountHistoryFreshForBorrowRouting: !!earn_canonicalSubaccountHistoryFreshForBorrowRouting,
                hiddenCollateralSupplyMarkets: Array.from(earn_hiddenCollateralSupplyMarkets || []),
                lendingPositions: earn_lendingPositions || [],
            };
            const previous = earn_lookupResultCache[cacheKey] || null;
            const snapshot = typeof EarnCachePolicy !== 'undefined'
                ? EarnCachePolicy.mergeTrustedLookupSnapshot(previous, candidate, {
                    maxTrustedAgeMs: EARN_LOOKUP_CACHE_TTL_MS,
                })
                : candidate;
            earn_preservedTrustedMarketIds = new Set(snapshot.preservedTrustedMarketIds || []);
            if (earn_preservedTrustedMarketIds.size > 0) {
                earn_totalYieldData = snapshot.totalYieldData || earn_totalYieldData;
                earn_resolvedTotalYieldData = snapshot.resolvedTotalYieldData || earn_resolvedTotalYieldData;
                earn_interestYieldData = snapshot.interestYieldData || earn_interestYieldData;
                earn_replayVerificationData = snapshot.replayVerificationData || earn_replayVerificationData;
                earn_replayVerificationSummary = snapshot.replayVerificationSummary || earn_replayVerificationSummary;
                earn_replayVerificationReady = !!snapshot.replayVerificationReady;
                earn_refreshResolvedTotalYieldData();
            }
            earn_lookupResultCache[cacheKey] = snapshot;
            try {
                sessionStorage.setItem(`earn-lookup:${cacheKey}`, JSON.stringify(earn_encodeCacheValue(snapshot)));
            } catch (e) {
                console.warn('Lookup cache write failed:', e.message || e);
            }
        }

        function earn_renderCachedLendingPositions() {
            const section = document.getElementById('earn-lending-section');
            const countEl = document.getElementById('earn-lending-count');
            if (!section) return;
            if (!earn_lendingPositions || earn_lendingPositions.length === 0) {
                section.style.display = 'none';
                return;
            }
            if (countEl) countEl.textContent = earn_lendingPositions.length;
            section.style.display = '';
            earn_reRenderLendingRows();
        }

        function earn_applyLookupCache(snapshot) {
            if (!snapshot || !snapshot.cachedAssets) return false;
            earn_cachedAssets = snapshot.cachedAssets || [];
            earn_historyData = snapshot.historyData || [];
            earn_totalYieldData = snapshot.totalYieldData || {};
            earn_resolvedTotalYieldData = snapshot.resolvedTotalYieldData || {};
            earn_interestYieldData = snapshot.interestYieldData || {};
            earn_replayVerificationData = snapshot.replayVerificationData || {};
            earn_replayVerificationSummary = snapshot.replayVerificationSummary || { total: 0, verified: 0, mismatch: 0, unverified: 0 };
            earn_replayVerificationReady = !!snapshot.replayVerificationReady;
            earn_preservedTrustedMarketIds = new Set(snapshot.preservedTrustedMarketIds || []);
            earn_replayUsedSubgraphFallback = !!snapshot.replayUsedSubgraphFallback;
            earn_subgraphTokens = snapshot.subgraphTokens || {};
            earn_marketRates = snapshot.marketRates || {};
            earn_borrowPositionData = snapshot.borrowPositionData || [];
            earn_collateralPositionData = snapshot.collateralPositionData || [];
            earn_openBorrowAccounts = new Set(snapshot.openBorrowAccounts || []);
            earn_replayBorrowAccountsOverride = new Set(snapshot.replayBorrowAccountsOverride || snapshot.openBorrowAccounts || []);
            earn_setCanonicalSubaccountHistoryState(
                snapshot.canonicalSubaccountHistoryLastScannedBlock,
                snapshot.canonicalSubaccountHistoryFreshForBorrowRouting
            );
            earn_hiddenCollateralSupplyMarkets = new Set(snapshot.hiddenCollateralSupplyMarkets || []);
            earn_lendingPositions = snapshot.lendingPositions || [];
            if (snapshot.chainId && snapshot.marketRates && Object.keys(snapshot.marketRates || {}).length > 0) {
                earn_marketRatesCache[String(snapshot.chainId)] = {
                    savedAt: snapshot.savedAt || Date.now(),
                    rates: snapshot.marketRates || {},
                };
            }

            earn_refreshResolvedTotalYieldData();
            earn_setResultsRefreshing(true);
            earn_renderResults(earn_cachedAssets, { skipSummary: false, softRefresh: true });
            earn_renderCachedLendingPositions();
            earn_renderWithdrawnAssets();
            return true;
        }

        function earn_startDeferredSummaryFetches(addr, chainId, runId) {
            const tasks = [
                earn_fetchOdoloClaimed(addr).catch(() => 0),
                earn_fetchMerklRewards(addr, chainId).catch(() => ({})),
            ];
            if (chainId === 'berachain') tasks.push(earn_fetchIBGTRewards(addr).catch(() => null));
            if (chainId === 'arbitrum') tasks.push(earn_fetchDGMXRewards(addr).catch(() => null));
            return Promise.allSettled(tasks).then(() => {
                if (!earn_isLookupRunCurrent(runId)) return false;
                const table = document.querySelector('.earn-asset-table');
                if (table) table.classList.add('no-animate');
                if (earn_cachedAssets && earn_cachedAssets.length > 0) {
                    earn_renderResults(earn_cachedAssets, { skipSummary: false, softRefresh: true });
                    const activeAddr = document.getElementById('earn-address').value.trim();
                    earn_saveLookupCache(chainId, activeAddr);
                }
                return true;
            });
        }

        async function earn_lookup() {
            // Reset animation suppression for fresh search
            const tbl = document.querySelector('.earn-asset-table');
            if (tbl) tbl.classList.remove('no-animate');

            const addr = document.getElementById('earn-address').value.trim();
            const chainId = document.getElementById('earn-chain').value;
            const btn = document.getElementById('earn-search-btn');

            // Validate address
            if (!addr || !/^0x[a-fA-F0-9]{40}$/.test(addr)) {
                earn_hideAll();
                earn_showError('Please enter a valid EVM address (0x...)');
                return;
            }

            const lookupRunId = earn_startLookupRun();
            earn_activeLookupAddr = addr;
            const isCurrentLookup = () => earn_isLookupRunCurrent(lookupRunId);
            const cachedLookup = earn_loadLookupCache(chainId, addr);
            const lookupProfile = earn_createLookupProfiler(chainId, addr, !!cachedLookup);
            earn_preservedTrustedMarketIds = new Set();
            earn_hideAll();
            btn.classList.add('loading');
            btn.disabled = true;
            earn_cachedAssets = [];
            earn_netflowData = null;
            earn_acct0NetflowData = null;
            earn_totalYieldData = null;
            earn_resolvedTotalYieldData = null;
            earn_totalYieldDays = 0;
            earn_marketRates = {};
            earn_subgraphTokens = {};
            earn_borrowPositionData = [];
            earn_collateralPositionData = [];
            earn_lendingPositions = [];
            earn_replayAccountNumbers = [];
            earn_lastReplayError = null;
            earn_replayUsedSubgraphFallback = false;
            earn_openBorrowAccounts = new Set();
            earn_hiddenCollateralSupplyMarkets = new Set();
            earn_subgraphAccountSnapshot = null;
            earn_interestYieldData = null;
            earn_publishedResolvedInterestLedger = null;
            earn_replayStateData = {};
            earn_replayBlockTag = null;
            earn_resetCanonicalSubaccountHistoryState();
            earn_replayVerificationIncompleteMarkets = new Set();
            earn_replayTruncatedSubgraphMarkets = new Set();
            earn_replaySubgraphHistoryIncomplete = false;
            earn_replayReconciledMarkets = new Set();
            earn_replayActualSupplyMap = {};
            earn_replayActualBorrowMap = {};
            earn_replayActualCollateralMap = {};
            earn_replayEventData = [];
            earn_replayVerificationData = {};
            earn_replayVerificationSummary = { total: 0, verified: 0, mismatch: 0, unverified: 0 };
            earn_replayVerificationReady = false;
            earn_replayBorrowAccountsOverride = new Set();
            earn_merklRewards = {};
            earn_merklRewardsLoaded = false;
            earn_merklRewardsLoadedFor = '';
            earn_merklFetchStatus = 'idle';
            earn_merklFetchError = '';
            earn_odoloClaimed = 0;
            earn_odoloUnclaimed = 0;
            earn_odoloCumulative = 0;
            earn_odoloAmountPerNetwork = {};
            earn_odoloClaimedLoadedFor = '';
            earn_ibgtRewards = null;
            earn_ibgtRewardsLoadedFor = '';
            earn_dgmxRewards = null;
            earn_dgmxRewardsLoadedFor = '';
            earn_odoloMeta = null;
            earn_totalYieldStatus = 'loading';
            earn_replayStatus = 'loading';
            earn_globalEmptyState = false;
            earn_lookupLoading = false;
            earn_lookupUsingCachedSnapshot = false;
            earn_renderNotices();
            earn_showLookupLoadingState('Loading verified Earn data...', {
                runId: lookupRunId,
                chainId,
                cached: !!cachedLookup,
            });
            if (cachedLookup) {
                earn_lookupUsingCachedSnapshot = true;
                earn_applyLookupCache(cachedLookup);
                earn_lookupLoading = true;
                earn_setLookupProfileExtra(lookupProfile, 'cached assets', (cachedLookup.cachedAssets || []).length);
                earn_updateLookupRefreshBadge();
            }

            try {
                const chain = earn_getChain();
                if (chain.pending) {
                    earn_totalYieldStatus = 'idle';
                    earn_finishLookupLoadingUi({ runId: lookupRunId, recordEstimate: false });
                    earn_showError(chain.name + ' is not yet live on Dolomite. Check back soon!');
                    earn_logLookupProfile(lookupProfile, 'failed');
                    btn.classList.remove('loading');
                    btn.disabled = false;
                    return;
                }

                // Start exact upstream reads early so later verification stages can reuse the
                // same in-flight request instead of waiting to begin after balances render.
                const manifestPromise = earn_loadManifest();
                const currentAccountsPromise = earn_fetchCurrentAccountsFromSubgraph(addr);
                const canonicalHistoryPromise = earn_fetchSubaccountHistoryForAddress(chainId, addr);
                const verifiedLedgerPromise = manifestPromise
                    .catch(() => null)
                    .then(() => earn_fetchVerifiedLedgerForAddress(chainId, addr));
                const marketRatesPromise = earn_fetchMarketRates(chainId);
                Promise.allSettled([
                    manifestPromise,
                    currentAccountsPromise,
                    canonicalHistoryPromise,
                    verifiedLedgerPromise,
                    marketRatesPromise,
                ]);

                const publishedResolvedLedgerPromise = verifiedLedgerPromise.then(verifiedLedger => {
                    if (!isCurrentLookup()) return null;
                    earn_applyPublishedResolvedInterestLedger(verifiedLedger);
                    return verifiedLedger;
                });

                const replayBlockTagPromise = publishedResolvedLedgerPromise.then(() => Promise.all([
                    earn_rpcRequest('eth_blockNumber', [], 3),
                    canonicalHistoryPromise.catch(() => null),
                ])).then(([headBlockTag, canonicalHistory]) => {
                    let preferredBlockTag = headBlockTag;
                    const headBlock = earn_parseBlockNumberLike(headBlockTag);
                    const historyBlock = earn_parseBlockNumberLike(canonicalHistory && canonicalHistory.lastScannedBlock);
                    if (headBlock !== null && historyBlock !== null && headBlock >= historyBlock) {
                        const lag = headBlock - historyBlock;
                        const lagTolerance = earn_getCanonicalLookupBlockLagTolerance(chainId);
                        if (lag > 0n && lag <= lagTolerance) {
                            preferredBlockTag = earn_formatBlockTagFromBigInt(historyBlock) || headBlockTag;
                        }
                    }
                    if (isCurrentLookup()) {
                        earn_replayBlockTag = preferredBlockTag;
                    }
                    return preferredBlockTag;
                });

                const replayPromise = replayBlockTagPromise.then(blockTag => earn_fetchNetflow({
                    blockTag,
                    runId: lookupRunId,
                    onAsyncReplayUpdate: async () => {
                        if (!isCurrentLookup()) return;
                        earn_reconcileReplayToCachedCurrentPositions();
                        earn_refreshReplayVerificationFromCachedPositions();
                        earn_refreshResolvedTotalYieldData();
                        earn_renderNotices();
                        const tblRef = document.querySelector('.earn-asset-table');
                        if (tblRef) tblRef.classList.add('no-animate');
                        if (earn_cachedAssets && earn_cachedAssets.length > 0) {
                            earn_renderResults(earn_cachedAssets, { skipSummary: false, softRefresh: true });
                        }
                        earn_saveLookupCache(chainId, addr);
                    },
                }))
                    .then(() => {
                        if (!isCurrentLookup()) return false;
                        earn_replayStatus = 'ready';
                        earn_updateLookupLoadingUi(lookupRunId, {
                            stageIndex: 2,
                            progress: 0.56,
                            detail: 'Ledger replay is complete. Verifying total yield against trusted snapshots now.',
                        });
                        earn_renderNotices();
                        earn_markLookupProfile(lookupProfile, 'replay');
                        return true;
                    })
                    .catch(netflowErr => {
                        if (!isCurrentLookup()) return false;
                        earn_markLookupProfile(lookupProfile, 'replay');
                        earn_lastReplayError = netflowErr;
                        console.warn('Onchain replay failed, continuing with fallback balances:', netflowErr);
                        earn_interestYieldData = null;
                        earn_replayUsedSubgraphFallback = false;
                        earn_openBorrowAccounts = new Set();
                        earn_hiddenCollateralSupplyMarkets = new Set();
                        earn_replayStateData = {};
                        earn_replayEventData = [];
                        earn_replayVerificationData = {};
                        earn_replayVerificationSummary = { total: 0, verified: 0, mismatch: 0, unverified: 0 };
                        earn_replayVerificationReady = false;
                        earn_replayStatus = 'error';
                        earn_applyPublishedResolvedInterestLedger(earn_publishedResolvedInterestLedger);
                        earn_updateLookupLoadingUi(lookupRunId, {
                            stageIndex: 2,
                            progress: 0.56,
                            detail: 'Replay fell back to the safer path. Yield verification is still finishing with snapshot-backed data.',
                        });
                        earn_renderNotices();
                        return false;
                    });

                let balances;
                try {
                    await publishedResolvedLedgerPromise;
                    balances = await earn_fetchActiveSupplyBalances(addr, { blockTag: 'latest' });
                    if (!isCurrentLookup()) return;
                    earn_markLookupProfile(lookupProfile, 'balances');
                    earn_setLookupProfileExtra(lookupProfile, 'active balances', balances.length);
                    earn_updateLookupLoadingUi(lookupRunId, {
                        stageIndex: 1,
                        progress: 0.28,
                        detail: balances.length > 0
                            ? `Found ${balances.length} active position${balances.length !== 1 ? 's' : ''}. Replaying deposits and withdrawals now.`
                            : 'No active supply balances yet. Checking replay and history before deciding what to show.',
                    });
                } catch (balanceErr) {
                    if (!isCurrentLookup()) return;
                    earn_markLookupProfile(lookupProfile, 'balances');
                    earn_totalYieldStatus = 'error';
                    earn_finishLookupLoadingUi({ runId: lookupRunId, recordEstimate: false });
                    earn_showError('Balance lookup failed: ' + balanceErr.message);
                    earn_logLookupProfile(lookupProfile, 'failed');
                    return;
                }

                if (balances.length === 0) {
                    // Before giving up, check whether the replay discovered borrow-only accounts
                    const chainId = document.getElementById('earn-chain').value;

                    if (earn_borrowPositionData.length > 0) {
                        // Has borrow positions — proceed with borrow-only render
                        console.log(`No supply balances but found ${earn_borrowPositionData.length} borrow positions — rendering borrow-only view`);

                        // Fetch prices for borrow tokens
                        const borrowTokenAddrs = earn_borrowPositionData.map(bp => bp.tokenAddr).filter(Boolean);
                        const collateralTokenAddrs = earn_collateralPositionData.map(cp => cp.tokenAddr).filter(Boolean);
                        await earn_fetchCoinGeckoPrices([...borrowTokenAddrs, ...collateralTokenAddrs]);
                        if (!isCurrentLookup()) return;
                        earn_markLookupProfile(lookupProfile, 'prices');

                        // Build enriched array with only borrow positions
                        const enriched = [];
                        // Precise USD via BigInt scaling (wei is a BigInt) — avoids the
                        // Number(wei)/10^decimals float drift that affects sort order and
                        // the $1 dust boundary. Same price source as earn_getUsdPrice.
                        for (const cp of earn_collateralPositionData) {
                            cp.usdValue = Math.abs(earn_scaledUsdToNumber(earn_getTokenUsdScaled(cp.wei, cp.decimals, cp.symbol, cp.tokenAddr, chainId)));
                            enriched.push(cp);
                        }
                        for (const bp of earn_borrowPositionData) {
                            bp.usdValue = Math.abs(earn_scaledUsdToNumber(earn_getTokenUsdScaled(bp.wei, bp.decimals, bp.symbol, bp.tokenAddr, chainId)));
                            enriched.push(bp);
                        }
                        console.log(`Injected ${earn_collateralPositionData.length} collateral and ${earn_borrowPositionData.length} borrow positions (no visible supply)`);

                        earn_cachedAssets = enriched;
                        enriched.sort((a, b) => b.usdValue - a.usdValue);
                        earn_lookupLoading = false;
                        earn_lookupUsingCachedSnapshot = false;
                        earn_totalYieldStatus = 'ready';
                        earn_setResultsRefreshing(false);
                        earn_markLookupProfile(lookupProfile, 'firstRenderReady');
                        earn_renderResults(enriched, { skipSummary: false, softRefresh: !!cachedLookup });
                        earn_startDeferredSummaryFetches(addr, chainId, lookupRunId);
                        earn_logLookupProfile(lookupProfile, 'firstRenderReady');

                        // Also fetch lending positions
                        const lendingPromise = earn_fetchAndRenderLendingPositions({ runId: lookupRunId, addr, chainId })
                            .then(result => {
                                if (!isCurrentLookup()) return result;
                                earn_markLookupProfile(lookupProfile, 'lending');
                                return result;
                            })
                            .catch(e => console.warn('Lending load:', e));
                        const replaySyncedLendingPromise = replayPromise.then(async ok => {
                            if (!isCurrentLookup() || !ok) return null;
                            try {
                                return await earn_fetchAndRenderLendingPositions({ runId: lookupRunId, addr, chainId });
                            } catch (e) {
                                console.warn('Lending replay refresh:', e);
                                return null;
                            }
                        });

                        // After first render, suppress slide-in on re-renders
                        const tblNoSupply = document.querySelector('.earn-asset-table');
                        if (tblNoSupply) {
                            setTimeout(() => tblNoSupply.classList.add('no-animate'), 500);
                        }

                        // Also auto-load history for withdrawn assets
                        earn_lookupHistory({ runId: lookupRunId, allowReplayRetry: false }).then(ok => {
                            if (!isCurrentLookup()) return Promise.allSettled([lendingPromise, replaySyncedLendingPromise]);
                            if (ok) {
                                earn_markLookupProfile(lookupProfile, 'history');
                                const tblRef = document.querySelector('.earn-asset-table');
                                if (tblRef) tblRef.classList.add('no-animate');
                                if (earn_cachedAssets) earn_renderResults(earn_cachedAssets, { skipSummary: false, softRefresh: true });
                            }
                            return Promise.allSettled([lendingPromise, replaySyncedLendingPromise]).then(() => {
                                if (!isCurrentLookup()) return;
                                earn_markLookupProfile(lookupProfile, 'complete');
                                earn_logLookupProfile(lookupProfile, 'complete');
                                earn_saveLookupCache(chainId, addr);
                                earn_finishLookupLoadingUi({
                                    runId: lookupRunId,
                                    chainId,
                                    durationMs: lookupProfile.marks.complete,
                                });
                            });
                        }).catch(e => {
                            if (!isCurrentLookup()) return Promise.allSettled([lendingPromise, replaySyncedLendingPromise]);
                            console.warn('History load:', e);
                            return Promise.allSettled([lendingPromise, replaySyncedLendingPromise]).then(() => {
                                if (!isCurrentLookup()) return;
                                earn_markLookupProfile(lookupProfile, 'complete');
                                earn_logLookupProfile(lookupProfile, 'complete');
                                earn_saveLookupCache(chainId, addr);
                                earn_finishLookupLoadingUi({
                                    runId: lookupRunId,
                                    chainId,
                                    durationMs: lookupProfile.marks.complete,
                                });
                            });
                        });

                        return;
                    }

                    // Check if there's netflow history for this address
                    let netflowCheckFailed = false;
                    try {
                        const nfResp = await fetch(`${NETFLOW_BASE}/${chainId}.json`);
                        if (!nfResp.ok) netflowCheckFailed = true;
                        if (!isCurrentLookup()) return;
                        if (nfResp.ok) {
                            const nfData = await nfResp.json();
                            if (!isCurrentLookup()) return;
                            const addrFlows = nfData.netflows && nfData.netflows[addr.toLowerCase()];
                            if (addrFlows && Object.keys(addrFlows).length > 0) {
                                // Has history but no active deposits — auto-enable inactive toggle
                                earn_showInactive = true;
                                // Update button state
                                const btn = document.getElementById('earn-inactive-toggle');
                                if (btn) {
                                    btn.classList.add('active');
                                    const label = btn.querySelector('.earn-withdrawn-label');
                                    const icon = btn.querySelector('.earn-withdrawn-icon');
                                    if (label) label.textContent = 'Hide Past';
                                    if (icon) icon.innerHTML = '<path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/>';
                                }
                                // Load history and render in unified view
                                earn_lookupHistory({ runId: lookupRunId, allowReplayRetry: false }).then(() => {
                                if (!isCurrentLookup()) return;
                                earn_markLookupProfile(lookupProfile, 'history');
                                earn_markLookupProfile(lookupProfile, 'complete');
                                earn_lookupLoading = false;
                                earn_lookupUsingCachedSnapshot = false;
                                earn_setResultsRefreshing(false);
                                earn_totalYieldStatus = 'ready';
                                earn_logLookupProfile(lookupProfile, 'complete');
                                earn_renderResults([]);
                                earn_finishLookupLoadingUi({
                                    runId: lookupRunId,
                                    chainId,
                                    durationMs: lookupProfile.marks.complete,
                                });
                            }).catch(e => {
                                console.warn('History load:', e);
                                if (!isCurrentLookup()) return;
                                earn_markLookupProfile(lookupProfile, 'complete');
                                earn_lookupLoading = false;
                                earn_lookupUsingCachedSnapshot = false;
                                earn_setResultsRefreshing(false);
                                earn_logLookupProfile(lookupProfile, 'complete');
                                earn_finishLookupLoadingUi({
                                    runId: lookupRunId,
                                    chainId,
                                    durationMs: lookupProfile.marks.complete,
                                });
                            });
                                btn.classList.remove('loading');
                                btn.disabled = false;
                                return;
                            }
                        }
                    } catch (e) {
                        // Don't conflate a network failure with a genuine empty result —
                        // show a "couldn't verify" state so the user knows to retry.
                        console.warn('Netflow check failed:', e && e.message ? e.message : e);
                        netflowCheckFailed = true;
                    }

                    if (!isCurrentLookup()) return;
                    earn_lookupLoading = false;
                    earn_lookupUsingCachedSnapshot = false;
                    earn_setResultsRefreshing(false);
                    const searchAddr = document.getElementById('earn-address').value.trim();
                    const addrBadgeHtml = (typeof dolo_labelBadge === 'function') ? dolo_labelBadge(searchAddr) : '';
                    earn_totalYieldStatus = 'ready';
                    if (netflowCheckFailed) {
                        earn_showGlobalEmptyState({
                            title: addrBadgeHtml ? `<div style="display:flex;align-items:center;justify-content:center;gap:6px">Couldn’t verify deposits ${addrBadgeHtml}</div>` : 'Couldn’t verify deposits',
                            message: 'We couldn’t reach the data source to check this address. Please try again.',
                        });
                    } else {
                        earn_showGlobalEmptyState({
                            title: addrBadgeHtml ? `<div style="display:flex;align-items:center;justify-content:center;gap:6px">No deposits found ${addrBadgeHtml}</div>` : 'No deposits found',
                            message: 'This address has no active deposits on Dolomite',
                        });
                    }
                    earn_markLookupProfile(lookupProfile, 'complete');
                    earn_logLookupProfile(lookupProfile, 'complete');
                    earn_finishLookupLoadingUi({ runId: lookupRunId, chainId, durationMs: lookupProfile.marks.complete });
                    return;
                }


                // Start parallel fetches: netflow, CoinGecko prices, total yield
                const pricesPromise = earn_fetchCoinGeckoPrices([
                    ...balances.map(b => b.tokenAddr),
                    ...earn_collateralPositionData.map(b => b.tokenAddr).filter(Boolean),
                    ...earn_borrowPositionData.map(b => b.tokenAddr).filter(Boolean),
                ]).then(result => {
                    if (!isCurrentLookup()) return result;
                    earn_markLookupProfile(lookupProfile, 'prices');
                    return result;
                });
                const batchCalls = [];
                const batchMap = []; // tracks what each call is for

                balances.forEach((b, i) => {
                    const key = chainId + ':' + b.tokenAddr.toLowerCase();
                    const cached = earn_tokenCache[key] || KNOWN_TOKENS[key] || earn_subgraphTokens[String(b.marketId)];
                    if (!cached) {
                        // Need symbol + decimals
                        batchCalls.push({ to: b.tokenAddr, data: '0x95d89b41' }); // symbol()
                        batchMap.push({ type: 'symbol', idx: i });
                        batchCalls.push({ to: b.tokenAddr, data: '0x313ce567' }); // decimals()
                        batchMap.push({ type: 'decimals', idx: i });
                    }
                });

                // Single batch RPC call for all token info
                const batchResults = batchCalls.length > 0 ? await earn_rpcBatch(batchCalls) : [];
                if (!isCurrentLookup()) return;

                // Parse batch results
                const tokenRaw = balances.map(() => ({ symHex: null, decHex: null }));
                batchMap.forEach((m, i) => {
                    const r = batchResults[i];
                    if (m.type === 'symbol') tokenRaw[m.idx].symHex = r;
                    else if (m.type === 'decimals') tokenRaw[m.idx].decHex = r;
                });

                // Fetch supply APR/APY data once per chain and reuse the shared cache.
                const apyPromise = earn_fetchMarketRates(chainId)
                    .then(() => {
                        if (!isCurrentLookup()) return;
                        earn_markLookupProfile(lookupProfile, 'apy');
                    })
                    .catch(e => {
                        if (!isCurrentLookup()) return;
                        earn_markLookupProfile(lookupProfile, 'apy');
                        console.warn('Dolomite APY fetch:', e);
                    });

                // Enrich with token info + USD value (use fallback prices for instant render)
                const enriched = balances.map((b, i) => {
                    const key = chainId + ':' + b.tokenAddr.toLowerCase();
                    let info = earn_tokenCache[key] || earn_subgraphTokens[String(b.marketId)];
                    if (!info && KNOWN_TOKENS[key]) {
                        info = { ...KNOWN_TOKENS[key] };
                        if (!info.icon && info.symbol) info.icon = SYMBOL_ICONS[info.symbol] || SYMBOL_ICONS[info.symbol.toUpperCase()] || null;
                        earn_tokenCache[key] = info;
                    }
                    if (!info) {
                        // Parse from batch results
                        let symbol = 'UNK';
                        const symHex = tokenRaw[i].symHex;
                        if (symHex && symHex.length > 2) {
                            try {
                                const raw = symHex.replace('0x', '');
                                if (raw.length === 64 * 1) {
                                    const bytes = [];
                                    for (let j = 0; j < 64; j += 2) {
                                        const byte = parseInt(raw.substr(j, 2), 16);
                                        if (byte > 0) bytes.push(byte);
                                    }
                                    symbol = String.fromCharCode(...bytes);
                                } else {
                                    const offsetIdx = parseInt(raw.slice(0, 64), 16) * 2;
                                    const len = parseInt(raw.slice(64, 128), 16);
                                    const hex = raw.slice(128, 128 + len * 2);
                                    const bytes = [];
                                    for (let j = 0; j < hex.length; j += 2) {
                                        bytes.push(parseInt(hex.substr(j, 2), 16));
                                    }
                                    symbol = String.fromCharCode(...bytes);
                                }
                            } catch (e) { /* fallback */ }
                        }
                        const decHex = tokenRaw[i].decHex;
                        const decimals = decHex ? Number(BigInt('0x' + decHex.replace('0x', ''))) : 18;
                        // Icon: direct lookup, PT-/GM- prefix match, or generate SVG fallback
                        let icon = SYMBOL_ICONS[symbol] || SYMBOL_ICONS[symbol.toUpperCase()];
                        if (!icon && symbol.startsWith('PT-')) icon = SYMBOL_ICONS['PENDLE'];
                        if (!icon && symbol.startsWith('GM:')) icon = SYMBOL_ICONS['GM'];
                        if (!icon) {
                            // Generate colored circle SVG with first letter
                            const ch = (symbol[0] || '?').toUpperCase();
                            const hue = [...symbol].reduce((h, c) => (h + c.charCodeAt(0) * 37) % 360, 0);
                            icon = `data:image/svg+xml,${encodeURIComponent(`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><circle cx='16' cy='16' r='16' fill='hsl(${hue},50%,35%)'/><text x='16' y='22' text-anchor='middle' font-size='16' font-weight='bold' fill='white'>${ch}</text></svg>`)}`;
                        }
                        // XSS guard: on-chain symbol() is deployer-controlled and the cached
                        // value feeds innerHTML templates downstream. Same rule as
                        // earn_getTokenInfo (:9556) and the subgraph decoder (:15692).
                        // Escape AFTER icon/hue computation so icon matching uses the raw symbol.
                        symbol = earn_escapeHtml(symbol);
                        info = { symbol, decimals, icon };
                        earn_tokenCache[key] = info;
                    }

                    // Precise USD via BigInt scaling (wei is a BigInt). Unknown tokens fall
                    // back to 0 (not a fabricated $0.01, which skewed the dust filter).
                    const usdValue = Math.abs(earn_scaledUsdToNumber(earn_getTokenUsdScaled(b.wei, info.decimals, info.symbol, b.tokenAddr, chainId)));
                    return {
                        ...b,
                        symbol: info.symbol,
                        decimals: info.decimals,
                        icon: info.icon,
                        usdValue,
                    };
                });

                const updateAssetUsdValuesFromPriceCache = () => {
                    enriched.forEach(asset => {
                        const cgKey = chainId + ':' + String(asset.tokenAddr || '').toLowerCase();
                        const livePrice = earn_priceCache[cgKey];
                        if (livePrice) {
                            // Precise BigInt scaling (asset.wei is a BigInt).
                            asset.usdValue = Math.abs(earn_scaledUsdToNumber(earn_getTokenUsdScaled(asset.wei, asset.decimals, asset.symbol, asset.tokenAddr, chainId)));
                        }
                    });
                };
                const sortEnrichedAssets = () => {
                    enriched.sort((a, b) => {
                        const rankA = a.isBorrow ? 2 : a.isCollateral ? 1 : 0;
                        const rankB = b.isBorrow ? 2 : b.isCollateral ? 1 : 0;
                        if (rankA !== rankB) return rankA - rankB;
                        return b.usdValue - a.usdValue;
                    });
                };

                if (earn_collateralPositionData.length > 0) {
                    for (const cp of earn_collateralPositionData) {
                        cp.usdValue = Math.abs(earn_scaledUsdToNumber(earn_getTokenUsdScaled(cp.wei, cp.decimals, cp.symbol, cp.tokenAddr, chainId)));
                        enriched.push(cp);
                    }
                    console.log(`Injected ${earn_collateralPositionData.length} collateral supply positions into enriched assets`);
                }

                // Inject borrow positions from onchain account balances
                if (earn_borrowPositionData.length > 0) {
                    const existingMarkets = new Set(enriched.map(a => a.marketId));
                    for (const bp of earn_borrowPositionData) {
                        // Skip if this market already appears as a supply position in enriched
                        // (shouldn't happen, but safety check)
                        if (existingMarkets.has(bp.marketId) && enriched.find(a => a.marketId === bp.marketId && !a.isBorrow)) {
                            // Market exists as supply — add borrow separately
                        }
                        bp.usdValue = Math.abs(earn_scaledUsdToNumber(earn_getTokenUsdScaled(bp.wei, bp.decimals, bp.symbol, bp.tokenAddr, chainId)));
                        enriched.push(bp);
                    }
                    console.log(`Injected ${earn_borrowPositionData.length} borrow positions into enriched assets`);
                }

                // Update cached assets with borrows included
                sortEnrichedAssets();
                earn_cachedAssets = enriched;
                const activeMarketIdsForYield = Array.from(new Set(
                    balances.map(b => earn_normalizeMarketId(b.marketId)).filter(Boolean)
                ));
                const totalYieldWarmPromise = earn_fetchTotalYield({
                    suppressRender: true,
                    runId: lookupRunId,
                    activeMarketIds: activeMarketIdsForYield,
                    allowSnapshotFallback: false,
                })
                    .then(result => {
                        if (!isCurrentLookup()) return result;
                        if (result) {
                            earn_updateLookupLoadingUi(lookupRunId, {
                                stageIndex: 2,
                                progress: 0.76,
                                detail: (earn_replayStatus === 'ready' || earn_replayStatus === 'error')
                                    ? 'Verified yield is ready. Loading history and lending analytics before reveal.'
                                    : 'Historical yield is loaded. Waiting for replay reconciliation before revealing the final verified result.',
                            });
                        }
                        if (
                            result &&
                            !earn_lookupLoading &&
                            earn_cachedAssets &&
                            earn_cachedAssets.length > 0 &&
                            earn_replayStatus !== 'loading' &&
                            earn_replayStatus !== 'idle' &&
                            earn_replayVerificationReady
                        ) {
                            const tblRef = document.querySelector('.earn-asset-table');
                            if (tblRef) tblRef.classList.add('no-animate');
                            earn_renderResults(earn_cachedAssets, { skipSummary: false, softRefresh: true });
                        }
                        return result;
                    })
                    .catch(e => {
                        if (!isCurrentLookup()) return false;
                        earn_totalYieldStatus = 'error';
                        earn_renderNotices();
                        console.warn('Total yield load:', e);
                        return false;
                    });
                const totalYieldPromise = Promise.allSettled([replayPromise, totalYieldWarmPromise])
                    .then(() => {
                        if (!isCurrentLookup()) return false;
                        const currentYieldData = earn_totalYieldData || {};
                        const replayMarketIds = Object.keys(earn_netflowData || {});
                        const needsReplayExpansion = replayMarketIds.some(mid => !Object.prototype.hasOwnProperty.call(currentYieldData, String(mid)));
                        if (!needsReplayExpansion) return !!earn_totalYieldData;
                        return earn_fetchTotalYield({
                            suppressRender: true,
                            runId: lookupRunId,
                            activeMarketIds: activeMarketIdsForYield,
                            allowSnapshotFallback: false,
                        });
                    })
                    .then(result => {
                        if (!isCurrentLookup()) return result;
                        earn_markLookupProfile(lookupProfile, 'totalYield');
                        earn_updateLookupLoadingUi(lookupRunId, {
                            stageIndex: 2,
                            progress: 0.8,
                            detail: 'Total yield is verified. Final sections are being prepared now.',
                        });
                        return result;
                    })
                    .catch(e => {
                        if (!isCurrentLookup()) return false;
                        earn_markLookupProfile(lookupProfile, 'totalYield');
                        earn_totalYieldStatus = 'error';
                        earn_renderNotices();
                        console.warn('Total yield refresh:', e);
                        return false;
                    });

                // Show the first live render immediately using cached/fallback USD values.
                // Pricing, replay verification, and total yield continue in the background and
                // trigger a follow-up render once they finish.
                sortEnrichedAssets();
                earn_lookupLoading = false;
                earn_lookupUsingCachedSnapshot = false;
                earn_setResultsRefreshing(true);
                earn_markLookupProfile(lookupProfile, 'firstRenderReady');
                earn_renderResults(enriched, { skipSummary: false, softRefresh: !!cachedLookup });
                earn_startDeferredSummaryFetches(addr, chainId, lookupRunId);
                earn_logLookupProfile(lookupProfile, 'firstRenderReady');

                const lendingPromise = earn_fetchAndRenderLendingPositions({ runId: lookupRunId, addr, chainId })
                    .then(result => {
                        if (!isCurrentLookup()) return result;
                        earn_markLookupProfile(lookupProfile, 'lending');
                        earn_updateLookupLoadingUi(lookupRunId, {
                            stageIndex: 3,
                            progress: 0.92,
                            detail: 'Lending analytics are ready. Final verified dashboard is being revealed next.',
                        });
                        return result;
                    })
                    .catch(e => console.warn('Lending load:', e));

                const pricesRefreshPromise = pricesPromise.then(() => {
                    if (!isCurrentLookup()) return false;
                    updateAssetUsdValuesFromPriceCache();
                    sortEnrichedAssets();
                    earn_cachedAssets = enriched;
                    return true;
                }).catch(e => {
                    console.warn('Price refresh after first render:', e);
                    return false;
                });

                const historyPromise = Promise.allSettled([replayPromise, totalYieldPromise])
                    .then(() => {
                        if (!isCurrentLookup()) return false;
                        return earn_lookupHistory({ runId: lookupRunId, allowReplayRetry: false });
                    })
                    .then(result => {
                        if (!isCurrentLookup()) return false;
                        if (result) earn_markLookupProfile(lookupProfile, 'history');
                        if (result) {
                            earn_updateLookupLoadingUi(lookupRunId, {
                                stageIndex: 3,
                                progress: 0.88,
                                detail: 'History snapshots are loaded. Wrapping up lending analytics now.',
                            });
                        }
                        return !!result;
                    })
                    .catch(e => {
                        if (!isCurrentLookup()) return false;
                        console.warn('History load:', e);
                        return false;
                    });

                // Batch background data (APY + replay + prices + history + total yield) → single soft refresh
                Promise.allSettled([
                    pricesRefreshPromise,
                    apyPromise,
                    totalYieldPromise,
                    replayPromise.then(ok => {
                        if (!isCurrentLookup()) return null;
                        if (!ok) return null;
                        earn_reconcileReplayToCachedCurrentPositions();
                        earn_refreshReplayVerificationFromCachedPositions();
                        return true;
                    }),
                    replayPromise.then(async ok => {
                        if (!isCurrentLookup() || !ok) return null;
                        try {
                            return await earn_fetchAndRenderLendingPositions({ runId: lookupRunId, addr, chainId });
                        } catch (e) {
                            console.warn('Lending replay refresh:', e);
                            return null;
                        }
                    }),
                    historyPromise,
                    lendingPromise,
                ]).then(() => {
                    if (!isCurrentLookup()) return;
                    earn_lookupLoading = false;
                    earn_lookupUsingCachedSnapshot = false;
                    earn_setResultsRefreshing(false);
                    try {
                        earn_updateLookupLoadingUi(lookupRunId, {
                            stageIndex: 3,
                            progress: 0.99,
                            headline: 'Finalizing verified Earn dashboard',
                            detail: 'All critical data is loaded. Rendering the final stable view now.',
                        });
                        const tblRef = document.querySelector('.earn-asset-table');
                        if (tblRef) tblRef.classList.add('no-animate');
                        earn_renderResults(enriched, { skipSummary: false, softRefresh: true });
                        earn_markLookupProfile(lookupProfile, 'complete');
                        earn_logLookupProfile(lookupProfile, 'complete');
                        earn_saveLookupCache(chainId, addr);
                    } catch (finalRenderErr) {
                        console.warn('Final Earn reveal after first render:', finalRenderErr);
                        earn_markLookupProfile(lookupProfile, 'complete');
                    } finally {
                        if (isCurrentLookup()) {
                            earn_finishLookupLoadingUi({
                                runId: lookupRunId,
                                chainId,
                                durationMs: lookupProfile.marks.complete || (earn_nowMs() - lookupProfile.startedAt),
                            });
                        }
                    }
                }).catch(finalRevealErr => {
                    if (!isCurrentLookup()) return;
                    console.warn('Final Earn reveal failed:', finalRevealErr);
                    earn_lookupLoading = false;
                    earn_lookupUsingCachedSnapshot = false;
                    earn_setResultsRefreshing(false);
                    earn_markLookupProfile(lookupProfile, 'complete');
                    earn_finishLookupLoadingUi({
                        runId: lookupRunId,
                        chainId,
                        durationMs: lookupProfile.marks.complete || (earn_nowMs() - lookupProfile.startedAt),
                    });
                });
            } catch (e) {
                if (!isCurrentLookup()) return;
                console.error('EARN lookup error:', e, e.stack);
                earn_totalYieldStatus = 'error';
                earn_finishLookupLoadingUi({ runId: lookupRunId, recordEstimate: false });
                earn_renderNotices();
                earn_showError('Failed to fetch data from RPC. Please try again.');
                earn_logLookupProfile(lookupProfile, 'failed');
            } finally {
                if (isCurrentLookup()) {
                    btn.classList.remove('loading');
                    btn.disabled = false;
                }
            }
        }

        // ---- Detail row helpers ----
        let earn_openDetailIdx = null; // track which detail row is currently open
        let earn_openPastDetailIdx = null; // track which withdrawn detail row is currently open
        let earn_pastSortKey = 'yield';
        let earn_pastSortDesc = true;
        function earn_scrollDetailIntoView(detail, dataRow, containerId) {
            const container = document.getElementById(containerId || 'earn-supply-section');
            if (!detail) return;
            if (!container) {
                detail.scrollIntoView({ behavior: 'smooth', block: 'end' });
                return;
            }

            const containerRect = container.getBoundingClientRect();
            const focusRect = detail.getBoundingClientRect();
            const rowRect = dataRow ? dataRow.getBoundingClientRect() : focusRect;
            const topPadding = 72;
            const bottomPadding = 28;

            if (focusRect.bottom > containerRect.bottom - bottomPadding) {
                container.scrollBy({
                    top: focusRect.bottom - containerRect.bottom + bottomPadding,
                    behavior: 'smooth',
                });
                return;
            }

            if (rowRect.top < containerRect.top + topPadding) {
                container.scrollBy({
                    top: rowRect.top - containerRect.top - topPadding,
                    behavior: 'smooth',
                });
            }
        }

        function earn_toggleDetail(idx) {
            const detail = document.getElementById('earn-detail-' + idx);
            const dataRow = document.getElementById('earn-row-' + idx);
            if (!detail || !dataRow) return;

            // Close previously open detail row (single-open)
            if (earn_openDetailIdx !== null && earn_openDetailIdx !== idx) {
                const prevDetail = document.getElementById('earn-detail-' + earn_openDetailIdx);
                const prevRow = document.getElementById('earn-row-' + earn_openDetailIdx);
                if (prevDetail) prevDetail.classList.remove('open');
                if (prevRow) prevRow.classList.remove('expanded');
            }

            const isOpen = detail.classList.toggle('open');
            dataRow.classList.toggle('expanded', isOpen);
            earn_openDetailIdx = isOpen ? idx : null;

            // Scroll the detail row into view when opening
            if (isOpen) {
                setTimeout(() => {
                    earn_scrollDetailIntoView(detail, dataRow);
                }, 50);
            }
        }

        function earn_toggleHistDetail(idx) {
            const detail = document.getElementById('earn-hist-detail-' + idx);
            const dataRow = document.getElementById('earn-hist-row-' + idx);
            if (!detail || !dataRow) return;
            const isOpen = detail.classList.toggle('open');
            dataRow.classList.toggle('expanded', isOpen);
        }

        function earn_togglePastDetail(idx) {
            const detail = document.getElementById('earn-past-detail-' + idx);
            const dataRow = document.getElementById('earn-past-row-' + idx);
            if (!detail || !dataRow) return;

            if (earn_openPastDetailIdx !== null && earn_openPastDetailIdx !== idx) {
                const prevDetail = document.getElementById('earn-past-detail-' + earn_openPastDetailIdx);
                const prevRow = document.getElementById('earn-past-row-' + earn_openPastDetailIdx);
                if (prevDetail) prevDetail.classList.remove('open');
                if (prevRow) prevRow.classList.remove('expanded');
            }

            const isOpen = detail.classList.toggle('open');
            dataRow.classList.toggle('expanded', isOpen);
            earn_openPastDetailIdx = isOpen ? idx : null;

            if (isOpen) {
                setTimeout(() => {
                    earn_scrollDetailIntoView(detail, dataRow, 'earn-past-section');
                }, 50);
            }
        }

        function earn_sortPastPositions(key) {
            if (!earn_historyData || earn_historyData.length === 0) return;
            if (earn_pastSortKey === key) {
                earn_pastSortDesc = !earn_pastSortDesc;
            } else {
                earn_pastSortKey = key;
                earn_pastSortDesc = key !== 'token';
            }

            earn_updateSortHeaders('.earn-past-table thead th[data-sort]', earn_pastSortKey, earn_pastSortDesc);

            const table = document.querySelector('.earn-past-table');
            if (table) table.classList.add('no-animate');
            earn_renderWithdrawnAssets();
            if (table) requestAnimationFrame(() => table.classList.remove('no-animate'));
        }

        function earn_copyAddr(addr, el) {
            navigator.clipboard.writeText(addr);
            const t = document.getElementById('copy-toast');
            if (t) { t.classList.add('show'); setTimeout(() => t.classList.remove('show'), 1500); }
            if (el) { el.classList.add('copied'); setTimeout(() => el.classList.remove('copied'), 1500); }
        }

        // Build source breakdown HTML for the detail row
        const FLOW_TYPES = [
            { key: 'd', label: 'Deposits', cls: 'earn-seg-d' },
            { key: 'w', label: 'Withdrawals', cls: 'earn-seg-w' },
            { key: 's', label: 'Swaps', cls: 'earn-seg-s' },
            { key: 'x', label: 'Moved Between Earn/Borrow', cls: 'earn-seg-x' },
            { key: 'l', label: 'Liquidations', cls: 'earn-seg-l' },
        ];

        function earn_buildBreakdown(mid, decimals, symbol) {
            if (!earn_netflowData || !earn_netflowData[mid]) return '';
            const fd = earn_netflowData[mid];
            if (typeof fd === 'string') return ''; // old format, no breakdown

            // Collect absolute values for bar proportions
            const entries = [];
            let absSum = 0n;
            for (const ft of FLOW_TYPES) {
                const raw = fd[ft.key];
                if (!raw || raw === '0') continue;
                const val = BigInt(raw);
                const abs = val < 0n ? -val : val;
                entries.push({ ...ft, val, abs });
                absSum += abs;
            }
            if (entries.length === 0) return '';

            // Bar segments
            let barHtml = '';
            for (const e of entries) {
                const pct = absSum > 0n ? Number(e.abs * 10000n / absSum) / 100 : 0;
                barHtml += `<div class="earn-breakdown-seg ${e.cls}" style="width:${pct}%"></div>`;
            }

            // Label items
            let itemsHtml = '';
            for (const e of entries) {
                const sign = e.val > 0n ? '+' : '';
                const fmt = earn_formatAmount(e.val, decimals, symbol);
                itemsHtml += `<div class="earn-breakdown-item">
                    <span class="earn-breakdown-dot ${e.cls}"></span>
                    <span class="earn-breakdown-label">${e.label}</span>
                    <span class="earn-breakdown-val">${sign}${fmt}</span>
                </div>`;
            }

            return `<div class="earn-breakdown">
                <div class="earn-breakdown-title">Asset sources</div>
                <div class="earn-breakdown-bar">${barHtml}</div>
                <div class="earn-breakdown-items">${itemsHtml}</div>
            </div>`;
        }
        // ═══════ Lending Positions (Borrow) — address-prefix risk shards ═══════
        let earn_lendingPositions = [];
        const earn_liqRiskShardPromises = {};
        function earn_fetchLiqRiskForWallet(chainKey, address) {
            const addr = String(address || '').trim().toLowerCase();
            if (!/^0x[a-f0-9]{40}$/.test(addr)) return Promise.resolve(null);
            const prefix = addr.slice(2, 4);
            const cacheKey = `${chainKey}:${prefix}`;
            if (!earn_liqRiskShardPromises[cacheKey]) {
                earn_liqRiskShardPromises[cacheKey] = fetch(
                    `${LIQUIDATION_RISK_SHARD_BASE}/${chainKey}/${prefix}.json`,
                    { cache: 'no-store' }
                ).then(response => response.ok ? response.json() : null).catch(() => null);
            }
            return earn_liqRiskShardPromises[cacheKey];
        }

        function earn_getRiskClass(p) {
            if (p.collateralUSD < 0.01 && p.debtUSD > 0) return 'baddebt';
            if (p.healthFactor === null) return 'strong';
            if (p.healthFactor < 0.95) return 'full-liq';
            if (p.healthFactor < 1.0) return 'partial-liq';
            if (p.healthFactor <= 1.003) return 'danger';
            if (p.healthFactor <= 1.01) return 'low-buffer';
            if (p.healthFactor <= 1.10) return 'moderate';
            if (p.healthFactor <= 1.25) return 'balanced';
            if (p.healthFactor <= 1.50) return 'good';
            return 'strong';
        }

        const EARN_EMODE_TIP = "E-Mode applies special risk parameters for correlated assets in the same category. It can improve borrow efficiency, but liquidation still depends on the account's collateral, debt, and selected E-Mode category.";
        const EARN_EMODE_ICON = '<span class="earn-emode-icon" aria-hidden="true"><svg class="earn-emode-flame" viewBox="0 0 24 24"><path d="M12.2 1.25c.2 3.05-1.3 5.2-3.85 7.36-1.85 1.58-3 3.6-3 6.03a6.65 6.65 0 0 0 13.3 0c0-5.03-3.2-8.56-6.45-13.39Z" fill="#fb923c"/><path d="M12.2 8.05c.18 2.08-1.9 3.1-1.9 5.2a1.9 1.9 0 1 0 3.8 0c0-1.76-.78-3.08-1.9-5.2Z" fill="#fbbf24"/><path d="M12.2 11.45c.1.93-.78 1.32-.78 2.22a.78.78 0 1 0 1.56 0c0-.74-.3-1.35-.78-2.22Z" fill="#fff1c1"/></svg></span>';
        function earn_emodeBadge(active) {
            return active
                ? `<span class="earn-hf-emode-inline" data-tip="${EARN_EMODE_TIP}">${EARN_EMODE_ICON}E-Mode</span>`
                : '';
        }

        function earn_emodeCell(active) {
            return earn_emodeBadge(active) || '<span class="earn-emode-empty">—</span>';
        }

        function earn_formatUSD(n) {
            if (n === null || n === undefined) return '—';
            const value = Number(n);
            if (!Number.isFinite(value)) return '—';
            const sign = value < 0 ? '-' : '';
            const abs = Math.abs(value);
            if (abs >= 999_500_000) return sign + '$' + (abs / 1_000_000_000).toFixed(2) + 'B';
            if (abs >= 999_500) return sign + '$' + (abs / 1_000_000).toFixed(2) + 'M';
            if (abs >= 1_000) return sign + '$' + (abs / 1_000).toFixed(2) + 'K';
            return sign + '$' + abs.toFixed(abs >= 1 ? 2 : 4);
        }

        function earn_formatUSDOneDecimal(n) {
            if (n === null || n === undefined) return '—';
            const value = Number(n);
            if (!Number.isFinite(value)) return '—';
            const sign = value < 0 ? '-' : '';
            const abs = Math.abs(value);
            if (abs >= 999_500_000) return sign + '$' + (abs / 1_000_000_000).toFixed(1) + 'B';
            if (abs >= 999_500) return sign + '$' + (abs / 1_000_000).toFixed(1) + 'M';
            if (abs >= 1_000) return sign + '$' + (abs / 1_000).toFixed(1) + 'K';
            return sign + '$' + abs.toFixed(1);
        }

        function earn_formatUSDExact(n) {
            if (n === null || n === undefined) return '—';
            const value = Number(n);
            if (!Number.isFinite(value)) return '—';
            const sign = value < 0 ? '-' : '';
            const abs = Math.abs(value);
            const digits = abs >= 1 ? 2 : 4;
            return sign + '$' + abs.toLocaleString('en-US', {
                minimumFractionDigits: digits,
                maximumFractionDigits: digits
            });
        }

        function earn_formatUSDCompact(n) {
            if (n === null || n === undefined) return '';
            const value = Number(n);
            if (!Number.isFinite(value)) return '';
            const sign = value < 0 ? '-' : '';
            const abs = Math.abs(value);
            if (abs >= 999_500_000) return sign + '$' + (abs / 1_000_000_000).toFixed(1) + 'B';
            if (abs >= 999_500) return sign + '$' + (abs / 1_000_000).toFixed(1) + 'M';
            if (abs >= 1_000) return sign + '$' + (abs / 1_000).toFixed(1) + 'K';
            if (abs >= 1) return sign + '$' + abs.toFixed(0);
            return sign + '$' + abs.toFixed(2);
        }

        function earnTokenIconFrameClass(symbol) {
            return /^(?:wstETH|ylstETH|(?:d?PT|d?YT)-|gm(?!x$)|dGM(?:$|[-\s])|d?GLV|(?:m|plv|dplv|dfs|magic|s)GLP)/i.test(String(symbol || '').trim()) ? ' full-logo' : '';
        }

        function earn_renderTokenPills(tokens) {
            if (!tokens || tokens.length === 0) return '<span style="color:var(--text-muted)">—</span>';
            return tokens.map(t => {
                const icon = SYMBOL_ICONS[t.symbol] || SYMBOL_ICONS[(t.symbol || '').toUpperCase()];
                const safeSym = earn_escapeHtml(t.symbol || '?');   // subgraph/onchain symbol → innerHTML
                const iconHtml = icon
                    ? `<span class="earn-token-pill-icon${earnTokenIconFrameClass(t.symbol)}"><img src="${icon}" alt="${safeSym}" onerror="this.parentElement.textContent='${String(t.symbol || '?').replace(/[^A-Za-z0-9]/g, '').slice(0, 2) || '?'}'"></span>`
                    : '';
                const sym = (t.symbol || '?');
                const short = sym.length > 12 ? sym.slice(0, 10) + '…' : sym;
                return `<span class="earn-token-pill">${iconHtml}${earn_escapeHtml(short)}<span class="earn-token-pill-usd">${earn_formatUSDCompact(t.usd)}</span></span>`;
            }).join('');
        }

        function earn_buildReplayFallbackLendingPositions() {
            const chainId = document.getElementById('earn-chain')?.value || 'ethereum';
            const collateralTokens = [];
            const debtTokens = [];
            const accruedCollateral = [];
            const accruedDebt = [];
            let totalAccruedYield = 0;
            let totalAccruedCost = 0;

            (earn_collateralPositionData || []).forEach(item => {
                const usd = Math.abs(Number(item.usdValue || 0));
                if (!(usd > 0)) return;
                collateralTokens.push({
                    symbol: earn_escapeHtml(item.symbol || '?'),   // subgraph symbol → innerHTML downstream
                    usd,
                });
                const calc = earn_calculateYield(item, { requireVerifiedInterest: false });
                const openYieldRaw = calc && calc.openCollateralYield !== undefined
                    ? BigInt(calc.openCollateralYield || 0)
                    : 0n;
                const accruedUsd = earn_scaledUsdToNumber(
                    earn_getTokenUsdScaled(openYieldRaw, item.decimals, item.symbol, item.tokenAddr, chainId)
                );
                if (Math.abs(accruedUsd) > 0.0001) {
                    accruedCollateral.push({
                        symbol: earn_escapeHtml(item.symbol || '?'),
                        accruedUSD: accruedUsd,
                    });
                    totalAccruedYield += accruedUsd;
                }
            });

            (earn_borrowPositionData || []).forEach(item => {
                const usd = Math.abs(Number(item.usdValue || 0));
                if (!(usd > 0)) return;
                debtTokens.push({
                    symbol: earn_escapeHtml(item.symbol || '?'),   // subgraph symbol → innerHTML downstream
                    usd,
                });
                const calc = earn_calculateYield(item, { requireVerifiedInterest: false });
                const openBorrowRaw = calc && calc.openBorrowYield !== undefined
                    ? BigInt(calc.openBorrowYield || 0)
                    : 0n;
                const openBorrowCostRaw = openBorrowRaw < 0n ? -openBorrowRaw : openBorrowRaw;
                const accruedUsd = earn_scaledUsdToNumber(
                    earn_getTokenUsdScaled(openBorrowCostRaw, item.decimals, item.symbol, item.tokenAddr, chainId)
                );
                if (Math.abs(accruedUsd) > 0.0001) {
                    accruedDebt.push({
                        symbol: earn_escapeHtml(item.symbol || '?'),
                        accruedUSD: accruedUsd,
                    });
                    totalAccruedCost += accruedUsd;
                }
            });

            if (collateralTokens.length === 0 && debtTokens.length === 0) return [];

            const collateralUSD = collateralTokens.reduce((sum, item) => sum + item.usd, 0);
            const debtUSD = debtTokens.reduce((sum, item) => sum + item.usd, 0);

            return [{
                accountNumber: 'replay-fallback',
                healthFactor: null,
                collateralUSD,
                debtUSD,
                collateralTokens,
                debtTokens,
                accruedCollateral,
                accruedDebt,
                totalAccruedYield,
                totalAccruedCost,
                totalExternalRewardsUSD: 0,
                netAccrued: totalAccruedYield - totalAccruedCost,
                externalRewards: [],
                eMode: false,
                openTimestamp: 0,
                replayFallback: true,
            }];
        }

        function earn_getOpenRouteYieldForAccount(accountNumber, marketId) {
            const account = String(accountNumber === undefined || accountNumber === null ? '0' : accountNumber);
            const mid = earn_normalizeMarketId(marketId);
            if (!mid || !earn_replayAccountStateData) return null;
            const state = earn_replayAccountStateData[`${account}|${mid}`];
            if (!state) return null;
            const par = BigInt(state.par || '0');
            if (par <= 0n) return null;
            return BigInt(state.liveYield || '0');
        }

        function earn_getOpenDebtYieldForAccount(accountNumber, marketId) {
            const account = String(accountNumber === undefined || accountNumber === null ? '0' : accountNumber);
            const mid = earn_normalizeMarketId(marketId);
            if (!mid || !earn_replayAccountStateData) return null;
            const state = earn_replayAccountStateData[`${account}|${mid}`];
            if (!state) return null;
            const par = BigInt(state.par || '0');
            if (par >= 0n) return null;
            return BigInt(state.liveYield || '0');
        }

        async function earn_fetchAndRenderLendingPositions(opts) {
            opts = opts || {};
            const runId = opts.runId;
            const section = document.getElementById('earn-lending-section');
            const tbody = document.getElementById('earn-lending-tbody');
            const countEl = document.getElementById('earn-lending-count');
            if (!section || !tbody) return;
            if (!earn_isLookupRunCurrent(runId)) return null;

            // Prefer the address/chain captured when the lookup started (passed via opts)
            // over re-reading the DOM here — the input may have been edited mid-flight,
            // which previously interpolated a half-typed address straight into GraphQL.
            const addr = (opts.addr != null ? String(opts.addr) : document.getElementById('earn-address').value.trim()).toLowerCase();
            const chainName = earn_getChain().name.toLowerCase();

            // Map chain name to chain key used in liquidation_risk.json
            const chainKeyMap = {
                'ethereum': 'ethereum',
                'berachain': 'berachain',
                'arbitrum': 'arbitrum',
                'mantle': 'mantle',
                'polygon zkevm': 'polygon_zkevm',
                'x layer': 'xlayer',
            };
            const chainKey = chainKeyMap[chainName] || chainName;
            const chainId = opts.chainId != null ? String(opts.chainId) : document.getElementById('earn-chain').value;
            const sgEndpoint = SUBGRAPH_ENDPOINTS[chainId];

            try {
                const currentAccounts = await earn_fetchCurrentAccountsFromSubgraph(addr).catch(() => null);
                if (!earn_isLookupRunCurrent(runId)) return null;
                if (currentAccounts && sgEndpoint) {
                    const hasCurrentBorrow = currentAccounts.positions.some(position =>
                        BigInt(position.par || '0') < 0n || BigInt(position.wei || '0') < 0n
                    );
                    if (!hasCurrentBorrow) {
                        earn_lendingPositions = [];
                        section.style.display = 'none';
                        earn_updateSummaryDebt([]);
                        return [];
                    }
                }

                // Fire the wallet risk shard, subgraph queries, and rewards in parallel.
                const liqRiskPromise = earn_fetchLiqRiskForWallet(chainKey, addr);
                const merklPromise = earn_fetchMerklRewards(addr, chainId);
                const odoloMetaPromise = earn_fetchOdoloMetadata();
                // Chain-specific reward fetches (run in parallel, results stored in globals)
                const rewardFetches = [];
                if (chainId === 'berachain') rewardFetches.push(earn_fetchIBGTRewards(addr).catch(() => null));
                if (chainId === 'arbitrum') rewardFetches.push(earn_fetchDGMXRewards(addr).catch(() => null));
                const sgPromise = (sgEndpoint ? Promise.all([
                    earn_subgraphQuery(sgEndpoint,
                        `{ borrowPositions(first: 100, where: { effectiveUser: "${addr}", status: "OPEN" }) { marginAccount { accountNumber } openTimestamp amounts { token { id marketId symbol decimals } amountPar } } }`
                    ),
                    earn_subgraphQuery(sgEndpoint,
                        `{ interestIndexes(first: 1000) { id supplyIndex borrowIndex } }`
                    ),
                    // Also fetch total market supply for oDOLO proportional calc
                    earn_subgraphQuery(sgEndpoint,
                        `{ dolomiteMargins(first: 1) { id supplyLiquidityUSD } tokens(first: 100) { id marketId symbol decimals supplyLiquidity } }`
                    ),
                // .catch here so an early return (e.g. no positions — the common case) cannot
                // leave this Promise.all unobserved and trigger an unhandledrejection.
                ]) : Promise.resolve(null)).catch(() => null);

                const data = await liqRiskPromise;
                if (!earn_isLookupRunCurrent(runId)) return null;
                if (!data) {
                    const replayFallbackPositions = earn_buildReplayFallbackLendingPositions();
                    earn_lendingPositions = replayFallbackPositions;
                    if (replayFallbackPositions.length > 0) {
                        countEl.textContent = replayFallbackPositions.length;
                        section.style.display = '';
                        earn_reRenderLendingRows();
                        earn_updateSummaryDebt(replayFallbackPositions);
                        return replayFallbackPositions;
                    }
                    section.style.display = 'none';
                    return;
                }
                const positions = (data.positions || []).filter(p =>
                    p.address.toLowerCase() === addr && p.chain.toLowerCase() === chainKey
                );

                earn_lendingPositions = positions;

                if (positions.length === 0) {
                    const replayFallbackPositions = earn_buildReplayFallbackLendingPositions();
                    if (replayFallbackPositions.length > 0) {
                        earn_lendingPositions = replayFallbackPositions;
                        countEl.textContent = replayFallbackPositions.length;
                        section.style.display = '';
                        earn_reRenderLendingRows();
                        earn_updateSummaryDebt(replayFallbackPositions);
                        return replayFallbackPositions;
                    }
                    section.style.display = 'none';
                    earn_updateSummaryDebt([]);
                    return;
                }

                countEl.textContent = positions.length;
                section.style.display = '';

                // ═══ ENRICH with subgraph data (par values + interest indexes) ═══
                const sgResult = await sgPromise;
                if (!earn_isLookupRunCurrent(runId)) return null;
                // Await external rewards data
                const merklData = await merklPromise;
                if (!earn_isLookupRunCurrent(runId)) return null;
                earn_merklRewards = merklData;
                earn_merklRewardsLoaded = true;
                const odoloMeta = await odoloMetaPromise;
                if (!earn_isLookupRunCurrent(runId)) return null;
                earn_odoloMeta = odoloMeta;
                await Promise.allSettled(rewardFetches); // ensure iBGT/dGMX data is populated
                if (!earn_isLookupRunCurrent(runId)) return null;

                if (sgResult) {
                    const [bpData, ixData, marketData] = sgResult;
                    try {

                        // Build interest index lookup (keyed by token address)
                        const indexMap = {};
                        (ixData.interestIndexes || []).forEach(r => {
                            indexMap[r.id.toLowerCase()] = {
                                supplyIdx: parseFloat(r.supplyIndex) || 1,
                                borrowIdx: parseFloat(r.borrowIndex) || 1,
                            };
                        });

                        // Build total supply per token for oDOLO proportional calc
                        const totalSupplyByToken = {};
                        if (marketData && marketData.tokens) {
                            marketData.tokens.forEach(t => {
                                const addr = (t.id || '').toLowerCase();
                                const supply = parseFloat(t.supplyLiquidity || '0');
                                if (addr && supply > 0) totalSupplyByToken[addr] = supply;
                            });
                        }

                        // Match subgraph positions to liquidation_risk positions by accountNumber
                        const bpByAccount = {};
                        (bpData.borrowPositions || []).forEach(bp => {
                            const accNum = bp.marginAccount?.accountNumber;
                            if (accNum) bpByAccount[accNum] = bp;
                        });

                        const collateralActualByAccount = {};
                        const collateralActualByToken = {};
                        Object.entries(bpByAccount).forEach(([accountNumber, bp]) => {
                            (bp.amounts || []).forEach(amt => {
                                const par = parseFloat(amt.amountPar || '0');
                                if (!(par > 0)) return;
                                const tokenAddr = (amt.token.id || '').toLowerCase();
                                if (!tokenAddr) return;
                                const idx = indexMap[tokenAddr] || { supplyIdx: 1, borrowIdx: 1 };
                                const actualTokens = par * idx.supplyIdx;
                                if (!(actualTokens > 0)) return;
                                if (!collateralActualByAccount[accountNumber]) collateralActualByAccount[accountNumber] = {};
                                collateralActualByAccount[accountNumber][tokenAddr] = (collateralActualByAccount[accountNumber][tokenAddr] || 0) + actualTokens;
                                collateralActualByToken[tokenAddr] = (collateralActualByToken[tokenAddr] || 0) + actualTokens;
                            });
                        });

                        const allocateTokenRewardToPosition = (accountNumber, tokenAddr, totalRewardAmount) => {
                            const accountExposure = collateralActualByAccount[String(accountNumber)] || {};
                            const accountActual = accountExposure[tokenAddr] || 0;
                            const totalActual = collateralActualByToken[tokenAddr] || 0;
                            if (!(accountActual > 0) || !(totalActual > 0) || !(totalRewardAmount > 0)) return 0;
                            return totalRewardAmount * (accountActual / totalActual);
                        };

                        // Prepare oDOLO per-token weekly allocation for this chain
                        const DOLO_CHAIN_IDS_REV = { ethereum: '1', berachain: '80094', arbitrum: '42161', mantle: '5000' };
                        const odoloChainKey = DOLO_CHAIN_IDS_REV[chainId] || '';
                        const odoloWeights = (earn_odoloMeta && earn_odoloMeta.allChainWeights && earn_odoloMeta.allChainWeights[odoloChainKey]) || {};
                        const odoloEpochStart = earn_odoloMeta ? (earn_odoloMeta.odoloStartTimestamp || 0) : 0;
                        const odoloEpochDuration = 604800; // 7 days in seconds
                        const DOLO_PRICE = earn_priceCache[chainId + ':0x0f81001ef0a83ecce5ccebf63eb302c70a39a654'] || TOKEN_USD_FALLBACK['DOLO'] || 0.03;
                        // Addresses blacklisted from oDOLO rewards (e.g. WLFI — confirmed by Dolomite team)
                        const ODOLO_BLACKLIST = new Set([
                            '0x5be9a4959308a0d0c7bc0870e319314d8d957dbb', // World Liberty Financial
                        ]);
                        const isOdoloBlacklisted = ODOLO_BLACKLIST.has(addr.toLowerCase());

                        // Enrich each position with accrued interest data
                        for (const p of positions) {
                            const bp = bpByAccount[p.accountNumber];
                            if (!bp) continue;

                            p.openTimestamp = parseInt(bp.openTimestamp) || 0;
                            p.accruedCollateral = []; // { symbol, accruedTokens, accruedUSD }
                            p.accruedDebt = [];       // { symbol, accruedTokens, accruedUSD }
                            p.externalRewards = [];   // { symbol, amount, usd, apr, claimUrl, source, assetSymbol }
                            const seenRewardTokens = new Set();

                            for (const amt of (bp.amounts || [])) {
                                const par = parseFloat(amt.amountPar || '0');
                                if (par === 0) continue;
                                const tokenAddr = (amt.token.id || '').toLowerCase();
                                const symbol = amt.token.symbol || '?';
                                const decimals = parseInt(amt.token.decimals) || 18;
                                const idx = indexMap[tokenAddr] || { supplyIdx: 1, borrowIdx: 1 };

                                // Get USD price from earn_priceCache or TOKEN_USD_FALLBACK
                                const priceKey = chainId + ':' + tokenAddr;
                                const price = earn_priceCache[priceKey] || TOKEN_USD_FALLBACK[symbol] || 0;

                                if (par > 0) {
                                    // Collateral yield should match the replay ledger for this
                                    // account/market. The raw index delta is market-level math and
                                    // can overstate user yield for routed collateral.
                                    const actualTokens = par * idx.supplyIdx;
                                    const replayOpenYieldWei = earn_getOpenRouteYieldForAccount(p.accountNumber, amt.token.marketId);
                                    const accruedTokens = replayOpenYieldWei !== null
                                        ? earn_bigIntToDecimalNumber(replayOpenYieldWei, decimals)
                                        : 0;
                                    const accruedUSD = accruedTokens * price;
                                    if (replayOpenYieldWei !== null && Math.abs(accruedUSD) > 0.0001) {
                                        p.accruedCollateral.push({
                                            symbol, accruedTokens, accruedUSD,
                                            parTokens: par, actualTokens, decimals, price, index: idx.supplyIdx,
                                            tokenAddr: tokenAddr,
                                            source: 'replay-ledger',
                                        });
                                    }

                                    const shouldAllocateTokenRewards = !seenRewardTokens.has(tokenAddr);
                                    if (shouldAllocateTokenRewards) seenRewardTokens.add(tokenAddr);

                                    // === oDOLO reward calc for this collateral token ===
                                    const weeklyOdolo = shouldAllocateTokenRewards ? parseFloat(odoloWeights[tokenAddr] || '0') : 0;
                                    if (weeklyOdolo > 0 && totalSupplyByToken[tokenAddr] && price > 0 && !isOdoloBlacklisted) {
                                        const totalSupply = totalSupplyByToken[tokenAddr];
                                        const positionActualTokens = ((collateralActualByAccount[String(p.accountNumber)] || {})[tokenAddr]) || actualTokens;
                                        const userShare = positionActualTokens / totalSupply;
                                        const openTs = p.openTimestamp || 0;
                                        // Clamp to oDOLO program start
                                        const effectiveStart = Math.max(openTs, odoloEpochStart);
                                        const now = Math.floor(Date.now() / 1000);
                                        const weeksActive = Math.max(0, (now - effectiveStart) / odoloEpochDuration);
                                        const estOdolo = userShare * weeklyOdolo * weeksActive;
                                        if (estOdolo > 0.01) {
                                            const rateEntry = earn_marketRates[chainId + ':' + tokenAddr] || earn_marketRates['sym:' + symbol.toUpperCase()];
                                            p.externalRewards.push({
                                                symbol: 'oDOLO', amount: estOdolo,
                                                usd: estOdolo * DOLO_PRICE,
                                                apr: rateEntry ? rateEntry.rewards : 0,
                                                claimUrl: 'https://app.dolomite.io/rewards',
                                                source: 'dolomite',
                                                assetSymbol: symbol,
                                                icon: 'odolo-logo-official.svg',
                                            });
                                        }
                                    }

                                    // === MERKL WLFI reward — exact per-token from API ===
                                    for (const [merklSym, merklData] of (shouldAllocateTokenRewards ? Object.entries(earn_merklRewards) : [])) {
                                        const totalPerTokenAmt = merklData.perToken ? merklData.perToken[tokenAddr] : 0;
                                        const exactPerAccountAmt = merklData.perAccountToken
                                            && merklData.perAccountToken[String(p.accountNumber)]
                                            ? (merklData.perAccountToken[String(p.accountNumber)][tokenAddr] || 0)
                                            : 0;
                                        const assignedPerTokenAmt = merklData.assignedPerToken ? (merklData.assignedPerToken[tokenAddr] || 0) : 0;
                                        const unattributedPerTokenAmt = Math.max(0, totalPerTokenAmt - assignedPerTokenAmt);
                                        const perTokenAmt = exactPerAccountAmt + allocateTokenRewardToPosition(p.accountNumber, tokenAddr, unattributedPerTokenAmt);
                                        if (perTokenAmt > 0.01) {
                                            const merklPrice = earn_getRewardTokenUsdPrice(merklSym, merklData.token, chainId);
                                            const rateEntry = earn_marketRates[chainId + ':' + tokenAddr] || earn_marketRates['sym:' + symbol.toUpperCase()];
                                            const rewardApr = rateEntry && rateEntry.rewardParts
                                                ? (rateEntry.rewardParts.find(rp => rp.symbol === merklSym) || {}).apr || 0
                                                : 0;
                                            p.externalRewards.push({
                                                symbol: merklSym, amount: perTokenAmt,
                                                usd: perTokenAmt * merklPrice,
                                                apr: rewardApr * 100,
                                                claimUrl: 'https://app.merkl.xyz/',
                                                source: 'merkl',
                                                assetSymbol: symbol,
                                                icon: SYMBOL_ICONS[merklSym] || SYMBOL_ICONS[merklSym.toUpperCase()] || '',
                                            });
                                        }
                                    }

                                    // === iBGT staking rewards for diBGT collateral positions ===
                                    if (earn_ibgtRewards && earn_ibgtRewards.rewards.length > 0 && symbol === 'diBGT') {
                                        const ibgtPrice = earn_priceCache[chainId + ':' + IBGT_CONTRACTS.DIBGT_FACTORY.toLowerCase()]
                                            || earn_priceCache[chainId + ':0xac03caba51e17c86c921e1f6cbfbdc91f8bb2e6b']
                                            || TOKEN_USD_FALLBACK['iBGT'] || 4;
                                        for (const reward of earn_ibgtRewards.rewards) {
                                            // Use iBGT price for wiBGT (1:1 wrapper)
                                            const rPrice = reward.symbol === 'wiBGT' ? ibgtPrice
                                                : (earn_priceCache[chainId + ':' + reward.address.toLowerCase()]
                                                    || TOKEN_USD_FALLBACK[reward.symbol] || 0);
                                            p.externalRewards.push({
                                                symbol: reward.symbol,
                                                amount: reward.amount,
                                                usd: reward.amount * rPrice,
                                                apr: 0,
                                                claimUrl: 'https://app.dolomite.io/rewards',
                                                source: 'infrared-ibgt',
                                                icon: SYMBOL_ICONS[reward.symbol] || SYMBOL_ICONS['iBGT'] || '',
                                            });
                                        }
                                    }

                                    // === dGMX staking rewards (WETH + esGMX via dfsGLP vault) ===
                                    if (earn_dgmxRewards && earn_dgmxRewards.staked > 0 && symbol === 'dGMX') {
                                        // Always show staked amount as info even if no pending rewards
                                        if (earn_dgmxRewards.rewards.length > 0) {
                                            for (const reward of earn_dgmxRewards.rewards) {
                                                const rPrice = earn_priceCache[chainId + ':' + reward.address.toLowerCase()]
                                                    || TOKEN_USD_FALLBACK[reward.symbol] || 0;
                                                p.externalRewards.push({
                                                    symbol: reward.symbol,
                                                    amount: reward.amount,
                                                    usd: reward.amount * rPrice,
                                                    apr: 0,
                                                    claimUrl: 'https://app.dolomite.io/balances',
                                                    source: 'gmx-staking',
                                                    icon: SYMBOL_ICONS[reward.symbol] || SYMBOL_ICONS['GMX'] || '',
                                                });
                                            }
                                        }
                                    }
                                } else {
                                    const absPar = Math.abs(par);
                                    const actualTokens = absPar * idx.borrowIdx;
                                    const replayOpenDebtYieldWei = earn_getOpenDebtYieldForAccount(p.accountNumber, amt.token.marketId);
                                    const replayDebtCostWei = replayOpenDebtYieldWei === null
                                        ? null
                                        : (replayOpenDebtYieldWei < 0n ? -replayOpenDebtYieldWei : replayOpenDebtYieldWei);
                                    const accruedTokens = replayDebtCostWei !== null
                                        ? earn_bigIntToDecimalNumber(replayDebtCostWei, decimals)
                                        : Math.max(0, actualTokens - absPar);
                                    const accruedUSD = accruedTokens * price;
                                    if (Math.abs(accruedUSD) > 0.0001) {
                                        p.accruedDebt.push({
                                            symbol, accruedTokens, accruedUSD,
                                            parTokens: absPar, actualTokens, decimals, price, index: idx.borrowIdx,
                                            source: replayDebtCostWei !== null ? 'replay-ledger' : 'index-estimate',
                                        });
                                    }
                                }
                            }

                            // Compute totals (including external rewards)
                            p.totalAccruedYield = p.accruedCollateral.reduce((s, c) => s + c.accruedUSD, 0);
                            p.totalAccruedCost = p.accruedDebt.reduce((s, c) => s + c.accruedUSD, 0);
                            p.totalExternalRewardsUSD = p.externalRewards.reduce((s, r) => s + r.usd, 0);
                            p.netAccrued = p.totalAccruedYield + p.totalExternalRewardsUSD - p.totalAccruedCost;
                        }

                        console.log('Subgraph enrichment: matched', Object.keys(bpByAccount).length, 'positions with par data');
                        if (Object.keys(earn_merklRewards).length > 0) console.log('MERKL rewards:', earn_merklRewards);
                    } catch (e) {
                        console.warn('Subgraph enrichment failed (falling back to estimates):', e);
                    }
                }

                // Sort by health factor ascending (riskiest first)
                positions.sort((a, b) => {
                    const ha = a.healthFactor ?? 999;
                    const hb = b.healthFactor ?? 999;
                    return ha - hb;
                });
                if (!earn_isLookupRunCurrent(runId)) return null;

                tbody.innerHTML = positions.map((p, i) => {
                    const riskClass = earn_getRiskClass(p);
                    const hfDecimals = ['good', 'strong', 'balanced'].includes(riskClass) ? 2 : 4;
                    const hfText = p.healthFactor !== null
                        ? (p.healthFactor > 10 ? '10<' : p.healthFactor.toFixed(hfDecimals))
                        : '—';

                    const emodeCell = earn_emodeCell(p.eMode);

                    const collateralDisplay = p.collateralUSD < 0.01 ? '$0.00' : earn_formatUSD(p.collateralUSD);

                    // Compact token list for merged columns
                    const renderMergedTokens = (tokens) => {
                        if (!tokens || tokens.length === 0) return '';
                        return '<div class="earn-merged-tokens">' + tokens.map(t => {
                            const icon = SYMBOL_ICONS[t.symbol] || SYMBOL_ICONS[(t.symbol || '').toUpperCase()];
                            const safeSym = earn_escapeHtml(t.symbol);   // subgraph/onchain symbol → innerHTML
                            const iconHtml = icon ? `<img src="${icon}" alt="${safeSym}" onerror="this.style.display='none'">` : '';
                            return `<span class="earn-merged-token">${iconHtml}${safeSym} ${earn_formatUSDCompact(t.usd)}</span>`;
                        }).join('') + '</div>';
                    };

                    // Utilization ratio bar
                    const utilization = p.collateralUSD > 0 ? Math.min(100, (p.debtUSD / p.collateralUSD) * 100) : 0;
                    const ratioBar = `<div class="earn-hf-ratio-bar"><div class="earn-hf-ratio-fill risk-${riskClass}" style="width:${utilization.toFixed(1)}%"></div></div>`;

                    // --- Build detail panel content ---
                    const useApy = typeof earn_showApy !== 'undefined' && earn_showApy;
                    const rateLabel = useApy ? 'APY' : 'APR';

                    // Collateral earnings breakdown
                    let totalAnnualYield = 0;
                    const collateralRows = (p.collateralTokens || []).map(t => {
                        const rate = earn_getTokenRate(t.symbol, 'supply');
                        const displayRate = useApy && rate > 0 ? aprToApy(rate) : rate;
                        const annualYield = (t.usd || 0) * (rate / 100);
                        totalAnnualYield += annualYield;
                        const icon = SYMBOL_ICONS[t.symbol] || SYMBOL_ICONS[(t.symbol || '').toUpperCase()];
                        const iconHtml = icon ? `<img src="${icon}" alt="${t.symbol}" onerror="this.style.display='none'">` : '';
                        return `<div class="earn-lend-token-row">
                            <span class="earn-lend-token-left">${iconHtml}${t.symbol} <span style="color:rgba(255,255,255,0.3)">${earn_formatUSDCompact(t.usd)}</span></span>
                            <span><span class="earn-lend-token-apr supply">${displayRate > 0 ? displayRate.toFixed(2) + '% ' + rateLabel : '—'}</span><span class="earn-lend-token-annual">${annualYield > 0.01 ? '+' + earn_formatUSD(annualYield) + '/yr' : ''}</span></span>
                        </div>`;
                    }).join('');

                    // Debt cost breakdown
                    let totalAnnualCost = 0;
                    const debtRows = (p.debtTokens || []).map(t => {
                        const rate = earn_getTokenRate(t.symbol, 'borrow');
                        const displayRate = useApy && rate > 0 ? aprToApy(rate) : rate;
                        const annualCost = (t.usd || 0) * (rate / 100);
                        totalAnnualCost += annualCost;
                        const icon = SYMBOL_ICONS[t.symbol] || SYMBOL_ICONS[(t.symbol || '').toUpperCase()];
                        const iconHtml = icon ? `<img src="${icon}" alt="${t.symbol}" onerror="this.style.display='none'">` : '';
                        return `<div class="earn-lend-token-row">
                            <span class="earn-lend-token-left">${iconHtml}${t.symbol} <span style="color:rgba(255,255,255,0.3)">${earn_formatUSDCompact(t.usd)}</span></span>
                            <span><span class="earn-lend-token-apr borrow">${displayRate > 0 ? displayRate.toFixed(2) + '% ' + rateLabel : '—'}</span><span class="earn-lend-token-annual">${annualCost > 0.01 ? '-' + earn_formatUSD(annualCost) + '/yr' : ''}</span></span>
                        </div>`;
                    }).join('');

                    // Net P&L
                    const netAnnual = totalAnnualYield - totalAnnualCost;
                    const netPositive = netAnnual >= 0;
                    const netSign = netPositive ? '+' : '-';
                    const netApr = p.collateralUSD > 0 ? (netAnnual / p.collateralUSD) * 100 : 0;
                    const displayNetApr = useApy && Math.abs(netApr) > 0.01 ? aprToApy(Math.abs(netApr)) : Math.abs(netApr);

                    // Age badge for collapsed row
                    const ageBadge = p.openTimestamp ? `<span class="earn-age-badge">${earn_formatAge(p.openTimestamp).replace('Opened ', '')}</span>` : '';

                    // Inline Net P&L for 4th column
                    const pnlValue = p.netAccrued !== undefined ? p.netAccrued : null;
                    const pnlClass = pnlValue !== null ? (pnlValue >= 0 ? 'positive' : 'negative') : 'neutral';
                    const pnlDisplay = pnlValue !== null && Math.abs(pnlValue) > 0.01
                        ? `${pnlValue >= 0 ? '+' : '-'}${earn_formatUSDOneDecimal(Math.abs(pnlValue))}`
                        : '—';
                    const annualDisplay = Math.abs(netAnnual) > 0.01
                        ? `<div class="earn-net-sub-inline">${netSign}${earn_formatUSDOneDecimal(Math.abs(netAnnual))}/yr</div>`
                        : '';

                    const dataRow = `<tr class="earn-lend-row risk-${riskClass}" data-idx="${i}" data-earn-layout-row onclick="earn_toggleLendDetail(${i})" style="animation-delay:${i * 0.08}s">
                        <td data-column="health">
                            <span class="earn-hf-badge ${riskClass}"><span class="earn-hf-dot ${riskClass}"></span>${hfText}</span>${ageBadge}
                            ${ratioBar}
                        </td>
                        <td data-column="emode" class="earn-emode-cell">${emodeCell}</td>
                        <td data-column="collateral"><div class="earn-merged-col"><span class="earn-usd-collateral">${collateralDisplay}</span>${renderMergedTokens(p.collateralTokens)}</div></td>
                        <td data-column="debt"><div class="earn-merged-col"><span class="earn-usd-debt">${earn_formatUSD(p.debtUSD)}</span>${renderMergedTokens(p.debtTokens)}</div></td>
                        <td data-column="pnl"><div class="earn-net-inline ${pnlClass}">${pnlDisplay}</div>${annualDisplay}</td>
                        <td data-column="details" class="earn-details-cell">${earn_renderDetailsButton(`earn_toggleLendDetail(${i})`)}</td>
                    </tr>`;

                    const detailRow = `<tr class="earn-lend-detail" id="earn-lend-detail-${i}" data-earn-layout-detail>
                        <td colspan="6">
                            <div class="earn-lend-detail-inner">
                                <div class="earn-lend-section">
                                    <div class="earn-lend-section-title earn">Collateral Yield</div>
                                    ${collateralRows || '<div style="color:var(--text-muted);font-size:11px">No collateral</div>'}
                                    ${(p.accruedCollateral && p.accruedCollateral.length > 0) ? `<div style="border-top:1px solid rgba(52,211,153,0.1);margin-top:8px;padding-top:8px">
                                        <div class="earn-accrued-label">Open Route Yield</div>
                                        ${p.accruedCollateral.map(c => {
                        const icon = SYMBOL_ICONS[c.symbol] || SYMBOL_ICONS[(c.symbol || '').toUpperCase()];
                        const iconHtml = icon ? `<img src="${icon}" alt="${c.symbol}" onerror="this.style.display='none'">` : '';
                        const routeYieldSign = c.accruedUSD >= 0 ? '+' : '-';
                        const routeYieldClass = c.accruedUSD >= 0 ? 'supply' : 'borrow';
                        return `<div class="earn-lend-token-row"><span class="earn-lend-token-left">${iconHtml}${c.symbol} <span style="color:rgba(52,211,153,0.5)">open route</span></span><span class="earn-lend-token-apr ${routeYieldClass}">${routeYieldSign}${earn_formatUSD(Math.abs(c.accruedUSD))}</span></div>`;
                    }).join('')}
                                    </div>` : ''}
                                </div>
                                ${(p.externalRewards && p.externalRewards.length > 0) ? `<div class="earn-lend-section">
                                    <div class="earn-lend-section-title rewards">External Rewards</div>
                                    ${p.externalRewards.map(r => {
                        const rewardSymbol = earn_escapeHtml(r.symbol || 'Reward');
                        const iconHtml = r.icon ? `<img src="${earn_escapeHtml(r.icon)}" alt="${rewardSymbol}" onerror="this.style.display='none'">` : '';
                        const claimHtml = r.claimUrl ? `<a href="${earn_escapeHtml(r.claimUrl)}" target="_blank" class="earn-reward-claim-link" onclick="event.stopPropagation()">Claim ↗</a>` : '';
                        const aprHtml = r.apr > 0 ? `<span class="earn-lend-token-annual" style="color:rgba(251,191,36,0.6)">${r.apr.toFixed(2)}% APR</span>` : '';
                        const assetHint = r.assetSymbol ? `<span class="earn-lend-token-source">For ${earn_escapeHtml(r.assetSymbol)}</span>` : '';
                        return `<div class="earn-lend-token-row"><span class="earn-lend-token-left">${iconHtml}<span class="earn-lend-token-stack"><span class="earn-lend-token-main">${rewardSymbol}${claimHtml}</span>${assetHint}</span></span><span><span class="earn-lend-token-apr rewards">+${r.amount >= 1000 ? (r.amount / 1000).toFixed(2) + 'K' : r.amount.toFixed(2)}</span><span class="earn-lend-token-annual" style="color:rgba(251,191,36,0.5)"> ~${earn_formatUSD(r.usd)}</span>${aprHtml}</span></div>`;
                    }).join('')}
                                    <div style="border-top:1px solid rgba(251,191,36,0.08);margin-top:6px;padding-top:4px">
                                        <div class="earn-lend-token-row"><span class="earn-lend-token-left" style="color:rgba(251,191,36,0.7);font-weight:600">Total Rewards</span><span class="earn-lend-token-apr rewards">+${earn_formatUSD(p.totalExternalRewardsUSD)}</span></div>
                                    </div>
                                </div>` : ''}
                                <div class="earn-lend-section">
                                    <div class="earn-lend-section-title cost">Borrow Costs</div>
                                    ${debtRows || '<div style="color:var(--text-muted);font-size:11px">No debt</div>'}
                                    ${(p.accruedDebt && p.accruedDebt.length > 0) ? `<div style="border-top:1px solid rgba(248,113,113,0.1);margin-top:8px;padding-top:8px">
                                        <div class="earn-accrued-label">Accrued Interest</div>
                                        ${p.accruedDebt.map(c => {
                        const icon = SYMBOL_ICONS[c.symbol] || SYMBOL_ICONS[(c.symbol || '').toUpperCase()];
                        const iconHtml = icon ? `<img src="${icon}" alt="${c.symbol}" onerror="this.style.display='none'">` : '';
                        return `<div class="earn-lend-token-row"><span class="earn-lend-token-left">${iconHtml}${c.symbol} <span style="color:rgba(248,113,113,0.5)">accrued</span></span><span class="earn-lend-token-apr borrow">-${earn_formatUSD(c.accruedUSD)}</span></div>`;
                    }).join('')}
                                    </div>` : ''}
                                </div>
                                <div class="earn-lend-section">
                                    ${(p.netAccrued !== undefined) ? `
                                        <div class="earn-lend-section-title net">Accrued P&L</div>
                                        <div class="earn-lend-net-value ${p.netAccrued >= 0 ? 'positive' : 'negative'}">${p.netAccrued >= 0 ? '+' : '-'}${earn_formatUSD(Math.abs(p.netAccrued))}<span style="font-size:11px;font-weight:400;color:rgba(255,255,255,0.4)"> total</span></div>
                                        <div class="earn-lend-net-sub">Open route ${earn_formatUSD(p.totalAccruedYield || 0)}${p.totalExternalRewardsUSD > 0.01 ? ' + <span style="color:#fbbf24">Rewards ' + earn_formatUSD(p.totalExternalRewardsUSD) + '</span>' : ''} − Borrow ${earn_formatUSD(p.totalAccruedCost || 0)}</div>
                                        ${p.openTimestamp ? `<div class="earn-lend-net-sub" style="margin-top:4px">Opened ${earn_formatAge(p.openTimestamp)}</div>` : ''}
                                        <div style="border-top:1px solid rgba(255,255,255,0.05);margin-top:8px;padding-top:6px">
                                            <div class="earn-lend-net-sub" style="margin-bottom:2px">Est. annual at current rates:</div>
                                            <div class="earn-lend-net-apr ${netPositive ? 'positive' : 'negative'}">${netSign}${earn_formatUSD(Math.abs(netAnnual))}/yr <span style="font-weight:400">(${netSign}${displayNetApr.toFixed(2)}% net ${rateLabel})</span></div>
                                        </div>
                                    ` : `
                                        <div class="earn-lend-section-title net">Net Position (Annual Est.)</div>
                                        <div class="earn-lend-net-value ${netPositive ? 'positive' : 'negative'}">${netSign}${earn_formatUSD(Math.abs(netAnnual))}<span style="font-size:11px;font-weight:400;color:rgba(255,255,255,0.4)"> / year</span></div>
                                        <div class="earn-lend-net-apr ${netPositive ? 'positive' : 'negative'}">${netSign}${displayNetApr.toFixed(2)}% net ${rateLabel}</div>
                                        <div class="earn-lend-net-sub">Yield ${earn_formatUSD(totalAnnualYield)} − Cost ${earn_formatUSD(totalAnnualCost)}</div>
                                    `}
                                </div>
                                <div class="earn-net-summary-bar">
                                    <div class="earn-net-summary-item"><span class="earn-net-summary-label">Earn</span><span class="earn-net-summary-value ${totalAnnualYield > 0.01 ? 'positive' : 'neutral'}">${totalAnnualYield > 0.01 ? '+' : ''}${earn_formatUSD(totalAnnualYield)}/yr</span></div>
                                    <div class="earn-net-summary-divider"></div>
                                    <div class="earn-net-summary-item"><span class="earn-net-summary-label">Cost</span><span class="earn-net-summary-value ${totalAnnualCost > 0.01 ? 'negative' : 'neutral'}">${totalAnnualCost > 0.01 ? '-' : ''}${earn_formatUSD(totalAnnualCost)}/yr</span></div>
                                    <div class="earn-net-summary-divider"></div>
                                    <div class="earn-net-summary-item"><span class="earn-net-summary-label">Net</span><span class="earn-net-summary-value ${netPositive ? 'positive' : 'negative'}">${netSign}${earn_formatUSD(Math.abs(netAnnual))}/yr</span></div>
                                </div>
                            </div>
                        </td>
                    </tr>`;

                    return dataRow + detailRow;
                }).join('');

                // Update summary card with accurate Total Debt from liquidation_risk.json
                earn_updateSummaryDebt(positions);

                console.log(`Lending positions: ${positions.length} accounts for ${addr} on ${chainKey}`);
            } catch (e) {
                console.warn('Failed to fetch lending positions:', e);
                section.style.display = 'none';
            }
        }


        // Central layout manager for summary cards — adapts grid to card count
        function earn_updateSummaryCardLayout(el) {
            if (!el) el = document.getElementById('earn-summary-card');
            if (!el) return;
            const n = el.querySelectorAll('.earn-summary-stat').length;
            el.classList.remove('cols-6', 'cols-8');
            if (n >= 8) el.classList.add('cols-8');
            else if (n >= 6) el.classList.add('cols-6');
        }

        function earn_updateSummaryDebt(positions) {
            const summaryEl = document.getElementById('earn-summary-card');
            if (!summaryEl) return;

            const totalDebt = positions.reduce((s, p) => s + (p.debtUSD || 0), 0);
            const totalCollateral = positions.reduce((s, p) => s + (p.collateralUSD || 0), 0);
            const visibleDustThreshold = earn_showDust ? 0 : 1;
            const activeCount = (earn_cachedAssets || []).filter(a => !a.isBorrow && !a.isCollateral && a.usdValue >= visibleDustThreshold).length;
            const totalSupplyUsd = (earn_cachedAssets || []).filter(a => !a.isBorrow && !a.isCollateral).reduce((s, a) => s + (a.usdValue || 0), 0);
            const accruedPositions = positions.filter(p => p.netAccrued !== undefined && p.netAccrued !== null && Number.isFinite(p.netAccrued));
            const totalBorrowRoutePnl = accruedPositions.reduce((sum, p) => sum + (p.netAccrued || 0), 0);
            const hasBorrowPositions = positions.length > 0;
            const totalBorrowRouteAnnual = positions.reduce((sum, p) => {
                const collateralTokens = Array.isArray(p.collateralTokens) ? p.collateralTokens : [];
                const debtTokens = Array.isArray(p.debtTokens) ? p.debtTokens : [];
                const annualYield = collateralTokens.reduce((acc, token) => {
                    const rate = earn_getTokenRate(token.symbol, 'supply');
                    return acc + ((token.usd || 0) * (rate / 100));
                }, 0);
                const annualCost = debtTokens.reduce((acc, token) => {
                    const rate = earn_getTokenRate(token.symbol, 'borrow');
                    return acc + ((token.usd || 0) * (rate / 100));
                }, 0);
                return sum + annualYield - annualCost;
            }, 0);

            const portfolioVal = totalSupplyUsd + totalCollateral - totalDebt;
            const portfolioValueEl = document.getElementById('earn-summary-portfolio-value');
            const portfolioSubEl = document.getElementById('earn-summary-portfolio-sub');
            const supplyChipEl = document.getElementById('earn-summary-supply-chip');
            const borrowChipEl = document.getElementById('earn-summary-borrow-chip');
            if (portfolioValueEl) {
                portfolioValueEl.textContent = earn_formatUSD(portfolioVal);
                portfolioValueEl.setAttribute('data-tip', earn_formatUSDExact(portfolioVal));
                portfolioValueEl.removeAttribute('title');
                portfolioValueEl.className = 'earn-summary-value ' + (portfolioVal > 0 ? 'neutral' : 'negative');
            }
            if (portfolioSubEl) {
                portfolioSubEl.innerHTML = `<span class="sub-highlight">${activeCount}</span> supply · <span style="color:#f87171">${positions.length}</span> borrow`;
            }
            if (supplyChipEl) {
                supplyChipEl.textContent = `${activeCount} supply asset${activeCount !== 1 ? 's' : ''}`;
            }
            if (borrowChipEl) {
                borrowChipEl.textContent = hasBorrowPositions
                    ? `${positions.length} borrow route${positions.length !== 1 ? 's' : ''}`
                    : 'No borrow routes';
                borrowChipEl.className = 'earn-summary-chip ' + (hasBorrowPositions ? '' : 'is-muted');
            }
            const borrowRouteStat = summaryEl.querySelector('.earn-borrow-route-stat');
            const routeVal = document.getElementById('earn-summary-borrow-route-value');
            const routeSub = document.getElementById('earn-summary-borrow-route-sub');
            if (borrowRouteStat && routeVal && routeSub) {
                const keepsOpenRouteYield = routeVal.dataset.openRouteYield === 'true';
                borrowRouteStat.classList.toggle('is-muted', !hasBorrowPositions && !keepsOpenRouteYield);
                if (!keepsOpenRouteYield) {
                    routeVal.textContent = hasBorrowPositions ? String(positions.length) : 'None';
                    routeVal.className = 'earn-summary-value neutral';
                    routeSub.textContent = hasBorrowPositions
                        ? `${positions.length} borrow route${positions.length !== 1 ? 's' : ''} active`
                        : 'No open borrow route';
                }
            }

            const debtStat = summaryEl.querySelector('.earn-debt-stat');
            const debtValueEl = document.getElementById('earn-summary-debt-value');
            const debtSubEl = document.getElementById('earn-summary-debt-sub');
            if (debtStat && debtValueEl && debtSubEl) {
                debtStat.classList.toggle('is-muted', !hasBorrowPositions);
                debtValueEl.textContent = hasBorrowPositions ? `-${earn_formatUSD(totalDebt)}` : '$0.00';
                debtValueEl.className = 'earn-summary-value ' + (hasBorrowPositions && totalDebt > 0.01 ? 'negative' : 'neutral');
                debtSubEl.innerHTML = hasBorrowPositions
                    ? `Against <span class="sub-highlight">${earn_formatUSD(totalCollateral)}</span> collateral`
                    : 'No debt sourced from borrow routes';
            }

            const borrowPnlStat = summaryEl.querySelector('.earn-borrow-pnl-stat');
            const borrowPnlValueEl = document.getElementById('earn-summary-borrow-pnl-value');
            const borrowPnlSubEl = document.getElementById('earn-summary-borrow-pnl-sub');
            const hasAccruedBorrowPnl = accruedPositions.length > 0;
            const borrowPnlPositive = totalBorrowRoutePnl >= 0;
            const borrowPnlValueClass = hasAccruedBorrowPnl
                ? (borrowPnlPositive ? 'positive' : 'negative')
                : 'neutral';
            const borrowPnlValue = hasAccruedBorrowPnl
                ? `${borrowPnlPositive ? '+' : '-'}${earn_formatUSD(Math.abs(totalBorrowRoutePnl))}`
                : '—';
            const borrowAnnualPositive = totalBorrowRouteAnnual >= 0;
            const borrowPnlSub = hasAccruedBorrowPnl
                ? `${borrowAnnualPositive ? '+' : '-'}${earn_formatUSD(Math.abs(totalBorrowRouteAnnual))}/yr at current rates`
                : (hasBorrowPositions ? 'Waiting for borrow route accrual' : 'No open borrow route');
            if (borrowPnlStat && borrowPnlValueEl && borrowPnlSubEl) {
                borrowPnlStat.classList.toggle('is-muted', !hasBorrowPositions);
                borrowPnlValueEl.textContent = hasBorrowPositions ? borrowPnlValue : '—';
                borrowPnlValueEl.className = 'earn-summary-value ' + (hasBorrowPositions ? borrowPnlValueClass : 'neutral');
                borrowPnlSubEl.textContent = borrowPnlSub;
            }

            earn_updateSummaryCardLayout(summaryEl);
        }

        // Format a Unix timestamp as relative age (e.g. "42 days ago")
        // ═══════ Past & routed assets — renders earn_historyData inactive items in Earn-row UX ═══════
        function earn_renderWithdrawnAssets() {
            const section = document.getElementById('earn-past-section');
            const tbody = document.getElementById('earn-past-tbody');
            const countEl = document.getElementById('earn-past-count');
            if (!section || !tbody) return;

            if (!earn_historyData || earn_historyData.length === 0) {
                section.style.display = 'none';
                return;
            }

            // Get active token addresses to exclude
            const activeAddrs = new Set((earn_cachedAssets || []).filter(a => !a.isCollateral).map(a => a.tokenAddr?.toLowerCase()));
            const chainId = document.getElementById('earn-chain').value;

            // Filter to inactive (withdrawn) items only
            const inactiveItems = earn_historyData.filter(item => {
                if (item.isActive) return false;
                if (item.isIsolation && !item.isActive) return false;
                if (activeAddrs.has(item.tokenAddr?.toLowerCase())) return false;
                // Filter dust unless dust filter is off
                const balUsdScaled = earn_getTokenUsdScaled(item.currentWei, item.decimals, item.symbol, item.tokenAddr, chainId);
                const verifiedYieldUsdScaled = item.yieldTrustedForDisplay ? (item.yieldUsdScaled || 0n) : 0n;
                if (!earn_showDust && earn_isSubDollarYieldPair(balUsdScaled, verifiedYieldUsdScaled)) return false;
                return true;
            });

            if (inactiveItems.length === 0) {
                section.style.display = 'none';
                return;
            }

            if (earn_pastSortKey === 'yield') {
                inactiveItems.sort((a, b) => {
                    const aYield = a.yieldTrustedForDisplay ? (a.yieldUsdScaled || 0n) : 0n;
                    const bYield = b.yieldTrustedForDisplay ? (b.yieldUsdScaled || 0n) : 0n;
                    const diff = earn_compareBigInt(aYield, bYield);
                    return earn_pastSortDesc ? -diff : diff;
                });
            } else if (earn_pastSortKey === 'token') {
                inactiveItems.sort((a, b) => {
                    const diff = String(a.symbol || '').localeCompare(String(b.symbol || ''), undefined, { sensitivity: 'base' });
                    return earn_pastSortDesc ? -diff : diff;
                });
            }

            countEl.textContent = inactiveItems.length;
            section.style.display = '';
            earn_openPastDetailIdx = null;
            const explorerBase = earn_getChain().explorer || 'https://etherscan.io';

            earn_updateSortHeaders('.earn-past-table thead th[data-sort]', earn_pastSortKey, earn_pastSortDesc);

            // Render rows in exact Earn-row UX
            tbody.innerHTML = inactiveItems.map((item, i) => {
                // Icon
                let iconHtml;
                if (item.icon) {
                    const _gsF = new Set(['CRV', 'USD0', 'USD0++', 'deUSD', 'sdeUSD', 'MATIC', 'POL', 'stcUSD', 'cUSD', 'USDT', 'cbBTC']).has(item.symbol) ? ' style="filter:grayscale(1) brightness(1.5)"' : '';
                    iconHtml = `<div class="earn-token-icon${earnTokenIconFrameClass(item.symbol)}"><img src="${item.icon}" alt="${item.symbol}"${_gsF} onerror="this.parentElement.textContent='${String(item.symbol || '?').replace(/[^A-Za-z0-9]/g, '').slice(0, 2) || '?'}'"></div>`;
                } else {
                    iconHtml = `<div class="earn-token-icon">${item.symbol.slice(0, 2)}</div>`;
                }

                const yieldCalc = earn_calculateYield({
                    marketId: item.marketId,
                    tokenAddr: item.tokenAddr,
                    symbol: item.symbol,
                    decimals: item.decimals,
                    currentWei: item.currentWei,
                    currentPar: item.currentPar,
                }, { applyHistoryGuards: true });

                const yieldPositive = item.yieldWei >= 0n;
                const yieldSign = yieldPositive && item.yieldWei > 0n ? '+' : '';
                const yieldColor = yieldPositive ? 'earn-yield-positive' : 'earn-yield-negative';
                const yieldFmt = earn_formatAmountOneDecimal(item.yieldWei, item.decimals);
                const yieldUsdSign = item.yieldUsd > 0 ? '+' : (item.yieldUsd < 0 ? '-' : '');
                const yieldUsdStr = Math.abs(item.yieldUsd) >= 0.01
                    ? `<div class="earn-usd-sub" style="color:${yieldPositive ? 'rgba(52,211,153,0.5)' : 'rgba(248,113,113,0.5)'}">${yieldUsdSign}${earn_formatUSDOneDecimal(Math.abs(item.yieldUsd))}</div>`
                    : '';
                const qualityCellHtml = earn_renderSupplyQualityCell(
                    item.marketId,
                    item.symbol,
                    item.decimals,
                    yieldCalc,
                    {
                        positionStatus: item.isCollateralized
                            ? {
                                cls: 'routed',
                                label: 'Routed',
                                title: 'Asset is routed into an open borrow subaccount as collateral, so it is not a withdrawn supply asset.',
                            }
                            : {
                                cls: 'withdrawn',
                                label: 'Exited',
                                title: 'This supply position is no longer active.',
                            },
                    }
                );
                const rowId = `earn-past-row-${i}`;
                const explorerUrl = `${explorerBase}/address/${item.tokenAddr}`;
                const balanceUsdScaled = earn_getTokenUsdScaled(item.currentWei, item.decimals, item.symbol, item.tokenAddr, chainId);
                const balanceUsd = Math.abs(earn_scaledUsdToNumber(balanceUsdScaled));
                const detailPosition = {
                    marketId: item.marketId,
                    tokenAddr: item.tokenAddr,
                    symbol: item.symbol,
                    decimals: item.decimals,
                    wei: item.currentWei,
                    par: item.currentPar,
                    usdValue: balanceUsd,
                };

                let yieldCellHtml;
                if (earn_isTrustedInterestLedgerYieldCalc(yieldCalc)) {
                    yieldCellHtml = `<span class="earn-amount ${yieldColor}">${yieldSign}${yieldFmt}<span class="earn-amount-sym">${item.symbol}</span></span>${yieldUsdStr}`;
                } else {
                    yieldCellHtml = `<span class="earn-amount" style="color:var(--text-muted)">—</span>`;
                }

                const delay = i * 0.05;

                return `<tr class="earn-data-row earn-row-inactive" id="${rowId}" data-earn-layout-row onclick="earn_togglePastDetail(${i})" style="animation-delay:${delay}s">
                    <td data-column="token">
                        <div class="earn-token-cell">
                            <div class="earn-token-left">
                                ${iconHtml}
                                <div class="earn-token-info">
                                    <div class="earn-token-name">${item.symbol}</div>
                                </div>
                            </div>
                        </div>
                    </td>
                    <td data-column="quality">${qualityCellHtml}</td>
                    <td data-column="yield">
                        ${yieldCellHtml}
                    </td>
                    <td data-column="details" class="earn-details-cell">
                        ${earn_renderDetailsButton(`earn_togglePastDetail(${i})`)}
                    </td>
                </tr>${earn_buildSupplyDetailRow(i, detailPosition, yieldCalc, explorerUrl, { idPrefix: 'earn-past', colSpan: 4, includeRewards: false, openBorrowRouteYield: !!item.isCollateralized })}`;
            }).join('');
        }

        function earn_togglePastPositions() {
            const header = document.getElementById('earn-past-toggle');
            const body = document.getElementById('earn-past-body');
            const section = document.getElementById('earn-past-section');
            if (!header || !body) return;
            const nextOpen = !body.classList.contains('open');
            header.classList.toggle('open', nextOpen);
            body.classList.toggle('open', nextOpen);
            if (section) section.classList.toggle('open', nextOpen);
            header.setAttribute('aria-expanded', nextOpen ? 'true' : 'false');
        }

        function earn_handlePastHeaderKey(event) {
            if (!event) return;
            const key = event.key || event.code;
            if (key === 'Enter' || key === ' ' || key === 'Spacebar') {
                event.preventDefault();
                earn_togglePastPositions();
            }
        }

        function earn_toggleEarnSection(sectionKey) {
            const config = {
                supply: {
                    sectionId: 'earn-supply-section',
                    headerSelector: '.earn-supply-header',
                    bodyId: 'earn-supply-body',
                    buttonId: 'earn-supply-collapse'
                },
                lending: {
                    sectionId: 'earn-lending-section',
                    headerSelector: '.earn-lending-header',
                    bodyId: 'earn-lending-body',
                    buttonId: 'earn-lending-collapse'
                }
            }[sectionKey];
            if (!config) return;

            const section = document.getElementById(config.sectionId);
            const header = section ? section.querySelector(config.headerSelector) : null;
            const body = document.getElementById(config.bodyId);
            const button = document.getElementById(config.buttonId);
            if (!section || !header || !body) return;

            const nextOpen = !section.classList.contains('open');
            section.classList.toggle('open', nextOpen);
            header.classList.toggle('open', nextOpen);
            body.classList.toggle('open', nextOpen);
            if (button) button.setAttribute('aria-expanded', nextOpen ? 'true' : 'false');
        }

        function earn_formatAge(timestamp) {
            const now = Math.floor(Date.now() / 1000);
            const diff = now - timestamp;
            if (diff < 3600) return Math.floor(diff / 60) + ' min ago';
            if (diff < 86400) return Math.floor(diff / 3600) + ' hours ago';
            if (diff < 86400 * 30) return Math.floor(diff / 86400) + ' days ago';
            if (diff < 86400 * 365) return Math.floor(diff / (86400 * 30)) + ' months ago';
            return Math.floor(diff / (86400 * 365)) + ' years ago';
        }

        // Get supply or borrow APR for a token symbol from earn_marketRates
        function earn_getTokenRate(symbol, type) {
            if (!symbol) return 0;
            const key = 'sym:' + symbol.toUpperCase().replace(/[^A-Z0-9]/g, '');
            const rate = earn_marketRates[key];
            if (!rate) return 0;
            if (type === 'borrow') return rate.borrowApr || 0;
            return rate.apy || 0; // total supply APR
        }

        // Toggle expandable detail row for borrow positions
        function earn_toggleLendDetail(idx) {
            const detail = document.getElementById('earn-lend-detail-' + idx);
            const row = document.querySelector('.earn-lend-row[data-idx="' + idx + '"]');
            if (!detail || !row) return;

            const isOpen = detail.classList.contains('open');

            // Close all open panels first (accordion)
            document.querySelectorAll('.earn-lend-detail.open').forEach(el => el.classList.remove('open'));
            document.querySelectorAll('.earn-lend-row.open').forEach(el => el.classList.remove('open'));

            // Toggle the clicked one
            if (!isOpen) {
                detail.classList.add('open');
                row.classList.add('open');
            }
        }

        // ═══ Borrow Positions Sort (matches supply table sort pattern) ═══
        let earn_lendSortKey = 'hf';
        let earn_lendSortDesc = false; // HF: ascending (riskiest first) by default

        function earn_sortLendPositions(key) {
            if (!earn_lendingPositions || earn_lendingPositions.length === 0) return;
            if (earn_lendSortKey === key) {
                earn_lendSortDesc = !earn_lendSortDesc;
            } else {
                earn_lendSortKey = key;
                earn_lendSortDesc = (key !== 'hf'); // HF defaults ascending, others descending
            }

            earn_updateSortHeaders('.earn-lending-table thead th[data-sort]', 'lend-' + earn_lendSortKey, earn_lendSortDesc);

            // Sort cached positions
            if (key === 'hf') {
                earn_lendingPositions.sort((a, b) => {
                    const ha = a.healthFactor ?? 999;
                    const hb = b.healthFactor ?? 999;
                    return earn_lendSortDesc ? (hb - ha) : (ha - hb);
                });
            } else if (key === 'collateral') {
                earn_lendingPositions.sort((a, b) => {
                    const diff = (a.collateralUSD || 0) - (b.collateralUSD || 0);
                    return earn_lendSortDesc ? -diff : diff;
                });
            } else if (key === 'emode') {
                earn_lendingPositions.sort((a, b) => {
                    const diff = Number(!!a.eMode) - Number(!!b.eMode);
                    return earn_lendSortDesc ? -diff : diff;
                });
            } else if (key === 'debt') {
                earn_lendingPositions.sort((a, b) => {
                    const diff = (a.debtUSD || 0) - (b.debtUSD || 0);
                    return earn_lendSortDesc ? -diff : diff;
                });
            } else if (key === 'pnl') {
                earn_lendingPositions.sort((a, b) => {
                    const diff = (a.netAccrued || 0) - (b.netAccrued || 0);
                    return earn_lendSortDesc ? -diff : diff;
                });
            }

            // Re-render sorted rows without re-fetching
            earn_reRenderLendingRows();
        }

        function earn_reRenderLendingRows() {
            const tbody = document.getElementById('earn-lending-tbody');
            if (!tbody || !earn_lendingPositions || earn_lendingPositions.length === 0) return;

            const positions = earn_lendingPositions;
            const useApy = typeof earn_showApy !== 'undefined' && earn_showApy;
            const rateLabel = useApy ? 'APY' : 'APR';

            tbody.innerHTML = positions.map((p, i) => {
                const riskClass = earn_getRiskClass(p);
                const hfDecimals = ['good', 'strong', 'balanced'].includes(riskClass) ? 2 : 4;
                const hfText = p.healthFactor !== null
                    ? (p.healthFactor > 10 ? '10<' : p.healthFactor.toFixed(hfDecimals))
                    : '—';

                const emodeCell = earn_emodeCell(p.eMode);

                const collateralDisplay = p.collateralUSD < 0.01 ? '$0.00' : earn_formatUSD(p.collateralUSD);

                const renderMergedTokens = (tokens) => {
                    if (!tokens || tokens.length === 0) return '';
                    return '<div class="earn-merged-tokens">' + tokens.map(t => {
                        const icon = SYMBOL_ICONS[t.symbol] || SYMBOL_ICONS[(t.symbol || '').toUpperCase()];
                        const iconHtml = icon ? `<img src="${icon}" alt="${t.symbol}" onerror="this.style.display='none'">` : '';
                        return `<span class="earn-merged-token">${iconHtml}${t.symbol} ${earn_formatUSDCompact(t.usd)}</span>`;
                    }).join('') + '</div>';
                };

                const utilization = p.collateralUSD > 0 ? Math.min(100, (p.debtUSD / p.collateralUSD) * 100) : 0;
                const ratioBar = `<div class="earn-hf-ratio-bar"><div class="earn-hf-ratio-fill risk-${riskClass}" style="width:${utilization.toFixed(1)}%"></div></div>`;

                // Detail panel content
                let totalAnnualYield = 0;
                const collateralRows = (p.collateralTokens || []).map(t => {
                    const rate = earn_getTokenRate(t.symbol, 'supply');
                    const displayRate = useApy && rate > 0 ? aprToApy(rate) : rate;
                    const annualYield = (t.usd || 0) * (rate / 100);
                    totalAnnualYield += annualYield;
                    const icon = SYMBOL_ICONS[t.symbol] || SYMBOL_ICONS[(t.symbol || '').toUpperCase()];
                    const iconHtml = icon ? `<img src="${icon}" alt="${t.symbol}" onerror="this.style.display='none'">` : '';
                    return `<div class="earn-lend-token-row">
                        <span class="earn-lend-token-left">${iconHtml}${t.symbol} <span style="color:rgba(255,255,255,0.3)">${earn_formatUSDCompact(t.usd)}</span></span>
                        <span><span class="earn-lend-token-apr supply">${displayRate > 0 ? displayRate.toFixed(2) + '% ' + rateLabel : '—'}</span><span class="earn-lend-token-annual">${annualYield > 0.01 ? '+' + earn_formatUSD(annualYield) + '/yr' : ''}</span></span>
                    </div>`;
                }).join('');

                let totalAnnualCost = 0;
                const debtRows = (p.debtTokens || []).map(t => {
                    const rate = earn_getTokenRate(t.symbol, 'borrow');
                    const displayRate = useApy && rate > 0 ? aprToApy(rate) : rate;
                    const annualCost = (t.usd || 0) * (rate / 100);
                    totalAnnualCost += annualCost;
                    const icon = SYMBOL_ICONS[t.symbol] || SYMBOL_ICONS[(t.symbol || '').toUpperCase()];
                    const iconHtml = icon ? `<img src="${icon}" alt="${t.symbol}" onerror="this.style.display='none'">` : '';
                    return `<div class="earn-lend-token-row">
                        <span class="earn-lend-token-left">${iconHtml}${t.symbol} <span style="color:rgba(255,255,255,0.3)">${earn_formatUSDCompact(t.usd)}</span></span>
                        <span><span class="earn-lend-token-apr borrow">${displayRate > 0 ? displayRate.toFixed(2) + '% ' + rateLabel : '—'}</span><span class="earn-lend-token-annual">${annualCost > 0.01 ? '-' + earn_formatUSD(annualCost) + '/yr' : ''}</span></span>
                    </div>`;
                }).join('');

                const netAnnual = totalAnnualYield - totalAnnualCost;
                const netPositive = netAnnual >= 0;
                const netSign = netPositive ? '+' : '-';
                const netApr = p.collateralUSD > 0 ? (netAnnual / p.collateralUSD) * 100 : 0;
                const displayNetApr = useApy && Math.abs(netApr) > 0.01 ? aprToApy(Math.abs(netApr)) : Math.abs(netApr);

                // Age badge for collapsed row
                const ageBadge = p.openTimestamp ? `<span class="earn-age-badge">${earn_formatAge(p.openTimestamp).replace('Opened ', '')}</span>` : '';

                // Quick P&L preview for collapsed row
                const pnlValue = p.netAccrued !== undefined ? p.netAccrued : null;
                const pnlClass = pnlValue !== null ? (pnlValue >= 0 ? 'positive' : 'negative') : 'neutral';
                const pnlDisplay = pnlValue !== null && Math.abs(pnlValue) > 0.01
                    ? `${pnlValue >= 0 ? '+' : '-'}${earn_formatUSDOneDecimal(Math.abs(pnlValue))}`
                    : '—';
                const annualDisplay = Math.abs(netAnnual) > 0.01
                    ? `<div class="earn-net-sub-inline">${netSign}${earn_formatUSDOneDecimal(Math.abs(netAnnual))}/yr</div>`
                    : '';

                const dataRow = `<tr class="earn-lend-row risk-${riskClass}" data-idx="${i}" data-earn-layout-row onclick="earn_toggleLendDetail(${i})" style="animation-delay:${i * 0.08}s">
                    <td data-column="health">
                        <span class="earn-hf-badge ${riskClass}"><span class="earn-hf-dot ${riskClass}"></span>${hfText}</span>${ageBadge}
                        ${ratioBar}
                    </td>
                    <td data-column="emode" class="earn-emode-cell">${emodeCell}</td>
                    <td data-column="collateral"><div class="earn-merged-col"><span class="earn-usd-collateral">${collateralDisplay}</span>${renderMergedTokens(p.collateralTokens)}</div></td>
                    <td data-column="debt"><div class="earn-merged-col"><span class="earn-usd-debt">${earn_formatUSD(p.debtUSD)}</span>${renderMergedTokens(p.debtTokens)}</div></td>
                    <td data-column="pnl"><div class="earn-net-inline ${pnlClass}">${pnlDisplay}</div>${annualDisplay}</td>
                    <td data-column="details" class="earn-details-cell">${earn_renderDetailsButton(`earn_toggleLendDetail(${i})`)}</td>
                </tr>`;

                const detailRow = `<tr class="earn-lend-detail" id="earn-lend-detail-${i}" data-earn-layout-detail>
                    <td colspan="6">
                        <div class="earn-lend-detail-inner">
                            <div class="earn-lend-section">
                                <div class="earn-lend-section-title earn">Collateral Yield</div>
                                ${collateralRows || '<div style="color:var(--text-muted);font-size:11px">No collateral</div>'}
                                ${(p.accruedCollateral && p.accruedCollateral.length > 0) ? `<div style="border-top:1px solid rgba(52,211,153,0.1);margin-top:8px;padding-top:8px">
                                    <div class="earn-accrued-label">Open Route Yield</div>
                                    ${p.accruedCollateral.map(c => {
                    const icon = SYMBOL_ICONS[c.symbol] || SYMBOL_ICONS[(c.symbol || '').toUpperCase()];
                    const iconHtml = icon ? `<img src="${icon}" alt="${c.symbol}" onerror="this.style.display='none'">` : '';
                    const routeYieldSign = c.accruedUSD >= 0 ? '+' : '-';
                    const routeYieldClass = c.accruedUSD >= 0 ? 'supply' : 'borrow';
                    return `<div class="earn-lend-token-row"><span class="earn-lend-token-left">${iconHtml}${c.symbol} <span style="color:rgba(52,211,153,0.5)">open route</span></span><span class="earn-lend-token-apr ${routeYieldClass}">${routeYieldSign}${earn_formatUSD(Math.abs(c.accruedUSD))}</span></div>`;
                }).join('')}
                                </div>` : ''}
                            </div>
                            ${(p.externalRewards && p.externalRewards.length > 0) ? `<div class="earn-lend-section">
                                <div class="earn-lend-section-title rewards">External Rewards</div>
                                ${p.externalRewards.map(r => {
                    const rewardSymbol = earn_escapeHtml(r.symbol || 'Reward');
                    const iconHtml = r.icon ? `<img src="${earn_escapeHtml(r.icon)}" alt="${rewardSymbol}" onerror="this.style.display='none'">` : '';
                    const claimHtml = r.claimUrl ? `<a href="${earn_escapeHtml(r.claimUrl)}" target="_blank" class="earn-reward-claim-link" onclick="event.stopPropagation()">Claim ↗</a>` : '';
                    const aprHtml = r.apr > 0 ? `<span class="earn-lend-token-annual" style="color:rgba(251,191,36,0.6)">${r.apr.toFixed(2)}% APR</span>` : '';
                    const assetHint = r.assetSymbol ? `<span class="earn-lend-token-source">For ${earn_escapeHtml(r.assetSymbol)}</span>` : '';
                    return `<div class="earn-lend-token-row"><span class="earn-lend-token-left">${iconHtml}<span class="earn-lend-token-stack"><span class="earn-lend-token-main">${rewardSymbol}${claimHtml}</span>${assetHint}</span></span><span><span class="earn-lend-token-apr rewards">+${r.amount >= 1000 ? (r.amount / 1000).toFixed(2) + 'K' : r.amount.toFixed(2)}</span><span class="earn-lend-token-annual" style="color:rgba(251,191,36,0.5)"> ~${earn_formatUSD(r.usd)}</span>${aprHtml}</span></div>`;
                }).join('')}
                                <div style="border-top:1px solid rgba(251,191,36,0.08);margin-top:6px;padding-top:4px">
                                    <div class="earn-lend-token-row"><span class="earn-lend-token-left" style="color:rgba(251,191,36,0.7);font-weight:600">Total Rewards</span><span class="earn-lend-token-apr rewards">+${earn_formatUSD(p.totalExternalRewardsUSD)}</span></div>
                                </div>
                            </div>` : ''}
                            <div class="earn-lend-section">
                                <div class="earn-lend-section-title cost">Borrow Costs</div>
                                ${debtRows || '<div style="color:var(--text-muted);font-size:11px">No debt</div>'}
                                ${(p.accruedDebt && p.accruedDebt.length > 0) ? `<div style="border-top:1px solid rgba(248,113,113,0.1);margin-top:8px;padding-top:8px">
                                    <div class="earn-accrued-label">Accrued Interest</div>
                                    ${p.accruedDebt.map(c => {
                    const icon = SYMBOL_ICONS[c.symbol] || SYMBOL_ICONS[(c.symbol || '').toUpperCase()];
                    const iconHtml = icon ? `<img src="${icon}" alt="${c.symbol}" onerror="this.style.display='none'">` : '';
                    return `<div class="earn-lend-token-row"><span class="earn-lend-token-left">${iconHtml}${c.symbol} <span style="color:rgba(248,113,113,0.5)">accrued</span></span><span class="earn-lend-token-apr borrow">-${earn_formatUSD(c.accruedUSD)}</span></div>`;
                }).join('')}
                                </div>` : ''}
                            </div>
                            <div class="earn-lend-section">
                                ${(p.netAccrued !== undefined) ? `
                                    <div class="earn-lend-section-title net">Accrued P&L</div>
                                    <div class="earn-lend-net-value ${p.netAccrued >= 0 ? 'positive' : 'negative'}">${p.netAccrued >= 0 ? '+' : '-'}${earn_formatUSD(Math.abs(p.netAccrued))}<span style="font-size:11px;font-weight:400;color:rgba(255,255,255,0.4)"> total</span></div>
                                    <div class="earn-lend-net-sub">Open route ${earn_formatUSD(p.totalAccruedYield || 0)}${p.totalExternalRewardsUSD > 0.01 ? ' + <span style="color:#fbbf24">Rewards ' + earn_formatUSD(p.totalExternalRewardsUSD) + '</span>' : ''} − Borrow ${earn_formatUSD(p.totalAccruedCost || 0)}</div>
                                    ${p.openTimestamp ? `<div class="earn-lend-net-sub" style="margin-top:4px">Opened ${earn_formatAge(p.openTimestamp)}</div>` : ''}
                                    <div style="border-top:1px solid rgba(255,255,255,0.05);margin-top:8px;padding-top:6px">
                                        <div class="earn-lend-net-sub" style="margin-bottom:2px">Est. annual at current rates:</div>
                                        <div class="earn-lend-net-apr ${netPositive ? 'positive' : 'negative'}">${netSign}${earn_formatUSD(Math.abs(netAnnual))}/yr <span style="font-weight:400">(${netSign}${displayNetApr.toFixed(2)}% net ${rateLabel})</span></div>
                                    </div>
                                ` : `
                                    <div class="earn-lend-section-title net">Net Position (Annual Est.)</div>
                                    <div class="earn-lend-net-value ${netPositive ? 'positive' : 'negative'}">${netSign}${earn_formatUSD(Math.abs(netAnnual))}<span style="font-size:11px;font-weight:400;color:rgba(255,255,255,0.4)"> / year</span></div>
                                    <div class="earn-lend-net-apr ${netPositive ? 'positive' : 'negative'}">${netSign}${displayNetApr.toFixed(2)}% net ${rateLabel}</div>
                                    <div class="earn-lend-net-sub">Yield ${earn_formatUSD(totalAnnualYield)} − Cost ${earn_formatUSD(totalAnnualCost)}</div>
                                `}
                            </div>
                            <div class="earn-net-summary-bar">
                                <div class="earn-net-summary-item"><span class="earn-net-summary-label">Earn</span><span class="earn-net-summary-value ${totalAnnualYield > 0.01 ? 'positive' : 'neutral'}">${totalAnnualYield > 0.01 ? '+' : ''}${earn_formatUSD(totalAnnualYield)}/yr</span></div>
                                <div class="earn-net-summary-divider"></div>
                                <div class="earn-net-summary-item"><span class="earn-net-summary-label">Cost</span><span class="earn-net-summary-value ${totalAnnualCost > 0.01 ? 'negative' : 'neutral'}">${totalAnnualCost > 0.01 ? '-' : ''}${earn_formatUSD(totalAnnualCost)}/yr</span></div>
                                <div class="earn-net-summary-divider"></div>
                                <div class="earn-net-summary-item"><span class="earn-net-summary-label">Net</span><span class="earn-net-summary-value ${netPositive ? 'positive' : 'negative'}">${netSign}${earn_formatUSD(Math.abs(netAnnual))}/yr</span></div>
                            </div>
                        </div>
                    </td>
                </tr>`;

                return dataRow + detailRow;
            }).join('');
        }

        function earn_renderResults(assets, opts) {
            opts = opts || {};
            const getVerifiedYieldCalc = earn_createVerifiedYieldCalcCache();
            if (earn_globalEmptyState) {
                const resultsEl = document.getElementById('earn-results');
                if (resultsEl) resultsEl.classList.remove('visible', 'is-refreshing');
                const modeToggle = document.getElementById('earn-mode-toggle');
                if (modeToggle) modeToggle.classList.remove('visible');
                const filterBar = document.getElementById('earn-filter-bar');
                if (filterBar) filterBar.style.display = 'none';
                return;
            }
            const preservedOpenDetailIdx = opts.softRefresh ? earn_openDetailIdx : null;
            earn_openDetailIdx = null; // reset tracked open detail on re-render
            // Get current chain explorer
            const chain = earn_getChain();
            const explorerBase = chain.explorer || 'https://etherscan.io';

            // Build table rows
            const tbody = document.getElementById('earn-table-body');
            // Separate supply and borrow positions (respect dust toggle)
            const dustThreshold = earn_showDust ? 0 : 1;
            const totalSupplyAssets = assets.filter(a => !a.isBorrow && !a.isCollateral);
            const supplyAssets = totalSupplyAssets.filter(a => a.usdValue >= dustThreshold);
            const borrowAssets = assets.filter(a => a.isBorrow && a.usdValue >= dustThreshold);
            const hasBorrowContext = assets.some(a => a.isBorrow || a.isCollateral)
                || ((earn_lendingPositions || []).length > 0);
            const hasHistoricalEarnContext = Array.isArray(earn_historyData)
                && earn_historyData.some(item => item && !item.isActive && !item.isIsolation);
            const shouldShowSupplySection = totalSupplyAssets.length > 0
                || hasBorrowContext
                || hasHistoricalEarnContext;

            let html = '';

            // Check if ANY supply asset has yield data — if not, hide yield column
            // Note: don't exclude borrow markets here — borrow market filter only matters
            // for which yield CALCULATION method to use (netflow vs snapshot), not for
            // whether yield data EXISTS. Column visibility should be independent.
            const hasAnyYield = totalSupplyAssets.some(a => {
                const mid = String(a.marketId);
                const hasNF = earn_netflowData && earn_netflowData[mid] !== undefined;
                const hasA0 = earn_acct0NetflowData && earn_acct0NetflowData[mid] !== undefined;
                const hasIL = earn_interestYieldData && earn_interestYieldData[mid] && earn_interestYieldData[mid].earnYield !== undefined;
                const h = earn_totalYieldData && earn_totalYieldData[mid];
                const hasSS = h && h.cumulativeYield !== undefined;
                return hasNF || hasA0 || hasIL || hasSS;
            });
            const table = document.querySelector('.earn-asset-table:not(.earn-past-table)');
            const supplyTableShell = document.querySelector('#earn-supply-section .earn-section-table-shell');
            const supplyEmptyState = document.getElementById('earn-supply-empty-state');
            const keepYieldColumnVisible = hasAnyYield || earn_totalYieldStatus === 'loading';
            if (table) table.classList.toggle('no-yield', !keepYieldColumnVisible);

            // Keep the supply section visible while filters are active so Hide Dust can always be toggled back off.
            const supplySection = document.getElementById('earn-supply-section');
            if (supplySection) {
                supplySection.style.display = shouldShowSupplySection ? '' : 'none';
            }
            const supplyCountEl = document.getElementById('earn-supply-count');
            if (supplyCountEl) {
                supplyCountEl.textContent = supplyAssets.length;
            }

            let supplyEmptyTitle = '';
            let supplyEmptyHint = '';
            let showSupplyEmptyState = false;

            supplyAssets.forEach((a, idx) => {
                let yieldCellHtml;
                const yieldCalc = getVerifiedYieldCalc(a);

                if (earn_isTrustedInterestLedgerYieldCalc(yieldCalc)) {
                    const yieldFmt = earn_formatAmountOneDecimal(yieldCalc.absYield, a.decimals);
                    const yieldUsdStr = Math.abs(yieldCalc.yieldUsd) >= 0.01
                        ? `<div class="earn-usd-sub" style="color:${yieldCalc.yieldPositive ? 'rgba(52,211,153,0.5)' : 'rgba(248,113,113,0.5)'}">${yieldCalc.yieldSign}${earn_formatUSDOneDecimal(Math.abs(yieldCalc.yieldUsd))}</div>`
                        : '';
                    yieldCellHtml = `<span class="earn-amount ${yieldCalc.yieldColor}">${yieldCalc.yieldSign + yieldFmt}<span class="earn-amount-sym">${a.symbol}</span></span>${yieldUsdStr}`;
                } else {
                    const yieldPlaceholder = earn_totalYieldStatus === 'loading'
                        ? 'Loading...'
                        : '—';
                    yieldCellHtml = `<span class="earn-amount" style="color:var(--text-muted)">${yieldPlaceholder}</span>`;
                }

                const weiFmt = earn_formatAmount(a.wei, a.decimals, a.symbol);
                const marketPrice = earn_getUsdPrice(a.symbol, a.tokenAddr, document.getElementById('earn-chain').value);

                // Icon
                let iconHtml;
                if (a.icon) {
                    const _gsF2 = new Set(['CRV', 'USD0', 'USD0++', 'deUSD', 'sdeUSD', 'MATIC', 'POL', 'stcUSD', 'cUSD', 'USDT', 'cbBTC']).has(a.symbol) ? ' style="filter:grayscale(1) brightness(1.5)"' : '';
                    iconHtml = `<div class="earn-token-icon${earnTokenIconFrameClass(a.symbol)}"><img src="${a.icon}" alt="${a.symbol}"${_gsF2} onerror="this.parentElement.textContent='${String(a.symbol || '?').replace(/[^A-Za-z0-9]/g, '').slice(0, 2) || '?'}'"></div>`;
                } else {
                    iconHtml = `<div class="earn-token-icon">${a.symbol.slice(0, 2)}</div>`;
                }

                // Staggered animation delay
                const delay = idx * 0.08;

                // Explorer link
                const explorerUrl = `${explorerBase}/address/${a.tokenAddr}`;

                // Main data row
                // Build Supply APR cell (same breakdown as assets tab)
                let earnAprCellHtml;
                const cid = document.getElementById('earn-chain').value;
                const rateByAddr = earn_marketRates[cid + ':' + (a.tokenAddr || '').toLowerCase()];
                const rateBySymbol = earn_marketRates['sym:' + (a.symbol || '').toUpperCase().replace(/[^A-Z0-9]/g, '')];
                const rateData = rateByAddr || rateBySymbol;
                if (rateData && rateData.apy > 0) {
                    let adjApr = rateData.apy;
                    if (earn_excludeOdolo) adjApr -= (rateData.rewards || 0);
                    if (earn_excludeYield) adjApr -= (rateData.extYieldApr || 0);
                    if (earn_excludeLending) adjApr -= (rateData.lendingApr || 0);
                    const aprClass = adjApr > 0 ? 'assets-apy-green' : (adjApr < 0 ? 'assets-apy-red' : 'assets-apy-dim');
                    const displayApr = earn_showApy ? aprToApy(adjApr) : adjApr;
                    const aprStyle = displayApr > 0 ? 'font-size:15px;font-weight:700' : '';
                    // Match the compact Supply breakdown used by Dolomite Assets.
                    const supplyParts = [];
                    if ((rateData.lendingApr || 0) > 0.01 && !earn_excludeLending) {
                        supplyParts.push({ key: 'lending', label: 'Lending', rate: rateData.lendingApr });
                    }
                    if ((rateData.rewards || 0) > 0 && !earn_excludeOdolo) {
                        supplyParts.push({ key: 'odolo', label: 'oDOLO', rate: rateData.rewards });
                    }
                    if ((rateData.extYieldApr || 0) > 0.01 && !earn_excludeYield) {
                        supplyParts.push({ key: 'yield', label: 'Yield', rate: rateData.extYieldApr });
                    }
                    const supplyLinesHtml = supplyParts.map(part => {
                        const partRate = earn_showApy ? aprToApy(part.rate) : part.rate;
                        return `<div class="earn-supply-apr-line ${part.key}${partRate < 0 ? ' negative' : ''}"><span class="earn-supply-apr-dash">—</span><span class="earn-supply-apr-source">${part.label}</span><span class="earn-supply-apr-number">${partRate.toFixed(2)}%</span></div>`;
                    }).join('');
                    earnAprCellHtml = `<div class="earn-supply-apr-cell"><div class="earn-supply-apr-value${displayApr < 0 ? ' negative' : ''}">${displayApr.toFixed(2)}%</div><div class="earn-supply-apr-lines">${supplyLinesHtml}</div></div>`;
                } else {
                    earnAprCellHtml = `<span style="color:var(--text-muted)">—</span>`;
                }

                html += `<tr class="earn-data-row" id="earn-row-${idx}" data-earn-layout-row onclick="earn_toggleDetail(${idx})" style="animation-delay:${delay}s">
                    <td data-column="token">
                        <div class="earn-token-cell">
                            <div class="earn-token-left">
                                ${iconHtml}
                                <div class="earn-token-info">
                                    <div class="earn-token-name">${a.symbol}</div>
                                </div>
                            </div>
                        </div>
                    </td>
                    <td data-column="quality">${earn_renderSupplyQualityCell(a.marketId, a.symbol, a.decimals, yieldCalc)}</td>
                    <td data-column="price" class="earn-market-price-cell">
                        <span class="earn-market-price">${earn_formatMarketPrice(marketPrice)}</span>
                    </td>
                    <td data-column="supply" class="earn-supply-rate-cell">
                        ${earnAprCellHtml}
                    </td>
                    <td data-column="balance">
                        <span class="earn-amount earn-amount-primary">${weiFmt}<span class="earn-amount-sym">${a.symbol}</span></span>
                        <div style="font-size:11px;color:var(--text-muted);margin-top:2px">≈ ${earn_formatUSD(a.usdValue)}</div>
                    </td>
                    <td data-column="yield">
                        ${yieldCellHtml}
                    </td>
                    <td data-column="details" class="earn-details-cell">
                        ${earn_renderDetailsButton(`earn_toggleDetail(${idx})`)}
                    </td>
                </tr>`;
                html += earn_buildSupplyDetailRow(idx, a, yieldCalc, explorerUrl);
            });

            if (supplyAssets.length === 0 && totalSupplyAssets.length > 0) {
                showSupplyEmptyState = true;
                supplyEmptyTitle = 'All supply assets are hidden by the current filter';
                supplyEmptyHint = 'Turn off Hide Dust to show small balances again.';
            } else if (supplyAssets.length === 0 && shouldShowSupplySection) {
                showSupplyEmptyState = true;
                supplyEmptyTitle = hasBorrowContext
                    ? 'No active earn deposits for this address'
                    : 'No active earn deposits are visible right now';
                supplyEmptyHint = hasBorrowContext
                    ? 'Borrow positions are shown below, and the Earn filters stay available here.'
                    : hasHistoricalEarnContext
                        ? 'Past and routed assets are shown below, and you can still use Hide Dust and APR/APY here.'
                        : 'Use the controls above to adjust the current Earn view.';
            }

            if (supplyAssets.length > 0) {
                html += '<tr class="earn-table-spacer" aria-hidden="true"><td colspan="7"></td></tr>';
            }

            if (supplyTableShell) {
                supplyTableShell.style.display = showSupplyEmptyState ? 'none' : '';
            }
            if (supplyEmptyState) {
                if (showSupplyEmptyState) {
                    supplyEmptyState.style.display = '';
                    supplyEmptyState.innerHTML = `
                        <div class="earn-supply-empty-panel">
                            <div class="earn-supply-empty-title">${supplyEmptyTitle}</div>
                            <div class="earn-supply-empty-hint">${supplyEmptyHint}</div>
                        </div>`;
                } else {
                    supplyEmptyState.style.display = 'none';
                    supplyEmptyState.innerHTML = '';
                }
            }

            // ═══════ LENDING POSITIONS (separate section below supply) ═══════
            // Rendered asynchronously from liquidation_risk.json via earn_renderLendingPositions()

            // Recombine for downstream logic
            assets = [...supplyAssets];

            // === INACTIVE ASSETS (from history data) — render into SEPARATE container ===
            let withdrawnHtml = '';
            let withdrawnCount = 0;
            if (earn_historyData && earn_historyData.length > 0) {
                // Get IDs of active assets to avoid duplicates
                const activeTokenAddrs = new Set(assets.filter(a => !a.isCollateral).map(a => a.tokenAddr?.toLowerCase()));

                // Filter to only inactive (withdrawn) assets not already in active list
                const inactiveItems = earn_historyData.filter(item => {
                    if (item.isActive) return false;
                    if (item.isIsolation && !item.isActive) return false;
                    if (activeTokenAddrs.has(item.tokenAddr?.toLowerCase())) return false;
                    const chainId = document.getElementById('earn-chain').value;
                    const balanceUsdScaled = earn_getTokenUsdScaled(item.currentWei, item.decimals, item.symbol, item.tokenAddr, chainId);
                    const verifiedYieldUsdScaled = item.yieldTrustedForDisplay ? (item.yieldUsdScaled || 0n) : 0n;
                    if (!earn_showDust && earn_isSubDollarYieldPair(balanceUsdScaled, verifiedYieldUsdScaled)) return false;
                    return true;
                });

                withdrawnCount = inactiveItems.length;

                inactiveItems.forEach((item, i) => {
                    const ii = assets.length + i;
                    const delay = i * 0.05;

                    let iconHtml;
                    if (item.icon) {
                        const _gsF3 = new Set(['CRV', 'USD0', 'USD0++', 'deUSD', 'sdeUSD', 'MATIC', 'POL', 'stcUSD', 'cUSD', 'USDT', 'cbBTC']).has(item.symbol) ? ' style="filter:grayscale(1) brightness(1.5)"' : '';
                        iconHtml = `<div class="earn-token-icon${earnTokenIconFrameClass(item.symbol)}"><img src="${item.icon}" alt="${item.symbol}"${_gsF3} onerror="this.parentElement.textContent='${String(item.symbol || '?').replace(/[^A-Za-z0-9]/g, '').slice(0, 2) || '?'}'"></div>`;
                    } else {
                        iconHtml = `<div class="earn-token-icon">${item.symbol.slice(0, 2)}</div>`;
                    }

                    const yieldPositive = item.yieldWei >= 0n;
                    const yieldSign = yieldPositive && item.yieldWei > 0n ? '+' : '';
                    const yieldColor = yieldPositive ? 'earn-yield-positive' : 'earn-yield-negative';
                    const yieldFmt = earn_formatAmount(item.yieldWei, item.decimals, item.symbol);
                    const yieldUsdFmt = item.yieldUsd !== 0
                        ? `<div style="font-size:11px;color:var(--text-muted);margin-top:2px">${item.yieldUsd > 0 ? '+' : item.yieldUsd < 0 ? '-' : ''}$${Math.abs(item.yieldUsd).toFixed(2)}</div>`
                        : '';

                    const balFmt = earn_formatAmount(item.currentWei, item.decimals, item.symbol);
                    const explorerUrl = `${explorerBase}/address/${item.tokenAddr}`;

                    withdrawnHtml += `<tr class="earn-data-row earn-row-inactive" id="earn-row-${ii}" style="animation-delay:${delay}s">
                        <td>
                            <div class="earn-token-cell">
                                <div class="earn-token-left">
                                    ${iconHtml}
                                    <div class="earn-token-info">
                                        <div class="earn-token-name">${item.symbol}</div>
                                        <span class="earn-hist-badge earn-position-badge ${item.isCollateralized ? 'routed' : 'withdrawn'}"${item.isCollateralized ? ' data-tip="Asset is routed into a borrow subaccount as collateral, so it is not a withdrawn supply asset"' : ''}><span class="earn-status-dot"></span>${item.isCollateralized ? 'In Borrow Route' : 'Exited Position'}</span>
                                    </div>
                                </div>
                            </div>
                        </td>
                        <td><span style="color:var(--text-muted)">—</span></td>
                        <td>
                            <span class="earn-amount" style="color:var(--text-muted)">${balFmt}<span class="earn-amount-sym">${item.symbol}</span></span>
                            ${(() => {
                            const chainId = document.getElementById('earn-chain').value;
                            const balUsd = Math.abs(earn_scaledUsdToNumber(earn_getTokenUsdScaled(item.currentWei, item.decimals, item.symbol, item.tokenAddr, chainId)));
                            return balUsd >= 0.01 ? `<div style="font-size:11px;color:var(--text-muted);margin-top:2px">≈ ${earn_formatUSD(balUsd)}</div>` : '';
                        })()}
                        </td>
                        <td>
                            <span class="earn-amount ${yieldColor}">${yieldSign}${yieldFmt}<span class="earn-amount-sym">${item.symbol}</span></span>
                            ${yieldUsdFmt}
                        </td>
                    </tr>`;
                });
            }

            // Withdrawn section removed — skip rendering
            // (elements no longer in DOM)

            tbody.innerHTML = html;
            if (opts.softRefresh && preservedOpenDetailIdx !== null) {
                const preservedRow = document.getElementById('earn-row-' + preservedOpenDetailIdx);
                const preservedDetail = document.getElementById('earn-detail-' + preservedOpenDetailIdx);
                if (preservedRow && preservedDetail) {
                    preservedRow.classList.add('open');
                    preservedDetail.classList.add('open');
                    earn_openDetailIdx = preservedOpenDetailIdx;
                }
            }

            // ═══════ UX: Build Summary Card ═══════
            if (!opts.skipSummary) {
                const summaryEl = document.getElementById('earn-summary-card');
                if (summaryEl) {
                    let totalUsd = 0;
                    let totalYieldUsdScaled = 0n;
                    let openRouteYieldUsdScaled = 0n;
                    let openRouteYieldAssetCount = 0;
                    let pendingYieldAssetCount = 0;
                    let trustedYieldAssetCount = 0;
                    let bestSymbol = '';
                    let bestYieldUsdScaled = 0n;
                    const visibleVerifySummary = { total: 0, verified: 0, mismatch: 0, unverified: 0 };

                    const dustThreshold = earn_showDust ? 0 : 1;
                    const activeCount = (earn_cachedAssets || []).filter(a => !a.isBorrow && !a.isCollateral && a.usdValue >= dustThreshold).length;
                    const hasBorrowOnlyEarnContext = activeCount === 0
                        && withdrawnCount === 0
                        && (((earn_cachedAssets || []).some(a => a.isBorrow || a.isCollateral))
                            || ((earn_lendingPositions || []).length > 0));

                    // Active assets (supply only — borrows come from lending positions)
                    (earn_cachedAssets || []).forEach(a => {
                        if (a.isBorrow || a.isCollateral) return; // skip borrow entries and collateral parked in borrow accounts
                        if (a.usdValue < dustThreshold) return;
                        totalUsd += (a.usdValue || 0);
                        const verifiedYieldCalc = getVerifiedYieldCalc(a);
                        const verifyPresentation = earn_getVerificationPresentation(a.marketId, verifiedYieldCalc, a.symbol, a.decimals);
                        if (verifyPresentation && verifyPresentation.counted) {
                            visibleVerifySummary.total++;
                            visibleVerifySummary[verifyPresentation.status] = (visibleVerifySummary[verifyPresentation.status] || 0) + 1;
                        }
                        if (earn_isTrustedInterestLedgerYieldCalc(verifiedYieldCalc)) {
                            trustedYieldAssetCount++;
                            const countableYieldUsdScaled = BigInt(verifiedYieldCalc.yieldUsdScaled || 0n);
                            const routeYieldUsdScaled = BigInt(verifiedYieldCalc.openCollateralYieldUsdScaled || 0n);
                            totalYieldUsdScaled += countableYieldUsdScaled;
                            if (routeYieldUsdScaled !== 0n) {
                                openRouteYieldUsdScaled += routeYieldUsdScaled;
                                openRouteYieldAssetCount++;
                            }
                            if (countableYieldUsdScaled > bestYieldUsdScaled) {
                                bestYieldUsdScaled = countableYieldUsdScaled;
                                bestSymbol = a.symbol;
                            }
                            return;
                        }
                        // Track markets that currently rely on unverified/guarded fallback methods.
                        const pendingYieldCalc = verifiedYieldCalc.hasData
                            ? verifiedYieldCalc
                            : earn_calculateYield(a, { requireVerifiedInterest: false });
                        if (pendingYieldCalc.hasData) {
                            pendingYieldAssetCount++;
                        }
                    });

                    // Historical/withdrawn assets
                    if (earn_historyData) {
                        const trustedHistoryMethods = new Set([
                            'interest-ledger',
                            'interest-ledger-override',
                        ]);
                        earn_historyData.forEach(item => {
                            if (item.isActive || item.isIsolation) return;
                            const chainId = document.getElementById('earn-chain').value;
                            const balanceUsdScaled = earn_getTokenUsdScaled(item.currentWei, item.decimals, item.symbol, item.tokenAddr, chainId);
                            const verifiedYieldUsdScaled = item.yieldTrustedForDisplay ? (item.yieldUsdScaled || 0n) : 0n;
                            if (!earn_showDust && earn_isSubDollarYieldPair(balanceUsdScaled, verifiedYieldUsdScaled)) return;
                            const itemYieldCalc = earn_calculateYield({
                                marketId: item.marketId,
                                tokenAddr: item.tokenAddr,
                                symbol: item.symbol,
                                decimals: item.decimals,
                                currentWei: item.currentWei,
                                currentPar: item.currentPar,
                            }, { applyHistoryGuards: true });
                            const calcTrusted = earn_isTrustedInterestLedgerYieldCalc(itemYieldCalc);
                            const histMeta = earn_getResolvedTotalYieldEntry(item.marketId);
                            const histStatus = histMeta
                                ? String(histMeta.resolvedVerificationStatus || histMeta.verificationStatus || '')
                                : '';
                            const histIsLatest = histMeta ? (histMeta.isLatestSnapshot !== false) : true;
                            const histMethod = histMeta
                                ? String(histMeta.resolvedMethod || histMeta.method || item.yieldMethod || '')
                                : String(item.yieldMethod || '');
                            const histUsesReplay = trustedHistoryMethods.has(histMethod);
                            const histStatusTrusted = histUsesReplay && earn_isTrustedReplayYieldStatus(histStatus);
                            const histTrusted = !!(
                                histMeta
                                && histMeta.resolvedTrustedForTotal === true
                                && trustedHistoryMethods.has(histMethod)
                                && histStatusTrusted
                                && histIsLatest
                            );
                            if (!calcTrusted && !histTrusted) {
                                if ((item.yieldUsdScaled || 0n) !== 0n) pendingYieldAssetCount++;
                                return;
                            }
                            const effectiveYieldUsdScaled = calcTrusted
                                ? BigInt(itemYieldCalc.yieldUsdScaled || 0n)
                                : BigInt(item.yieldUsdScaled || 0n);
                            trustedYieldAssetCount++;
                            if (item.isCollateralized) {
                                openRouteYieldUsdScaled += effectiveYieldUsdScaled;
                                if (effectiveYieldUsdScaled !== 0n) openRouteYieldAssetCount++;
                                return;
                            }
                            totalYieldUsdScaled += effectiveYieldUsdScaled;
                            if (effectiveYieldUsdScaled > bestYieldUsdScaled) {
                                bestYieldUsdScaled = effectiveYieldUsdScaled;
                                bestSymbol = item.symbol;
                            }
                        });
                    }

                    const totalYieldUsd = earn_scaledUsdToNumber(totalYieldUsdScaled);
                    const openRouteYieldUsd = earn_scaledUsdToNumber(openRouteYieldUsdScaled);
                    const bestYieldUsd = earn_scaledUsdToNumber(bestYieldUsdScaled);
                    const historicalPnlEntries = Object.values(earn_totalYieldData || {}).filter(entry =>
                        entry && entry.historicalYieldValuationMethod === 'daily-snapshot-constant-par'
                    );
                    const historicalPnlUsd = historicalPnlEntries.reduce((sum, entry) => {
                        const value = Number(entry.historicalYieldUsd || 0);
                        return Number.isFinite(value) ? sum + value : sum;
                    }, 0);
                    const historicalPnlEligible = historicalPnlEntries.reduce((sum, entry) => sum + Number(entry.historicalYieldEligibleIntervals || 0), 0);
                    const historicalPnlPriced = historicalPnlEntries.reduce((sum, entry) => sum + Number(entry.historicalYieldPricedIntervals || 0), 0);
                    const historicalPnlSkipped = historicalPnlEntries.reduce((sum, entry) => sum + Number(entry.historicalYieldSkippedFlowIntervals || 0), 0);
                    const hasHistoricalPnl = historicalPnlPriced > 0;
                    const historicalPnlClass = historicalPnlUsd >= 0 ? 'positive' : 'negative';
                    const historicalPnlSign = historicalPnlUsd >= 0 ? '+' : '-';
                    const historicalPnlLoading = (earn_totalYieldStatus === 'loading' || earn_replayStatus === 'loading');
                    const historicalPnlSub = hasHistoricalPnl
                        ? `${historicalPnlPriced}/${historicalPnlEligible} daily intervals priced${historicalPnlSkipped > 0 ? ` · ${historicalPnlSkipped} principal changes excluded` : ''}`
                        : historicalPnlLoading ? 'Building historical valuation' : 'No priced yield intervals yet';
                    const historicalPnlTitle = earn_escapeHtml(
                        'Yield is valued with the token price for each daily accrual interval. Intervals with deposits, withdrawals, or other principal changes are excluded. Method: daily-snapshot-constant-par.'
                    );
                    const portfolioValueTitle = earn_escapeHtml(earn_formatUSDExact(totalUsd));
                    const hasVerifiedTotalYield = trustedYieldAssetCount > 0;
                    const totalYieldCurrentValueLabel = ' at current token prices';
                    const totalYieldTitle = earn_escapeHtml(!hasVerifiedTotalYield
                        ? 'No strict verified yield is available for this wallet.'
                        : openRouteYieldAssetCount > 0
                            ? `${earn_formatUSDExact(totalYieldUsd)} supply/closed-route yield${totalYieldCurrentValueLabel}. Open borrow-route collateral yield is shown separately: ${earn_formatUSDExact(openRouteYieldUsd)}${totalYieldCurrentValueLabel}.`
                            : `${earn_formatUSDExact(totalYieldUsd)}${totalYieldCurrentValueLabel}`);
                    const yieldClass = totalYieldUsd >= 0 ? 'positive' : 'negative';
                    const yieldSign = totalYieldUsd >= 0 ? '+' : '-';
                    const openRouteYieldClass = openRouteYieldUsd >= 0 ? 'positive' : 'negative';
                    const openRouteYieldSign = openRouteYieldUsd >= 0 ? '+' : '-';
                    const bestYieldSign = bestYieldUsd > 0 ? '+' : bestYieldUsd < 0 ? '-' : '';
                    const isYieldPipelineLoading = (earn_totalYieldStatus === 'loading' || earn_replayStatus === 'loading');
                    const isTotalYieldLoading = isYieldPipelineLoading && !hasVerifiedTotalYield && !hasBorrowOnlyEarnContext;
                    const isTotalYieldRefreshing = isYieldPipelineLoading && hasVerifiedTotalYield;
                    const totalYieldSub = hasBorrowOnlyEarnContext
                        ? 'Not applicable for borrow-only accounts'
                        : isTotalYieldLoading
                            ? 'Building verified yield'
                            : isTotalYieldRefreshing
                                ? 'Refreshing verified yield'
                                : pendingYieldAssetCount > 0
                                    ? `${trustedYieldAssetCount} verified · ${pendingYieldAssetCount} pending`
                                    : openRouteYieldAssetCount > 0
                                        ? 'Verified supply / closed-route yield'
                                        : hasVerifiedTotalYield
                                            ? 'Verified lifetime yield'
                                            : 'No verified yield data';
                    const provisionalVerifyTotal = trustedYieldAssetCount + pendingYieldAssetCount;
                    const hasProvisionalVerifySummary = !earn_replayVerificationReady && provisionalVerifyTotal > 0;
                    const verifySummary = visibleVerifySummary.total > 0
                        ? visibleVerifySummary
                        : (earn_replayVerificationSummary || { total: 0, verified: 0, mismatch: 0, unverified: 0 });
                    const verifyPendingCount = Math.max(0,
                        (verifySummary.total || 0)
                        - (verifySummary.verified || 0)
                        - (verifySummary.mismatch || 0)
                        - (verifySummary.unverified || 0)
                    );
                    const verifyValue = hasProvisionalVerifySummary
                        ? `${trustedYieldAssetCount}/${provisionalVerifyTotal}`
                        : verifySummary.total > 0
                            ? `${verifySummary.verified}/${verifySummary.total}`
                            : '—';
                    const verifyClass = hasProvisionalVerifySummary
                        ? (pendingYieldAssetCount > 0 ? 'neutral' : 'positive')
                        : verifySummary.mismatch > 0
                            ? 'negative'
                            : (verifySummary.unverified > 0 || verifyPendingCount > 0)
                                ? 'neutral'
                            : verifySummary.total > 0
                                ? 'positive'
                                : 'neutral';
                    const unverifiedLabel = earn_replayUsedSubgraphFallback ? 'fallback' : 'pending';
                    const verifySub = hasProvisionalVerifySummary
                        ? (pendingYieldAssetCount > 0
                            ? `${trustedYieldAssetCount} ready · ${pendingYieldAssetCount} pending`
                            : 'Visible yield is ready')
                        : verifySummary.total === 0
                            ? (earn_lastReplayError
                                ? 'Replay unavailable'
                                : earn_replayStatus === 'loading'
                                    ? 'Replay still loading'
                                    : earn_replayUsedSubgraphFallback
                                        ? 'Fallback replay mode'
                                        : 'No replay checks yet')
                            : verifySummary.mismatch > 0
                                ? `${verifySummary.mismatch} mismatch${verifySummary.mismatch !== 1 ? 'es' : ''}${verifySummary.unverified > 0 ? ' · ' + verifySummary.unverified + ' ' + unverifiedLabel : ''}`
                                : verifySummary.unverified > 0
                                    ? `${verifySummary.verified} ready · ${verifySummary.unverified} ${unverifiedLabel}`
                                    : verifyPendingCount > 0
                                        ? `${verifySummary.verified} ready · ${verifyPendingCount} pending`
                                    : 'All visible markets reconciled';

                    // Find best performer icon
                    let bestIcon = '';
                    if (bestSymbol) {
                        const chainId = document.getElementById('earn-chain').value;
                        const bestAsset = (earn_cachedAssets || []).find(a => a.symbol === bestSymbol);
                        if (bestAsset) {
                            const key = chainId + ':' + bestAsset.tokenAddr.toLowerCase();
                            const cached = earn_tokenCache[key] || KNOWN_TOKENS[key];
                            if (cached && cached.icon) bestIcon = cached.icon;
                        }
                    }
                    const bestIconHtml = bestIcon ? `<img class="best-icon" src="${bestIcon}" alt="">` : '';
                    const hasBorrowContext = (((earn_cachedAssets || []).some(a => a.isBorrow || a.isCollateral))
                        || ((earn_lendingPositions || []).length > 0));
                    const borrowRouteCount = (earn_lendingPositions || []).length;
                    const borrowRouteValue = borrowRouteCount > 0
                        ? String(borrowRouteCount)
                        : (hasBorrowContext ? 'Detected' : 'None');
                    const borrowRouteYieldValue = openRouteYieldAssetCount > 0
                        ? `${openRouteYieldSign}${earn_formatUSD(Math.abs(openRouteYieldUsd))}`
                        : borrowRouteValue;
                    const borrowRouteYieldClass = openRouteYieldAssetCount > 0
                        ? openRouteYieldClass
                        : 'neutral';
                    const borrowRouteSub = openRouteYieldAssetCount > 0
                        ? `${openRouteYieldAssetCount} collateral asset${openRouteYieldAssetCount !== 1 ? 's' : ''} accruing inside open borrow route`
                        : borrowRouteCount > 0
                            ? `${borrowRouteCount} borrow route${borrowRouteCount !== 1 ? 's' : ''} active`
                            : hasBorrowContext
                                ? 'Collateral is parked inside an open borrow route'
                                : 'No open borrow route';

                    const finalVerifyValue = hasBorrowOnlyEarnContext ? 'N/A' : verifyValue;
                    const finalVerifyClass = hasBorrowOnlyEarnContext ? 'neutral' : verifyClass;
                    const finalVerifySub = hasBorrowOnlyEarnContext
                        ? 'Not applicable for borrow-only accounts'
                        : verifySub;
                    const summaryContextText = hasBorrowOnlyEarnContext
                        ? 'Borrow-route only'
                        : withdrawnCount > 0 && activeCount === 0
                            ? 'Historical earn view'
                            : activeCount > 0
                                ? 'Live earn overview'
                                : 'Account snapshot';
                    const isVerificationLoading = (
                        earn_totalYieldStatus === 'loading'
                        || earn_replayStatus === 'loading'
                    ) && !earn_replayVerificationReady;
                    const summaryVerificationChip = isVerificationLoading
                        ? 'Verification loading'
                        : pendingYieldAssetCount > 0
                            ? `${pendingYieldAssetCount} pending verify`
                            : trustedYieldAssetCount > 0
                                ? 'Strict yield ready'
                                : 'No verified yield yet';
                    const summaryVerificationChipClass = isVerificationLoading
                        ? 'is-muted'
                        : pendingYieldAssetCount > 0
                            ? 'is-warn'
                            : trustedYieldAssetCount > 0
                                ? 'is-positive'
                                : 'is-muted';
                    const resultsRefreshing = !!document.getElementById('earn-results')?.classList.contains('is-refreshing');
                    const summaryRefreshChipHtml = resultsRefreshing
                        ? '<span class="earn-summary-chip is-live">Fresh data · refreshing in background</span>'
                        : '';
                    const summaryBorrowChip = hasBorrowContext
                        ? (borrowRouteCount > 0
                            ? `${borrowRouteCount} borrow route${borrowRouteCount !== 1 ? 's' : ''}`
                            : 'Borrow context detected')
                        : 'No borrow routes';
                    const summaryBorrowChipClass = hasBorrowContext ? '' : 'is-muted';
                    const initialDebtValue = hasBorrowContext ? 'Loading...' : '$0.00';
                    const initialDebtClass = hasBorrowContext ? 'neutral' : 'neutral';
                    const initialDebtSub = hasBorrowContext
                        ? 'Fetching collateral and debt...'
                        : 'No debt sourced from borrow routes';
                    const initialBorrowPnlValue = hasBorrowContext ? 'Loading...' : '—';
                    const initialBorrowPnlSub = hasBorrowContext
                        ? 'Annualized at current rates'
                        : 'No open borrow route';
                    const bestPerformerMutedClass = bestYieldUsd > 0 ? '' : ' is-muted';
                    const bestPerformerValueClass = bestYieldUsd > 0 ? 'positive' : 'neutral';
                    const rewardsMutedClass = ' is-muted';

                    // Portfolio sub label (will be updated when lending positions arrive)
                    const portfolioSub = `<span class="sub-highlight">${activeCount}</span> supply · <span style="color:#f87171">${borrowRouteCount}</span> borrow`;

                    // Check if the current address has a known identity
                    const searchAddr = document.getElementById('earn-address').value.trim();
                    const addrBadgeHtml = (typeof dolo_labelBadge === 'function') ? dolo_labelBadge(searchAddr) : '';
                    const summaryRunId = earn_activeLookupRunId;
                    const summaryAddr = String(searchAddr || '').trim().toLowerCase();
                    const summaryChainId = String(document.getElementById('earn-chain')?.value || '').trim().toLowerCase();
                    const isSummaryRenderCurrent = () => {
                        const currentAddr = String(document.getElementById('earn-address')?.value || '').trim().toLowerCase();
                        const currentChainId = String(document.getElementById('earn-chain')?.value || '').trim().toLowerCase();
                        return summaryRunId === earn_activeLookupRunId
                            && summaryAddr === currentAddr
                            && summaryChainId === currentChainId;
                    };

                    summaryEl.innerHTML = `
                        <div class="earn-summary-main">
                            <div class="earn-summary-stat earn-summary-hero is-primary">
                                <div class="earn-summary-hero-top">
                                    <div>
                                        <div class="earn-summary-label" style="display:flex;align-items:center;gap:4px">Portfolio Value${addrBadgeHtml}</div>
                                    </div>
                                    <div class="earn-summary-context-pill">${summaryContextText}</div>
                                </div>
                                <div class="earn-summary-value neutral" id="earn-summary-portfolio-value" data-tip="${portfolioValueTitle}">${earn_formatUSD(totalUsd)}</div>
                                <div class="earn-summary-sub" id="earn-summary-portfolio-sub">${portfolioSub}</div>
                                <div class="earn-summary-chip-row">
                                    <span class="earn-summary-chip" id="earn-summary-supply-chip">${activeCount} supply asset${activeCount !== 1 ? 's' : ''}</span>
                                    <span class="earn-summary-chip ${summaryBorrowChipClass}" id="earn-summary-borrow-chip">${summaryBorrowChip}</span>
                                    <span class="earn-summary-chip ${summaryVerificationChipClass}">${summaryVerificationChip}</span>
                                    ${summaryRefreshChipHtml}
                                </div>
                            </div>
                        </div>
                        <div class="earn-summary-side">
                            <div class="earn-summary-primary-grid">
                                <div class="earn-summary-stat kpi-primary">
                                    <div class="earn-summary-label">Total Yield Earned</div>
                                    <div class="earn-summary-value ${isTotalYieldLoading || !hasVerifiedTotalYield ? 'neutral' : yieldClass}" data-tip="${totalYieldTitle}">${hasBorrowOnlyEarnContext ? '—' : isTotalYieldLoading ? 'Loading...' : hasVerifiedTotalYield ? `${yieldSign}${earn_formatUSD(Math.abs(totalYieldUsd))}` : '—'}</div>
                                    <div class="earn-summary-sub">${totalYieldSub}</div>
                                </div>
                                <div class="earn-summary-stat kpi-primary">
                                    <div class="earn-summary-label">Historical Yield P&amp;L</div>
                                    <div class="earn-summary-value ${hasHistoricalPnl ? historicalPnlClass : 'neutral'}" data-tip="${historicalPnlTitle}">${hasHistoricalPnl ? `${historicalPnlSign}${earn_formatUSD(Math.abs(historicalPnlUsd))}` : isYieldPipelineLoading ? 'Loading...' : '—'}</div>
                                    <div class="earn-summary-sub">${historicalPnlSub}</div>
                                </div>
                                <div class="earn-summary-stat kpi-primary">
                                    <div class="earn-summary-label">Current Markets Check</div>
                                    <div class="earn-summary-value ${finalVerifyClass}">${finalVerifyValue}</div>
                                    <div class="earn-summary-sub">${finalVerifySub}</div>
                                </div>
                                <div class="earn-summary-stat kpi-primary earn-rewards-overview-stat${rewardsMutedClass}">
                                    <div class="earn-summary-label">Rewards</div>
                                    <div class="earn-summary-value neutral" id="earn-rewards-overview-val">Loading...</div>
                                    <div class="earn-summary-sub" id="earn-rewards-overview-sub">Checking reward sources...</div>
                                    <div class="earn-summary-mini-list" id="earn-rewards-overview-list"></div>
                                </div>
                            </div>
                            <div class="earn-summary-secondary-grid">
                                <div class="earn-summary-stat kpi-secondary earn-debt-stat${hasBorrowContext ? '' : ' is-muted'}">
                                    <div class="earn-summary-label is-negative">Total Debt</div>
                                    <div class="earn-summary-value ${initialDebtClass}" id="earn-summary-debt-value">${initialDebtValue}</div>
                                    <div class="earn-summary-sub" id="earn-summary-debt-sub">${initialDebtSub}</div>
                                </div>
                                <div class="earn-summary-stat kpi-secondary earn-borrow-pnl-stat${hasBorrowContext ? '' : ' is-muted'}">
                                    <div class="earn-summary-label is-warn">Open Borrow Route P&amp;L</div>
                                    <div class="earn-summary-value neutral" id="earn-summary-borrow-pnl-value">${initialBorrowPnlValue}</div>
                                    <div class="earn-summary-sub" id="earn-summary-borrow-pnl-sub">${initialBorrowPnlSub}</div>
                                </div>
                                <div class="earn-summary-stat kpi-secondary earn-best-performer-stat${bestPerformerMutedClass}">
                                    <div class="earn-summary-label">Best Performer</div>
                                    <div class="earn-summary-value ${bestPerformerValueClass}">${bestIconHtml}${bestSymbol || '—'}</div>
                                    <div class="earn-summary-sub">${bestYieldUsd > 0 ? '<span class="sub-highlight">' + bestYieldSign + earn_formatUSD(Math.abs(bestYieldUsd)) + '</span> current value' : 'No yield data'}</div>
                                </div>
                                <div class="earn-summary-stat kpi-secondary earn-borrow-route-stat${hasBorrowContext ? '' : ' is-muted'}">
                                    <div class="earn-summary-label">Borrow Route Yield</div>
                                    <div class="earn-summary-value ${borrowRouteYieldClass}" id="earn-summary-borrow-route-value" data-open-route-yield="${openRouteYieldAssetCount > 0 ? 'true' : 'false'}" data-tip="${earn_escapeHtml('Accrued collateral yield that remains inside an open borrow route. It is separated from Total Yield Earned until the route closes or collateral is withdrawn.')}">${borrowRouteYieldValue}</div>
                                    <div class="earn-summary-sub" id="earn-summary-borrow-route-sub">${borrowRouteSub}</div>
                                </div>
                            </div>
                        </div>`;
                    summaryEl.classList.add('visible');
                    earn_updateSummaryCardLayout(summaryEl);

                    // Re-apply lending positions debt if already loaded (survives re-render)
                    if (earn_lendingPositions && earn_lendingPositions.length > 0) {
                        earn_updateSummaryDebt(earn_lendingPositions);
                    }

                    const rewardsValueEl = document.getElementById('earn-rewards-overview-val');
                    const rewardsSubEl = document.getElementById('earn-rewards-overview-sub');
                    const rewardsListEl = document.getElementById('earn-rewards-overview-list');
                    const rewardsCardEl = summaryEl.querySelector('.earn-rewards-overview-stat');
                    const rewardsState = {
                        odoloClaimed: null,
                        odoloUnclaimed: earn_odoloUnclaimed || 0,
                        wlfiAccumulated: null,
                        wlfiUnclaimed: null,
                        merklUnavailable: false,
                        extraParts: [],
                    };
                    const formatRewardAmount = value => value >= 1000 ? (value / 1000).toFixed(2) + 'K' : value.toFixed(2);
                    const getRewardIcon = symbol => SYMBOL_ICONS[symbol] || SYMBOL_ICONS[String(symbol || '').toUpperCase()] || '';
                    const getRewardDisplayName = symbol => {
                        const key = String(symbol || '').trim();
                        const upper = key.toUpperCase();
                        const names = {
                            'ODOLO': 'oDOLO reward',
                            'WLFI': 'WLFI reward',
                            'HONEY': 'Honey',
                            'WBERA': 'Wrapped BERA',
                            'WIBGT': 'Wrapped iBGT',
                            'IBGT': 'iBGT',
                            'GMX': 'GMX',
                            'ESGMX': 'esGMX',
                            'WETH': 'Wrapped Ether',
                            'ETH': 'Ether',
                        };
                        return names[key] || names[upper] || key;
                    };
                    const getRewardFallbackLabel = symbol => {
                        const key = String(symbol || '').trim();
                        if (!key) return '?';
                        if (key.toLowerCase() === 'widgt') return 'wB';
                        if (key.toLowerCase() === 'wibgt') return 'wB';
                        if (key.toLowerCase() === 'odolo') return 'oD';
                        if (key.length <= 3) return key.toUpperCase();
                        return key.replace(/[^a-z0-9]/gi, '').slice(0, 2).toUpperCase();
                    };
                    const formatRewardSummary = count => count === 1 ? 'Farmed reward token' : 'Farmed reward tokens';
                    const renderRewardsOverview = () => {
                        if (!isSummaryRenderCurrent() || !rewardsValueEl || !rewardsSubEl || !rewardsListEl) return;
                        const parts = [];
                        if (rewardsState.odoloClaimed !== null) {
                            const totalOdolo = (rewardsState.odoloClaimed || 0) + (rewardsState.odoloUnclaimed || 0);
                            if (totalOdolo > 0.01) {
                                parts.push({ symbol: 'oDOLO', amountLabel: formatRewardAmount(totalOdolo) });
                            }
                        }
                        if (rewardsState.wlfiAccumulated !== null && rewardsState.wlfiAccumulated > 0.01) {
                            parts.push({ symbol: 'WLFI', amountLabel: formatRewardAmount(rewardsState.wlfiAccumulated || 0) });
                        }
                        rewardsState.extraParts.forEach(part => {
                            if (!part || !part.amountLabel || !part.symbol) return;
                            parts.push({ symbol: part.symbol, amountLabel: part.amountLabel });
                        });
                        const merklWarningPill = rewardsState.merklUnavailable
                            ? `<span class="earn-summary-mini-pill is-warning" aria-label="WLFI rewards unavailable">
                                <span class="earn-summary-mini-pill-main">
                                    <span class="earn-summary-mini-pill-icon-fallback">WL</span>
                                </span>
                                <span class="amount">Unavailable</span>
                            </span>`
                            : '';

                        if (parts.length === 0) {
                            rewardsValueEl.textContent = rewardsState.merklUnavailable ? 'Unavailable' : '0';
                            rewardsValueEl.className = 'earn-summary-value ' + (rewardsState.merklUnavailable ? 'warn' : 'neutral');
                            rewardsSubEl.textContent = rewardsState.merklUnavailable ? 'WLFI source did not respond' : 'No active reward streams';
                            rewardsListEl.innerHTML = merklWarningPill;
                            if (rewardsCardEl) rewardsCardEl.classList.toggle('is-muted', !rewardsState.merklUnavailable);
                            return;
                        }
                        if (rewardsCardEl) rewardsCardEl.classList.remove('is-muted');
                        rewardsValueEl.textContent = `${parts.length} reward${parts.length !== 1 ? 's' : ''}`;
                        rewardsValueEl.className = 'earn-summary-value positive';
                        rewardsSubEl.textContent = rewardsState.merklUnavailable ? 'Partial reward data' : formatRewardSummary(parts.length);
                        rewardsListEl.innerHTML = parts.map(part => (
                            (() => {
                                const icon = getRewardIcon(part.symbol);
                                const rewardName = getRewardDisplayName(part.symbol);
                                const tooltipText = rewardName === part.symbol
                                    ? rewardName
                                    : `${rewardName} (${part.symbol})`;
                                const iconOrFallback = icon
                                    ? `<img src="${earn_escapeHtml(icon)}" alt="${earn_escapeHtml(rewardName)}" class="earn-summary-mini-pill-icon" onerror="this.style.display='none';this.insertAdjacentHTML('afterend','<span class=&quot;earn-summary-mini-pill-icon-fallback&quot;>${earn_escapeHtml(getRewardFallbackLabel(part.symbol))}</span>')">`
                                    : `<span class="earn-summary-mini-pill-icon-fallback">${earn_escapeHtml(getRewardFallbackLabel(part.symbol))}</span>`;
                                return `<span class="earn-summary-mini-pill${icon ? ' has-icon' : ''}" aria-label="${earn_escapeHtml(tooltipText)} reward">
                                <span class="earn-summary-mini-pill-main" data-tip="${earn_escapeHtml(tooltipText)}" aria-label="${earn_escapeHtml(tooltipText)}">
                                    ${iconOrFallback}
                                    <span class="token">${earn_escapeHtml(part.symbol)}</span>
                                </span>
                                <span class="amount">${earn_escapeHtml(part.amountLabel)}</span>
                            </span>`;
                            })()
                        )).join('') + merklWarningPill;
                    };

                    // Fetch oDOLO claimed asynchronously
                    const earnAddr = document.getElementById('earn-address').value.trim();
                    const earnChainId = document.getElementById('earn-chain').value;
                    earn_fetchOdoloClaimed(earnAddr).then(claimed => {
                        if (!isSummaryRenderCurrent()) return;
                        rewardsState.odoloClaimed = claimed || 0;
                        rewardsState.odoloUnclaimed = earn_odoloUnclaimed || 0;
                        renderRewardsOverview();
                        earn_softRefreshRewardsUi(earnAddr, earnChainId);
                    });

                    // Fetch MERKL WLFI rewards and fold them into the unified rewards card
                    earn_fetchMerklRewards(earnAddr, earnChainId).then(merklData => {
                        if (!isSummaryRenderCurrent()) return;
                        earn_merklRewards = merklData || {};
                        earn_merklRewardsLoaded = true;
                        rewardsState.merklUnavailable = earn_merklFetchStatus === 'error';
                        const wlfiData = merklData['WLFI'];
                        rewardsState.wlfiAccumulated = wlfiData ? (wlfiData.accumulated || 0) : 0;
                        rewardsState.wlfiUnclaimed = wlfiData ? (wlfiData.unclaimed || 0) : 0;
                        renderRewardsOverview();
                    }).catch(e => {
                        rewardsState.merklUnavailable = true;
                        renderRewardsOverview();
                        console.warn('WLFI summary card fetch:', e);
                    });

                    // Fetch iBGT staking rewards (Berachain only)
                    if (earnChainId === 'berachain') {
                        earn_fetchIBGTRewards(earnAddr).then(ibgtData => {
                            if (!isSummaryRenderCurrent()) return;
                            const fmtIbgt = v => v >= 1000 ? (v / 1000).toFixed(2) + 'K' : v >= 1 ? v.toFixed(2) : v.toFixed(4);
                            if (ibgtData && (ibgtData.rewards.length > 0 || ibgtData.staked > 0.01)) {
                                rewardsState.extraParts = rewardsState.extraParts.filter(part => !String(part.key || '').startsWith('ibgt:'));
                                ibgtData.rewards.forEach(reward => {
                                    rewardsState.extraParts.push({
                                        key: `ibgt:${reward.symbol}`,
                                        symbol: reward.symbol,
                                        amountLabel: fmtIbgt(reward.amount),
                                    });
                                });
                                renderRewardsOverview();
                            }
                        }).catch(e => console.warn('iBGT rewards card fetch:', e));
                    }

                    // Fetch dGMX staking rewards (Arbitrum only)
                    if (earnChainId === 'arbitrum') {
                        earn_fetchDGMXRewards(earnAddr).then(dgmxData => {
                            if (!isSummaryRenderCurrent()) return;
                            const fmtGmx = v => v >= 1000 ? (v / 1000).toFixed(2) + 'K' : v >= 1 ? v.toFixed(2) : v.toFixed(4);
                            if (dgmxData && dgmxData.staked > 0.01) {
                                rewardsState.extraParts = rewardsState.extraParts.filter(part => !String(part.key || '').startsWith('dgmx:'));
                                dgmxData.rewards.forEach(reward => {
                                    rewardsState.extraParts.push({
                                        key: `dgmx:${reward.symbol}`,
                                        symbol: reward.symbol,
                                        amountLabel: fmtGmx(reward.amount),
                                    });
                                });
                                renderRewardsOverview();
                            }
                        }).catch(e => console.warn('dGMX rewards card fetch:', e));
                    }
                }
            } // end skipSummary guard for summary card

            earn_renderNotices();

            // Show results
            const resultsEl = document.getElementById('earn-results');
            const gatedLoading = earn_isLookupLoadingGateActive();
            if (resultsEl) resultsEl.classList.add('visible');
            earn_updateLookupRefreshBadge();
            const filterBar = document.getElementById('earn-filter-bar');
            const modeToggle = document.getElementById('earn-mode-toggle');
            if (!gatedLoading) {
                if (modeToggle) modeToggle.classList.add('visible');
                if (filterBar) filterBar.style.display = '';
            } else {
                if (modeToggle) modeToggle.classList.remove('visible');
                if (filterBar) filterBar.style.display = 'none';
            }

            // Bind tooltip float for earn tab toggles (body-level float)
            const ttFloat = document.getElementById('toggle-tooltip-float');
            if (ttFloat) {
                document.querySelectorAll('#earn-filter-bar .odolo-toggle-wrap[data-tooltip]').forEach(wrap => {
                    if (wrap._ttBound) return; // avoid duplicate binding
                    wrap._ttBound = true;
                    wrap.addEventListener('mouseenter', () => {
                        ttFloat.textContent = wrap.dataset.tooltip;
                        ttFloat.style.display = 'block';
                        const rect = wrap.getBoundingClientRect();
                        ttFloat.style.top = (rect.bottom + 8) + 'px';
                        ttFloat.style.right = (window.innerWidth - rect.right) + 'px';
                        ttFloat.style.left = 'auto';
                    });
                    wrap.addEventListener('mouseleave', () => {
                        ttFloat.style.display = 'none';
                    });
                });
            }
            // Update dust count — only count dust from VISIBLE items
            const dustToggle = document.getElementById('earn-dust-toggle');
            if (dustToggle) {
                let dustCount = 0;
                // Count dust in active supply assets (always visible)
                (earn_cachedAssets || []).forEach(a => {
                    if (a.isBorrow || a.isCollateral) return;
                    const yieldCalc = getVerifiedYieldCalc(a);
                    const verifiedYieldUsdScaled = earn_isTrustedInterestLedgerYieldCalc(yieldCalc)
                        ? (yieldCalc.yieldUsdScaled || 0n)
                        : 0n;
                    if (a.usdValue < 1 && earn_absUsdScaled(verifiedYieldUsdScaled) < EARN_USD_SCALE) dustCount++;
                });
                // Count dust in withdrawn items ONLY if withdrawn section is visible
                const withdrawnSection = document.getElementById('earn-withdrawn-section');
                const isWithdrawnVisible = withdrawnSection && withdrawnSection.style.display !== 'none';
                if (isWithdrawnVisible && earn_historyData && earn_historyData.length > 0) {
                    const activeAddrs = new Set(assets.filter(a => !a.isCollateral).map(a => a.tokenAddr?.toLowerCase()));
                    earn_historyData.forEach(item => {
                        if (item.isActive) return;
                        if (item.isIsolation && !item.isActive) return;
                        if (activeAddrs.has(item.tokenAddr?.toLowerCase())) return;
                        const chainId = document.getElementById('earn-chain').value;
                        const balanceUsdScaled = earn_getTokenUsdScaled(item.currentWei, item.decimals, item.symbol, item.tokenAddr, chainId);
                        const verifiedYieldUsdScaled = item.yieldTrustedForDisplay ? (item.yieldUsdScaled || 0n) : 0n;
                        if (earn_isSubDollarYieldPair(balanceUsdScaled, verifiedYieldUsdScaled)) dustCount++;
                    });
                }
                const keepDustToggleVisible = shouldShowSupplySection;
                if (dustCount > 0 || keepDustToggleVisible) {
                    dustToggle.style.display = '';
                    // active = filter ON = dust HIDDEN
                    dustToggle.classList.toggle('active', !earn_showDust);
                    dustToggle.setAttribute('aria-checked', String(!earn_showDust));
                } else {
                    // No visible context at all → hide the button entirely
                    dustToggle.style.display = 'none';
                    dustToggle.setAttribute('aria-checked', 'false');
                }
            }

            // Update position counter
            const posCount = document.getElementById('earn-position-count');
            if (posCount) {
                const activeCount = assets.filter(a => a.usdValue >= 0.01).length;
                const totalCount = activeCount + ((earn_historyData || []).filter(i => !i.isActive && !i.isIsolation).length);
                posCount.textContent = `Showing ${totalCount} position${totalCount !== 1 ? 's' : ''}`;
            }
        }

        // Enter key to search
        document.getElementById('earn-address').addEventListener('keydown', (e) => {
            if (e.key === 'Enter') earn_lookup();
        });

// ═══ UNIFIED PREMIUM TOOLTIP SYSTEM ═══
        // Single tooltip element for all types: depth badges, breakdown items, addresses, badge labels
        // Matches the DUST/LOW glass-morphism aesthetic across all UI
        (function () {
            const tip = document.createElement('div');
            tip.id = 'unified-tooltip';
            tip.innerHTML = '<div class="utip-title"></div><div class="utip-desc"></div>';
            document.body.appendChild(tip);

            let _activeEl = null;
            let _hideRAF = null;
            let _hideTimer = null;
            let _lastPointer = { x: 0, y: 0 };

            function showTip(el, title, desc, isMono) {
                if (_hideRAF) { cancelAnimationFrame(_hideRAF); _hideRAF = null; }
                if (_hideTimer) { clearTimeout(_hideTimer); _hideTimer = null; }
                _activeEl = el;
                const titleEl = tip.querySelector('.utip-title');
                const descEl = tip.querySelector('.utip-desc');

                // Title: only show if provided
                if (title) {
                    titleEl.textContent = title;
                    titleEl.style.display = 'block';
                    // Color title based on context
                    if (title.includes('DUST')) titleEl.style.color = '#f87171';
                    else if (title.includes('LOW')) titleEl.style.color = '#fbbf24';
                    else titleEl.style.color = 'rgba(99, 102, 241, 0.85)';
                } else {
                    titleEl.style.display = 'none';
                }

                descEl.textContent = desc;
                const classes = [];
                if (isMono) classes.push('utip-mono');
                if (el && el.closest && el.closest('#view-earn')) classes.push('earn-tooltip');
                tip.className = classes.join(' ');
                tip.id = 'unified-tooltip';
                tip.style.display = 'block';
                tip.style.opacity = '0';

                // Position above the element, flip below if no space
                requestAnimationFrame(function () {
                    if (_activeEl !== el) return;
                    const rect = el.getBoundingClientRect();
                    const tipW = tip.offsetWidth;
                    const tipH = tip.offsetHeight;

                    // Horizontal: center on element, clamp to viewport
                    let left = rect.left + rect.width / 2 - tipW / 2;
                    if (left < 8) left = 8;
                    if (left + tipW > window.innerWidth - 8) left = window.innerWidth - tipW - 8;

                    // Vertical: prefer above, flip below
                    let above = true;
                    let top = rect.top - tipH - 10;
                    if (top < 8) {
                        top = rect.bottom + 10;
                        above = false;
                    }

                    // Arrow direction
                    tip.classList.toggle('arrow-up', !above);

                    // Arrow horizontal position (relative to tooltip left)
                    const arrowLeft = Math.max(12, Math.min(rect.left + rect.width / 2 - left, tipW - 12));
                    tip.style.setProperty('--arrow-left', arrowLeft + 'px');
                    // Update the ::after left to match
                    tip.style.left = left + 'px';
                    tip.style.top = top + 'px';
                    tip.style.opacity = '1';
                });
            }

            function hideTip() {
                tip.style.display = 'none';
                tip.style.opacity = '0';
                _activeEl = null;
            }

            function scheduleHideTip() {
                if (_hideTimer) clearTimeout(_hideTimer);
                _hideTimer = setTimeout(function () {
                    const el = document.elementFromPoint(_lastPointer.x, _lastPointer.y);
                    if (_activeEl && el && _activeEl.contains(el)) return;
                    hideTip();
                }, 80);
            }

            // --- Unified mouseover handler ---
            document.addEventListener('mouseover', function (e) {
                _lastPointer = { x: e.clientX, y: e.clientY };
                // 1. Depth badges (DUST / LOW)
                const badge = e.target.closest('.assets-depth-badge');
                if (badge) {
                    const srcTip = badge.querySelector('.depth-tooltip');
                    if (!srcTip) return;
                    const titleEl = srcTip.querySelector('.depth-tooltip-title');
                    const descEl = srcTip.querySelector('.depth-tooltip-desc');
                    showTip(badge, titleEl ? titleEl.textContent : '', descEl ? descEl.textContent : '', false);
                    return;
                }

                // 2. Breakdown items (oDOLO, Lending, GM Performance, etc.)
                const breakdown = e.target.closest('.breakdown-item[data-tip], .breakdown-help-icon, .yield-help-icon, .tooltip-icon, .tooltip-wrap');
                if (breakdown) {
                    const text = breakdown.getAttribute('data-tip') ||
                        (breakdown.querySelector('.tooltip-bubble') ? breakdown.querySelector('.tooltip-bubble').textContent : '');
                    if (text) showTip(breakdown, null, text, false);
                    return;
                }

                // 3. Address tooltips
                const addr = e.target.closest('.addr-tooltip-wrap');
                if (addr) {
                    const fullAddr = addr.getAttribute('data-full-addr');
                    if (fullAddr) showTip(addr, null, fullAddr, true);
                    return;
                }

                // 4. Badge tooltips (CEX, LP, Protocol labels)
                const badgeWrap = e.target.closest('.badge-tooltip-wrap');
                if (badgeWrap) {
                    const badgeTip = badgeWrap.querySelector('.badge-tooltip');
                    if (badgeTip) showTip(badgeWrap, null, badgeTip.textContent, false);
                    return;
                }

                // 5. Generic data-tip elements, including legacy metric labels.
                const generic = e.target.closest('[data-tip], .tvl-metric-label[data-tip], .hero-label-tip');
                if (generic && !generic.closest('.breakdown-item')) {
                    const bubble = generic.querySelector('.tooltip-bubble');
                    const text = generic.getAttribute('data-tip') || (bubble ? bubble.textContent : '');
                    if (text) showTip(generic, null, text, false);
                    return;
                }
            });

            document.addEventListener('mousemove', function (e) {
                _lastPointer = { x: e.clientX, y: e.clientY };
            });

            // --- Unified mouseout handler ---
            document.addEventListener('mouseout', function (e) {
                _lastPointer = { x: e.clientX, y: e.clientY };
                if (!_activeEl) return;
                const related = e.relatedTarget;
                if (related && _activeEl.contains(related)) return;

                // Check if we're leaving the active element
                const leaving =
                    e.target.closest('.assets-depth-badge') === _activeEl ||
                    e.target.closest('.breakdown-item, .breakdown-help-icon, .yield-help-icon, .tooltip-icon, .tooltip-wrap') === _activeEl ||
                    e.target.closest('.addr-tooltip-wrap') === _activeEl ||
                    e.target.closest('.badge-tooltip-wrap') === _activeEl ||
                    e.target.closest('[data-tip], .tvl-metric-label[data-tip], .hero-label-tip') === _activeEl ||
                    e.target === _activeEl;

                if (leaving) scheduleHideTip();
            });

            // Hide on scroll
            window.addEventListener('scroll', function () {
                if (_activeEl) hideTip();
            }, true);
        })();
